const ZOO_CURATOR_VERSION = "V2.44.165";
const ZOO_REQUIRED_HTML_INTERFACE = 1;
const ZOO_REQUIRED_CSS_INTERFACE = 2;

const DESKTOP_UI_REFERENCE_WIDTH = 2560;
const DESKTOP_UI_MIN_SCALE = 0.68;

function desktopUiScale() {
    if (window.matchMedia('(max-width: 700px)').matches) return 1;

    const viewportRatio = Math.min(
        1,
        window.innerWidth / DESKTOP_UI_REFERENCE_WIDTH
    );
    const laptopRatio = 1366 / DESKTOP_UI_REFERENCE_WIDTH;
    const fullHdRatio = 1920 / DESKTOP_UI_REFERENCE_WIDTH;

    if (viewportRatio <= laptopRatio) return DESKTOP_UI_MIN_SCALE;
    if (viewportRatio <= fullHdRatio) {
        const t = (viewportRatio - laptopRatio) / (fullHdRatio - laptopRatio);
        return DESKTOP_UI_MIN_SCALE + t * (0.92 - DESKTOP_UI_MIN_SCALE);
    }

    const t = (viewportRatio - fullHdRatio) / (1 - fullHdRatio);
    return 0.92 + t * 0.08;

}

let desktopUiScaleFrame = 0;
function applyDesktopUiScaleNow() {
    const scale = desktopUiScale();
    document.documentElement.style.setProperty('--desktop-ui-scale', scale.toFixed(4));
    document.documentElement.style.setProperty('--desktop-header-height', `${(220 * scale).toFixed(2)}px`);
    return scale;
}
function refreshDesktopUiScale() {
    if (desktopUiScaleFrame) return;
    desktopUiScaleFrame = requestAnimationFrame(() => {
        desktopUiScaleFrame = 0;
        applyDesktopUiScaleNow();
    });
}

refreshDesktopUiScale();

function refreshDesktopPeripheralHeaderScale(){
    if (window.matchMedia('(max-width: 700px)').matches) return;
}

function suspendTrueCalendarLifecycle(){
    if(trueCalendarLifecycleSuspended)return;
    trueCalendarLifecycleSuspended=true;
    if(state?.gameMode==='true'&&!state.sandboxMode)stopTrueCalendarTimer({preserveRollover:true});
}
function resumeTrueCalendarLifecycle(){
    if(!trueCalendarLifecycleSuspended)return;
    trueCalendarLifecycleSuspended=false;
    if(state?.gameMode==='true'&&!state.sandboxMode){
        trueCalendarLastDriverAt=performance.now();
        if(!trueCalendarRolloverPending){
            if(trueCalendarPendingSpeed!=null)queueMicrotask(trueApplyPendingCalendarSpeed);
            else restartTrueCalendarTimer();
        }
    }
}
document.addEventListener('visibilitychange',()=>{
    if(document.hidden){dismissHoverPreviewForContextLoss();suspendTrueCalendarLifecycle();}
    else resumeTrueCalendarLifecycle();
});
window.addEventListener('blur',dismissHoverPreviewForContextLoss);
window.addEventListener('pagehide',()=>{dismissHoverPreviewForContextLoss();suspendTrueCalendarLifecycle();});
window.addEventListener('pageshow',()=>{if(!document.hidden)resumeTrueCalendarLifecycle();});

let desktopUiResizeRaf=0;
const scheduleDesktopUiScaleRefresh=()=>{
    if(desktopUiResizeRaf)cancelAnimationFrame(desktopUiResizeRaf);
    desktopUiResizeRaf=requestAnimationFrame(()=>{
        desktopUiResizeRaf=0;

        if(desktopUiScaleFrame){
            cancelAnimationFrame(desktopUiScaleFrame);
            desktopUiScaleFrame=0;
        }
        applyDesktopUiScaleNow();
        refreshDesktopPeripheralHeaderScale();

        desktopUiResizeRaf=requestAnimationFrame(()=>{
            desktopUiResizeRaf=0;
            fitProgressTrackerAroundActions?.();
            positionOpponentTradeArea?.(true);
            refreshContextualExchangeEligibilityGlows?.();
            scheduleAnimalGlowPrecedenceRefresh?.();
        });
    });
};
window.addEventListener('resize', scheduleDesktopUiScaleRefresh, { passive: true });
window.visualViewport?.addEventListener('resize', scheduleDesktopUiScaleRefresh, { passive: true });

function checkZooInterfaceCompatibility() {
    const htmlInterface = Number(window.ZOO_INTERFACES?.html || 0);
    const cssInterface = Number.parseInt(
        getComputedStyle(document.documentElement).getPropertyValue('--zoo-css-interface'),
        10
    ) || 0;

    const issues = [];
    if (htmlInterface < ZOO_REQUIRED_HTML_INTERFACE) {
        issues.push(`index.html interface ${htmlInterface || 'unknown'}; game.js requires ${ZOO_REQUIRED_HTML_INTERFACE}`);
    }
    if (cssInterface < ZOO_REQUIRED_CSS_INTERFACE) {
        issues.push(`style.css interface ${cssInterface || 'unknown'}; game.js requires ${ZOO_REQUIRED_CSS_INTERFACE}`);
    }

    if (issues.length) {
        console.warn('Zoo Curator compatibility warning:', issues.join('; '));
    }
    return issues;
}

window.__zooCompatibilityIssues = checkZooInterfaceCompatibility();

