function opponentHasCategoryPrerequisite(holdings, wantedAnimal) {
    if (!wantedAnimal) return false;
    if (wantedAnimal.level <= 1) return true;

    return (holdings || []).some(animal =>
        animal &&
        animal.category === wantedAnimal.category &&
        animal.level === wantedAnimal.level - 1
    );
}

function realZooCanTradeFor(record, wantedAnimal) {
    if (!record || !wantedAnimal) return false;

    const favourites = Array.isArray(record.preferred_categories)
        ? record.preferred_categories.filter(Boolean)
        : [];

    if (favourites.length === 1 && wantedAnimal.category !== favourites[0]) {
        return false;
    }

    return opponentHasCategoryPrerequisite(
        realZooTradeSpecs(record),
        wantedAnimal
    );
}

function realZooCanHelpfullyTradeFor(record, wantedAnimal) {
    if (!record || !wantedAnimal) return false;

    const favourites = Array.isArray(record.preferred_categories)
        ? record.preferred_categories.filter(Boolean)
        : [];

    return !(
        favourites.length === 1 &&
        wantedAnimal.category !== favourites[0]
    );
}

function fictionalZooCanTradeFor(opponentIndex, wantedAnimal) {
    return opponentHasCategoryPrerequisite(
        state.opponentTradeStocks[opponentIndex] || [],
        wantedAnimal
    );
}

function availableNextLevelFiles(category, level) {
    const nextLevel = Number(level) + 1;

    if (
        !category ||
        !Number.isFinite(nextLevel) ||
        nextLevel < 2 ||
        nextLevel > 5
    ) {
        return [];
    }

    const owned = playerOwnedCardKeys();
    return levelFiles(category, nextLevel).filter(file =>
        !owned.has(animalCardKey(category, nextLevel, file))
    );
}

function hasNextLevelInventory(category, level, owned=playerOwnedCardKeys()) {
    const nextLevel=Number(level)+1;
    if(!category||!Number.isFinite(nextLevel)||nextLevel<2||nextLevel>5)return false;
    for(const file of levelFiles(category,nextLevel)){
        if(!owned.has(animalCardKey(category,nextLevel,file)))return true;
    }
    return false;
}

function emergencyTradeNeeded() {
    return (
        state.historyViewTurn === null &&
        !state.sandboxMode &&
        !state.result &&
        !state.outgoingOffer &&
        !state.autonomousTradeOffer
    );
}

function emergencyTradeSelectionUncached(writeState = true) {
    if (!emergencyTradeNeeded()) return null;

    const playerAnimals = state.animals.filter(animal =>
        animal.enclosureId !== null &&
        animal.level >= 1 &&
        animal.level <= 5
    );

    const shuffledPlayers = seededShuffle(
        playerAnimals,
        `emergency-player|${state.turn}|${tradeOfferWindow()}`
    );

    if (isRealOpponentMode()) {
        for (const outgoing of shuffledPlayers) {
            const records = realZooRecordsAvailableForTrade(outgoing);
            const orderedRecords = selectPrestigeLocationCandidates(
                records.map(record => ({ record })),
                records.length,
                `emergency-real-record-order|${outgoing.id}|${state.turn}|${tradeOfferWindow()}`
            ).map(item => item.record);

            for (const record of orderedRecords) {
                if (!realZooCanTradeFor(record, outgoing)) continue;

                const matching = realZooTradeAnimals(record, true)
                    .filter(candidate =>
                                                candidate.level === outgoing.level &&
                        tradeIncomingHasDestinationAfterOutgoing(candidate, outgoing)
                    );
                if (!matching.length) continue;

                const { seed } = seededRoll(
                    `emergency-real-animal|${outgoing.id}|${record.name}|${state.turn}`
                );
                return {
                    outgoingId: outgoing.id,
                    record,
                    animal: matching[seed % matching.length]
                };
            }
        }
    }
    else {
        const opponentIndexes = [];
        for (
            let index = 0;
            index < Math.min(state.unlockedOpponentCount, state.opponentProfiles.length);
            index++
        ) {
            if (writeState) fillOpponentTradeStock(index);
            opponentIndexes.push(index);
        }

        const shuffledIndexes = seededShuffle(
            opponentIndexes.map(opponentIndex => ({ opponentIndex })),
            `emergency-fictional-zoos|${state.turn}|${tradeOfferWindow()}`
        ).map(item => item.opponentIndex);

        for (const outgoing of shuffledPlayers) {
            for (const opponentIndex of shuffledIndexes) {
                if (!fictionalZooCanTradeFor(opponentIndex, outgoing)) continue;

                const matching = (state.opponentTradeStocks[opponentIndex] || [])
                    .filter(candidate =>
                        candidate.level === outgoing.level &&
                        tradeIncomingHasDestinationAfterOutgoing(candidate, outgoing)
                    );
                if (!matching.length) continue;

                const { seed } = seededRoll(
                    `emergency-fictional-animal|${outgoing.id}|${opponentIndex}|${state.turn}`
                );

                return {
                    outgoingId: outgoing.id,
                    opponentIndex,
                    animal: matching[seed % matching.length]
                };
            }
        }
    }

    if (isRealOpponentMode()) {
        const allRealZoos = realZooRecordsAvailable();
        const tradePrestige = playerTradeAccessPrestige(
            state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo
                ? visibleZooPrestige()
                : currentZooPrestige()
        );

        for (const outgoing of shuffledPlayers) {
            const candidates = allRealZoos
                .filter(record => realZooCanHelpfullyTradeFor(record, outgoing))
                .map(record => {
                    const matching = realZooTradeAnimals(record, true)
                        .filter(candidate =>
                            candidate.level === outgoing.level &&
                            tradeIncomingHasDestinationAfterOutgoing(candidate, outgoing)
                        );
                    return { record, matching };
                })
                .filter(item => item.matching.length)
                .sort((a, b) => {
                    const prestigeDifference =
                        Math.abs(realZooPrestige(a.record) - tradePrestige) -
                        Math.abs(realZooPrestige(b.record) - tradePrestige);
                    if (prestigeDifference) return prestigeDifference;

                    const geographyDifference =
                        realZooGeographyBand(a.record) - realZooGeographyBand(b.record);
                    if (geographyDifference) return geographyDifference;

                    return String(a.record.name || '').localeCompare(
                        String(b.record.name || '')
                    );
                });

            if (candidates.length) {
                const chosenZoo = candidates[0];
                const { seed } = seededRoll(
                    `forced-real-animal|${outgoing.id}|${chosenZoo.record.name}|${state.turn}`
                );
                return {
                    outgoingId: outgoing.id,
                    record: chosenZoo.record,
                    animal: chosenZoo.matching[seed % chosenZoo.matching.length],
                    forcedRealZooTrade: true,
                    helpfulRealZooTrade: true
                };
            }
        }
    }

    if (isRealOpponentMode() && state.realZooDataLoadState !== 'ready') {
        return null;
    }

    const levelOnePlayers = shuffledPlayers.filter(animal => animal.level === 1);
    if (!levelOnePlayers.length) return null;

    const outgoing = levelOnePlayers[0];
    const ownedKeys = playerOwnedCardKeys();
    const available = [];

    for (const category of Object.keys(FOLDERS)) {
        if (!state.activeCategories.has(category)) continue;

        for (const filename of levelFiles(category, 1)) {
            const key = animalCardKey(category, 1, filename);
            if (ownedKeys.has(key)) continue;
            const candidate = {
                category,
                level: 1,
                filename: cleanFilename(filename),
                enclosureId: null,
                slotIndex: null,
                    };
            if (!tradeIncomingHasDestinationAfterOutgoing(candidate, outgoing)) continue;
            available.push({ category, filename });
        }
    }

    if (!available.length) return null;

    const { seed } = seededRoll(
        `private-pet-trade|${outgoing.id}|${state.turn}|${tradeOfferWindow()}`
    );
    const chosen = available[seed % available.length];

    return {
        outgoingId: outgoing.id,
        privatePetTrade: true,
        record: {
            name: 'Private Pet Trade',
            country: '',
            province: '',
            preferred_categories: []
        },
        animal: {
            id: writeState ? state.nextId++ : -1,
            category: chosen.category,
            level: 1,
            filename: cleanFilename(chosen.filename),
            enclosureId: null,
            slotIndex: null,
            }
    };
}

let emergencyTradePreviewCacheKey='',emergencyTradePreviewCacheValue=null,emergencyTradePreviewCacheHasValue=false;
function emergencyTradeSelection(writeState=true){
    if(writeState)return emergencyTradeSelectionUncached(true);
    const key=`${Number(state.turn)||0}|${tradeOfferWindow()}|${state.animals?.length||0}|${Number(state.nextId)||0}|${state.unlockedOpponentCount||0}`;
    if(emergencyTradePreviewCacheHasValue&&emergencyTradePreviewCacheKey===key)return emergencyTradePreviewCacheValue;
    const value=emergencyTradeSelectionUncached(false);
    emergencyTradePreviewCacheKey=key;emergencyTradePreviewCacheValue=value;emergencyTradePreviewCacheHasValue=true;
    return value;
}

function emergencyTradeForAnimal(outgoing, writeState = true) {
    if (!outgoing) return null;
    const rescue = emergencyTradeSelection(writeState);
    return rescue && rescue.outgoingId === outgoing.id ? rescue : null;
}

function normalTradeInterestCap() {
    return Math.floor(state.animals.length / 3);
}

function simultaneousTradeOfferCap() {
    return Math.max(1, Math.floor(state.animals.length / 3));
}

function normalTradeInterestAllowedIdsUncached() {
    const cap = normalTradeInterestCap();
    if (cap <= 0) return new Set();

    const candidates = state.animals.filter(candidate =>
        candidate &&
        candidate.level >= 1 &&
        candidate.level <= 5 &&
        candidate !== state.outgoingOffer
    );

    if (candidates.length <= cap) {
        return new Set(candidates.map(candidate => candidate.id));
    }

    return new Set(
        candidates
            .map(candidate => ({
                id: candidate.id,
                score: seededRoll(
                    `trade-interest-cap|${candidate.id}|${tradeOfferWindow()}`
                ).seed
            }))
            .sort((a, b) => a.score - b.score || a.id - b.id)
            .slice(0, cap)
            .map(entry => entry.id)
    );
}

let normalTradeInterestCacheKey='',normalTradeInterestCache=null;
function normalTradeInterestAllowedIds(){
    const key=`${tradeOfferWindow()}|${state.animals?.length||0}|${Number(state.nextId)||0}|${normalTradeInterestCap()}`;
    if(normalTradeInterestCache&&normalTradeInterestCacheKey===key)return normalTradeInterestCache;
    normalTradeInterestCache=normalTradeInterestAllowedIdsUncached();
    normalTradeInterestCacheKey=key;
    return normalTradeInterestCache;
}

function normalTradeInterestAllowed(animal, allowedIds = null) {
    if (!animal) return false;
    const ids = allowedIds || normalTradeInterestAllowedIds();
    return ids.has(animal.id);
}

function predictedPlayerTradeOffers(animal, writeCache = true) {
    if (!animal) return [];

    const emergency = emergencyTradeForAnimal(animal, writeCache);
    if (emergency) return [emergency];

    return predictedPlayerTradeOffersWithoutEmergency(animal, writeCache);
}

function predictedPlayerTradeOffersWithoutEmergency(animal, writeCache = true, normalInterestIds = null) {
    if (!animal) return [];

    const cached = cachedPlayerTradeOffers(animal);
    if (cached) return cached;

    if (!normalTradeInterestAllowed(animal, normalInterestIds)) {
        if (writeCache) storePlayerTradeOffers(animal, []);
        return [];
    }

    const frequency = tradeFrequencyFactor();

    if (frequency <= 0) {
        if (writeCache) storePlayerTradeOffers(animal, []);
        return [];
    }

    if (isRealOpponentMode()) {
        const overallRoll = seededRoll(
            `real-overall|${animal.id}|${tradeOfferWindow()}`
        ).roll;

        if (overallRoll > frequency) {
            if (writeCache) storePlayerTradeOffers(animal, []);
            return [];
        }

        const records = realZooRecordsAvailableForTrade(animal);
        const candidates = [];
        const playerKeys = playerOwnedTradeKeys();

        visitPrestigeLocationCandidates(
            records.map(record=>({record})),
            item=>{
                const record=item.record;
                if(!realZooCanTradeFor(record,animal))return true;

                const matching=[];
                for(const candidate of realZooTradeAnimals(record,true,playerKeys)){
                    if(
                        candidate.level===animal.level &&
                        tradeIncomingHasDestinationAfterOutgoing(candidate,animal)
                    )matching.push(candidate);
                }
                if(!matching.length)return true;

                const favourites=Array.isArray(record.preferred_categories)
                    ?record.preferred_categories:[];
                const likesOutgoing=favourites.includes(animal.category);
                const baseInterest=likesOutgoing?.27:.11;
                const levelPenalty=(animal.level-1)*.025;
                const zooChance=Math.max(.025,baseInterest-levelPenalty);
                const {seed,roll}=seededRoll(
                    `real-zoo|${animal.id}|${record.name}|${tradeOfferWindow()}`
                );
                if(roll>zooChance)return true;

                const offeredAnimal=weightedRandomItem(
                    matching,
                    candidate=>animalZooTypeWeight(
                        candidate,record.zoo_types||record.zooTypes||'general','trade'),
                    ((seed>>>8)%1000000)/1000000
                );
                candidates.push({record,animal:offeredAnimal});
                return candidates.length<simultaneousTradeOfferCap();
            },
            `real-record-order|${animal.id}|${tradeOfferWindow()}`
        );

        const locked = candidates.map(item => ({
            recordName: item.record.name,
            animalName: String(item.animal.filename || '').replace(/\.png$/i, ''),
            animalSpec: cachedTradeAnimalSpec(item.animal)
        }));

        if (writeCache) storePlayerTradeOffers(animal, locked);
        return locked;
    }

    const overallRoll = seededRoll(
        `fictional-overall|${animal.id}|${tradeOfferWindow()}`
    ).roll;

    if (overallRoll > frequency) {
        if (writeCache) storePlayerTradeOffers(animal, []);
        return [];
    }

    const candidates = [];

    state.opponentProfiles.forEach((profile, index) => {
        if (index >= state.unlockedOpponentCount) return;
        if (!fictionalZooCanTradeFor(index, animal)) return;

        const matching = (state.opponentTradeStocks[index] || [])
            .filter(candidate =>
                                candidate.level === animal.level &&
                tradeIncomingHasDestinationAfterOutgoing(candidate, animal)
            );
        if (!matching.length) return;

        const fav = profile.favourites.includes(animal.category);
        const zooChance = fav ? 0.34 : 0.14;

        const { seed, roll } = seededRoll(
            `fictional-zoo|${animal.id}|${index}|${tradeOfferWindow()}`
        );
        if (roll > zooChance) return;

        const offeredAnimal = weightedRandomItem(
            matching,
            candidate => animalZooTypeWeight(candidate, profile.zooTypes || 'general', 'trade'),
            ((seed >>> 8) % 1000000) / 1000000
        );
        if (offeredAnimal) {
            candidates.push({ opponentIndex: index, animal: offeredAnimal });
        }
    });

    const selected = seededShuffle(
        candidates,
        `fictional-select|${animal.id}|${tradeOfferWindow()}`
    ).slice(0, simultaneousTradeOfferCap());

    const locked = selected.map(item => ({
        opponentIndex: item.opponentIndex,
        animalName: String(item.animal.filename || '').replace(/\.png$/i, ''),
        animalSpec: cachedTradeAnimalSpec(item.animal)
    }));

    if (writeCache) storePlayerTradeOffers(animal, locked);
    return locked;
}

function animalCouldReceiveTradeInterest(animal, emergencySnapshot = undefined, normalInterestIds = null) {
    if (!animal || animal.level < 1 || animal.level > 5) return false;
    if (animal === state.outgoingOffer) return false;

    if (state.autonomousTradeOffer) {
        return outgoingFitsAutonomousOffer(animal);
    }

    if (emergencySnapshot !== undefined && emergencySnapshot?.outgoingId === animal.id) {
        return true;
    }

    const predicted = emergencySnapshot === undefined
        ? predictedPlayerTradeOffers(animal, true)
        : predictedPlayerTradeOffersWithoutEmergency(animal, true, normalInterestIds);

    if (predicted.some(item => item?.animal)) return true;

    return lockedPlayerTradeOffersHaveLiveOffer(animal, predicted);
}

function clearTradeEligibleGlow(immediate = true) {
    ++tradeEligibleGlowWorkToken;
    clearTimeout(tradeEligibleGlowHideTimer);
    tradeEligibleGlowHideTimer = null;
    tradeEligibleGlowActive = false;

    const cards=document.querySelectorAll('.animal-card.trade-eligible-glow');

    cards.forEach(card => {
        clearTimeout(card._tradeGlowFadeTimer);

        if (immediate) {
            card.classList.remove('trade-eligible-glow-fading');
            card.classList.remove('trade-eligible-glow');
            return;
        }

        card.classList.add('trade-eligible-glow-fading');

        card._tradeGlowFadeTimer = setTimeout(() => {
            card.classList.remove('trade-eligible-glow-fading');
            card.classList.remove('trade-eligible-glow');
            delete card._tradeGlowFadeTimer;
            refreshAnimalGlowPrecedence(card.parentElement || document);
        }, 1000);
    });
    if(immediate&&cards.length)refreshAnimalGlowPrecedence();
}

function applyTradeEligibleGlow() {
    if(trueDecorationToolActive){clearTradeEligibleGlow(true);return;}
    if (state.visitingZoo || visitingAnotherZooForActionUI()) {
        clearTradeEligibleGlow();
        return;
    }

    if (state.historyViewTurn !== null) {
        clearTradeEligibleGlow();
        return;
    }

    if (
        state.outgoingOffer ||
        (selectedTradeOffer() && !state.autonomousTradeOffer)
    ) {
        clearTradeEligibleGlow();
        return;
    }

    clearTimeout(tradeEligibleGlowHideTimer);
    tradeEligibleGlowHideTimer = null;

    document.querySelectorAll('.animal-card.trade-eligible-glow')
        .forEach(card => {
            clearTimeout(card._tradeGlowFadeTimer);
            card.classList.remove('trade-eligible-glow-fading');
        });

    tradeEligibleGlowActive = true;

    const workToken = ++tradeEligibleGlowWorkToken;
    const emergencySnapshot = state.autonomousTradeOffer
        ? null
        : emergencyTradeSelection(false);

    const normalInterestIds = state.autonomousTradeOffer
        ? null
        : normalTradeInterestAllowedIds();

    const cards=document.querySelectorAll('.animal-card[data-animal-id]');
    let cursor = 0;

    const processTradeGlowBatch = () => {
        if (workToken !== tradeEligibleGlowWorkToken || !tradeEligibleGlowActive) return;

        const end = Math.min(cards.length, cursor + 12);
        for (; cursor < end; cursor++) {
            const card = cards[cursor];
            const animal = classicAnimalById(card.dataset.animalId);
            card.classList.toggle(
                'trade-eligible-glow',
                Boolean(animal && animalCouldReceiveTradeInterest(animal, emergencySnapshot, normalInterestIds))
            );
        }

        if(cursor<cards.length)requestAnimationFrame(processTradeGlowBatch);
        else refreshAnimalGlowPrecedence();
    };

    requestAnimationFrame(processTradeGlowBatch);
}

function scheduleTradeEligibleGlowFade() {
    clearTimeout(tradeEligibleGlowHideTimer);

    tradeEligibleGlowHideTimer = setTimeout(() => {
        tradeEligibleGlowHideTimer = null;
        clearTradeEligibleGlow(false);
    }, 1000);
}

function tradeGlowTarget(target) {
    if (!target) return null;

    if (
        !state.outgoingOffer &&
        (target === outgoingOfferBox || outgoingOfferBox.contains(target))
    ) {
        return outgoingOfferBox;
    }

    if (
        !selectedTradeOffer() &&
        (target === incomingOfferBox || incomingOfferBox.contains(target))
    ) {
        return incomingOfferBox;
    }

    if (
        state.autonomousTradeOffer &&
        (target === incomingOfferBox || incomingOfferBox.contains(target))
    ) {
        return incomingOfferBox;
    }

    return null;
}

[incomingOfferBox].forEach(box => {
    if (!box) return;

    box.addEventListener('mouseenter', () => {
        if (window.matchMedia('(max-width: 700px)').matches) return;
        if (!tradeGlowTarget(box)) return;
        applyTradeEligibleGlow();
    });

    box.addEventListener('mouseleave', () => {
        if (window.matchMedia('(max-width: 700px)').matches) return;
        if (!tradeEligibleGlowActive) return;
        scheduleTradeEligibleGlowFade();
    });
});

document.addEventListener('pointerdown', event => {
    if (!window.matchMedia('(max-width: 700px)').matches) return;

    const tradeTarget = tradeGlowTarget(event.target);

    if (tradeTarget) {
        applyTradeEligibleGlow();
        return;
    }

    if (tradeEligibleGlowActive) {
        clearTradeEligibleGlow();
    }
}, true);

'use strict';

window.__zooScriptStarted = true;

function randomItem(array) {

    if (
        !Array.isArray(array) ||
        array.length === 0
    ) {
        return null;
    }

    return array[
        Math.floor(
            Math.random() *
            array.length
        )
    ];

}

function shuffle(array) {

    const copy = [...array];

    for (
        let i = copy.length - 1;
        i > 0;
        i--
    ) {

        const j =
            Math.floor(
                Math.random() *
                (i + 1)
            );

        [
            copy[i],
            copy[j]
        ] = [
            copy[j],
            copy[i]
        ];

    }

    return copy;

}

function clamp(
    value,
    min,
    max
) {

    return Math.max(
        min,
        Math.min(
            max,
            value
        )
    );

}

function cleanFilename(filename) {

    return String(
        filename || ''
    )
        .replace(
            /\\/g,
            '/'
        )
        .split('/')
        .pop();

}

function getFolder(category) {
    category=canonicalAnimalCategory(category);
    return (
        FOLDERS[category] ||
        String(category).toLowerCase()
    );
}

function animalPath(
    category,
    level,
    filename
) {

    return (
        ANIMAL_ROOT +
        getFolder(category) +
        '/' +
        level +
        '/' +
        cleanFilename(filename)
    );

}

function animalBackPath(
    category,
    level
) {

    return (
        ANIMAL_ROOT +
        getFolder(category) +
        '/' +
        level +
        '/Back.png'
    );

}

function enclosurePath(number) {

    return (
        ENCLOSURE_ROOT +
        'Enclosure ' +
        number +
        '.png'
    );

}

function updateBootLoadingStatus(
    status,
    detail = ''
) {

    if (bootStatus) {
        bootStatus.textContent = status;
    }

    if (bootDetail) {
        bootDetail.textContent = detail;
    }

}

function showFatal(error) {

    console.error(error);

    const errorText =
        'Zoo Curator could not start.\n\n' +
        (
            error?.stack ||
            error?.message ||
            String(error)
        );

    if (bootScreen) {
        bootScreen.classList.remove('hidden');
        bootScreen.style.display = '';
        bootScreen.style.opacity = '1';
        bootScreen.style.visibility = 'visible';
        bootScreen.style.pointerEvents = 'auto';
        bootScreen.style.background = '#fff';
        bootScreen.style.color = '#111';
        bootScreen.style.zIndex = '2147483647';
    }

    if (bootStatus) {
        bootStatus.textContent = 'Zoo Curator could not start';
        bootStatus.style.color = '#b00020';
    }

    if (bootDetail) {
        bootDetail.textContent = errorText;
        bootDetail.style.whiteSpace = 'pre-wrap';
        bootDetail.style.overflowWrap = 'anywhere';
        bootDetail.style.maxWidth = '90vw';
        bootDetail.style.maxHeight = '65vh';
        bootDetail.style.overflow = 'auto';
        bootDetail.style.color = '#111';
    }

    if (fatalError) {
        fatalError.classList.add('visible');
        fatalError.textContent = errorText;
    }
}

window.addEventListener('error', event => {
    if (!state.loaded) {
        showFatal(event.error || new Error(event.message || 'Unknown JavaScript error.'));
    }
});

window.addEventListener('unhandledrejection', event => {
    if (!state.loaded) {
        const reason = event.reason;
        showFatal(
            reason instanceof Error
                ? reason
                : new Error(typeof reason === 'string' ? reason : JSON.stringify(reason))
        );
    }
});

async function loadJson(
    path,
    description,
    timeoutMs = 0
) {
    updateBootLoadingStatus('Loading Zoo Curator...', description);

    const controller =
        typeof AbortController !== 'undefined' ? new AbortController() : null;
    let timeoutId = null;

    const fullRequest = (async () => {
        const response = await fetch(
            path,
            controller
                ? { signal: controller.signal, cache: 'default' }
                : { cache: 'default' }
        );

        if (!response.ok) {
            throw new Error(`Could not load ${path}. HTTP ${response.status}.`);
        }

        try {
            return await response.json();
        } catch (error) {
            if (error?.name === 'AbortError') throw error;
            throw new Error(
                `${path} was found but could not be read as JSON: ${error.message}`
            );
        }
    })();

    const timedRequest = timeoutMs > 0
        ? Promise.race([
            fullRequest,
            new Promise((_, reject) => {
                timeoutId = setTimeout(() => {
                    if (controller) controller.abort();
                    reject(new Error(
                        `${path} did not finish loading within ${Math.round(timeoutMs / 1000)} seconds.`
                    ));
                }, timeoutMs);
            })
        ])
        : fullRequest;

    try {
        return await timedRequest;
    } catch (error) {
        if (error?.name === 'AbortError') {
            throw new Error(
                `${path} did not finish loading within ${Math.round(timeoutMs / 1000)} seconds.`
            );
        }
        throw error;
    } finally {
        if (timeoutId !== null) clearTimeout(timeoutId);
    }
}

function loadOptionalJsonInBackground(path, timeoutMs = 8000) {
    const controller =
        typeof AbortController !== 'undefined' ? new AbortController() : null;
    let timeoutId = null;

    const fullRequest = (async () => {
        const response = await fetch(
            path,
            controller
                ? { signal: controller.signal, cache: 'default' }
                : { cache: 'default' }
        );
        if (!response.ok) {
            throw new Error(`Could not load ${path}. HTTP ${response.status}.`);
        }
        return await response.json();
    })();

    const timeout = new Promise((_, reject) => {
        timeoutId = setTimeout(() => {
            controller?.abort();
            reject(new Error(
                `${path} did not finish loading within ${Math.round(timeoutMs / 1000)} seconds.`
            ));
        }, timeoutMs);
    });

    return Promise.race([fullRequest, timeout]).finally(() => {
        if (timeoutId !== null) clearTimeout(timeoutId);
    });
}

function normaliseRealZooRecords(rawZoos) {
    if (Array.isArray(rawZoos)) {
        return rawZoos
            .filter(record => record && typeof record === 'object')
            .map(({ tier: _obsoleteTier, ...record }) => record);
    }
    if (!rawZoos || typeof rawZoos !== 'object') return [];

    const records = [];
    for (const [country, provinces] of Object.entries(rawZoos)) {
        if (!provinces || typeof provinces !== 'object' || Array.isArray(provinces)) continue;
        for (const [province, tiers] of Object.entries(provinces)) {
            if (!tiers || typeof tiers !== 'object' || Array.isArray(tiers)) continue;
            for (const tierRecords of Object.values(tiers)) {
                if (!Array.isArray(tierRecords)) continue;
                for (const rawRecord of tierRecords) {
                    if (!rawRecord || typeof rawRecord !== 'object') continue;
                    const { tier: _obsoleteTier, ...record } = rawRecord;
                    records.push({
                        ...record,
                        country: rawRecord.country || country,
                        province: rawRecord.province || province
                    });
                }
            }
        }
    }
    return records;
}

function rebuildRealZooStaticIdMap() {
    state.realZooRecordByStaticId = new Map();
    for (const record of state.realZooData?.zoos || []) {
        const id = Number(record?.trade_id);
        if (Number.isFinite(id)) state.realZooRecordByStaticId.set(id, record);
    }
}

function loadRealZooDataInBackground() {
    const path = 'real_zoo_opponents.json';
    const timeoutMs = 8000;

    const request = fetch(path, { cache: 'default' })
        .then(response => {
            if (!response.ok) {
                throw new Error(
                    `Could not load ${path}. HTTP ${response.status}.`
                );
            }
            return response.json();
        });

    let timeoutId = null;
    const timeout = new Promise((_, reject) => {
        timeoutId = setTimeout(
            () => reject(
                new Error(
                    `${path} did not finish loading within ${Math.round(timeoutMs / 1000)} seconds.`
                )
            ),
            timeoutMs
        );
    });

    Promise.race([request, timeout])
        .then(data => {
            if (timeoutId !== null) clearTimeout(timeoutId);
            const zoos = normaliseRealZooRecords(data?.zoos);
            if (!data || !zoos.length) {
                throw new Error(`${path} does not contain any valid zoo records.`);
            }

            state.realZooData = { ...data, zoos };
            state.realZooDataLoadState = 'loading-prestige';
            const embeddedTradeIndex = data?.trade_index;
            state.realZooTradeIndex = (
                embeddedTradeIndex?.schema_version === 1 &&
                embeddedTradeIndex?.candidates_by_outgoing &&
                typeof embeddedTradeIndex.candidates_by_outgoing === 'object'
            ) ? embeddedTradeIndex : null;
            resetRealZooSessionHoldings();
            if(pendingPortableRealZooHoldings){
                const pending=pendingPortableRealZooHoldings;
                pendingPortableRealZooHoldings=null;
                state.realZooSessionHoldings=decodePortableRealZooSessionHoldings(pending);
            }
            rebuildRealZooStaticIdMap();
            loadPregeneratedRealZooLayouts().then(() => {
                state.realZooDataLoadState = 'ready';
                state.tradeOfferCache.clear();
                const newZooOverlay = document.getElementById('generateZooOverlay');
                if (newZooOverlay?._refreshRealZooChoices) newZooOverlay._refreshRealZooChoices();
                const directoryOverlay=document.getElementById('realZooDirectoryOverlay');
                if(directoryOverlay?.style.display==='flex') renderRealZooDirectory();
                if (tradeEligibleGlowActive || state.outgoingOfferTradeHoverActive) {
                    enqueueMicrotask(applyTradeEligibleGlow);
                }
                if (state.loaded && isRealOpponentMode()) renderOpponentTradeState();
                renderAll?.();
            });

        })
        .catch(error => {
            if (timeoutId !== null) clearTimeout(timeoutId);
            console.warn(
                'Real zoo opponent database unavailable; game continues without it:',
                error
            );
            state.realZooData = { zoos: [] };
            state.realZooDataLoadState = 'failed';
            state.realZooTradeIndex = null;
            state.realZooRecordByStaticId = new Map();
            state.realZooSessionHoldings = new Map();
        });
}

function loadProvinceConnectionsInBackground() {
    const path = 'province_connections.json';
    fetch(path, { cache: 'default' })
        .then(response => {
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            return response.json();
        })
        .then(data => {
            if (!data?.provinces || typeof data.provinces !== 'object') {
                throw new Error('No provinces object found.');
            }
            state.provinceConnections = data;
            state.provinceDistanceCache = new Map();
            state.tradeOfferCache.clear();
        })
        .catch(error => {
            console.warn(
                'Province connection database unavailable; using country-level trade distance:',
                error
            );
            state.provinceConnections = { provinces: {} };
            state.provinceDistanceCache = new Map();
        });
}

function getCategorySource(category) {

    if (!state.inventory) {
        return null;
    }

    category=canonicalAnimalCategory(category);
    const folder =
        getFolder(category);

    if (state.inventory.animals) {

        if (
            state.inventory.animals[
                category
            ]
        ) {

            return state.inventory.animals[
                category
            ];

        }

        if (
            state.inventory.animals[
                folder
            ]
        ) {

            return state.inventory.animals[
                folder
            ];

        }

    }

    if (state.inventory[category]) {
        return state.inventory[category];
    }

    if (state.inventory[folder]) {
        return state.inventory[folder];
    }

    return null;

}

function inventoryFilenames(filenames) {
    return filenames || [];
}

const LEVEL_FILES_CACHE=new Map();
function levelFilesUncached(
    category,
    level
) {

    const source =
        getCategorySource(category);

    if (!source) {
        return [];
    }

    if (
        !Array.isArray(source) &&
        typeof source === 'object'
    ) {

        const possible = [

            source[level],

            source[
                String(level)
            ],

            source[
                `Level ${level}`
            ],

            source[
                `level${level}`
            ]

        ];

        for (
            const candidate
            of possible
        ) {

            if (
                candidate &&
                !Array.isArray(candidate) &&
                typeof candidate === 'object'
            ) {
                return inventoryFilenames(Object.keys(candidate)
                        .map(cleanFilename)
                        .filter(Boolean)
                        .filter(filename => !/^back\.png$/i.test(filename))
                );
            }

            if (
                Array.isArray(candidate)
            ) {

                return inventoryFilenames(candidate

                    .map(item => {

                        if (
                            typeof item ===
                            'string'
                        ) {

                            return cleanFilename(
                                item
                            );

                        }

                        if (
                            item &&
                            typeof item ===
                            'object'
                        ) {

                            return cleanFilename(
                                item.file ??
                                item.filename ??
                                item.path ??
                                item.name ??
                                ''
                            );

                        }

                        return '';

                    })

                    .filter(Boolean)

                    .filter(
                        filename =>
                            !/^back\.png$/i.test(
                                filename
                            )
                    )
                );

            }

        }

    }

    if (Array.isArray(source)) {

        return inventoryFilenames(source

            .filter(item => {

                if (
                    typeof item ===
                    'string'
                ) {
                    return true;
                }

                const itemLevel =
                    Number(
                        item?.level ??
                        item?.Level ??
                        item?.tier ??
                        item?.Tier
                    );

                return (
                    itemLevel ===
                    Number(level)
                );

            })

            .map(item => {

                if (
                    typeof item ===
                    'string'
                ) {

                    return cleanFilename(
                        item
                    );

                }

                return cleanFilename(
                    item.file ??
                    item.filename ??
                    item.path ??
                    item.name ??
                    ''
                );

            })

            .filter(Boolean)

            .filter(
                filename =>
                    !/^back\.png$/i.test(
                        filename
                    )
            )
        );

    }

    return [];

}

function levelFiles(category,level){
    category=canonicalAnimalCategory(category);
    const key=`${category}\u001f${Number(level)}`;
    const cached=LEVEL_FILES_CACHE.get(key);
    if(cached)return cached;
    const files=Object.freeze(levelFilesUncached(category,level).slice());
    LEVEL_FILES_CACHE.set(key,files);
    return files;
}

function levelInventoryEntry(category, level) {
    const source = getCategorySource(category);
    if (!source || Array.isArray(source) || typeof source !== 'object') return null;
    return source[level] ?? source[String(level)] ?? source[`Level ${level}`] ?? source[`level${level}`] ?? null;
}

function animalInventoryTags(category, level, filename) {
    const entry = levelInventoryEntry(category, level);
    if (!entry || Array.isArray(entry) || typeof entry !== 'object') return [];
    const wanted = cleanFilename(filename).toLowerCase();
    const key = Object.keys(entry).find(item => cleanFilename(item).toLowerCase() === wanted);
    const value = key ? entry[key] : null;
    const tags = Array.isArray(value) ? value : (Array.isArray(value?.tags) ? value.tags : []);
    return tags.map(tag => String(tag).trim().toLowerCase()).filter(Boolean);
}

const TRUE_POPULATION_PROFILE_TEMPLATES={
    solitary:{structures:[{weight:1,males:[0,1],females:[0,1],total:[1,1],management:'solitary'}]},
    pair:{structures:[{weight:1,males:[1,1],females:[1,1],total:[2,2],management:'pair'}]},
    breeding_group:{structures:[{weight:1,males:[1,3],females:[1,5],total:[3,8],management:'breeding_group'}]},
    bachelor_group:{structures:[{weight:1,males:[2,8],females:[0,0],total:[2,8],management:'bachelor_group'}]},
    female_group:{structures:[{weight:1,males:[0,0],females:[2,8],total:[2,8],management:'female_group'}]},
    harem:{structures:[{weight:1,males:[1,1],females:[2,8],total:[3,9],management:'harem'}]}
};
const TRUE_POPULATION_STRUCTURAL_PROFILES=new Set(Object.keys(TRUE_POPULATION_PROFILE_TEMPLATES));
const TRUE_POPULATION_PROFILE_ALIASES={
    family_group:'breeding_group',small_breeding_group:'breeding_group',multi_male_group:'breeding_group',multi_female_group:'breeding_group',
    herd:'breeding_group',flock:'breeding_group',colony:'breeding_group',school:'breeding_group'
};
function trueNormalisePopulationProfileName(value){
    const raw=String(value||'').trim().toLowerCase().replace(/[\s-]+/g,'_');
    return TRUE_POPULATION_PROFILE_ALIASES[raw]||raw;
}
function truePopulationStructuresForProfiles(names=[]){
    const unique=[...new Set((names||[]).map(trueNormalisePopulationProfileName).filter(Boolean))];
    const large=unique.includes('large_group');
    const structures=[];
    for(const name of unique){
        if(!TRUE_POPULATION_STRUCTURAL_PROFILES.has(name))continue;
        const template=TRUE_POPULATION_PROFILE_TEMPLATES[name];
        for(const source of template.structures||[]){
            const row={...source,management:source.management||name,profileName:name};
            if(large){
                if(name==='breeding_group'){row.males=[1,8];row.females=[1,16];row.total=[3,24];}
                else if(name==='harem'){row.males=[1,1];row.females=[2,23];row.total=[3,24];}
                else if(name==='bachelor_group'){row.males=[2,24];row.females=[0,0];row.total=[2,24];}
                else if(name==='female_group'){row.males=[0,0];row.females=[2,24];row.total=[2,24];}
                row.largeGroup=true;
            }
            structures.push(row);
        }
    }
    return {profiles:unique,largeGroup:large,structures};
}
function truePopulationInventoryEntry(animal){
    if(!animal||!state.inventory)return null;
    const category=animal.category,level=Number(animal.level)||1,filename=cleanFilename(animal.filename||'');
    const source=getCategorySource(category);
    if(source&&!Array.isArray(source)&&typeof source==='object'){
        const bucket=source[level]||source[String(level)]||source[`Level ${level}`]||source[`level${level}`];
        if(bucket&&!Array.isArray(bucket)&&typeof bucket==='object'){
            const raw=bucket[filename]??bucket[animal.filename]??null;
            if(raw&&typeof raw==='object'&&!Array.isArray(raw))return raw;
        }
    }
    const maps=[state.inventory.population_profiles,state.inventory.populationProfiles,state.inventory.species_population_profiles];
    for(const map of maps){
        if(!map||typeof map!=='object')continue;
        const raw=map[filename]||map[String(filename).replace(/\.png$/i,'')]||map[animalCardKey(animal)];
        if(raw)return raw;
    }
    return null;
}
function truePopulationProfile(animal){
    const entry=truePopulationInventoryEntry(animal);
    const listed=Array.isArray(entry?.population_profiles)?entry.population_profiles
        :Array.isArray(entry?.populationProfiles)?entry.populationProfiles:null;
    if(listed?.length){
        const built=truePopulationStructuresForProfiles(listed);
        if(built.structures.length){
            const first=built.profiles.find(name=>TRUE_POPULATION_STRUCTURAL_PROFILES.has(name))||'pair';
            return {template:first,profiles:built.profiles,structures:built.structures,largeGroup:built.largeGroup,management:null,fallback:false};
        }
    }

    let raw=entry?.population_profile??entry?.populationProfile??null;
    if(!raw&&entry?.social_type)raw=entry;
    if(typeof raw==='string')raw={template:raw};
    if(!raw||typeof raw!=='object')return {template:'pair',profiles:['pair'],structures:TRUE_POPULATION_PROFILE_TEMPLATES.pair.structures,largeGroup:false,management:'pair',fallback:true};
    const legacyTemplate=String(raw.template||raw.social_type||raw.socialType||'pair').trim().toLowerCase().replace(/[\s-]+/g,'_');
    const template=trueNormalisePopulationProfileName(legacyTemplate);
    const largeGroup=['herd','flock','colony','school'].includes(legacyTemplate)||raw.large_group===true||raw.largeGroup===true;
    const built=truePopulationStructuresForProfiles([template,...(largeGroup?['large_group']:[])]);
    return {...raw,template:TRUE_POPULATION_STRUCTURAL_PROFILES.has(template)?template:'pair',profiles:built.profiles.length?built.profiles:['pair'],structures:built.structures.length?built.structures:TRUE_POPULATION_PROFILE_TEMPLATES.pair.structures,largeGroup,management:trueNormalisePopulationProfileName(raw.management||raw.default_management||template),fallback:false};
}
function truePopulationRangeValue(range,roll,min=0){
    if(Number.isFinite(Number(range)))return Math.max(min,Math.round(Number(range)));
    if(!Array.isArray(range)||!range.length)return min;
    const lo=Math.max(min,Math.round(Number(range[0])||0)),hi=Math.max(lo,Math.round(Number(range[1]??range[0])||lo));
    return lo+Math.floor(Math.max(0,Math.min(.999999,roll))*(hi-lo+1));
}
function trueGeneratedPopulation(animal,seed='',options={}){
    const profile=truePopulationProfile(animal),template=TRUE_POPULATION_PROFILE_TEMPLATES[profile.template]||TRUE_POPULATION_PROFILE_TEMPLATES.pair;
    const structures=Array.isArray(profile.structures)&&profile.structures.length?profile.structures:template.structures;
    let totalWeight=structures.reduce((sum,x)=>sum+Math.max(0,Number(x.weight)||1),0);
    let pick=seededRoll(`population-structure|${seed}|${animalCardKey(animal)}`).roll*totalWeight,structure=structures[0]||{};
    for(const row of structures){pick-=Math.max(0,Number(row.weight)||1);if(pick<=0){structure=row;break;}}
    const males=truePopulationRangeValue(structure.males??profile.males,seededRoll(`population-males|${seed}|${animalCardKey(animal)}`).roll,0);
    const females=truePopulationRangeValue(structure.females??profile.females,seededRoll(`population-females|${seed}|${animalCardKey(animal)}`).roll,0);
    let unknown=truePopulationRangeValue(structure.unknown??profile.unknown,seededRoll(`population-unknown|${seed}|${animalCardKey(animal)}`).roll,0);
    let m=males,f=females;
    const totalRange=structure.total??profile.total;
    if(Array.isArray(totalRange)){
        const target=truePopulationRangeValue(totalRange,seededRoll(`population-total|${seed}|${animalCardKey(animal)}`).roll,1);
        while(m+f+unknown>target){if(f>m&&f>0)f--;else if(m>0)m--;else if(unknown>0)unknown--;else break;}
        while(m+f+unknown<target)unknown++;
    }
    if(m+f+unknown<=0)unknown=1;
    return {population:{males:m,females:f,unknown},management:structure.management||profile.management||profile.template,profile};
}
function trueApplyGeneratedPopulation(animal,seed='',options={}){
    if(!animal)return animal;
    const generated=trueGeneratedPopulation(animal,seed,options);
    animal.population={...generated.population};
    animal.truePopulationManagement=generated.management||null;
    return animal;
}

function truePopulationStructureTotalRange(structure={},profile={}){
    const explicit=structure.total??profile.total;
    if(Number.isFinite(Number(explicit)))return [Math.max(1,Math.round(Number(explicit))),Math.max(1,Math.round(Number(explicit)))];
    if(Array.isArray(explicit)&&explicit.length){
        const lo=Math.max(1,Math.round(Number(explicit[0])||1)),hi=Math.max(lo,Math.round(Number(explicit[1]??explicit[0])||lo));
        return [lo,hi];
    }
    const bounds=key=>{
        const raw=structure[key]??profile[key];
        if(Number.isFinite(Number(raw))){const n=Math.max(0,Math.round(Number(raw)));return [n,n];}
        if(Array.isArray(raw)&&raw.length){const lo=Math.max(0,Math.round(Number(raw[0])||0)),hi=Math.max(lo,Math.round(Number(raw[1]??raw[0])||lo));return [lo,hi];}
        return [0,0];
    };
    const m=bounds('males'),f=bounds('females'),u=bounds('unknown'),o=bounds('offspring');
    return [Math.max(1,m[0]+f[0]+u[0]),Math.max(1,m[1]+f[1]+u[1]+o[1])];
}

function truePopulationStructureBounds(structure={},profile={},key){
    const raw=structure[key]??profile[key];
    if(Number.isFinite(Number(raw))){const n=Math.max(0,Math.round(Number(raw)));return [n,n];}
    if(Array.isArray(raw)&&raw.length){const lo=Math.max(0,Math.round(Number(raw[0])||0)),hi=Math.max(lo,Math.round(Number(raw[1]??raw[0])||lo));return [lo,hi];}
    return [0,Infinity];
}
function truePopulationGroupSizeStatus(animal){
    const p=normaliseTrueAnimalPopulation(animal),total=Math.max(0,p.males+p.females+p.unknown);
    const profile=truePopulationProfile(animal),template=TRUE_POPULATION_PROFILE_TEMPLATES[profile.template]||TRUE_POPULATION_PROFILE_TEMPLATES.pair;
    const structures=Array.isArray(profile.structures)&&profile.structures.length?profile.structures:template.structures;
    const rows=structures.map(structure=>{
        const totalRange=truePopulationStructureTotalRange(structure,profile);
        const male=truePopulationStructureBounds(structure,profile,'males');
        const female=truePopulationStructureBounds(structure,profile,'females');
        const unknown=truePopulationStructureBounds(structure,profile,'unknown');
        const totalValid=total>=totalRange[0]&&total<=totalRange[1];
        const maleDeficit=Math.max(0,male[0]-p.males),femaleDeficit=Math.max(0,female[0]-p.females);
        const sexMinimumValid=maleDeficit+femaleDeficit<=p.unknown;
        const maleMaxValid=!Number.isFinite(male[1])||p.males<=male[1];
        const femaleMaxValid=!Number.isFinite(female[1])||p.females<=female[1];
        const sexValid=sexMinimumValid&&maleMaxValid&&femaleMaxValid;
        return {structure,totalRange,male,female,unknown,totalValid,sexValid,valid:totalValid&&sexValid};
    });
    const ranges=rows.map(r=>r.totalRange),valid=rows.some(r=>r.valid);
    const totalValid=rows.some(r=>r.totalValid),sexValid=rows.some(r=>r.sexValid&&r.totalValid);
    const min=Math.min(...ranges.map(r=>r[0])),max=Math.max(...ranges.map(r=>r[1]));
    return {total,min,max,valid,tooSmall:total<min,tooLarge:total>max,structureMismatch:totalValid&&!sexValid,ranges,structures:rows,population:p};
}

function trueKnownSexLegalPopulation(animal,seed=''){
    const profile=truePopulationProfile(animal),template=TRUE_POPULATION_PROFILE_TEMPLATES[profile.template]||TRUE_POPULATION_PROFILE_TEMPLATES.pair;
    const structures=Array.isArray(profile.structures)&&profile.structures.length?profile.structures:template.structures;
    const ordered=[...structures].sort((a,b)=>
        seededRoll(`starter-structure|${seed}|${JSON.stringify(a)}`).roll-
        seededRoll(`starter-structure|${seed}|${JSON.stringify(b)}`).roll);
    for(const structure of ordered){
        const totalRange=truePopulationStructureTotalRange(structure,profile);
        const male=truePopulationStructureBounds(structure,profile,'males');
        const female=truePopulationStructureBounds(structure,profile,'females');
        const lo=Math.max(1,totalRange[0]),hi=Math.min(totalRange[1],Math.max(lo,12));
        const totals=[...Array(Math.max(1,hi-lo+1)).keys()].map(i=>lo+i).sort((a,b)=>
            seededRoll(`starter-total|${seed}|${a}`).roll-seededRoll(`starter-total|${seed}|${b}`).roll);
        for(const total of totals){
            const mLo=Math.max(0,male[0],total-(Number.isFinite(female[1])?female[1]:total));
            const mHi=Math.min(total,Number.isFinite(male[1])?male[1]:total,total-female[0]);
            if(mLo>mHi)continue;
            const span=mHi-mLo+1;
            const m=mLo+Math.floor(seededRoll(`starter-sex|${seed}|${total}`).roll*span);
            const population={males:m,females:total-m,unknown:0};
            const probe={...animal,population};
            if(truePopulationGroupSizeStatus(probe).valid)return population;
        }
    }
    for(let total=1;total<=20;total++)for(let m=0;m<=total;m++){
        const population={males:m,females:total-m,unknown:0};
        if(truePopulationGroupSizeStatus({...animal,population}).valid)return population;
    }
    return {males:1,females:1,unknown:0};
}

function trueOpeningDuplicatePopulationSplit(publicAnimal,backstageAnimal,seed=''){
    if(!publicAnimal||!backstageAnimal)return false;
    const flip=seededRoll(`duplicate-pair-sex|${seed}|${animalCardKey(publicAnimal)}`).roll<.5;
    const publicPop=flip
        ? {males:1,females:0,unknown:0}
        : {males:0,females:1,unknown:0};
    const backstage=flip
        ? {males:0,females:1,unknown:0}
        : {males:1,females:0,unknown:0};
    const preferred={males:1,females:1,unknown:0};
    publicAnimal.population=publicPop;
    backstageAnimal.population=backstage;
    publicAnimal.trueTutorialPreferredPopulation={...preferred};
    backstageAnimal.trueTutorialPreferredPopulation={...preferred};
    publicAnimal.trueTutorialMissingPopulation={...backstage};
    backstageAnimal.trueTutorialCompletesPublicGroup=true;
    backstageAnimal.trueTutorialSeparatedPair=true;
    return true;
}

function truePopulationStructureLabel(name){
    return ({
        solitary:'Solitary',pair:'Pair',breeding_group:'Breeding group',
        bachelor_group:'Bachelor group',female_group:'Female group',harem:'Harem',
        large_group:'Large group'
    })[String(name||'').toLowerCase()]||String(name||'Managed group').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
}
function truePopulationCurrentStructure(animal){
    const status=truePopulationGroupSizeStatus(animal);
    const valid=status.structures.find(r=>r.valid)||null;
    if(valid){
        const name=valid.structure?.profileName||valid.structure?.management||truePopulationProfile(animal).template;
        return {valid:true,name,label:truePopulationStructureLabel(name),row:valid,status};
    }
    return {valid:false,name:null,label:status.tooSmall?'Group too small':status.tooLarge?'Group too large':'Composition mismatch',row:null,status};
}
function truePopulationHusbandrySummary(animal){
    const condition=trueHusbandryConditionForAnimal(animal);
    const structure=truePopulationCurrentStructure(animal);
    const baseline=trueAnimalMinimumEnclosureCells(animal);
    const shared=condition.enclosureSpace?.mixed?' · mixed exhibit':'';
    const driver=condition.enclosureSpace?.driver;
    const drivenBy=condition.enclosureSpace?.mixed&&driver&&driver.key!==animalCardKey(animal)?` · requirement set by ${animalDisplayName(driver.animals[0])}`:'';
    const ownRequired=trueAnimalManagedEnclosureCells(animal);
    const displayRequired=condition.enclosureSpace?.mixed&&driver&&driver.key!==animalCardKey(animal)
        ?condition.required
        :ownRequired;
    let combinedWant='';
    if(condition.enclosureSpace?.mixed){
        const residents=condition.enclosureSpace.residents||[];
        let combinationCells=Math.max(1,residents.length);
        while(combinationCells<64&&!enclosureAnimalSizeSpaceStatus(combinationCells,residents).valid)combinationCells++;
        const combinedRequired=Math.max(Number(condition.enclosureSpace.required)||1,combinationCells);
        combinedWant=` · ${combinedRequired} combined recommended`;
    }
    const space=condition.cells==null?'No built enclosure':`${condition.cells} cells · ${displayRequired} recommended${displayRequired>baseline?` (${baseline} species baseline)`:''}${combinedWant}${shared}${drivenBy}`;
    const profile=truePopulationProfile(animal);
    const preferred=[...new Set((profile.profiles?.length?profile.profiles:[profile.template]).filter(Boolean).map(truePopulationStructureLabel))];
    const composition=structure.valid?structure.label:structure.label;
    const pop=normaliseTrueAnimalPopulation(animal),total=(pop?.males||0)+(pop?.females||0)+(pop?.unknown||0);
    const populationText=pop?.unknown>0?`${total} animals (${pop.males} male, ${pop.females} female, ${pop.unknown} unknown)`:`${total} animals`;
    return `${space} · Population: ${populationText} · Current group: ${composition} · Preferred: ${preferred.join(', ')||'Managed group'}`;
}

