    'africa':        { title: 'African Area',        className: 'theme-africa',        layer: 'geography' },
    'asia':          { title: 'Asian Area',          className: 'theme-asia',          layer: 'geography' },
    'europe':        { title: 'European Area',       className: 'theme-europe',        layer: 'geography' },
