function getGroups(enclosure) {

    if (enclosure?.trueBuilt) {
        const count=Math.max(1,Array.isArray(enclosure.cells)?enclosure.cells.length:Number(enclosure.capacity)||1);
        return [Array.from({length:count},(_,i)=>i)];
    }

    return (
        GROUPS[
            enclosure.number
        ] ||
        [[0]]
    );

}

function getAllSlots(enclosure) {
    if(!enclosure?.trueBuilt)return classicRenderSlots(enclosure);
    return getGroups(enclosure).flat();
}

const CLASSIC_ENCLOSURE_GROUP_CACHE = new Map();
const CLASSIC_ENCLOSURE_SLOT_CACHE = new Map();

function classicRenderGroups(enclosure) {
    if (enclosure?.trueBuilt) return getGroups(enclosure);
    const number=Number(enclosure?.number);
    let groups=CLASSIC_ENCLOSURE_GROUP_CACHE.get(number);
    if(!groups){
        groups=GROUPS[number] || [[0]];
        CLASSIC_ENCLOSURE_GROUP_CACHE.set(number,groups);
    }
    return groups;
}

function classicRenderSlots(enclosure, groups = null) {
    if (enclosure?.trueBuilt) return (groups || getGroups(enclosure)).flat();
    const number=Number(enclosure?.number);
    let slots=CLASSIC_ENCLOSURE_SLOT_CACHE.get(number);
    if(!slots){
        slots=(groups || classicRenderGroups(enclosure)).flat();
        CLASSIC_ENCLOSURE_SLOT_CACHE.set(number,slots);
    }
    return slots;
}

function enclosureSlotCapacity(
    enclosureNumber
) {

    return (
        GROUPS[
            enclosureNumber
        ] ||
        [[0]]
    ).flat().length;

}

function reserveAnimalZooSlot(animal, enclosureId, slotIndex) {
    invalidateClassicOccupancyCache();
    if (!animal || enclosureId == null || slotIndex == null) return;
    animal.reservedEnclosureId = enclosureId;
    animal.reservedSlotIndex = slotIndex;
}
function clearAnimalZooReservation(animal) {
    invalidateClassicOccupancyCache();
    if (!animal) return;
    delete animal.reservedEnclosureId;
    delete animal.reservedSlotIndex;
}

function hasPendingPlayerAction() {
    return state.exchange.some(Boolean) || Boolean(state.result) || Boolean(state.outgoingOffer);
}
function releaseOutgoingTradeReservation() {
    if (state.outgoingOffer) clearAnimalZooReservation(state.outgoingOffer);
}
function clearOrphanedZooSlotReservations(){
    const legitimate=new Set();
    if(state.outgoingOffer?.id!=null)legitimate.add(String(state.outgoingOffer.id));
    for(const animal of (state.exchange||[])){
        if(animal?.id!=null)legitimate.add(String(animal.id));
    }
    if(state.drag?.type==='animal'&&state.drag?.animal?.id!=null)
        legitimate.add(String(state.drag.animal.id));
    let changed=false;
    for(const animal of (state.animals||[])){
        if(animal?.reservedEnclosureId==null&&animal?.reservedSlotIndex==null)continue;
        if(legitimate.has(String(animal.id)))continue;
        clearAnimalZooReservation(animal);
        changed=true;
    }
    return changed;
}

let classicOccupancyCacheAnimals=null;
let classicOccupancyCacheRevision=-1;
let classicOccupancyRevision=0;
let classicOccupancyBySlot=new Map();
let classicReservedOccupancyBySlot=new Map();
let classicOccupancyByEnclosure=new Map();
let classicReservedOccupancyByEnclosure=new Map();
let classicReservedOccupancyCount=0;
function invalidateClassicOccupancyCache(){classicOccupancyRevision++;}
function ensureClassicOccupancyCache(){
    if(classicOccupancyCacheAnimals===state.animals&&classicOccupancyCacheRevision===classicOccupancyRevision)return;
    classicOccupancyCacheAnimals=state.animals;classicOccupancyCacheRevision=classicOccupancyRevision;
    classicOccupancyBySlot=new Map();classicReservedOccupancyBySlot=new Map();
    classicOccupancyByEnclosure=new Map();classicReservedOccupancyByEnclosure=new Map();
    classicReservedOccupancyCount=0;
    const add=(slotMap,enclosureMap,enclosureId,slotIndex,animal)=>{
        const key=`${enclosureId}:${slotIndex}`;
        let list=slotMap.get(key);if(!list){list=[];slotMap.set(key,list);}list.push(animal);
        const enclosureKey=String(enclosureId);
        let bySlot=enclosureMap.get(enclosureKey);if(!bySlot){bySlot=new Map();enclosureMap.set(enclosureKey,bySlot);}
        let slotList=bySlot.get(Number(slotIndex));if(!slotList){slotList=[];bySlot.set(Number(slotIndex),slotList);}slotList.push(animal);
    };
    for(const animal of state.animals||[]){
        if(animal?.enclosureId!=null&&animal?.slotIndex!=null){
            add(classicOccupancyBySlot,classicOccupancyByEnclosure,animal.enclosureId,animal.slotIndex,animal);
        }
        if(animal?.reservedEnclosureId!=null&&animal?.reservedSlotIndex!=null){
            add(classicReservedOccupancyBySlot,classicReservedOccupancyByEnclosure,animal.reservedEnclosureId,animal.reservedSlotIndex,animal);
            classicReservedOccupancyCount++;
        }
    }
}
function animalAtSlot(
    enclosureId,
    slotIndex,
    ignoreAnimalId = null,
    includeReserved = true
) {

    ensureClassicOccupancyCache();
    const key=`${enclosureId}:${slotIndex}`;
    const direct=classicOccupancyBySlot.get(key)||[];
    const found=direct.find(animal=>animal.id!==ignoreAnimalId);
    if(found||!includeReserved)return found;
    return (classicReservedOccupancyBySlot.get(key)||[]).find(animal=>animal.id!==ignoreAnimalId);

}

function compatibilityName(value) {
    return String(value || '')
        .replace(/\.[^.]+$/, '')
        .replace(/[’‘]/g, "'")
        .replace(/[_-]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
}

function compatibilityAnimalName(animal) {
    return compatibilityName(animalDisplayName(animal));
}

function graphAddEdge(graph, a, b) {
    a = compatibilityName(a);
    b = compatibilityName(b);
    if (!a || !b || a === b) return;

    if (!graph.has(a)) graph.set(a, new Set());
    if (!graph.has(b)) graph.set(b, new Set());

    graph.get(a).add(b);
    graph.get(b).add(a);
}

function rebuildCompatibilityGraphs() {
    const direct = new Map();

    for (const pairEntry of state.compatibilityData?.compatible_pairs || []) {
        const pair = Array.isArray(pairEntry)
            ? pairEntry
            : (Array.isArray(pairEntry?.animals) ? pairEntry.animals : pairEntry?.pair);
        if (!Array.isArray(pair) || pair.length < 2) continue;
        graphAddEdge(direct, pair[0], pair[1]);
    }

    state.compatibilityDirectGraph = direct;

    const effective = new Map();
    for (const [name, neighbours] of direct.entries()) {
        effective.set(name, new Set(neighbours));
    }

    const proxy = state.compatibilityData?.proxy_compatibility;

    const namedGroups = proxy?.groups && typeof proxy.groups === 'object'
        ? proxy.groups
        : {};

    const normalisedGroupMembers = groupName =>
        (Array.isArray(namedGroups[groupName]) ? namedGroups[groupName] : [])
            .map(compatibilityName)
            .filter(Boolean);

    for (const groupName of proxy?.complete_groups || []) {
        const members = normalisedGroupMembers(groupName);
        for (let i = 0; i < members.length; i++) {
            for (let j = i + 1; j < members.length; j++) {
                graphAddEdge(effective, members[i], members[j]);
            }
        }
    }

    for (const link of proxy?.group_links || []) {
        if (!link || typeof link !== 'object') continue;
        const fromMembers = normalisedGroupMembers(link.from);
        const toMembers = normalisedGroupMembers(link.to);

        const exactPartnerInheritance =
            String(link.to || '').endsWith('_shared_partner_pool') ||
            link.mode === 'shared_partner_inheritance';

        if (exactPartnerInheritance) {
            for (const partner of toMembers) {
                const hasDocumentedAnchor = fromMembers.some(sourceMember =>
                    direct.get(sourceMember)?.has(partner)
                );
                if (!hasDocumentedAnchor) continue;
                for (const sourceMember of fromMembers) {
                    graphAddEdge(effective, sourceMember, partner);
                }
            }
            continue;
        }

        for (const fromName of fromMembers) {
            for (const toName of toMembers) {
                graphAddEdge(effective, fromName, toName);
            }
        }
    }

    state.compatibilityEffectiveGraph = effective;
}

let compatibilityPairCacheGraph=null;
let compatibilityPairCache=new Map();
function clearCompatibilityPairCacheIfNeeded(){
    if(compatibilityPairCacheGraph!==state.compatibilityEffectiveGraph){
        compatibilityPairCacheGraph=state.compatibilityEffectiveGraph;
        compatibilityPairCache=new Map();
    }
}
const EMPTY_COMPATIBILITY_GROUP_SET=new Set();
let compatibilityProxyMembershipGraph=null;
let compatibilityProxyMembershipCache={groupsByAnimal:new Map(),completeGroups:new Set()};
function compatibilityProxyMembership(){
    if(compatibilityProxyMembershipGraph===state.compatibilityEffectiveGraph)return compatibilityProxyMembershipCache;
    const proxy=state.compatibilityData?.proxy_compatibility;
    const groupsByAnimal=new Map();
    for(const [groupName,members] of Object.entries(proxy?.groups||{})){
        if(!Array.isArray(members))continue;
        for(const member of members){
            const name=compatibilityName(member);if(!name)continue;
            let groups=groupsByAnimal.get(name);if(!groups){groups=new Set();groupsByAnimal.set(name,groups);}
            groups.add(String(groupName));
        }
    }
    compatibilityProxyMembershipCache={
        groupsByAnimal,
        completeGroups:new Set((proxy?.complete_groups||[]).map(String))
    };
    compatibilityProxyMembershipGraph=state.compatibilityEffectiveGraph;
    return compatibilityProxyMembershipCache;
}
function animalsAreCompatibleUncached(a, b) {
    if (!a || !b) return false;

    const aName = compatibilityAnimalName(a);
    const bName = compatibilityAnimalName(b);

    if (aName && aName === bName) return true;
    if (!aName || !bName) return false;

    if (state.compatibilityEffectiveGraph.get(aName)?.has(bName)) return true;

    const proxy = state.compatibilityData?.proxy_compatibility;
    if (!proxy?.enabled || !proxy.groups || typeof proxy.groups !== 'object') {
        return false;
    }

    const membership=compatibilityProxyMembership();
    const aGroups=membership.groupsByAnimal.get(aName)||EMPTY_COMPATIBILITY_GROUP_SET;
    const bGroups=membership.groupsByAnimal.get(bName)||EMPTY_COMPATIBILITY_GROUP_SET;
    const completeGroups=membership.completeGroups;

    for (const groupName of aGroups) {
        if (bGroups.has(groupName) && completeGroups.has(groupName)) {
            return true;
        }
    }

    for (const link of Array.isArray(proxy.group_links) ? proxy.group_links : []) {
        if (!link || typeof link !== 'object') continue;
        const from = String(link.from || '');
        const to = String(link.to || '');
        if (!from || !to) continue;

        const forward = aGroups.has(from) && bGroups.has(to);
        const reverse = aGroups.has(to) && bGroups.has(from);
        if (!forward && !reverse) continue;

        const exactPartnerInheritance =
            to.endsWith('_shared_partner_pool') ||
            link.mode === 'shared_partner_inheritance';

        if (exactPartnerInheritance) {
            const sourceMembers = (proxy.groups[from] || []).map(compatibilityName);
            const exactPartner = forward ? bName : aName;
            if (sourceMembers.some(sourceMember =>
                state.compatibilityDirectGraph.get(sourceMember)?.has(exactPartner)
            )) {
                return true;
            }
            continue;
        }

        return true;
    }

    return false;
}


function animalsAreCompatible(a,b){
    if(!a||!b)return false;
    clearCompatibilityPairCacheIfNeeded();
    const aName=compatibilityAnimalName(a),bName=compatibilityAnimalName(b);
    if(!aName||!bName)return false;
    const key=aName<bName?`${aName}\u001f${bName}`:`${bName}\u001f${aName}`;
    if(compatibilityPairCache.has(key))return compatibilityPairCache.get(key);
    const result=animalsAreCompatibleUncached(a,b);
    compatibilityPairCache.set(key,result);
    return result;
}

const CLASSIC_SLOT_GROUP_CACHE=new Map();
function enclosureGroupForSlot(enclosure, slotIndex) {
    if(!enclosure)return null;
    if(enclosure.trueBuilt)return getGroups(enclosure).find(group=>group.includes(slotIndex))||null;
    const number=Number(enclosure.number);
    let slotMap=CLASSIC_SLOT_GROUP_CACHE.get(number);
    if(!slotMap){
        slotMap=new Map();
        for(const group of classicRenderGroups(enclosure))
            for(const slot of group)slotMap.set(Number(slot),group);
        CLASSIC_SLOT_GROUP_CACHE.set(number,slotMap);
    }
    return slotMap.get(Number(slotIndex))||null;
}

function classicMoveStaysInSameLogicalExhibit(drag, animal) {
    if(
        state.gameMode==='true' ||
        state.sandboxMode ||
        drag?.type!=='animal' ||
        drag.originalEnclosureId==null ||
        animal?.enclosureId==null ||
        String(drag.originalEnclosureId)!==String(animal.enclosureId)
    ) return false;
    const enclosure=enclosureByIdFast(animal.enclosureId);
    if(!enclosure)return false;
    const fromGroup=enclosureGroupForSlot(enclosure,Number(drag.originalSlotIndex));
    const toGroup=enclosureGroupForSlot(enclosure,Number(animal.slotIndex));
    return !!fromGroup&&fromGroup===toGroup;
}

function animalsInEnclosureGroup(enclosure, group, ignoreAnimalId = null, includeReserved = true) {
    if (!enclosure || !group) return [];

    ensureClassicOccupancyCache();
    const result=[],seen=new Set();
    for(const slotIndex of group){
        const key=`${enclosure.id}:${slotIndex}`;
        for(const animal of classicOccupancyBySlot.get(key)||[]){
            if(animal.id===ignoreAnimalId||seen.has(animal.id))continue;
            seen.add(animal.id);result.push(animal);
        }
        if(includeReserved)for(const animal of classicReservedOccupancyBySlot.get(key)||[]){
            if(animal.id===ignoreAnimalId||seen.has(animal.id))continue;
            seen.add(animal.id);result.push(animal);
        }
    }
    return result;
}

function animalsFormCompatibilityChain(animals) {
    if (animals.length <= 1) return true;

    for (let i = 0; i < animals.length; i++) {
        for (let j = i + 1; j < animals.length; j++) {
            if (!animalsAreCompatible(animals[i], animals[j])) {
                return false;
            }
        }
    }

    return true;
}

function compatibilityAllowsPlacement(animal, enclosure, slotIndex) {
    if (state.gameOptions?.enforceAnimalCombinations === false) return true;
    const group = enclosureGroupForSlot(enclosure, slotIndex);
    if (!group) return false;

    if (group.length <= 1) return true;

    const occupants = animalsInEnclosureGroup(enclosure, group, animal.id, false);

    if (occupants.length === 0) return true;

    return animalsFormCompatibilityChain([...occupants, animal]);
}

function slotCompatibilityGlowKey(enclosureId, slotIndex) {
    return `${enclosureId}:${slotIndex}`;
}

function compatibilityHintAnimals() {
    if (state.drag?.type === 'animal') return [state.drag.animal];

    if (state.compatibilityIntentActiveAnimal) {
        return [state.compatibilityIntentActiveAnimal];
    }

    return [];
}

let enclosureByIdCacheArray=null,enclosureByIdCacheLength=-1,enclosureByIdCache=new Map();
function enclosureByIdFast(id){
    const list=state.enclosures||[];
    if(enclosureByIdCacheArray!==list||enclosureByIdCacheLength!==list.length){
        enclosureByIdCache=new Map(list.filter(Boolean).map(enclosure=>[String(enclosure.id),enclosure]));
        enclosureByIdCacheArray=list;enclosureByIdCacheLength=list.length;
    }
    return enclosureByIdCache.get(String(id))||null;
}
function animalIsSatisfiedInCombinationExhibit(animal) {
    if (!animal || animal.enclosureId === null || animal.enclosureId === undefined) {
        return false;
    }

    const enclosure = enclosureByIdFast(animal.enclosureId);
    if (!enclosure) return false;

    const group = enclosureGroupForSlot(enclosure, animal.slotIndex);
    if (!group || group.length <= 1) return false;

    const animalName = compatibilityAnimalName(animal);
    const partners = animalsInEnclosureGroup(enclosure, group, animal.id, false);

    return partners.some(partner =>
        compatibilityAnimalName(partner) !== animalName &&
        animalsAreCompatible(animal, partner)
    );
}

function slotIsCompatibilityMatch(enclosure, slotIndex, candidateAnimals = compatibilityHintAnimals()) {
    if (animalAtSlot(enclosure.id, slotIndex)) return false;

    const group = enclosureGroupForSlot(enclosure, slotIndex);
    if (!group || group.length <= 1) return false;

    const occupants = animalsInEnclosureGroup(enclosure, group);
    if (occupants.length === 0) return false; // not "available due to a match"

    return candidateAnimals.some(animal => {
        if (animal?.enclosureId !== null && animal?.enclosureId !== undefined &&
            animal.enclosureId === enclosure.id) {
            return false;
        }

        const candidateName = compatibilityAnimalName(animal);

        const hasDifferentSpeciesOccupant = occupants.some(
            occupant => compatibilityAnimalName(occupant) !== candidateName
        );

        if (!hasDifferentSpeciesOccupant) return false;

        return compatibilityAllowsPlacement(animal, enclosure, slotIndex);
    });
}

const EMPTY_COMPATIBILITY_GLOW_KEYS=new Set();
function currentCompatibilityGlowKeys(candidateAnimals = compatibilityHintAnimals()) {
    if(visitingAnotherZooForActionUI()||trueLayoutToolEditingActive()||!candidateAnimals.length)
        return EMPTY_COMPATIBILITY_GLOW_KEYS;
    const keys=new Set();
    const activeIntent=(!state.drag&&state.compatibilityIntentActiveAnimal)||null;
    const candidates=activeIntent&&animalIsSatisfiedInCombinationExhibit(activeIntent)
        ? candidateAnimals.filter(animal=>animal?.id!==activeIntent.id)
        : candidateAnimals;
    if(!candidates.length)return keys;

    for (const enclosure of state.enclosures) {
        for (const slotIndex of getAllSlots(enclosure)) {
            if (slotIsCompatibilityMatch(enclosure, slotIndex, candidates)) {
                keys.add(slotCompatibilityGlowKey(enclosure.id, slotIndex));
            }
        }
    }

    return keys;
}

function applyCompatibilityDestinationGlowClasses() {
    if(trueDecorationToolActive){
        state.compatibilityGlowKeys=new Set();state.compatibilityGlowFadeKeys=new Set();
        state.compatibilityGlowHoldUntil=0;state.compatibilityGlowFadeUntil=0;
        document.querySelectorAll('.compatibility-match-glow,.compatibility-match-glow-fading').forEach(el=>el.classList.remove('compatibility-match-glow','compatibility-match-glow-fading'));
        return;
    }
    const now = Date.now();
    const activeKeys = currentCompatibilityGlowKeys();

    classicDropDomElements().slots.forEach(slot => {
        const key = slotCompatibilityGlowKey(
            Number(slot.dataset.enclosureId),
            Number(slot.dataset.slotIndex)
        );

        slot.classList.remove(
            'compatibility-match-glow',
            'compatibility-match-glow-fading'
        );

        if (activeKeys.has(key)) {
            slot.classList.add('compatibility-match-glow');
        } else if (
            state.compatibilityGlowFadeKeys.has(key) &&
            now < state.compatibilityGlowHoldUntil
        ) {
            slot.classList.add('compatibility-match-glow');
        } else if (
            state.compatibilityGlowFadeKeys.has(key) &&
            now < state.compatibilityGlowFadeUntil
        ) {
            slot.classList.add('compatibility-match-glow-fading');
        }
    });
}

function beginCompatibilityGlowFade(keys) {
    state.compatibilityGlowFadeKeys = new Set(keys || []);

    if (!state.compatibilityGlowFadeKeys.size) {
        state.compatibilityGlowHoldUntil = 0;
        state.compatibilityGlowFadeUntil = 0;
        return;
    }

    const now = Date.now();

    state.compatibilityGlowHoldUntil = now;
    state.compatibilityGlowFadeUntil = now + 1000;

    applyCompatibilityDestinationGlowClasses();

    setTimeout(() => {
        if (Date.now() >= state.compatibilityGlowFadeUntil) {
            state.compatibilityGlowFadeKeys.clear();
            state.compatibilityGlowHoldUntil = 0;
            state.compatibilityGlowFadeUntil = 0;
            applyCompatibilityDestinationGlowClasses();
        }
    }, 1020);
}

function compatibilityCandidatesForHoveredSlot(enclosure, slotIndex) {
    if (visitingAnotherZooForActionUI()) return [];
    if (!enclosure || animalAtSlot(enclosure.id, slotIndex)) return [];

    const group = enclosureGroupForSlot(enclosure, slotIndex);
    if (!group || group.length <= 1) return [];

    const occupants = animalsInEnclosureGroup(enclosure, group);
    if (occupants.length === 0) return [];

    return state.animals.filter(animal => {
        if (occupants.some(occupant => occupant.id === animal.id)) return false;

        const candidateName = compatibilityAnimalName(animal);
        const hasDifferentSpeciesOccupant = occupants.some(
            occupant => compatibilityAnimalName(occupant) !== candidateName
        );
        if (!hasDifferentSpeciesOccupant) return false;

        return compatibilityAllowsPlacement(animal, enclosure, slotIndex);
    });
}

function applyCompatibilityAnimalHoverClasses() {
    const now = Date.now();
    const active = state.compatibilityAnimalHoverIds || new Set();

    classicDropDomElements().animalCards.forEach(card => {
        const id = Number(card.dataset.animalId);
        card.classList.remove(
            'compatibility-animal-match',
            'compatibility-animal-match-fading'
        );
        card.style.removeProperty('--compatibility-animal-fade-delay');

        if (!active.has(id)) return;

        if (now < state.compatibilityAnimalHoverHoldUntil) {
            card.classList.add('compatibility-animal-match');
            return;
        }

        if (now < state.compatibilityAnimalHoverFadeUntil) {
            card.classList.add('compatibility-animal-match-fading');
            const fadeElapsed = Math.max(
                0,
                now - state.compatibilityAnimalHoverHoldUntil
            );
            card.style.animationDelay = `${-Math.min(fadeElapsed, 1000)}ms`;
        }
    });

    refreshAnimalGlowPrecedence();
}

function applyCompatibilityHoveredSlotClasses() {
    const now = Date.now();

    classicDropDomElements().slots.forEach(slot => {
        slot.classList.remove(
            'compatibility-hover-slot-match',
            'compatibility-hover-slot-match-fading'
        );
        slot.style.removeProperty('--compatibility-hover-slot-fade-delay');

        const key = slotCompatibilityGlowKey(
            Number(slot.dataset.enclosureId),
            Number(slot.dataset.slotIndex)
        );

        if (!state.compatibilityHoveredSlotKey || key !== state.compatibilityHoveredSlotKey) {
            return;
        }

        if (!state.compatibilityAnimalHoverIds?.size) return;

        if (now < state.compatibilityHoveredSlotHoldUntil) {
            slot.classList.add('compatibility-hover-slot-match');
            return;
        }

        if (now < state.compatibilityHoveredSlotFadeUntil) {
            slot.classList.add('compatibility-hover-slot-match-fading');
            const fadeElapsed = Math.max(
                0,
                now - state.compatibilityHoveredSlotHoldUntil
            );
            slot.style.animationDelay = `${-Math.min(fadeElapsed, 1000)}ms`;
        }
    });
}

function clearCompatibilityHoverImmediately() {
    if (state.compatibilityAnimalHoverTimer) {
        clearTimeout(state.compatibilityAnimalHoverTimer);
        state.compatibilityAnimalHoverTimer = null;
    }
    if (state.compatibilityHoveredSlotTimer) {
        clearTimeout(state.compatibilityHoveredSlotTimer);
        state.compatibilityHoveredSlotTimer = null;
    }

    state.compatibilityAnimalHoverIds = new Set();
    state.compatibilityAnimalHoverHoldUntil = 0;
    state.compatibilityAnimalHoverFadeUntil = 0;
    state.compatibilityHoveredSlotKey = null;
    state.compatibilityHoveredSlotHoldUntil = 0;
    state.compatibilityHoveredSlotFadeUntil = 0;

    applyCompatibilityAnimalHoverClasses();
    applyCompatibilityHoveredSlotClasses();
}

function startCompatibilityAnimalHover(enclosure, slotIndex) {
    if(trueDecorationToolActive){clearCompatibilityHoverImmediately();return;}
    if (visitingAnotherZooForActionUI() || document.body.classList.contains('history-viewing')) return;

    if (state.drag?.type === 'animal') {
        clearCompatibilityHoverImmediately();
        return;
    }

    const candidates = compatibilityCandidatesForHoveredSlot(
        enclosure,
        slotIndex
    );

    if (state.compatibilityAnimalHoverTimer) {
        clearTimeout(state.compatibilityAnimalHoverTimer);
        state.compatibilityAnimalHoverTimer = null;
    }
    if (state.compatibilityHoveredSlotTimer) {
        clearTimeout(state.compatibilityHoveredSlotTimer);
        state.compatibilityHoveredSlotTimer = null;
    }

    state.compatibilityAnimalHoverIds = new Set(
        candidates.map(animal => animal.id)
    );
    state.compatibilityAnimalHoverHoldUntil = Number.POSITIVE_INFINITY;
    state.compatibilityAnimalHoverFadeUntil = Number.POSITIVE_INFINITY;

    state.compatibilityHoveredSlotKey = candidates.length
        ? slotCompatibilityGlowKey(enclosure.id, slotIndex)
        : null;
    state.compatibilityHoveredSlotHoldUntil = candidates.length
        ? Number.POSITIVE_INFINITY
        : 0;
    state.compatibilityHoveredSlotFadeUntil = candidates.length
        ? Number.POSITIVE_INFINITY
        : 0;

    applyCompatibilityAnimalHoverClasses();
    applyCompatibilityHoveredSlotClasses();
}

function finishCompatibilityAnimalHover() {
    if (!state.compatibilityAnimalHoverIds?.size) {
        clearCompatibilityHoverImmediately();
        return;
    }

    const now = Date.now();

    state.compatibilityAnimalHoverHoldUntil = now;
    state.compatibilityAnimalHoverFadeUntil = now + 1000;
    state.compatibilityHoveredSlotHoldUntil = now;
    state.compatibilityHoveredSlotFadeUntil = now + 1000;

    applyCompatibilityAnimalHoverClasses();
    applyCompatibilityHoveredSlotClasses();

    if (state.compatibilityAnimalHoverTimer) {
        clearTimeout(state.compatibilityAnimalHoverTimer);
    }

    state.compatibilityAnimalHoverTimer = setTimeout(() => {
        clearCompatibilityHoverImmediately();
    }, 1020);
}

function canPlace(
    animal,
    enclosure,
    slotIndex
) {

    if (
        !animal ||
        !enclosure
    ) {
        return false;
    }

    if (
        !state.sandboxMode &&
        enclosure.number === 10 &&
        !state.enclosure10Unlocked &&
        !level4IsInZoo()
    ) {
        return false;
    }

    if (
        !getAllSlots(enclosure)
            .includes(slotIndex)
    ) {
        return false;
    }

    if (
        animalAtSlot(
            enclosure.id,
            slotIndex,
            animal.id,
            false
        )
    ) {
        return false;
    }

    if (state.sandboxMode) return true;

    return compatibilityAllowsPlacement(
        animal,
        enclosure,
        slotIndex
    );

}

function canPlaceStartingAnimal(animal, enclosure, slotIndex) {
    if (!canPlace(animal, enclosure, slotIndex)) return false;

    const group = enclosureGroupForSlot(enclosure, slotIndex);
    if (!group) return true;

    const occupants = animalsInEnclosureGroup(enclosure, group);

    if (group.length <= 1) return occupants.length === 0;

    return true;
}

function hasSafeLevelOneDrawSpace() {
    ensureClassicOccupancyCache();
    const enclosure10NeedsLevel4=!state.sandboxMode&&!state.enclosure10Unlocked;
    const hasLevel4=enclosure10NeedsLevel4?level4IsInZoo():false;
    return state.enclosures.some(enclosure => {
        if (enclosure.number===10&&enclosure10NeedsLevel4&&!hasLevel4) {
            return false;
        }
        const groups = GROUPS[enclosure.number] || [];
        const enclosureKey=String(enclosure.id);
        const occupied=classicOccupancyByEnclosure.get(enclosureKey);
        const reserved=classicReservedOccupancyByEnclosure.get(enclosureKey);

        for (const group of groups) {
            let blocked=false;
            for(const slot of group){
                if((occupied?.get(Number(slot))||[]).length||(reserved?.get(Number(slot))||[]).length){
                    blocked=true;break;
                }
            }
            if(!blocked)return true;
        }

        if (!groups.length) {
            return getAllSlots(enclosure).some(slotIndex =>
                !(occupied?.get(Number(slotIndex))||[]).length &&
                !(reserved?.get(Number(slotIndex))||[]).length
            );
        }
        return false;
    });
}

function eligibleDestinationsForAnimal(animal) {
    if (!animal) return [];

    const destinations = [];
    for (const enclosure of state.enclosures) {
        for (const slotIndex of getAllSlots(enclosure)) {
            if (canPlace(animal, enclosure, slotIndex)) {
                destinations.push({ enclosure, slotIndex });
            }
        }
    }
    return destinations;
}

function randomEligibleDestinationForAnimal(animal) {
    const destinations = eligibleDestinationsForAnimal(animal);
    return destinations.length ? randomItem(destinations) : null;
}

const classicTradeDestinationCache=new Map();
let classicTradeDestinationCacheRevision=-1;
function classicTradeDestinationRevision(){
    return `${classicOccupancyRevision}|${Number(state.areaPlacementRevision)||0}|${state.enclosures?.length||0}`;
}
function clearStaleClassicTradeDestinationCache(){
    const revision=classicTradeDestinationRevision();
    if(revision!==classicTradeDestinationCacheRevision){
        classicTradeDestinationCache.clear();
        classicTradeDestinationCacheRevision=revision;
    }
}
function tradeIncomingHasDestinationAfterOutgoing(incoming, outgoing) {
    if (!incoming || !outgoing) return false;
    clearStaleClassicTradeDestinationCache();
    const cacheKey=`${outgoing.id}|${animalCardKey(incoming)}|${outgoing.enclosureId??''}|${outgoing.slotIndex??''}|${outgoing.reservedEnclosureId??''}|${outgoing.reservedSlotIndex??''}`;
    if(classicTradeDestinationCache.has(cacheKey))return classicTradeDestinationCache.get(cacheKey);

    const oldEnclosureId = outgoing.enclosureId;
    const oldSlotIndex = outgoing.slotIndex;
    const oldReservedEnclosureId = outgoing.reservedEnclosureId;
    const oldReservedSlotIndex = outgoing.reservedSlotIndex;

    let result=false;
    try {
        outgoing.enclosureId = null;
        outgoing.slotIndex = null;
        clearAnimalZooReservation(outgoing);
        invalidateClassicOccupancyCache();
        outer:for(const enclosure of state.enclosures||[]){
            for(const slotIndex of getAllSlots(enclosure)){
                if(canPlace(incoming,enclosure,slotIndex)){result=true;break outer;}
            }
        }
    } finally {
        outgoing.enclosureId = oldEnclosureId;
        outgoing.slotIndex = oldSlotIndex;
        if (oldReservedEnclosureId != null && oldReservedSlotIndex != null) {
            reserveAnimalZooSlot(outgoing, oldReservedEnclosureId, oldReservedSlotIndex);
        }
        invalidateClassicOccupancyCache();
    }
    // Restoration itself increments occupancy revision, so cache against the resulting
    // stable layout revision rather than the transient revision from before the probe.
    clearStaleClassicTradeDestinationCache();
    const stableKey=`${outgoing.id}|${animalCardKey(incoming)}|${outgoing.enclosureId??''}|${outgoing.slotIndex??''}|${outgoing.reservedEnclosureId??''}|${outgoing.reservedSlotIndex??''}`;
    classicTradeDestinationCache.set(stableKey,result);
    return result;
}

function nextLevelOneHasEligibleDestination() {
    if (state.nextDrawSpec && !levelOneSpecStillDrawable(state.nextDrawSpec)) {
        state.nextDrawSpec = null;
        state.nextDrawReadyPromise = null;
    }

    if (!state.nextDrawSpec) {
        const used=playerOwnedCardKeys();
        let drawable=false;
        for(const category of Object.keys(FOLDERS)){
            if(!state.activeCategories.has(category))continue;
            for(const filename of levelFiles(category,1)){
                if(!used.has(animalCardKey(category,1,filename))){drawable=true;break;}
            }
            if(drawable)break;
        }
        if(!drawable)return false;
    }

    if (!hasSafeLevelOneDrawSpace()) return false;

    if (state.nextDrawSpec) {
        ensureClassicOccupancyCache();
        for(const enclosure of state.enclosures)for(const slotIndex of getAllSlots(enclosure)){
            if(!canPlace(state.nextDrawSpec,enclosure,slotIndex))continue;
            const group=enclosureGroupForSlot(enclosure,slotIndex);
            if(!group)continue;
            let free=true;
            for(const groupSlot of group){
                const key=`${enclosure.id}:${groupSlot}`;
                if((classicReservedOccupancyBySlot.get(key)||[]).length||
                   (classicOccupancyBySlot.get(key)||[]).length){free=false;break;}
            }
            if(free)return true;
        }
        return false;
    }

    return true;
}

function markNewPlacementGlow(animal) {
    if (!animal) return;
    state.newPlacementGlowStartedAt[animal.id] = Date.now();

    setTimeout(() => {
        const started = Number(state.newPlacementGlowStartedAt[animal.id] || 0);
        if (started && Date.now() - started >= 4000) {
            delete state.newPlacementGlowStartedAt[animal.id];
            document.querySelectorAll(`.animal-card[data-animal-id="${animal.id}"]`)
                .forEach(card => {
                    card.classList.remove('new-placement-glow');
                    card.style.removeProperty('animation-delay');
                });
        }
    }, 4050);
}

function removeAnimalFromLocations(
    animal
) {
    invalidateExchangeGroupCounts();

    animal.enclosureId = null;
    animal.slotIndex = null;
    state.exchange =
        state.exchange.map(
            item =>
                item?.id ===
                animal.id
                    ? null
                    : item
        );

    if (state.outgoingOffer?.id === animal.id) {
        state.outgoingOffer = null;
        state.tradeOffers = [];
        state.selectedTradeOpponent = null;
    }

}

function placeAnimal(
    animal,
    enclosure,
    slotIndex
) {
    invalidateClassicOccupancyCache();

    const movingFromEnclosureId =
        animal?.enclosureId ?? animal?.reservedEnclosureId ?? null;
    const movingFromSlotIndex =
        animal?.slotIndex ?? animal?.reservedSlotIndex ?? null;
    ensureClassicOccupancyCache();
    const displacedReservationOwner=(classicReservedOccupancyBySlot.get(`${enclosure?.id}:${slotIndex}`)||[])
        .find(other=>other?.id!==animal?.id)||null;

    if (
        !canPlace(
            animal,
            enclosure,
            slotIndex
        )
    ) {
        return false;
    }

    normaliseTrueAnimalPopulation(animal);

    if (
        displacedReservationOwner &&
        movingFromEnclosureId !== null &&
        movingFromSlotIndex !== null
    ) {
        reserveAnimalZooSlot(
            displacedReservationOwner,
            movingFromEnclosureId,
            movingFromSlotIndex
        );
    }

    removeAnimalFromLocations(
        animal
    );

    animal.enclosureId =
        enclosure.id;

    animal.slotIndex =
        slotIndex;

    if(state.gameMode==='true'){delete animal.trueLoosePopulation;delete animal.x;delete animal.y;}
    clearAnimalZooReservation(animal);
    collectionMarkEnteredZoo(animal);
    if(state.gameMode==='true')updateCollectionCohabitation();

    checkEnclosure10Unlock();
    state.areaPlacementRevision = (Number(state.areaPlacementRevision) || 0) + 1;
    areaSignatureTaskCache=null;
    areaSignatureTaskShape='';
    invalidateClassicGeneratedGeography();
    releaseSuppressedAreasForNewSpecies();

    enqueueMicrotask(()=>refreshDrawAvailabilityState?.());
    return true;

}

function level4IsInZoo() {
    for(const animal of state.animals||[])
        if(animal&&animal.level>=4&&animal.enclosureId!==null)return true;
    return false;
}

function checkEnclosure10Unlock() {

    if (
        state.enclosure10Unlocked
    ) {
        return;
    }

    if (!level4IsInZoo()) {
        return;
    }

    state.enclosure10Unlocked =
        true;

}

function startupProgressionRewardKeys() {
    const present = new Set();

    for (const animal of state.animals) {
        if (!animal) continue;
        present.add(progressionKey(animal.category, animal.level));
    }

    const rewardKeys = [];
    for (let level = 2; level <= 5; level++) {
        let count = 0;
        for (const key of present) {
            const [, levelText] = key.split('|');
            if (Number(levelText) === level) count++;
        }

        for (const milestone of state.gameOptions.enclosureRewardMilestones) {
            if (count >= milestone) rewardKeys.push(`${level}|${milestone}`);
        }
    }

    return rewardKeys;
}

function startupLayoutStats(numbers) {
    return numbers.reduce((stats, number) => {
        stats.spots += enclosureSlotCapacity(number);
        stats.physical += (GROUPS[number] || [[0]]).length;
        return stats;
    }, { spots: 0, physical: 0 });
}

function chooseStartupEnclosures(rewardCount = 0) {
    const available = [1,2,3,4,5,6,7,8,9];
    const hugeEnclosureEligible = state.animals.some(animal => Number(animal?.level) >= 4);
    const HUGE_ENCLOSURE_GENERATION_CHANCE = 0.05;
    const collectionRules = startingCollectionSizeRules(state.gameOptions.startingCollectionSize);
    const zooRules = startingZooSizeRules(state.gameOptions.startingZooSize);
    const requiredAnimals = collectionRules.species;

    const targetSpots = zooRules.maxSpaces;

    const numbers = [];
    for (let i = 0; i < rewardCount; i++) {
        const useHuge = hugeEnclosureEligible && Math.random() < HUGE_ENCLOSURE_GENERATION_CHANCE;
        numbers.push(useHuge ? 10 : randomItem(available));
    }

    const stats = startupLayoutStats(numbers);
    const missingSpots = Math.max(0, targetSpots - stats.spots);

    const maxExtraSpots = Math.max(40, missingSpots + 12);
    const dp = Array(maxExtraSpots + 1).fill(null);
    dp[0] = [];

    for (let spots = 0; spots <= maxExtraSpots; spots++) {
        const current = dp[spots];
        if (!current) continue;

        for (const number of shuffle(available)) {
            const nextSpots = spots + enclosureSlotCapacity(number);
            if (nextSpots > maxExtraSpots) continue;
            const proposed = [...current, number];
            if (!dp[nextSpots] || proposed.length < dp[nextSpots].length) {
                dp[nextSpots] = proposed;
            }
        }
    }

    const candidates = [];
    for (let extraSpots = missingSpots; extraSpots <= maxExtraSpots; extraSpots++) {
        if (!dp[extraSpots]) continue;
        candidates.push({
            extra: dp[extraSpots],
            totalSpots: stats.spots + extraSpots,
            totalCards: numbers.length + dp[extraSpots].length
        });
    }

    function layoutSupportsGeneratedAnimalSizes(candidateNumbers) {
        const exhibitRanks = [];
        for (const number of candidateNumbers) {
            for (const group of (GROUPS[number] || [[0]])) {
                exhibitRanks.push(ENCLOSURE_SIZE_RANK[enclosureGroupSizeName(group)] || 1);
            }
        }
        exhibitRanks.sort((a,b)=>a-b);
        const needs = state.animals.map(animal => ENCLOSURE_SIZE_RANK[animalEnclosureSize(animal)] || 1).sort((a,b)=>b-a);
        const availableRanks = [...exhibitRanks];
        for (const need of needs) {
            const index = availableRanks.findIndex(rank => rank >= need);
            if (index < 0) return false;
            availableRanks.splice(index,1);
        }
        return true;
    }
    const sizeValidCandidates = candidates.filter(item => layoutSupportsGeneratedAnimalSizes([...numbers, ...item.extra]));
    if (sizeValidCandidates.length) {
        candidates.splice(0, candidates.length, ...sizeValidCandidates);
    }

    if (!candidates.length) {
        throw new Error(
            `Could not build a starting enclosure layout with about ${targetSpots} spaces.`
        );
    }

    const smallestCapacity = Math.min(...candidates.map(item => item.totalSpots));
    const capacityMatches = candidates.filter(item => item.totalSpots === smallestCapacity);
    const fewestCards = Math.min(...capacityMatches.map(item => item.totalCards));
    const best = capacityMatches.filter(item => item.totalCards === fewestCards);

    numbers.push(...randomItem(best).extra);

    let physical = startupLayoutStats(numbers).physical;
    while (physical < requiredAnimals) {
        let bestSwap = null;
        for (let i = 0; i < numbers.length; i++) {
            const oldNumber = numbers[i];
            const oldCapacity = enclosureSlotCapacity(oldNumber);
            const oldPhysical = (GROUPS[oldNumber] || [[0]]).length;
            for (const candidate of available) {
                if (enclosureSlotCapacity(candidate) !== oldCapacity) continue;
                const candidatePhysical = (GROUPS[candidate] || [[0]]).length;
                const gain = candidatePhysical - oldPhysical;
                if (gain <= 0) continue;
                if (!bestSwap || gain > bestSwap.gain) {
                    bestSwap = { index: i, number: candidate, gain };
                }
            }
        }
        if (!bestSwap) break;
        numbers[bestSwap.index] = bestSwap.number;
        physical += bestSwap.gain;
    }

    while (physical < requiredAnimals) {
        const maxYield = Math.max(...available.map(number =>
            (GROUPS[number] || [[0]]).length
        ));
        const choices = available.filter(number =>
            (GROUPS[number] || [[0]]).length === maxYield
        );
        const number = randomItem(choices);
        numbers.push(number);
        physical += (GROUPS[number] || [[0]]).length;
    }

    if (requiredAnimals >= 24) {
        physical = startupLayoutStats(numbers).physical;
        const byPhysicalYield = [...available].sort((a, b) =>
            (GROUPS[b] || [[0]]).length - (GROUPS[a] || [[0]]).length
        );
        while (physical < requiredAnimals) {
            const maxYield = (GROUPS[byPhysicalYield[0]] || [[0]]).length;
            const choices = byPhysicalYield.filter(number =>
                (GROUPS[number] || [[0]]).length === maxYield
            );
            const number = randomItem(choices);
            numbers.push(number);
            physical += (GROUPS[number] || [[0]]).length;
        }
    }

    return shuffle(numbers);
}

function rectanglesOverlap(
    a,
    b,
    gap = 0
) {

    return !(
        a.x + a.w + gap <= b.x ||
        b.x + b.w + gap <= a.x ||
        a.y + a.h + gap <= b.y ||
        b.y + b.h + gap <= a.y
    );

}

function connectedPosition(
    existing,
    occupied,
    gap = ENCLOSURE_GAP
) {

    const directions = shuffle([
        'right',
        'left',
        'bottom',
        'top'
    ]);

    for (const direction of directions) {

        let x = existing.x;
        let y = existing.y;

        if (direction === 'right') {
            x = existing.x + ENCLOSURE_W + gap;
        }
        else if (direction === 'left') {
            x = existing.x - ENCLOSURE_W - gap;
        }
        else if (direction === 'bottom') {
            y = existing.y + ENCLOSURE_H + gap;
        }
        else {
            y = existing.y - ENCLOSURE_H - gap;
        }

        if (
            x < 40 ||
            y < 40 ||
            x + ENCLOSURE_W > WORKSPACE_W - 40 ||
            y + ENCLOSURE_H > WORKSPACE_H - 40
        ) {
            continue;
        }

        const candidate = { x, y, w: ENCLOSURE_W, h: ENCLOSURE_H };

        const collides = occupied.some(item =>
            item.id !== existing.id &&
            rectanglesOverlap(
                candidate,
                { x: item.x, y: item.y, w: ENCLOSURE_W, h: ENCLOSURE_H },
                gap
            )
        );

        if (!collides) {
            return { x, y };
        }
    }

    return null;
}

function startupGridCoordinate(value, origin, step) {
    return Math.round((value - origin) / step);
}

function createsStartupThreeByThree(candidate, occupied) {
    const stepX = ENCLOSURE_W + ENCLOSURE_GAP;
    const stepY = ENCLOSURE_H + ENCLOSURE_GAP;
    const originX = STARTUP_CENTER_X - ENCLOSURE_W / 2;
    const originY = STARTUP_CENTER_Y;

    const cells = new Set();

    for (const item of [...occupied, candidate]) {
        const gx = startupGridCoordinate(item.x, originX, stepX);
        const gy = startupGridCoordinate(item.y, originY, stepY);
        cells.add(`${gx}|${gy}`);
    }

    const candidateGX = startupGridCoordinate(candidate.x, originX, stepX);
    const candidateGY = startupGridCoordinate(candidate.y, originY, stepY);

    for (let left = candidateGX - 2; left <= candidateGX; left++) {
        for (let top = candidateGY - 2; top <= candidateGY; top++) {
            let full = true;

            for (let dx = 0; dx < 3 && full; dx++) {
                for (let dy = 0; dy < 3; dy++) {
                    if (!cells.has(`${left + dx}|${top + dy}`)) {
                        full = false;
                        break;
                    }
                }
            }

            if (full) return true;
        }
    }

    return false;
}

function startupConnectedPosition(existing, occupied, gap = ENCLOSURE_GAP) {
    const directions = shuffle(['right', 'left', 'bottom', 'top']);

    for (const direction of directions) {
        let x = existing.x;
        let y = existing.y;

        if (direction === 'right') x = existing.x + ENCLOSURE_W + gap;
        else if (direction === 'left') x = existing.x - ENCLOSURE_W - gap;
        else if (direction === 'bottom') y = existing.y + ENCLOSURE_H + gap;
        else y = existing.y - ENCLOSURE_H - gap;

        if (
            x < 40 ||
            y < 40 ||
            x + ENCLOSURE_W > WORKSPACE_W - 40 ||
            y + ENCLOSURE_H > WORKSPACE_H - 40
        ) {
            continue;
        }

        const candidate = {
            x,
            y,
            w: ENCLOSURE_W,
            h: ENCLOSURE_H
        };

        const collides = occupied.some(item =>
            item.id !== existing.id &&
            rectanglesOverlap(
                candidate,
                {
                    x: item.x,
                    y: item.y,
                    w: ENCLOSURE_W,
                    h: ENCLOSURE_H
                },
                gap
            )
        );

        if (collides) continue;

        if (createsStartupThreeByThree(candidate, occupied)) {
            continue;
        }

        return { x, y };
    }

    return null;
}

function positionStartupEnclosures(numbers) {

    for (let buildAttempt = 0; buildAttempt < 300; buildAttempt++) {

        const positioned = [{
            id: state.nextId++,
            number: numbers[0],
            x: STARTUP_CENTER_X - ENCLOSURE_W / 2,
            y: STARTUP_CENTER_Y
        }];

        let failed = false;

        for (let i = 1; i < numbers.length; i++) {
            let position = null;

            const anchors = shuffle(positioned);
            for (const anchor of anchors) {
                position = startupConnectedPosition(
                    anchor,
                    positioned,
                    ENCLOSURE_GAP
                );
                if (position) break;
            }

            if (!position) {
                failed = true;
                break;
            }

            positioned.push({
                id: state.nextId++,
                number: numbers[i],
                x: position.x,
                y: position.y
            });
        }

        if (!failed) return positioned;
    }

    throw new Error('Could not arrange the starting enclosure cards without overlap.');
}

function startingCategoryHasLevel(category, level) {
    return state.animals.some(animal =>
        animal.category === category &&
        animal.level === level
    );
}

function availableStartingCardsAtLevel(level, allowDuplicateSpecies = trueModeAllowsDuplicateSpecies()) {
    const candidates = [];

    for (const category of Object.keys(FOLDERS)) {
        if (!state.activeCategories.has(category)) continue;

        if (
            level > 1 &&
            !startingCategoryHasLevel(category, level - 1)
        ) {
            continue;
        }

        const files = levelFiles(category, level).filter(file =>
            allowDuplicateSpecies ||
            !state.animals.some(animal =>
                animal.category === category &&
                animal.level === level &&
                animal.filename.toLowerCase() === file.toLowerCase()
            )
        );

        for (const filename of files) {
            candidates.push({ category, level, filename });
        }
    }

    return candidates;
}

function startingCollectionProgressionIsValid(animals = state.animals) {
    const levelsByCategory = new Map();
    for (const animal of animals || []) {
        if (!animal?.category || !Number.isFinite(Number(animal.level))) continue;
        if (!levelsByCategory.has(animal.category)) levelsByCategory.set(animal.category, new Set());
        levelsByCategory.get(animal.category).add(Number(animal.level));
    }

    for (const levels of levelsByCategory.values()) {
        for (const level of levels) {
            if (level > 1 && level <= 4 && !levels.has(level - 1)) return false;
        }
    }
    return true;
}

function randomAvailableStartingAnimal(levelChances, preferredCategories = null, options = {}) {
    const allowDuplicateSpecies = options.allowDuplicateSpecies === true;
    const roll = Math.random();
    let cumulative = 0;
    let rolledLevel = 1;

    for (let level = 1; level <= 4; level++) {
        cumulative += Number(levelChances[level] || 0);
        if (roll <= cumulative) {
            rolledLevel = level;
            break;
        }
    }

    const preferredSet = new Set(Array.isArray(preferredCategories) ? preferredCategories : []);

    if (preferredSet.size) {
        for (let level = rolledLevel; level >= 1; level--) {
            const preferred = availableStartingCardsAtLevel(level, allowDuplicateSpecies)
                .filter(candidate => preferredSet.has(candidate.category));
            if (preferred.length) {
                if (level === 1) return randomCardByEqualCategory(preferred);
                return weightedCardByEqualCategory(
                    preferred,
                    candidate => animalZooTypeWeight(candidate, state.zooType, 'generation')
                );
            }
        }
    }

    for (let level = rolledLevel; level >= 1; level--) {
        const candidates = availableStartingCardsAtLevel(level, allowDuplicateSpecies);
        if (candidates.length) {
            if (level === 1) return randomCardByEqualCategory(candidates);
            return weightedRandomItem(
                candidates,
                candidate => animalZooTypeWeight(candidate, state.zooType, 'generation')
            );
        }
    }

    const configuredCategories = Object.keys(FOLDERS);
    const enabledCategories = state.activeCategories instanceof Set
        ? configuredCategories.filter(category => state.activeCategories.has(category))
        : [];
    const fallbackCategories = enabledCategories.length ? enabledCategories : configuredCategories;
    const emergencyCandidates = [];
    for (const category of fallbackCategories) {
        for (const filename of levelFiles(category, 1)) {
            if (!allowDuplicateSpecies && state.animals.some(animal =>
                animal.category === category &&
                Number(animal.level) === 1 &&
                String(animal.filename || '').toLowerCase() === String(filename || '').toLowerCase()
            )) continue;
            emergencyCandidates.push({ category, level: 1, filename });
        }
    }
    if (emergencyCandidates.length) {
        console.warn('Starting-animal candidate pool unexpectedly emptied; using rebuilt Level 1 inventory pool.', {
            gameMode: state.gameMode,
            allowDuplicateSpecies,
            activeCategories: state.activeCategories instanceof Set ? [...state.activeCategories] : state.activeCategories,
            fallbackCandidateCount: emergencyCandidates.length
        });
        return randomCardByEqualCategory(emergencyCandidates);
    }

    throw new Error(`No legal starting animal cards remain (mode=${state.gameMode}, duplicates=${allowDuplicateSpecies}, activeCategories=${state.activeCategories instanceof Set ? state.activeCategories.size : 'invalid'}, inventory=${state.inventory ? 'loaded' : 'missing'}).`);
}

function createStartingZoo(options = {}) {
    lifetimeCollectionLastMergeSignature='';

    const requestedGameMode = ['classic', 'true'].includes(options.gameMode)
        ? options.gameMode
        : (state.gameMode === 'true' ? 'true' : 'classic');

    resetTransientStateForImport();
    clearTransientZooUIForSandbox();

    state.gameMode = requestedGameMode;
    state.zooColourScheme = 'overloon';
    applyZooColourScheme();
    if (!(state.activeCategories instanceof Set)) {
        state.activeCategories = new Set(Array.isArray(state.activeCategories) ? state.activeCategories : []);
    }
    if (!state.activeCategories.size) state.activeCategories = new Set(Object.keys(FOLDERS));
    state.sandboxMode = false;
    state.sandboxLooseAnimals = [];
    restoreNormalActionBoxesIfNeeded();
    state.enclosures = [];
    state.animals = [];
    state.trueEnclosureBuilder = {
        converted:false,
        geometryVersion:2,
        totalSpaces: 0,
        unlockedCellCapacity:0,
        cellCapacityInitialised:false,
        landExpansionLevel:0,
        landExpansionCredits:0,
        landExpansionMilestonesSeen:0,
        landExpansionInitialised:false,
        landExpansionLastPrestige:0,
        mode:'new',
        preset:'small',
        zooGrounds:null,
        zooGroundsVersion:2,
        zooEntrance:null
    };
    state.areaLabelPositions = new Map();
    state.customAreas = [];
    state.generatedAreaMembership = new Map();
    state.generatedAreaOverrides = new Map();
    state.suppressedGeneratedAreas = new Map();
    state.areaPlacementRevision = 0;
    state.areaDeleteUndo = null;

    state.exchange = [
        null,
        null
    ];

    state.result = null;
    state.outgoingOffer = null;
    state.trueProposalOutgoingOffers = [];
    state.tradeOffers = [];
    state.selectedTradeOpponent = null;
    state.opponentTradeStocks = [];
    state.opponentStockCycle = 0;
    state.autonomousTradeOffer = null;
    state.nextAutonomousOfferTurn = null;
    state.tradeHistory = [];
    state.animalLineage = new Map();
    state.collectionRecords = new Map();
    state.collectionCohabitationActive = new Map();
    state.collectionPlaythroughId = null;
    state.collectionActiveLevel = 1;
    state.unlockedOpponentCount = 2;
    state.playerLevelsSeen = new Set([1]);
    state.highestZooPrestige = 0;
    resetRealZooSessionHoldings();
    state.tradeOfferCache = new Map();
    state.nextDrawSpec = null;
    state.nextDrawReadyPromise = null;

    state.turn = 1;
    resetTrueCalendarSimulation();
    resetTurnHistory();

    state.trueEnclosureDecorations = [];
    state.truePlacedDecorations = [];
    trueDecorationDrag = null;
    trueDecorationUndoStack.length = 0;
    trueDecorationRedoStack.length = 0;
    document.getElementById('trueDecorationLayer')?.remove();
    document.getElementById('truePlacedDecorationLowLayer')?.remove();
    document.getElementById('truePlacedDecorationTreeLayer')?.remove();

    state.enclosure10Unlocked =
        false;

    state.enclosureRewards =
        new Set();

    state.glowingEnclosureIds =
        new Set();

    state.suppressedExchangeGlowIds = new Set();
    state.lastExchangeGroupCounts = new Map();
    state.previewHoveredAnimalId = null;
    if (state.previewHideTimer) clearTimeout(state.previewHideTimer);
    state.previewHideTimer = null;
    if (state.previewIntentTimer) clearTimeout(state.previewIntentTimer);
    state.previewIntentTimer = null;
    state.previewIntentAnimalId = null;
    state.discoveredCategoryLevels = new Set();
    state.acquiredLevel2Categories = new Set();
    state.awardedLevel2Milestones = new Set();
    state.awardedProgressMilestones = new Set();
    state.progressionGlowHoverKey = null;
    state.progressionGlowPinnedKeys = new Set();

    const startupRules = startingCollectionSizeRules(state.gameOptions.startingCollectionSize);
    if(requestedGameMode==='true'){
        startupRules.species=7;
        startupRules.maxSpaces=10;
    }
    const requireSingleStartingDuplicate = requestedGameMode === 'true';
    const allowDuplicateStartingSpecies = false;

    const specialistCategories = specialistStartingCategories();
    const specialistQuota = specialistStartingQuota(startupRules.species);
    let specialistCount = 0;

    let classicExchangeAnchorCards = [];
    if(requestedGameMode==='classic' && startupRules.species>=3){
        const levelOneByCategory=new Map();
        for(const candidate of availableStartingCardsAtLevel(1,false)){
            if(!hasNextLevelInventory(candidate.category,1))continue;
            if(!levelOneByCategory.has(candidate.category))
                levelOneByCategory.set(candidate.category,[]);
            levelOneByCategory.get(candidate.category).push(candidate);
        }
        let anchorCategories=[...levelOneByCategory.entries()]
            .filter(([,cards])=>cards.length>=3)
            .map(([category])=>category);
        if(specialistQuota>=3 && specialistCategories.length){
            const specialistAnchors=anchorCategories.filter(category=>
                specialistCategories.includes(category));
            if(specialistAnchors.length)anchorCategories=specialistAnchors;
        }
        if(anchorCategories.length){
            const anchorCategory=randomItem(anchorCategories);
            classicExchangeAnchorCards=shuffle(
                [...levelOneByCategory.get(anchorCategory)]
            ).slice(0,3);
        }else{
            console.warn('Classic startup could not find a category with three distinct Level 1 cards and a Level 2 Exchange result.');
        }
    }

    for (let i = 0; i < startupRules.species; i++) {
        const stillNeeded = Math.max(0, specialistQuota - specialistCount);
        const slotsRemaining = startupRules.species - i;
        const preferSpecialist = specialistCategories.length && stillNeeded > 0 &&
            (specialistCount < specialistQuota || slotsRemaining <= stillNeeded);
        let startingCard;
        let tutorialDuplicateSourceId=null;
        if(requireSingleStartingDuplicate && i===startupRules.species-1 && state.animals.length){
            const eligibleDuplicatePool=state.animals.filter(animal=>{
                const pairProbe={...animal,population:{males:1,females:1,unknown:0}};
                return truePopulationGroupSizeStatus(pairProbe).valid;
            });
            const specialistDuplicatePool=eligibleDuplicatePool.filter(animal=>
                !specialistCategories.length||specialistCategories.includes(animal.category)
            );
            const duplicatePool=specialistDuplicatePool.length?specialistDuplicatePool:eligibleDuplicatePool;
            const source=(duplicatePool.length?duplicatePool:state.animals)[Math.floor(Math.random()*(duplicatePool.length?duplicatePool:state.animals).length)];
            startingCard={category:source.category,level:source.level,filename:source.filename};
            tutorialDuplicateSourceId=source.id;
        }else if(classicExchangeAnchorCards[i]){
            startingCard=classicExchangeAnchorCards[i];
        }else{
            startingCard = randomAvailableStartingAnimal(
                startupRules.levelChances,
                preferSpecialist ? specialistCategories : null,
                { allowDuplicateSpecies: false }
            );
        }
        const animal = createAnimal(
            startingCard.category,
            startingCard.level,
            startingCard.filename
        );
        if(tutorialDuplicateSourceId!=null){
            animal.trueTutorialStartingDuplicate=true;
            animal.trueTutorialDuplicateOfId=tutorialDuplicateSourceId;
        }
        if(requestedGameMode==='classic' && i<classicExchangeAnchorCards.length)
            animal.classicStartingExchangeAnchor=true;
        state.animals.push(animal);
        if (specialistCategories.includes(animal.category)) specialistCount += 1;
        markPlayerLevelSeen(animal.level);
    }
    state.enclosure10Unlocked = state.animals.some(animal => Number(animal?.level) >= 4);

    const startupRewardKeys = startupProgressionRewardKeys();
    state.awardedProgressMilestones = new Set(startupRewardKeys);
    state.awardedLevel2Milestones = new Set(
        startupRewardKeys
            .map(key => String(key).split('|'))
            .filter(([levelText]) => Number(levelText) === 2)
            .map(([, milestoneText]) => Number(milestoneText))
    );

    const numbers = chooseStartupEnclosures(startupRewardKeys.length);

    state.enclosures = ensureGeneratedEnclosureRotations(positionStartupEnclosures(numbers));

    const startupEnclosures = [];

    for (
        const enclosure
        of state.enclosures
    ) {

        for (
            const group
            of getGroups(enclosure)
        ) {

            startupEnclosures.push({
                enclosure,
                group
            });

        }

    }

    function clearStartupPlacements() {
        for (const animal of state.animals) {
            animal.enclosureId = null;
            animal.slotIndex = null;
        }
    }

    const STARTUP_SEARCH_NODE_LIMIT = Math.max(2500, startupRules.species * 700);
    let startupSearchNodes = 0;

    function placeStartingCollectionBacktracking(animals, index = 0) {
        if (index >= animals.length) return true;
        if (++startupSearchNodes > STARTUP_SEARCH_NODE_LIMIT) return false;

        let bestIndex = index;
        let bestCandidates = null;

        for (let i = index; i < animals.length; i++) {
            const animal = animals[i];
            const candidates = [];

            for (const entry of startupEnclosures) {
                for (const slotIndex of entry.group) {
                    if (canPlaceStartingAnimal(animal, entry.enclosure, slotIndex)) {
                        candidates.push({ enclosure: entry.enclosure, slotIndex });
                    }
                }
            }

            const generationCandidates = sortGenerationDestinationsForAreas(
                animal,
                preferSizeAppropriateGenerationDestinations(animal, candidates)
            );
            if (bestCandidates === null || generationCandidates.length < bestCandidates.length) {
                bestCandidates = generationCandidates;
                bestIndex = i;
            }
            if (!candidates.length) break;
        }

        if (!bestCandidates?.length) return false;

        [animals[index], animals[bestIndex]] = [animals[bestIndex], animals[index]];
        const animal = animals[index];

        for (const destination of bestCandidates) {
            if (startupSearchNodes > STARTUP_SEARCH_NODE_LIMIT) break;

            animal.enclosureId = destination.enclosure.id;
            animal.slotIndex = destination.slotIndex;

            if (placeStartingCollectionBacktracking(animals, index + 1)) return true;

            animal.enclosureId = null;
            animal.slotIndex = null;
        }

        [animals[index], animals[bestIndex]] = [animals[bestIndex], animals[index]];
        return false;
    }

    let placed = false;

    const compatibilityPairsReady =
        Array.isArray(state.compatibilityData?.compatible_pairs) &&
        state.compatibilityData.compatible_pairs.length > 0;

    if (!compatibilityPairsReady && startupEnclosures.length >= state.animals.length) {
        clearStartupPlacements();
        const emptyDestinations = shuffle([...startupEnclosures]);

        for (let i = 0; i < state.animals.length; i++) {
            const entry = emptyDestinations[i];
            const slotIndex = entry.group[0];
            state.animals[i].enclosureId = entry.enclosure.id;
            state.animals[i].slotIndex = slotIndex;
        }
        placed = true;
    }

    function rebuildStartingLevelState() {
        state.playerLevelsSeen = new Set([1]);
        state.unlockedOpponentCount = 2;
        for (const animal of state.animals) {
            const level = Number(animal?.level);
            if (!Number.isFinite(level)) continue;
            state.playerLevelsSeen.add(level);
            if (level >= 2) {
                state.unlockedOpponentCount = Math.max(
                    state.unlockedOpponentCount,
                    Math.min(6, level + 1)
                );
            }
        }
    }

    const maxCollectionRepairs = Math.min(12, Math.max(4, startupRules.species));

    for (let attempt = 0; attempt <= maxCollectionRepairs && !placed; attempt++) {
        clearStartupPlacements();
        startupSearchNodes = 0;
        const ordered = shuffle([...state.animals]);
        placed = placeStartingCollectionBacktracking(ordered);

        if (placed) break;
        if (attempt === maxCollectionRepairs || !state.animals.length) break;

        const speciesKey=animal=>`${animal.category}|${Number(animal.level)||1}|${cleanFilename(animal.filename)}`;
        const speciesCounts=new Map();
        for(const animal of state.animals){const key=speciesKey(animal);speciesCounts.set(key,(speciesCounts.get(key)||0)+1);}
        const duplicateKeys=new Set([...speciesCounts.entries()].filter(([,count])=>count>1).map(([key])=>key));
        const repairableIndexes=state.animals.map((animal,index)=>({animal,index})).filter(({animal})=>
            (speciesCounts.get(speciesKey(animal))||0)===1 &&
            !duplicateKeys.has(speciesKey(animal)) &&
            !animal?.trueTutorialStartingDuplicate &&
            !animal?.classicStartingExchangeAnchor
        ).map(({index})=>index);
        if(!repairableIndexes.length)break;
        const replaceIndex = repairableIndexes[Math.floor(Math.random() * repairableIndexes.length)];
        const oldAnimal = state.animals[replaceIndex];
        state.animals.splice(replaceIndex, 1);

        const specialistCountAfterRemoval = state.animals.filter(animal =>
            specialistCategories.includes(animal.category)
        ).length;
        const repairPreferredCategories =
            specialistCategories.length && specialistCountAfterRemoval < specialistQuota
                ? specialistCategories
                : null;

        let replacement = null;
        try {
            const replacementCard = randomAvailableStartingAnimal(
                startupRules.levelChances,
                repairPreferredCategories,
                { allowDuplicateSpecies: false }
            );
            replacement = {
                id: state.nextId,
                category: replacementCard.category,
                level: replacementCard.level,
                filename: cleanFilename(replacementCard.filename),
                enclosureId: null,
                slotIndex: null
            };
            state.animals.splice(replaceIndex, 0, replacement);

            if (!startingCollectionProgressionIsValid(state.animals)) {
                throw new Error('Starting collection repair broke category progression.');
            }

            const repairedRewardKeys = startupProgressionRewardKeys();
            if (
                repairedRewardKeys.length !== startupRewardKeys.length ||
                repairedRewardKeys.some(key => !startupRewardKeys.includes(key))
            ) {
                throw new Error('Starting collection repair changed progression rewards.');
            }

            state.nextId += 1;
            ensureAnimalLineage(replacement, state.zooName || 'Your Zoo');
            removePlayerClaimedCardFromOpponents(
                replacement.category,
                replacement.level,
                replacement.filename
            );
            markPlayerLevelSeen(replacement.level);

            state.animalLineage.delete(oldAnimal.id);
        } catch (error) {
            if (replacement) {
                const insertedIndex = state.animals.findIndex(animal => animal.id === replacement.id);
                if (insertedIndex >= 0) state.animals.splice(insertedIndex, 1);
                state.animalLineage.delete(replacement.id);
            }
            if (!state.animals.some(animal => animal.id === oldAnimal.id)) {
                state.animals.splice(replaceIndex, 0, oldAnimal);
            }
        }
    }

    rebuildStartingLevelState();

    if (!placed) {
        clearStartupPlacements();
        let fallbackFailed = false;

        for (const animal of state.animals) {
            let destination = null;

            for (const entry of startupEnclosures) {
                if (animalsInEnclosureGroup(entry.enclosure, entry.group).length) continue;
                const slotIndex = entry.group.find(slot =>
                    !animalAtSlot(entry.enclosure.id, slot) &&
                    canPlaceStartingAnimal(animal, entry.enclosure, slot)
                );
                if (slotIndex !== undefined) {
                    destination = { enclosure: entry.enclosure, slotIndex };
                    break;
                }
            }

            if (!destination) {
                outer:
                for (const entry of startupEnclosures) {
                    for (const slotIndex of entry.group) {
                        if (canPlaceStartingAnimal(animal, entry.enclosure, slotIndex)) {
                            destination = { enclosure: entry.enclosure, slotIndex };
                            break outer;
                        }
                    }
                }
            }

            if (!destination) {
                fallbackFailed = true;
                break;
            }

            animal.enclosureId = destination.enclosure.id;
            animal.slotIndex = destination.slotIndex;
        }

        if (fallbackFailed) {
            const originalCount = state.animals.length;
            const fallbackCounts = [7, 6].filter(count => count < originalCount);

            for (const targetCount of fallbackCounts) {
                while (state.animals.length > targetCount) {
                    const targetSpecialistQuota = specialistStartingQuota(
                        targetCount,
                        state.zooType
                    );
                    const removableIndexes = [];

                    for (let index = 0; index < state.animals.length; index++) {
                        if(state.animals[index]?.classicStartingExchangeAnchor)continue;
                        const candidateAnimals = state.animals.filter((_, i) => i !== index);
                        if (!startingCollectionProgressionIsValid(candidateAnimals)) continue;

                        const candidateSpecialistCount = candidateAnimals.filter(animal =>
                            specialistCategories.includes(animal.category)
                        ).length;
                        if (candidateSpecialistCount < targetSpecialistQuota) continue;

                        const liveAnimals = state.animals;
                        state.animals = candidateAnimals;
                        const candidateRewardKeys = startupProgressionRewardKeys();
                        state.animals = liveAnimals;
                        if (
                            candidateRewardKeys.length !== startupRewardKeys.length ||
                            candidateRewardKeys.some(key => !startupRewardKeys.includes(key))
                        ) {
                            continue;
                        }

                        removableIndexes.push(index);
                    }

                    if (!removableIndexes.length) {
                        fallbackFailed = true;
                        break;
                    }

                    const nonSpecialistIndexes = removableIndexes.filter(index =>
                        !specialistCategories.includes(state.animals[index].category)
                    );
                    const pool = nonSpecialistIndexes.length
                        ? nonSpecialistIndexes
                        : removableIndexes;
                    const removeIndex = pool[Math.floor(Math.random() * pool.length)];
                    const [removedAnimal] = state.animals.splice(removeIndex, 1);
                    if (removedAnimal) state.animalLineage.delete(removedAnimal.id);
                }

                if (fallbackFailed) continue;

                rebuildStartingLevelState();

                clearStartupPlacements();
                fallbackFailed = false;

                for (const animal of state.animals) {
                    let destination = null;

                    for (const entry of startupEnclosures) {
                        if (animalsInEnclosureGroup(entry.enclosure, entry.group).length) continue;
                        const slotIndex = entry.group.find(slot =>
                            !animalAtSlot(entry.enclosure.id, slot) &&
                            canPlaceStartingAnimal(animal, entry.enclosure, slot)
                        );
                        if (slotIndex !== undefined) {
                            destination = { enclosure: entry.enclosure, slotIndex };
                            break;
                        }
                    }

                    if (!destination) {
                        outerFallback:
                        for (const entry of startupEnclosures) {
                            for (const slotIndex of entry.group) {
                                if (canPlaceStartingAnimal(animal, entry.enclosure, slotIndex)) {
                                    destination = { enclosure: entry.enclosure, slotIndex };
                                    break outerFallback;
                                }
                            }
                        }
                    }

                    if (!destination) {
                        fallbackFailed = true;
                        break;
                    }

                    animal.enclosureId = destination.enclosure.id;
                    animal.slotIndex = destination.slotIndex;
                }

                if (!fallbackFailed) {
                    placed = true;
                    console.warn(`Startup reduced from ${originalCount} to ${targetCount} animals after compatibility placement failed.`);
                    break;
                }
            }

            if (fallbackFailed) {
                throw new Error(
                    `Could not find a compatible starting layout even after reducing the opening collection to ${state.animals.length} animals ` +
                    `inside ${startingZooSizeRules(state.gameOptions.startingZooSize).maxSpaces} starting spaces.`
                );
            }
        }

        placed = true;
        console.warn('Startup used bounded greedy placement after compatibility search reached its limit.');
    }

    for(const animal of state.animals)delete animal.classicStartingExchangeAnchor;

    checkEnclosure10Unlock();
    arrangeGeneratedZooForAreas();
    if (requestedGameMode === 'true') {
        convertCurrentTrueZooToBuiltEnclosures();
        if(!trueRepairOpeningCompatibility()){
            throw new Error('True opening generation produced an incompatible enclosure with no safe relocation.');
        }
        truePrepareOpeningZooChallenges();
        trueInitialiseFirstNewSpeciesExpansionBaseline();
        normaliseTrueBuiltEnclosureOccupancy();
        const openingPlacedCount=(state.animals||[]).filter(a=>a?.enclosureId!=null).length;
        if(openingPlacedCount<5||openingPlacedCount>7){
            throw new Error(`True opening must contain 5-7 placed animal cards; generated ${openingPlacedCount}.`);
        }
        repairTrueBuiltEnclosureGeometry();
        initialiseTrueZooGroundsFromCurrentLayout(false);
        updateDiscoveredCategoryLevels();
        state.truePublicPrestige=currentZooPrestige();
        state.truePublicPrestigeLastDate=normaliseTrueCalendarState().date;
        state.trueGuestAttendanceDays={};
    }
    updateHighestZooPrestige();

    updateDiscoveredCategoryLevels();
    updateTurnDisplay();

}

const TRUE_CALENDAR_SPEEDS = [0, 1, 2, 3];
const TRUE_CALENDAR_INTERVAL_MS = { 1: 4000, 2: 4000, 3: 4000 };
const TRUE_CALENDAR_MINUTES_PER_TICK = { 1: 5, 2: 60, 3: 600 };
const TRUE_CALENDAR_DRIVER_MS = 250;
let trueCalendarLastDriverAt = 0;
let trueCalendarMinuteRemainder = 0;
let trueCalendarTimer = null;
let trueCalendarVisualClockRaf = 0;
let lastTrueCalendarAutoResumeWriteAt = 0;
let lastTrueCalendarAutosavePerfAt = 0;
const TRUE_CALENDAR_AUTOSAVE_MS = 30000;
let trueCalendarAutosaveQueued=false;
let trueCalendarAutosaveGeneration=0;

function normaliseTrueCalendarState() {
    if (!state.trueCalendar || typeof state.trueCalendar !== 'object') state.trueCalendar = {};
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(state.trueCalendar.date || ''))) state.trueCalendar.date = '2026-04-18';
    if (!Number.isInteger(Number(state.trueCalendar.hour)) || Number(state.trueCalendar.hour)<9 || Number(state.trueCalendar.hour)>18) state.trueCalendar.hour = 9;
    if (!Number.isInteger(Number(state.trueCalendar.minute)) || Number(state.trueCalendar.minute)<0 || Number(state.trueCalendar.minute)>59) state.trueCalendar.minute = 0;
    {
        const savedSpeed=Number(state.trueCalendar.speed);
        if(savedSpeed===5)state.trueCalendar.speed=2;
        else if(savedSpeed===20)state.trueCalendar.speed=3;
        else if(!TRUE_CALENDAR_SPEEDS.includes(savedSpeed))state.trueCalendar.speed=0;
    }
    if (!Array.isArray(state.trueCalendar.scheduledEvents)) state.trueCalendar.scheduledEvents = [];
    state.trueCalendar.lastMonthKey = String(state.trueCalendar.lastMonthKey || state.trueCalendar.date.slice(0, 7));
    if (!Array.isArray(state.trueActivityLog)) state.trueActivityLog = [];
    if (!Number.isFinite(Number(state.trueActivityNextId))) state.trueActivityNextId = 1;
    if(state.truePublicPrestige!==null&&state.truePublicPrestige!==''&&!Number.isFinite(Number(state.truePublicPrestige)))
        state.truePublicPrestige=null;
    state.truePublicPrestigeLastDate=String(state.truePublicPrestigeLastDate||'');
    state.trueGuestAttendanceDays=(state.trueGuestAttendanceDays&&typeof state.trueGuestAttendanceDays==='object'&&!Array.isArray(state.trueGuestAttendanceDays))
        ?state.trueGuestAttendanceDays:{};
    if (!state.trueDaytimeActivity || typeof state.trueDaytimeActivity !== 'object') state.trueDaytimeActivity = {};
    if (!Array.isArray(state.trueDaytimeActivity.generatedKeys)) state.trueDaytimeActivity.generatedKeys = [];
    if (!state.trueDaytimeActivity.round || typeof state.trueDaytimeActivity.round !== 'object') state.trueDaytimeActivity.round = null;
    if (!state.trueEvents || typeof state.trueEvents !== 'object' || Array.isArray(state.trueEvents)) state.trueEvents = {};
    if (!Array.isArray(state.trueEvents.items)) state.trueEvents.items = [];
    if (!Number.isFinite(Number(state.trueEvents.nextId))) state.trueEvents.nextId = 1;
    if (!state.trueEvents.lastGeneratedDate) state.trueEvents.lastGeneratedDate = state.trueCalendar.date;
    normaliseTrueMarketplaceState();
    normaliseTrueRealZooWorld();
    return state.trueCalendar;
}

function resetTrueCalendarSimulation() {
    stopTrueCalendarTimer();
    state.trueCalendar = { date: '2026-04-18', hour: 9, minute: 0, speed: 0, lastMonthKey: '2026-04', scheduledEvents: [] };
    state.trueActivityLog = [];
    state.trueActivityNextId = 1;
    state.trueEvents = { items: [], nextId: 1, lastGeneratedDate: '2026-04-18' };
    state.trueHusbandryConcerns = {};
    state.trueBirths = { byAnimal: {}, lastProcessedDate: '' };
    state.truePublicPrestige = null;
    state.truePublicPrestigeLastDate = '';
    state.trueGuestAttendanceDays = {};
    state.trueGuestDailyTargetManual = false;
    state.trueGuestDailyTarget = null;
    state.trueDaytimeActivity = { generatedKeys: [], round: null };
    state.trueMarketplace = { listings: [], wants: [], playerListings: [], nextPlayerListingId: 1, nextListingId: 1, lastRefreshMonth: '', lastRollingRefreshDate: '', rollingLifecycleVersion: 1, initialized: false };
    state.trueRelationships = {};
    state.trueTransferProposals = [];
    state.trueTransferProposalNextId = 1;
    state.trueRealZooWorld = { zoos:{}, nextSweepIndex:0 };
    realZooVisitLayouts?.clear?.();
    if (state.gameMode === 'true') {
        addTrueActivity({
            type: 'info',
            title: 'True mode started',
            message: 'Time is paused. Use the calendar controls when you are ready for the zoo world to advance.'
        });
    }
}

function classicTutorialStorageKey(){return 'zooCuratorClassicContextTutorialV2';}
function classicTutorialSeen(){
    try{return window.localStorage.getItem(classicTutorialStorageKey())==='1';}
    catch(error){return !!showFirstClassicWelcomeBriefing.completedThisSession;}
}
function classicTutorialRememberComplete(){
    showFirstClassicWelcomeBriefing.completedThisSession=true;
    try{window.localStorage.setItem(classicTutorialStorageKey(),'1');}catch(error){}
}
function classicTutorialEligible(){
    return state.gameMode==='classic'&&!state.sandboxMode&&!localClassicMatch&&!classicTutorialSeen();
}
function removeClassicTutorialHint(){
    document.getElementById('classicContextTutorialHint')?.remove();
    document.querySelectorAll('.classic-tutorial-target').forEach(el=>el.classList.remove('classic-tutorial-target'));
}
function classicTutorialAnchorAnimal(){
    const counts=new Map();
    for(const animal of state.animals||[]){
        if(Number(animal?.level)!==1)continue;
        const key=`${animal.category}|1`;
        if(!counts.has(key))counts.set(key,[]);
        counts.get(key).push(animal);
    }
    const group=[...counts.values()].find(animals=>
        animals.length>=3&&hasNextLevelInventory(animals[0].category,1));
    return group?.[0]||null;
}
function classicTutorialAnimalElement(animal){
    if(!animal)return null;
    return [...zooCanvas.querySelectorAll('[data-animal-id]')].find(el=>
        String(el.dataset.animalId)===String(animal.id))||null;
}
function classicTutorialEnclosureElement(){
    const enclosures=state.enclosures||[];
    const preferred=enclosures.filter(enclosure=>{
        const cells=getAllSlots(enclosure)?.length||0;
        return cells===2||cells===3;
    });
    const pool=preferred.length?preferred:enclosures;
    if(!pool.length)return null;
    const enclosure=pool[Math.floor(Math.random()*pool.length)];
    return zooCanvas.querySelector(`.enclosure[data-enclosure-id="${CSS.escape(String(enclosure.id))}"]`);
}
function classicTutorialWorldPointForElement(target){
    if(!target||!zooBoard||!zooCanvas)return null;
    const boardRect=zooBoard.getBoundingClientRect();
    const rect=target.getBoundingClientRect();
    const zoom=Math.max(.01,Number(state.zoom)||1);
    return {
        x:(zooBoard.scrollLeft+rect.left-boardRect.left+rect.width/2)/zoom,
        y:(zooBoard.scrollTop+rect.top-boardRect.top+rect.height/2)/zoom,
        width:rect.width/zoom,
        height:rect.height/zoom
    };
}
function classicTutorialPlaceBoardHint(hint,target,side='right'){
    const point=classicTutorialWorldPointForElement(target);
    if(!point)return false;
    const gap=18;
    const hintWidth=300;
    const canvasHeight=Math.max(zooCanvas.scrollHeight||0,zooCanvas.offsetHeight||0);
    const canvasWidth=Math.max(zooCanvas.scrollWidth||0,zooCanvas.offsetWidth||0);
    let left=point.x+(side==='right'?point.width/2+gap:-hintWidth-gap);
    let top=point.y-point.height/2;
    left=Math.max(12,Math.min(Math.max(12,canvasWidth-hintWidth-12),left));
    top=Math.max(12,Math.min(Math.max(12,canvasHeight-150),top));
    hint.style.left=`${Math.round(left)}px`;
    hint.style.top=`${Math.round(top)}px`;
    return true;
}
function classicTutorialPlaceHeaderHint(hint,target){
    if(!hint||!target)return false;
    const rect=target.getBoundingClientRect();
    const gap=8;
    const width=300;
    const viewportWidth=document.documentElement.clientWidth||window.innerWidth||width;
    let left=rect.left+rect.width/2-width/2;
    left=Math.max(8,Math.min(Math.max(8,viewportWidth-width-8),left));
    hint.style.left=`${Math.round(left)}px`;
    hint.style.top=`${Math.round(rect.bottom+gap)}px`;
    return true;
}
function renderClassicTutorialHint(){
    removeClassicTutorialHint();
    if(!classicTutorialEligible())return;
    const step=Number(showFirstClassicWelcomeBriefing.step)||1;
    let target=null,title='',body='',side='right',anchorMode='board';
    if(step===1){
        const animal=classicTutorialAnchorAnimal();
        target=classicTutorialAnimalElement(animal);
        title='Try an Exchange';
        body=`Whenever you collect three animals from the same category at the same level, you can trade two in for one animal a level higher. You already have three Level 1 ${animal?.category||'category'} cards. Drag any two of them into the Exchange slots to get a Level 2.`;
    }else if(step===2){
        target=drawCard;
        anchorMode='header';
        title='Draw an Animal';
        body='The deck is how new Level 1 animals enter your zoo. Draw a card and place it in a free enclosure.';
    }else if(step===3){
        target=outgoingOfferBox;
        anchorMode='header';
        title='Trade with Other Zoos';
        body='Drag one of your animals into Your Offer. Other zoos will offer animals in return, giving you another way to shape your collection and find species you cannot simply draw.';
    }else if(step===4){
        target=classicTutorialEnclosureElement();
        title='Build a Better Zoo';
        body='Some species can share an enclosure. Discover convincing combinations and group enclosures into geographically accurate Areas to earn extra Prestige. Prestige is your zoo’s reputation: as it rises, more zoos and trading opportunities open up.';
    }else{
        classicTutorialRememberComplete();
        return;
    }
    if(!target)return;
    target.classList.add('classic-tutorial-target');
    const hint=document.createElement('button');
    hint.type='button';
    hint.id='classicContextTutorialHint';
    hint.className='classic-context-tutorial-hint';
    hint.innerHTML=`<strong>${title}</strong><span>${body}</span><small>Click to continue</small>`;
    hint.onclick=event=>{
        event.stopPropagation();
        advanceClassicTutorial(step,true);
    };
    if(anchorMode==='header'){
        hint.classList.add('classic-context-tutorial-hint--header');
        document.body.appendChild(hint);
        if(!classicTutorialPlaceHeaderHint(hint,target)){
            hint.remove();
            target.classList.remove('classic-tutorial-target');
        }
    }else{
        zooCanvas.appendChild(hint);
        if(!classicTutorialPlaceBoardHint(hint,target,side)){
            hint.remove();
            target.classList.remove('classic-tutorial-target');
        }
    }
}
function advanceClassicTutorial(expectedStep,forced=false){
    if(!classicTutorialEligible()||Number(showFirstClassicWelcomeBriefing.step)!==expectedStep)return;
    showFirstClassicWelcomeBriefing.step=expectedStep+1;
    if(showFirstClassicWelcomeBriefing.step>4){
        removeClassicTutorialHint();
        classicTutorialRememberComplete();
        return;
    }
    requestAnimationFrame(()=>renderClassicTutorialHint());
}
function showFirstClassicWelcomeBriefing(){
    if(!classicTutorialEligible())return;
    showFirstClassicWelcomeBriefing.step=1;
    requestAnimationFrame(()=>renderClassicTutorialHint());
}

