function showTrueOpeningDayBriefing() {
    if (state.gameMode !== 'true' || state.sandboxMode) return;

    setTrueCalendarSpeed(0);

    let overlay = document.getElementById('trueOpeningDayOverlay');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.id = 'trueOpeningDayOverlay';
        overlay.className = 'save-load-overlay';
        overlay.style.zIndex = '10040';
        overlay.innerHTML = `
            <div class="save-load-modal" role="dialog" aria-modal="true" aria-labelledby="trueOpeningDayTitle" style="max-width:520px;">
                <div style="font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#766b56;margin-bottom:5px;">18 April 2026 · Opening Day</div>
                <h2 id="trueOpeningDayTitle" style="margin-top:0;">Welcome to <span id="trueOpeningDayZooName"></span>!</h2>
                <p style="margin-bottom:12px;"><strong>Today is opening day!</strong> The animals are in, the gates are ready to open, and your first visitors will be arriving soon.</p>
                <p style="margin-bottom:12px;">From here, the zoo develops day by day. Build enclosures for new arrivals, manage your animal groups and keep an eye on breeding. Growing populations may need more space, splitting up or a new home elsewhere.</p>
                <p style="margin-bottom:12px;">Stay in touch with other zoos too. Animals can move between collections, and good relationships will give you more opportunities to bring in new species or find homes for animals you no longer have room for.</p>
                <p style="margin-bottom:12px;">Visitors are what turn a collection into a successful zoo. As more people come through the gates and see what you've built, your reputation will grow and new opportunities will become available.</p>
                <p style="margin-bottom:16px;">There's plenty to do, but you don't have to do everything at once.</p>
                <p style="margin-bottom:10px;"><strong>Ready? Open the gates!</strong></p>
                <div class="save-load-footer" style="justify-content:flex-end;">
                    <button type="button" id="trueOpeningDayBegin">Open the Gates</button>
                </div>
            </div>`;
        document.body.appendChild(overlay);
    }

    const name = overlay.querySelector('#trueOpeningDayZooName');
    if (name) name.textContent = state.zooName || 'Zoo Curator';

    const begin = () => {
        if (!overlay.classList.contains('visible')) return;
        overlay.classList.remove('visible');
        overlay.setAttribute('aria-hidden', 'true');
        setTrueCalendarSpeed(1);
        writeAutoResumeSnapshot(true);
    };
    overlay.querySelector('#trueOpeningDayBegin').onclick = begin;
    overlay.onclick = event => { if (event.target === overlay) begin(); };
    overlay.onkeydown = event => {
        if (event.key === 'Escape') { event.preventDefault(); begin(); }
    };

    overlay.classList.add('visible');
    overlay.setAttribute('aria-hidden', 'false');
    requestAnimationFrame(() => overlay.querySelector('#trueOpeningDayBegin')?.focus());
}

function trueDateObject(value = null) {
    const raw=value==null?String(state.trueCalendar?.date||''):String(value);
    const safe=/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw:'2026-04-18';
    const [y,m,d] = safe.split('-').map(Number);
    return new Date(Date.UTC(y, Math.max(0,m-1), d));
}

function trueDateString(date) {
    return date.toISOString().slice(0, 10);
}

function trueCurrentDate() { return trueDateObject(state.trueCalendar?.date||'2026-04-18'); }
function trueDateKey(date = trueCurrentDate()) { return trueDateString(date); }

function formatTrueDate(value, includeYear = true) {
    const date = trueDateObject(value);
    return new Intl.DateTimeFormat(undefined, {
        day: 'numeric', month: 'long', ...(includeYear ? { year: 'numeric' } : {}), timeZone: 'UTC'
    }).format(date);
}

function addTrueActivity({ type='info', title='Activity', message='', date=null, actionLabel='', action=null, unread=true,
    transferId=null, transferLegId=null, animal=null, glowAnimal=false, eventId=null } = {}) {
    normaliseTrueCalendarState();
    const item = {
        id: state.trueActivityNextId++, type, title, message,
        date: date || state.trueCalendar.date,
        time: `${String(state.trueCalendar.hour).padStart(2,'0')}:${String(state.trueCalendar.minute).padStart(2,'0')}`,
        actionLabel: actionLabel || '',
        action: typeof action === 'string' ? action : '',
        transferId: transferId==null?null:transferId,
        transferLegId: transferLegId==null?null:String(transferLegId),
        animal: animal ? cloneForSave(animal) : null,
        glowAnimal: !!glowAnimal,
        eventId: eventId==null?null:String(eventId),
        unread: unread !== false,
        resolved: false
    };
    state.trueActivityLog.unshift(item);
    if (state.trueActivityLog.length > 80) state.trueActivityLog.length = 80;
    renderTrueSimulationPanel();
    return item;
}

function scheduleTrueEvent({ date, type='info', title='Activity', message='', actionLabel='', action='', pause=false, payload=null } = {}) {
    normaliseTrueCalendarState();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date || ''))) return null;
    const event = { id: `te-${Date.now()}-${Math.random().toString(36).slice(2,8)}`, date, type, title, message, actionLabel, action, pause: !!pause, payload: payload && typeof payload === 'object' ? cloneForSave(payload) : null };
    state.trueCalendar.scheduledEvents.push(event);
    state.trueCalendar.scheduledEvents.sort((a,b) => String(a.date).localeCompare(String(b.date)));
    return event;
}

