function trueResolvePopulationPressureFollowUp(eventId){
    const original=trueEventById(eventId);if(!original||original.populationPressureFollowUpResolved)return;
    original.populationPressureFollowUpResolved=true;
    const animal=classicAnimalsByCardKey(original.animal)[0];
    const surplus=truePlayerPopulationSurplus(animal);if(!animal||!surplus)return;
    const records=trueEventEligibleSourceRecords('population-pressure-follow-up').filter(record=>trueDestinationCanReceiveSurplus(record,animal,surplus.population));
    if(!records.length)return; // no second gameplay effect => deliberately no follow-up card
    const preferred=records.find(r=>realZooHoldingKey(r)===original.networkAdviceSourceKey);
    const record=preferred||records[Math.floor(seededRoll(`population-pressure-followup-zoo|${original.id}`).roll*records.length)];
    const candidate={record,sourceKey:realZooHoldingKey(record),profile:realZooProfile(record,0),rel:trueRelationshipForProfile(realZooProfile(record,0),realZooHoldingKey(record)),animal,surplus,weight:1};
    const event=trueCreateSurplusReliefEvent(candidate,normaliseTrueCalendarState().date);
    event.parentEventId=original.id;event.followUpEvent=true;
    trueRelationshipRecord(event.profile,event.sourceKey,'population-advice-follow-up',`Responded with a practical placement option for surplus ${animalDisplayName(animal)}.`,{trust:1,familiarity:1});
}
function trueResolveEventFollowUp(eventId){
    const original=trueEventById(eventId);if(!original||original.followUpResolved)return;
    original.followUpResolved=true;
    const record=(state.realZooData?.zoos||[]).find(r=>realZooHoldingKey(r)===original.sourceKey);
    if(!record)return;
    const events=normaliseTrueEventState(),today=normaliseTrueCalendarState().date;
    const rel=trueRelationshipForProfile(original.profile,original.sourceKey);

    if(original.kind==='population-advice'){
        const animal=classicAnimalsByCardKey(original.animal).find(a=>!a.trueArrivalPending);
        if(!animal)return;
        const surplus=truePlayerPopulationSurplus(animal);
        const easing=Boolean(surplus);
        trueEventAddModifier({
            type:'birth-chance-multiplier',value:easing?.82:1.12,untilDate:addTrueDays(today,7),
            animalKey:animalCardKey(animal),sourceEventId:original.id,
            text:easing
                ?`${original.profile?.name||'A partner zoo'} has helped refine a short-term population-management plan.`
                :`${original.profile?.name||'A partner zoo'} has shared follow-up breeding-management advice.`
        });
        trueRelationshipRecord(original.profile,original.sourceKey,'population-advice-follow-up',
            `Provided practical follow-up population advice for ${animalDisplayName(animal)}.`,{trust:.5,familiarity:.5});
        addTrueActivity({type:'information',title:'Population advice followed up',message:easing
            ?`${original.profile?.name||'The partner zoo'} has helped your team refine management of the ${animalDisplayName(animal)} population; breeding pressure will be lower for the next seven zoo days.`
            :`${original.profile?.name||'The partner zoo'} has followed up with breeding-management advice for ${animalDisplayName(animal)}; conditions are slightly more favourable for the next seven zoo days.`});
        return;
    }

    if(original.kind!=='collection-planning')return;
    if(!original.animal||!tradeIncomingHasDestinationAfterOutgoing(original.animal,null))return;
    const roll=seededRoll(`event-follow-up|${original.id}|${today}`).roll;
    if(roll>=Math.min(.72,.48+Math.max(0,Number(rel.trust)||0)*.003))return;
    const sourceEntry=trueWorldPopulation(record,original.animal,{create:true,reason:'collection planning follow-up'});
    const sourcePop=normaliseTrueAnimalPopulation(sourceEntry.population);
    const offeredPop=sourcePop.unknown>0?{males:0,females:0,unknown:1}:sourcePop.males>1?{males:1,females:0,unknown:0}:sourcePop.females>1?{males:0,females:1,unknown:0}:null;
    if(!offeredPop)return;
    const narrative=trueEventNarrative({profile:original.profile,animal:original.animal,population:offeredPop,reason:'population management'},'transfer-opportunity',rel);
    const expiry=trueDateObject(today);expiry.setUTCDate(expiry.getUTCDate()+14);
    const event={id:`ze-${events.nextId++}`,kind:'transfer-opportunity',status:'active',createdDate:today,expiresDate:trueDateString(expiry),
        independentEvent:true,sourceKey:original.sourceKey,profile:cloneForSave(original.profile),animal:cloneForSave(original.animal),
        population:cloneForSave(offeredPop),scale:trueEventScaleFor('transfer-opportunity',original.animal,rel),
        title:narrative.title,message:`Following their earlier collection planning, ${original.profile?.name||'the zoo'} is now ready to discuss placing ${animalDisplayName(original.animal)}.`,detail:narrative.detail,
        impactText:`The earlier collection-planning contact has developed into a real transfer opportunity. Your response can change the population outcome and your relationship with ${original.profile?.name||'the zoo'}.`,
        parentEventId:original.id,followUpEvent:true};
    events.items.unshift(event);events.lastGeneratedDate=today;trueEventRememberFamily(events,'transfer-opportunity');
    addTrueActivity({type:'opportunity',title:'Collection plan develops',message:event.message,actionLabel:'View event',action:'event',eventId:event.id});
    trueQueueEventPresentation(event);
}
function normaliseTrueHusbandryConcernState(){
    if(!state.trueHusbandryConcerns||typeof state.trueHusbandryConcerns!=='object'||Array.isArray(state.trueHusbandryConcerns))state.trueHusbandryConcerns={};
    return state.trueHusbandryConcerns;
}
function trueEnclosureManagedSpaceAssessment(enclosure){
    const cells=Math.max(1,trueCanonicalCellList(enclosure?.cells||[]).length);
    const residents=classicAnimalsByEnclosure(enclosure?.id).filter(a=>trueAnimalPopulationTotal(a)>0);
    const bySpecies=new Map();
    for(const animal of residents){
        const key=animalCardKey(animal);
        let row=bySpecies.get(key);
        if(!row)bySpecies.set(key,row={key,animals:[],baseline:0,total:0});
        row.animals.push(animal);
        row.baseline=Math.max(row.baseline,trueAnimalMinimumEnclosureCells(animal));
        row.total+=trueAnimalPopulationTotal(animal);
    }
    let required=1,driver=null;
    for(const row of bySpecies.values()){
        row.required=row.baseline+Math.max(0,Math.ceil((row.total-6)/6));
        if(row.required>required){required=row.required;driver=row;}
    }
    return {cells,required,residents,species:[...bySpecies.values()],driver,mixed:bySpecies.size>1};
}
function trueHusbandryConditionForAnimal(animal){
    if(!animal||animal.enclosureId==null)return {bad:false,spaceBad:false,groupBad:false};
    const enc=enclosureByIdFast(animal.enclosureId);
    if(!enc?.trueBuilt)return {bad:false,spaceBad:false,groupBad:false};
    const enclosureSpace=trueEnclosureManagedSpaceAssessment(enc);
    const cells=enclosureSpace.cells,required=enclosureSpace.required;
    const group=truePopulationGroupSizeStatus(animal);
    const spaceBad=cells<required,groupBad=!group.valid;
    const spaceSeverity=spaceBad?Math.max(0,Math.min(1,(required-cells)/Math.max(1,required))):0;
    let groupSeverity=0;
    if(group.tooSmall)groupSeverity=Math.min(1,(group.min-group.total)/Math.max(1,group.min));
    else if(group.tooLarge)groupSeverity=Math.min(1,(group.total-group.max)/Math.max(1,group.max));
    else if(group.structureMismatch)groupSeverity=.35;
    return {bad:spaceBad||groupBad,spaceBad,groupBad,cells,required,group,enclosureSpace,spaceSeverity,groupSeverity,severity:Math.max(spaceSeverity,groupSeverity)};
}
function trueConcernZooForAnimal(animal,today){
    const records=state.realZooData?.zoos||[];
    if(!records.length)return null;

    const localRows=records.map((record,index)=>({
        record,index,band:realZooGeographyBand(record)
    }));
    let eligible=localRows.filter(row=>row.band===0);
    if(!eligible.length)eligible=localRows.filter(row=>row.band===1);
    if(!eligible.length)return null;

    const rows=eligible.map(({record,index})=>{
        const profile=realZooProfile(record,index),sourceKey=realZooHoldingKey(record),rel=trueRelationshipForProfile(profile,sourceKey);
        return {record,profile,sourceKey,rel,weight:1+Math.min(4,(Number(rel.trust)||0)/15)+Math.min(2,(Number(rel.familiarity)||0)/10)};
    });
    let total=rows.reduce((n,r)=>n+r.weight,0),pick=seededRoll(`welfare-zoo|${animalCardKey(animal)}|${today}`).roll*total;
    for(const row of rows){pick-=row.weight;if(pick<=0)return row;}
    return rows[0];
}

function truePopulationExactRepairOptions(animal){
    if(!animal)return {send:null,receive:null};
    const current=normaliseTrueAnimalPopulation(animal);
    if(truePopulationGroupSizeStatus(animal).valid)return {send:null,receive:null};
    const best={send:null,receive:null};
    const consider=(mode,pop,result)=>{
        if(!truePopulationGroupSizeStatus({...animal,population:result}).valid)return;
        const amount=(pop.males||0)+(pop.females||0)+(pop.unknown||0);
        const sexes=(pop.males>0?1:0)+(pop.females>0?1:0)+(pop.unknown>0?1:0);
        const score=[amount,sexes,pop.unknown||0],old=best[mode];
        if(!old||score.some((v,i)=>v<old.score[i]&&score.slice(0,i).every((x,j)=>x===old.score[j])))
            best[mode]={mode,population:pop,result,score};
    };
    for(let m=0;m<=current.males;m++)for(let f=0;f<=current.females;f++)for(let u=0;u<=current.unknown;u++){
        const n=m+f+u;if(!n||n>=current.males+current.females+current.unknown)continue;
        consider('send',{males:m,females:f,unknown:u},{males:current.males-m,females:current.females-f,unknown:current.unknown-u});
    }
    for(let m=0;m<=8;m++)for(let f=0;f<=8;f++){
        const n=m+f;if(!n||n>8)continue;
        consider('receive',{males:m,females:f,unknown:0},{males:current.males+m,females:current.females+f,unknown:current.unknown});
    }
    return best;
}
function trueConcernZooWithExactRepair(animal,repair,today){
    if(!repair)return null;
    const records=state.realZooData?.zoos||[];
    const local=records.map((record,index)=>({record,index,band:realZooGeographyBand(record)}));
    let eligible=local.filter(x=>x.band===0);if(!eligible.length)eligible=local.filter(x=>x.band===1);
    const rows=[];
    for(const row of eligible){
        const profile=realZooProfile(row.record,row.index),sourceKey=realZooHoldingKey(row.record);
        if(repair.mode==='send'){
            if(!trueDestinationCanReceiveSurplus(row.record,animal,repair.population))continue;
        }else{
            const entry=trueWorldPopulation(row.record,animal,{create:true,reason:'welfare exact group repair'});
            if(!entry)continue;
            const before=normaliseTrueAnimalPopulation(entry.population),give=normaliseTrueAnimalPopulation(repair.population);
            if(give.males>before.males||give.females>before.females||give.unknown>before.unknown)continue;
            const after={males:before.males-give.males,females:before.females-give.females,unknown:before.unknown-give.unknown};
            if(!truePopulationGroupSizeStatus({...animal,population:after,truePopulationManagement:entry.management||null}).valid)continue;
        }
        const rel=trueRelationshipForProfile(profile,sourceKey);
        rows.push({record,profile,sourceKey,rel,weight:1+Math.max(0,Number(rel.trust)||0)/20+Math.max(0,Number(rel.familiarity)||0)/30});
    }
    if(!rows.length)return null;
    let total=rows.reduce((n,r)=>n+r.weight,0),pick=seededRoll(`welfare-repair-zoo|${animalCardKey(animal)}|${today}`).roll*total;
    for(const row of rows){pick-=row.weight;if(pick<=0)return row;}return rows[0];
}
