        const card=document.createElement('section');card.id='trueCuratorRoundCard';
        card.style.cssText='pointer-events:auto;width:min(560px,calc(100vw - 36px));background:#f8f3e7;color:#30291f;border:1px solid rgba(80,70,55,.35);border-radius:12px;box-shadow:0 8px 30px rgba(35,28,20,.24);padding:18px 20px 16px;';
        overlay.appendChild(card);document.body.appendChild(overlay);
