let trueGuestViewingPointCache={signature:'',at:0,points:[]};
function trueGuestViewingPoints(){
    const walk=trueGuestRuntime.walk;if(!walk)return [];
    const now=performance.now();
    const signature=String(trueGuestRuntime.layoutSig||'');
    if(trueGuestViewingPointCache.signature===signature&&now-trueGuestViewingPointCache.at<200){
        return trueGuestViewingPointCache.points;
    }
    const points=[];
    const cal=normaliseTrueCalendarState();
    const minutesNow=(Number(cal.hour)||9)*60+(Number(cal.minute)||0);
    for(const enc of state.enclosures||[]){
        if(!enc?.trueBuilt)continue;
        const occupants=classicAnimalsByEnclosure(enc.id);
        if(!occupants.length)continue;

        const levels=occupants.map(a=>Math.max(1,Math.min(5,Number(a?.level)||1)));
        const attractionLevel=Math.min(5,Math.max(...levels)+Math.min(.5,(levels.length-1)*.1));
        const eventAttraction=trueGuestEventAttraction(enc.id,minutesNow);
        const cells=trueBuiltWorldCells(enc);
        const own=new Set(cells.map(cell=>trueBuilderCellKey(cell.col,cell.row)));
        const seen=new Set();

        for(const cell of cells){
            for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
                const nc=cell.col+dc,nr=cell.row+dr,nk=trueBuilderCellKey(nc,nr);
                if(own.has(nk)||!walk.free.has(nk))continue;

                const horizontal=dr!==0;
                const edgeKey=`${cell.col},${cell.row},${dc},${dr}`;
                if(seen.has(edgeKey))continue;seen.add(edgeKey);

                const edgeLength=horizontal?TRUE_ENC_CELL_W:TRUE_ENC_CELL_H;
                const samples=Math.max(3,Math.ceil(edgeLength/28));
                for(let i=0;i<samples;i++){
                    const t=(i+1)/(samples+1);
                    let x,y;
                    const minBodyClearance=20;
                    const requestedGap=minBodyClearance+Math.random()*80;
                    const maxSafeGap=Math.max(minBodyClearance,(horizontal?TRUE_ENC_CELL_H:TRUE_ENC_CELL_W)*.48);
                    const gap=Math.min(requestedGap,maxSafeGap);
                    if(horizontal){
                        x=(cell.col+t)*TRUE_ENC_CELL_W;
                        y=dr>0?(cell.row+1)*TRUE_ENC_CELL_H:cell.row*TRUE_ENC_CELL_H;
                        y+=dr*gap;
                    }else{
                        x=dc>0?(cell.col+1)*TRUE_ENC_CELL_W:cell.col*TRUE_ENC_CELL_W;
                        y=(cell.row+t)*TRUE_ENC_CELL_H;
                        x+=dc*gap;
                    }
                    points.push({enclosureId:enc.id,x,y,attractionLevel,eventAttraction,viewingPoint:true,gap});
                }
            }
        }
    }
    trueGuestViewingPointCache={signature,at:now,points};
    return points;
}

function trueEnclosureVisitorViewabilityDiagnostic(){
    const walk=trueGuestBuildWalkGraph();
    if(!walk)return [];
    return (state.enclosures||[]).filter(e=>e?.trueBuilt).map(enc=>{
        const cells=trueBuiltWorldCells(enc),own=new Set(cells.map(c=>trueBuilderCellKey(c.col,c.row)));
        let frontage=0;
        for(const cell of cells)for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
            const k=trueBuilderCellKey(cell.col+dc,cell.row+dr);
            if(!own.has(k)&&walk.free.has(k))frontage++;
        }
        const animal=(state.animals||[]).find(a=>String(a?.enclosureId)===String(enc.id));
        return {enclosureId:enc.id,animal:animal?animalDisplayName(animal):'',viewable:frontage>0,reachableFrontageEdges:frontage};
    });
}
if(typeof window!=='undefined')window.zooViewabilityDiagnostic=trueEnclosureVisitorViewabilityDiagnostic;

function trueGuestWatchDuration(level){
    const L=Math.max(1,Math.min(5,Number(level)||1));
    const min=1000,max=15000;
    const rarityBias=(L-1)/4;
    const roll=Math.random();
    const shaped=Math.pow(roll,1.65-.95*rarityBias);
    return min+(max-min)*shaped;
}
let trueGuestInterestCache={signature:'',options:[],byEnclosure:new Map(),groupInterests:new Map()};
