        const interestPull=trueGuestInterestForEnclosure(g,p.enclosureId,interestCache,guestInterest);
        const favouritePull=g.favouriteEnclosureId!=null&&String(p.enclosureId)===String(g.favouriteEnclosureId)?2.35:1;
