function trueGuestTickFrame(now){
    const layer=trueGuestLayer();
    if(!layer){for(const g of trueGuestRuntime.guests)g.el?.remove();trueGuestRuntime.guests=[];trueGuestRuntime.spawnQueue=0;trueGuestRuntime.spawnGroupId=null;trueGuestRuntime.nextSpawnAt=0;trueGuestRuntime.nextGroupAt=0;trueGuestRuntime.nextLayoutCheckAt=0;trueGuestRuntime.last=0;return;}
    let sig=trueGuestRuntime.layoutSig;
    const layoutRevision=Number(state.areaPlacementRevision)||0;
    if(!sig||layoutRevision!==trueGuestRuntime.layoutRevision||now>=(Number(trueGuestRuntime.nextLayoutCheckAt)||0)){
        sig=trueGuestLayoutSignature();
        trueGuestRuntime.layoutRevision=layoutRevision;
        trueGuestRuntime.nextLayoutCheckAt=now+1000;
    }
    const frameEntrance=trueGuestEntrancePoint();
    if(sig!==trueGuestRuntime.layoutSig){
        trueGuestRuntime.layoutSig=sig;trueGuestRuntime.walk=trueGuestBuildWalkGraph();
        const walk=trueGuestRuntime.walk;
        const segmentIsWalkable=(a,b)=>{
            if(!a||!b)return false;
            const distance=Math.hypot(b.x-a.x,b.y-a.y);
            const step=Math.max(8,Math.min(TRUE_ENC_CELL_W,TRUE_ENC_CELL_H)*.18);
            const samples=Math.max(1,Math.ceil(distance/step));
            for(let i=0;i<=samples;i++){
                const f=i/samples;
                if(!trueGuestPointIsWalkable({x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f},walk))return false;
            }
            return true;
        };
        for(const g of trueGuestRuntime.guests){
            if(!trueGuestPointIsWalkable(g,walk)){
                const freeCell=trueGuestCellForPoint(g,walk);
                if(freeCell){
                    g.x=(freeCell.c+.5)*TRUE_ENC_CELL_W;
                    g.y=(freeCell.r+.5)*TRUE_ENC_CELL_H;
                }
            }
            const remaining=(g.path||[]).slice(Math.max(0,Number(g.pathIndex)||0));
            let previous={x:g.x,y:g.y};
            let routeStillValid=true;
            for(const point of remaining){
                if(!trueGuestPointIsWalkable(point,walk)||!segmentIsWalkable(previous,point)){
                    routeStillValid=false;break;
                }
                previous=point;
            }
            if(routeStillValid)continue;
            g.path=[];g.pathIndex=0;g.wait=0;
            if(g.leaving){
                g.viewingDestination=null;
                g.path=trueGuestPath(g,frameEntrance);g.pathIndex=0;
            }else trueGuestChooseDestination(g);
        }
    }
    const rawDt=Math.min(1/30,Math.max(0,(now-(trueGuestRuntime.last||now))/1000));trueGuestRuntime.last=now;
    const calendar=normaliseTrueCalendarState();
    const calendarSpeed=Number(calendar.speed)||0;
    const simSpeed=trueCalendarRolloverPending?0:trueGuestSimulationSpeedMultiplier();
    const dt=rawDt*simSpeed;
    const target=trueGuestDailyTarget();
    if(trueCalendarRolloverPending){trueGuestRuntime.last=now;return;}
    // The calendar is authoritative at every speed. Guests must read it
    // behaviour run ahead and could reintroduce apparent time snap-backs.
    const calendarHour=Number(calendar.hour)||9;
    if(trueGuestRuntime.dailyTargetDate!==calendar.date){
        trueGuestRuntime.dailyTargetDate=calendar.date;
        trueGuestRuntime.dailyEntered=0;
    }
    if(trueGuestRuntime.lastCalendarDate&&trueGuestRuntime.lastCalendarDate!==calendar.date){
        for(const g of trueGuestRuntime.guests)g.el?.remove();
        trueGuestRuntime.guests=[];trueGuestRuntime.spawnQueue=0;trueGuestRuntime.spawnGroupId=null;trueGuestRuntime.spawnGroupSize=0;trueGuestRuntime.spawnGroupDepartureMinute=null;
        trueGuestRuntime.nextSpawnAt=now;trueGuestRuntime.nextGroupAt=now+Math.random()*900;
    }
    trueGuestRuntime.lastCalendarDate=calendar.date;trueGuestRuntime.lastCalendarHour=calendarHour;
    const calendarMinute=Number(calendar.minute)||0;
    const minutesNow=calendarHour*60+calendarMinute;
    if(
        minutesNow!==trueGuestRuntime.lastAnimalEventMinute||
        now>=(Number(trueGuestRuntime.nextAnimalEventCheckAt)||0)
    ){
        trueGuestRuntime.lastAnimalEventMinute=minutesNow;
        trueGuestRuntime.nextAnimalEventCheckAt=now+250;
        trueGuestUpdateAnimalEvents(minutesNow);
    }
    if(minutesNow>=9*60&&minutesNow!==trueGuestRuntime.lastDepartureCheckMinute){
        trueGuestRuntime.lastDepartureCheckMinute=minutesNow;
        if(minutesNow>=17*60){trueGuestRuntime.spawnQueue=0;trueGuestRuntime.spawnGroupId=null;trueGuestRuntime.spawnGroupSize=0;trueGuestRuntime.spawnGroupDepartureMinute=null;}
        for(const g of trueGuestRuntime.guests){
            const leaveAt=Math.min(18*60,Number(g.plannedDepartureMinute)||Number(g.groupDepartureMinute)||18*60);
            if(!g.leaving&&minutesNow>=leaveAt){
                g.wait=0;g.visits=99;g.leaving=true;g.viewingDestination=null;
                g.path=trueGuestPath(g,frameEntrance);g.pathIndex=0;
            }
        }
    }
    const admissionStart=9*60,admissionEnd=17*60;
    const pacedProgress=trueGuestArrivalProgress(minutesNow);
    const shouldHaveEntered=Math.min(target,minutesNow>=16*60?target:Math.floor(target*pacedProgress));
    const remainingToday=Math.max(0,target-trueGuestRuntime.dailyEntered);
    let dueNow=Math.max(0,Math.min(remainingToday,shouldHaveEntered-trueGuestRuntime.dailyEntered));
    const visualCap=trueGuestVisualCap();
    if(visualCap<=0&&trueGuestRuntime.guests.length){
        for(const g of trueGuestRuntime.guests)g.el?.remove();
        trueGuestRuntime.guests=[];
    }
    if(dueNow>0&&(visualCap<=0||trueGuestRuntime.guests.length>=visualCap)){
        trueGuestRuntime.dailyEntered+=dueNow;
        dueNow=0;
        trueGuestRuntime.spawnQueue=0;
        trueGuestRuntime.spawnGroupId=null;
        trueGuestRuntime.spawnGroupDepartureMinute=null;
    }
    if(simSpeed>0&&visualCap>0&&minutesNow<17*60&&trueGuestRuntime.spawnQueue<=0&&dueNow>0&&now>=trueGuestRuntime.nextGroupAt){
        trueGuestRuntime.spawnQueue=Math.min(dueNow,1+Math.floor(Math.random()*5));
        trueGuestRuntime.spawnGroupSize=trueGuestRuntime.spawnQueue;
        trueGuestRuntime.spawnGroupId=trueGuestRuntime.nextGroupId++;
        const groupStayMinutes=120+Math.floor(Math.random()*301);
        trueGuestRuntime.spawnGroupDepartureMinute=Math.min(minutesNow+groupStayMinutes,17*60+Math.floor(Math.random()*61),18*60);
        trueGuestRuntime.nextSpawnAt=now;
        trueGuestRuntime.nextGroupAt=now+(900+Math.random()*2400)/Math.max(.75,simSpeed);
    }
    if(simSpeed>0&&visualCap>0&&trueGuestRuntime.spawnQueue>0&&now>=trueGuestRuntime.nextSpawnAt){
        if(trueGuestRuntime.guests.length>=visualCap){
            const aggregate=Math.min(trueGuestRuntime.spawnQueue,Math.max(0,target-trueGuestRuntime.dailyEntered));
            trueGuestRuntime.dailyEntered+=aggregate;
            trueGuestRuntime.spawnQueue=0;trueGuestRuntime.spawnGroupId=null;trueGuestRuntime.spawnGroupSize=0;trueGuestRuntime.spawnGroupDepartureMinute=null;
        }
        if(trueGuestRuntime.spawnQueue<=0){
        }else{
        const entrance=frameEntrance;
        const entranceClear=entrance&&(calendarSpeed===3||!trueGuestRuntime.guests.some(g=>{
            const dx=g.x-entrance.x,dy=g.y-entrance.y;
            const clearance=(g.radius||20)+28;
            return dx*dx+dy*dy<clearance*clearance;
        }));
        if(entranceClear){
            const gid=trueGuestRuntime.spawnGroupId;
            const isLeader=trueGuestRuntime.spawnQueue===trueGuestRuntime.spawnGroupSize;
            trueGuestSpawn(layer,gid,isLeader,trueGuestRuntime.spawnGroupDepartureMinute);trueGuestRuntime.dailyEntered++;trueGuestRuntime.spawnQueue--;
            if(trueGuestRuntime.spawnQueue<=0){trueGuestRuntime.spawnGroupId=null;trueGuestRuntime.spawnGroupSize=0;trueGuestRuntime.spawnGroupDepartureMinute=null;}
            trueGuestRuntime.nextSpawnAt=now+(220+Math.random()*420)/Math.max(.75,simSpeed);
        }else trueGuestRuntime.nextSpawnAt=now+120/Math.max(.75,simSpeed);
        }
    }
    refreshTrueGuestsTodayCounter();
    const lightweightGuests=calendarSpeed===3;
    if(!lightweightGuests){
        const guestGroups=new Map();
        for(const member of trueGuestRuntime.guests){
            member._frameGroupPeers=null;
            if(member.groupId==null||member.leaving)continue;
            const key=String(member.groupId);
            let peers=guestGroups.get(key);
            if(!peers){peers=[];guestGroups.set(key,peers);}
            peers.push(member);
        }
        for(const peers of guestGroups.values())for(const member of peers)member._frameGroupPeers=peers;
    }
    const frameGrounds=trueZooGroundsBounds();
    const paintGuests=calendarSpeed!==3||now>=(Number(trueGuestRuntime.nextVisualPaintAt)||0);
    if(paintGuests&&calendarSpeed===3)trueGuestRuntime.nextVisualPaintAt=now+100;
    for(let guestIndex=trueGuestRuntime.guests.length-1;guestIndex>=0;guestIndex--){
        const g=trueGuestRuntime.guests[guestIndex];
        if(g.wait>0){g.wait-=dt*1000;continue;}
        if(!lightweightGuests&&g.groupId!=null&&!g.entering&&!g.leaving){
            const peers=g._frameGroupPeers||[];
            const farBehind=peers.some(x=>
                x!==g&&
                String(x.lastEnclosureId)===String(g.lastEnclosureId)&&
                (x.wait||0)>2000
            );
            if(farBehind){g.wait=180;continue;}
        }
        const dest=g.path?.[g.pathIndex];
        if(!dest){
            if(g.entering){
                g.entering=false;g.path=[];g.pathIndex=0;
                trueGuestChooseDestination(g);continue;
            }
            if(g.leaving){trueGuestRemove(g,now,guestIndex);continue;}
            const view=g.viewingDestination;
            if(!view||String(view.enclosureId)!==String(g.lastEnclosureId)){
                g.path=[];g.pathIndex=0;trueGuestChooseDestination(g);continue;
            }
            g.x=view.x;g.y=view.y;
            if(paintGuests&&g.el?.isConnected)g.el.style.transform=`translate3d(${g.x}px,${g.y}px,0) translate(-50%,-50%)`;
            if(!(g.visitedEnclosureIds instanceof Set))g.visitedEnclosureIds=new Set(g.visitedEnclosureIds||[]);
            g.visitedEnclosureIds.add(String(g.lastEnclosureId));
            if(!Array.isArray(g.visitedOrder))g.visitedOrder=[];
            if(!g.visitedOrder.includes(String(g.lastEnclosureId)))g.visitedOrder.push(String(g.lastEnclosureId));
            g.visits++;
            const atFavourite=g.favouriteEnclosureId!=null&&String(g.lastEnclosureId)===String(g.favouriteEnclosureId);
            if(atFavourite)g.favouriteVisits=(Number(g.favouriteVisits)||0)+1;
            let watch=trueGuestWatchDuration(g.destinationAttractionLevel||1);
            if(atFavourite)watch=Math.min(24000,Math.max(5000,watch*1.8));
            if(!lightweightGuests&&g.groupId!=null){
                const peers=g._frameGroupPeers||[];
                const sameStop=peers.find(x=>x!==g&&String(x.lastEnclosureId)===String(g.lastEnclosureId)&&Number.isFinite(x.groupWatchBase));
                const base=sameStop?.groupWatchBase??watch;
                g.groupWatchBase=base;
                watch=Math.max(1000,Math.min(atFavourite?24000:15000,base-1000+Math.random()*2000));
            }else g.groupWatchBase=null;
            g.wait=watch;
            trueGuestChooseDestination(g);continue;}
        const dx=dest.x-g.x,dy=dest.y-g.y,distSq=dx*dx+dy*dy,step=g.speed*dt,stepSq=step*step;
        let nx=g.x,ny=g.y,dist=Math.sqrt(distSq);
        if(distSq<=stepSq){nx=dest.x;ny=dest.y;}
        else if(dist){nx+=dx/dist*step;ny+=dy/dist*step;}

        g.x=nx;g.y=ny;
        if(dist<=step)g.pathIndex++;

        if(g.leaving){
            const exit=frameEntrance;
            const exitClearance=Math.max(8,(Number(g.radius)||0)+3);
            if(exit){
                const exitDx=g.x-exit.x,exitDy=g.y-exit.y;
                if(exitDx*exitDx+exitDy*exitDy<=exitClearance*exitClearance){
                trueGuestRemove(g,now,guestIndex);
                continue;
                }
            }
        }
        if(frameGrounds){
            const bodyInset=Math.max(1,(Number(g.radius)||0)+2);
            g.x=Math.max(frameGrounds.x+bodyInset,Math.min(frameGrounds.x+frameGrounds.w-bodyInset,g.x));
            g.y=Math.max(frameGrounds.y+bodyInset,Math.min(frameGrounds.y+frameGrounds.h-bodyInset,g.y));
        }
        if(paintGuests&&g.el?.isConnected)g.el.style.transform=`translate3d(${g.x}px,${g.y}px,0) translate(-50%,-50%)`;
    }
}
let trueGuestLastFrameErrorAt=0;
function trueGuestTick(now){
    trueGuestRuntime.raf=0;
    try{
        trueGuestTickFrame(now);
    }catch(error){
        if(now-trueGuestLastFrameErrorAt>2000){
            trueGuestLastFrameErrorAt=now;
            console.warn('Guest animation frame recovered from an error:',error);
        }
    }finally{
        if(state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo&&document.getElementById('trueGuestLayer')){
            if((Number(state.trueCalendar?.speed)||0)===0){
                clearTimeout(trueGuestRuntime.idleTimer);
                trueGuestRuntime.idleTimer=setTimeout(()=>{
                    trueGuestRuntime.idleTimer=0;
                    if(!trueGuestRuntime.raf)trueGuestRuntime.raf=requestAnimationFrame(trueGuestTick);
                },160);
            }else{
                trueGuestRuntime.raf=requestAnimationFrame(trueGuestTick);
            }
        }
    }
}
function ensureTrueGuestSimulation(){
    if(state.gameMode!=='true'||state.sandboxMode||state.visitingZoo){
        if(trueGuestRuntime.raf)cancelAnimationFrame(trueGuestRuntime.raf);trueGuestRuntime.raf=0;
        clearTimeout(trueGuestRuntime.idleTimer);trueGuestRuntime.idleTimer=0;
        document.getElementById('trueGuestLayer')?.remove();
        for(const g of trueGuestRuntime.guests)g.el?.remove();trueGuestRuntime.guests=[];trueGuestRuntime.spawnQueue=0;trueGuestRuntime.spawnGroupId=null;trueGuestRuntime.nextSpawnAt=0;trueGuestRuntime.nextGroupAt=0;trueGuestRuntime.last=0;return;
    }
    trueGuestLayer();
    if(!trueGuestRuntime.raf)trueGuestRuntime.raf=requestAnimationFrame(trueGuestTick);
}

function ensureTrueSimulationPanel() {
    const controls = document.getElementById('exchangeControls');
    if (!controls) return null;
    let panel = document.getElementById('trueSimulationPanel');
    if (!panel) {
        panel = document.createElement('section');
        panel.id = 'trueSimulationPanel';
        panel.setAttribute('aria-label', 'True mode calendar and activity');
        const outgoingAnchor = outgoingOfferBox && outgoingOfferBox.parentElement === controls
            ? outgoingOfferBox
            : (outgoingOfferBox && outgoingOfferBox.parentElement && outgoingOfferBox.parentElement.parentElement === controls
                ? outgoingOfferBox.parentElement
                : null);
        if (outgoingAnchor) controls.insertBefore(panel, outgoingAnchor);
        else controls.appendChild(panel);
    }
    return panel;
}

function trueTransferById(id){return normaliseTrueTransfers().find(t=>String(t.id)===String(id))||null;}
function trueTransferLegForActivity(item){
    const t=trueTransferById(item?.transferId);if(!t)return {transfer:null,leg:null,animal:null};
    trueTransferNormaliseLegs(t);
    const leg=t.incomings.find(l=>String(l.legId)===String(item?.transferLegId))||t.incomings[0]||null;
    const animal=leg?(state.animals||[]).find(a=>String(a.trueIncomingTransferId)===String(t.id)&&String(a.trueIncomingTransferLegId)===String(leg.legId)):null;
    return {transfer:t,leg,animal};
}

function startTrueArrivalOverlayDrag(event,animal,sourceEl){
    if(event.button!==0||!animal?.trueArrivalPending||state.drag||state.pan)return;
    event.preventDefault();event.stopPropagation();
    const rect=sourceEl.getBoundingClientRect();
    const relativeX=(event.clientX-rect.left)/Math.max(1,rect.width);
    const relativeY=(event.clientY-rect.top)/Math.max(1,rect.height);
    const dragWidth=ANIMAL_W*state.zoom,dragHeight=ANIMAL_H*state.zoom;
    const ghost=document.createElement('img');ghost.className='dragging-animal';
    applyLocalizedAnimalImage(ghost,animal);
    Object.assign(ghost.style,{position:'fixed',width:`${dragWidth}px`,height:`${dragHeight}px`,objectFit:'contain',pointerEvents:'none',zIndex:'10030'});
    document.body.appendChild(ghost);
    const position=e=>{ghost.style.left=`${e.clientX-relativeX*dragWidth}px`;ghost.style.top=`${e.clientY-relativeY*dragHeight}px`;};
    position(event);
    state.drag={
        type:'animal',animal,location:'true-arrival-overlay',
        exchangeGlowIds:new Set(),compatibilityGlowKeys:new Set(),
        emergencyTradeAtDragStart:null,liveTradeOffersAtDragStart:[],
        originalEnclosureId:null,originalSlotIndex:null,
        originalLooseX:null,originalLooseY:null,originalWasTrueLoose:false,
        originalWasTrueArrivalOverlay:true,originalExchangeIndex:-1,originalWasOutgoing:false,
        originalTradeOffers:null,originalSelectedTradeOpponent:null,
        offsetX:relativeX*dragWidth,offsetY:relativeY*dragHeight,image:ghost,
        startClientX:event.clientX,startClientY:event.clientY
    };
}

function trueTransferActivityCard(item,size=34){
    const {transfer,leg,animal}=trueTransferLegForActivity(item);
    const source=animal||leg?.animal||item?.animal;if(!source)return null;
    const img=document.createElement('img');applyLocalizedAnimalImage(img,source);
    img.className='true-transfer-activity-card';
    Object.assign(img.style,{width:`${size}px`,height:`${Math.round(size*ANIMAL_H/ANIMAL_W)}px`,objectFit:'contain',display:'block',borderRadius:'3px',
        boxShadow:(item.glowAnimal&&!leg?.completed)?'0 0 0 1px #d7b44a,0 0 9px 3px rgba(231,190,58,.9)':'0 1px 2px rgba(0,0,0,.2)',
        animation:(item.glowAnimal&&!leg?.completed)?'trueIncomingGlow 1.15s ease-in-out infinite alternate':'none',
        cursor:animal&&animal.trueArrivalPending?'grab':'default'});
    img.title=animal&&animal.trueArrivalPending?'Drag this arriving population into an enclosure':
        (leg?.completed?'Placed in the zoo':transfer?.arrivalDate?`Expected ${formatTrueDate(transfer.arrivalDate,false)}`:'Incoming population');
    if(animal&&animal.trueArrivalPending){
        img.addEventListener('pointerdown',e=>startTrueArrivalOverlayDrag(e,animal,img));
    }
    return img;
}
function ensureTrueIncomingGlowStyle(){
    if(document.getElementById('trueIncomingGlowStyle'))return;
    const st=document.createElement('style');st.id='trueIncomingGlowStyle';
    st.textContent='@keyframes trueIncomingGlow{from{filter:drop-shadow(0 0 2px rgba(231,190,58,.65))}to{filter:drop-shadow(0 0 10px rgba(255,216,78,1))}}';
    document.head.appendChild(st);
}
function renderTrueIncomingTransferOverlay(){
    let host=document.getElementById('trueIncomingTransferOverlay');
    if(state.gameMode!=='true'||state.sandboxMode||state.visitingZoo){
        host?.remove();return;
    }
    const transfers=normaliseTrueTransfers().map(trueTransferNormaliseLegs).filter(t=>t.status==='awaiting-placement');
    const legs=[];
    for(const t of transfers)for(const leg of t.incomings||[]){
        if(leg.completed)continue;
        const actual=(state.animals||[]).find(a=>String(a.trueIncomingTransferId)===String(t.id)&&String(a.trueIncomingTransferLegId)===String(leg.legId)&&a.trueArrivalPending);
        if(actual)legs.push({t,leg,actual});
    }
    if(!legs.length){host?.remove();return;}
    ensureTrueIncomingGlowStyle();
    if(!host){host=document.createElement('div');host.id='trueIncomingTransferOverlay';document.body.appendChild(host);}
    const proposal=document.getElementById('trueTransferProposalPanel');
    const pr=proposal?.getBoundingClientRect();
    const top=Math.min(window.innerHeight-330,Math.max(86,(pr?.bottom||82)+12));
    Object.assign(host.style,{position:'fixed',right:'18px',top:`${top}px`,zIndex:'10005',display:'flex',flexDirection:'column',alignItems:'flex-end',gap:'10px',pointerEvents:'none'});
    host.innerHTML='';
    for(const {t,leg,actual} of legs.slice(0,3)){
        const wrap=document.createElement('div');wrap.style.cssText='position:relative;pointer-events:auto;text-align:right;';
        const img=document.createElement('img');applyLocalizedAnimalImage(img,actual||leg.animal);
        Object.assign(img.style,{width:`${ANIMAL_W*2}px`,height:`${ANIMAL_H*2}px`,objectFit:'contain',display:'block',
            filter:'drop-shadow(0 0 7px rgba(238,196,54,.95))',animation:'trueIncomingGlow 1.15s ease-in-out infinite alternate',
            cursor:actual&&actual.trueArrivalPending?'grab':'default'});
        const note=document.createElement('div');
        note.textContent='ARRIVED · drag into an enclosure';
        note.style.cssText='margin-top:2px;padding:3px 6px;border-radius:5px;background:rgba(243,239,227,.96);border:1px solid rgba(70,60,45,.35);font-size:10px;font-weight:800;color:#30291f;';
        if(actual&&actual.trueArrivalPending){
            img.title='Drag into a suitable enclosure';
            img.addEventListener('pointerdown',e=>startTrueArrivalOverlayDrag(e,actual,img));
        }else img.title=`Accepted transfer · expected ${formatTrueDate(t.arrivalDate,false)}`;
        wrap.append(img,note);host.appendChild(wrap);
    }
}

function trueHideZooVisitControls(){
    if(state.gameMode!=='true')return;
    for(const el of document.querySelectorAll('[data-action="visit-zoo"],.visit-zoo-btn,.visitZooBtn,#visitZooBtn')){
        el.style.display='none';
    }
}
function renderTrueSimulationPanel() {
    const classicOpponentUi=document.getElementById('opponentZoos');
    if(classicOpponentUi)classicOpponentUi.style.setProperty('display','none','important');
    const classicOpponentHeader=document.getElementById('otherZoosHeader');
    if(classicOpponentHeader)classicOpponentHeader.style.setProperty('display','none','important');
    trueHideZooVisitControls();
    refreshTruePausedOverlay();
    const panel = document.getElementById('trueSimulationPanel') || (state.gameMode === 'true' ? ensureTrueSimulationPanel() : null);
    if (!panel) return;
    if (state.gameMode !== 'true' || state.sandboxMode) { panel.style.display = 'none'; return; }
    panel.style.display = 'flex';
    if(!panel.dataset.pointerIsolationBound){
        panel.dataset.pointerIsolationBound='1';
        panel.addEventListener('pointerdown',e=>{
            if(e.target?.closest?.('button,input,select,textarea,a,[role="button"]'))e.stopPropagation();
        });
    }
    normaliseTrueCalendarState();
    ensureTrueGuestSimulation();

    const minHeight=170;
    const savedHeight=Math.max(minHeight,Math.min(window.innerHeight-40,Number(state.trueActivityPanelHeight)||minHeight));
    state.trueActivityPanelHeight=savedHeight;
    const unread = state.trueActivityLog.filter(item => item.unread).length;
    const recent = state.trueActivityLog.slice(0,80);
    panel.innerHTML = '';
    if(panel.parentElement!==document.body)document.body.appendChild(panel);
    const trueHeaderLeft=Math.max(190,Math.min(230,Math.round(window.innerWidth*.115)));
    const trueProposalReserve=Math.min(500,Math.max(400,Math.round(window.innerWidth*.245)));
    Object.assign(panel.style, {
        position:'fixed',left:`${trueHeaderLeft}px`,top:'12px',
        width:`calc(100vw - ${trueHeaderLeft + trueProposalReserve + 18}px)`,
        maxWidth:'none',minWidth:'420px',
        height:`${savedHeight}px`, minHeight:`${minHeight}px`, maxHeight:'calc(100vh - 24px)', boxSizing:'border-box',
        flexDirection:'column', gap:'6px', padding:'9px 12px 13px', border:'1px solid #bbb6aa',
        borderRadius:'8px', background:'#ebe8df', color:'#30291f', overflow:'hidden',
        boxShadow:'0 3px 8px rgba(0,0,0,.12)',zIndex:'10020'
    });

    const top = document.createElement('div');
    top.style.cssText='display:grid;grid-template-columns:minmax(180px,1fr) auto auto;align-items:center;gap:14px;min-height:30px;';
    const zooIdentity=document.createElement('button');
    zooIdentity.type='button';zooIdentity.className='true-activity-zoo-name';
    zooIdentity.title='Change zoo name';
    zooIdentity.innerHTML=`<span>${escapeHtml(String(state.visitingZoo?.name||state.zooName||'Zoo'))}</span>${state.visitingZoo?'':' <span aria-hidden="true" style="font-size:12px;opacity:.65">✎</span>'}`;
    zooIdentity.style.cssText='border:0;background:transparent;padding:0;text-align:left;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:inherit;font-size:17px;font-weight:900;color:inherit;cursor:pointer;';
    zooIdentity.disabled=!!state.visitingZoo;
    zooIdentity.addEventListener('click',()=>{
        const edit=playerZooName?.querySelector?.('.zoo-name-edit-button');
        if(edit&&!edit.disabled)edit.click();
    });

    const date = document.createElement('strong'); const cal=normaliseTrueCalendarState();
    date.id='trueCalendarVisualClock';
    const shownCal=trueCalendarDisplayParts();
    date.textContent = `${String(shownCal.hour).padStart(2,'0')}:${String(shownCal.minute).padStart(2,'0')} - ${formatTrueDate(shownCal.date)}`;
    date.style.cssText='font-size:15px;white-space:nowrap;font-variant-numeric:tabular-nums;';
    ensureTrueCalendarVisualClock();

    const speedCluster=document.createElement('div');speedCluster.style.cssText='display:flex;align-items:center;gap:9px;';
    const guestCounter=document.createElement('span');
    guestCounter.id='trueGuestsTodayCounter';
    guestCounter.title='Total visitors who have entered the zoo today';
    guestCounter.style.cssText='font-size:10px;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums;';
    guestCounter.textContent=`Guests today: ${Math.max(0,Math.round(Number(trueGuestRuntime?.dailyEntered)||0))}`;

    const speeds = document.createElement('div'); speeds.style.cssText='display:flex;gap:4px;';
    for (const speed of TRUE_CALENDAR_SPEEDS) {
        const button=document.createElement('button'); button.type='button';
        button.textContent=speed===0?'⏸':speed===1?'▶':speed===2?'▶▶':'▶▶▶';
        button.title=speed===0?'Pause':speed===1?'Regular — 5 minutes per tick':speed===2?'Fast — 1 hour per tick':'Max — 10 hours per tick (simulate 09:00–19:00)';
        button.setAttribute('aria-label',button.title);
        button.dataset.trueCalendarSpeed=String(speed);
        button.style.cssText=`min-width:34px;height:28px;padding:0 7px;border-radius:6px;border:1px solid #aaa69b;background:#fffdf6;color:#30291f;cursor:pointer;font-size:10px;font-weight:700;${state.trueCalendar.speed===speed?'outline:2px solid #9b8b48;outline-offset:1px;background:#fff;':''}`;
        button.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();setTrueCalendarSpeed(speed);});
        button.addEventListener('click',event=>event.preventDefault());
        speeds.appendChild(button);
    }
    speedCluster.append(guestCounter,speeds);
    top.append(zooIdentity,date,speedCluster); panel.appendChild(top);

    const heading=document.createElement('div');
    heading.style.cssText='display:flex;justify-content:space-between;align-items:center;font-size:11px;letter-spacing:.08em;font-weight:800;opacity:.9;border-top:1px solid rgba(70,58,39,.18);padding-top:6px;';
    heading.innerHTML=`<span>ACTIVITY${unread ? ` (${unread})` : ''}</span>`;
    const headingActions=document.createElement('div');headingActions.style.cssText='display:flex;align-items:center;gap:8px;';
    const roundButton=document.createElement('button');roundButton.type='button';roundButton.textContent='Start curator round';roundButton.title='Inspect a few useful observations from around the zoo';roundButton.style.cssText='font-size:10px;padding:3px 7px;border-radius:5px;border:1px solid #aaa69b;background:#fffdf6;color:#30291f;cursor:pointer;font-weight:700;letter-spacing:0;';roundButton.addEventListener('click',trueStartCuratorRound);
    const latest=document.createElement('span');latest.textContent='latest';latest.style.cssText='opacity:.6;font-weight:600;letter-spacing:.08em;';headingActions.append(roundButton,latest);heading.appendChild(headingActions);
    panel.appendChild(heading);

    const list=document.createElement('div');
    list.style.cssText='display:flex;flex:1 1 auto;flex-direction:column;gap:3px;overflow:auto;min-height:0;padding-right:4px;padding-bottom:3px;';
    if (!recent.length) {
        const empty=document.createElement('div'); empty.textContent='No activity yet.'; empty.style.cssText='font-size:12px;opacity:.62;padding:5px 0;'; list.appendChild(empty);
    }
    for (const item of recent) {
        const itemDateText=`${formatTrueDate(item.date,false)}${item.time?` · ${item.time}`:''}`;
        const activityTransferState=item.transferId?trueTransferLegForActivity(item):null;
        const hasTransferCard=!!(item.glowAnimal&&activityTransferState?.animal?.trueArrivalPending);
        const row=document.createElement('div');
        row.style.cssText=`display:grid;grid-template-columns:7px ${hasTransferCard?'38px ':''}minmax(0,1fr) auto 116px;gap:6px;align-items:start;font-size:11px;padding:4px 0;${item.unread?'font-weight:700;':''}`;
        const dot=document.createElement('span'); dot.textContent=item.unread?'●':'·'; dot.style.opacity=item.unread?'1':'.45';
        const copy=document.createElement('div'); copy.style.minWidth='0';
        copy.innerHTML=`<div style="line-height:1.25">${escapeHtml(item.title||'')}</div><div style="opacity:.66;font-weight:400;line-height:1.3;white-space:normal;overflow-wrap:anywhere">${escapeHtml(item.message||'')}</div>`;
        row.appendChild(dot);
        if(hasTransferCard){const mini=trueTransferActivityCard(item,32);if(mini)row.appendChild(mini);}
        row.appendChild(copy);
        if (item.actionLabel && item.action) {
            const b=document.createElement('button');
            b.type='button';b.textContent=item.actionLabel;
            b.style.cssText='font-size:10px;padding:3px 6px;border-radius:5px;white-space:nowrap;position:relative;z-index:2;pointer-events:auto;cursor:pointer;';
            b.addEventListener('pointerdown',e=>e.stopPropagation());
            b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();runTrueActivityAction(item);});
            row.appendChild(b);
        }
        else row.appendChild(document.createElement('span'));
        const dateCol=document.createElement('span');dateCol.textContent=itemDateText;dateCol.style.cssText='opacity:.52;font-size:9px;font-weight:600;white-space:nowrap;text-align:right;font-variant-numeric:tabular-nums;padding-top:1px;';row.appendChild(dateCol);
        row.addEventListener('click',()=>{
            if(!item.unread)return;
            item.unread=false;dot.textContent='·';dot.style.opacity='.45';row.style.fontWeight='';
            const unreadNow=state.trueActivityLog.filter(entry=>entry.unread).length;
            heading.firstElementChild.textContent=`ACTIVITY${unreadNow?` (${unreadNow})`:''}`;
        });
        list.appendChild(row);
    }
    panel.appendChild(list);

    const resize=document.createElement('div');
    resize.className='true-activity-resize-handle';
    resize.title='Drag to resize Activity Center';
    resize.setAttribute('aria-label','Resize Activity Center');
    resize.style.cssText='position:absolute;left:10px;right:10px;bottom:0;height:10px;cursor:ns-resize;z-index:3;touch-action:none;';
    const grip=document.createElement('div');
    grip.style.cssText='position:absolute;left:50%;bottom:2px;transform:translateX(-50%);width:48px;height:3px;border-radius:3px;background:rgba(70,58,39,.28);';
    resize.appendChild(grip);
    resize.addEventListener('pointerdown',event=>{
        if(event.button!==0)return;
        event.preventDefault();event.stopPropagation();
        const startY=event.clientY,startHeight=panel.getBoundingClientRect().height;
        resize.setPointerCapture?.(event.pointerId);
        const move=e=>{
            const next=Math.max(minHeight,Math.min(window.innerHeight-24,startHeight+(e.clientY-startY)));
            panel.style.height=`${next}px`;state.trueActivityPanelHeight=Math.round(next);
        };
        const finish=()=>{
            resize.removeEventListener('pointermove',move);resize.removeEventListener('pointerup',finish);resize.removeEventListener('pointercancel',finish);
            writeAutoResumeSnapshot?.(true);
            try{renderTrade();}catch(_){}
        };
        resize.addEventListener('pointermove',move);resize.addEventListener('pointerup',finish);resize.addEventListener('pointercancel',finish);
    });
    panel.appendChild(resize);
    trueApplyDesktopHeaderGeometry();
    renderTrueIncomingTransferOverlay();
}

let turnDisplaySignature='';
function updateTurnDisplay() {
    const trueHidden=state.gameMode==='true'&&!state.sandboxMode;
    const text=trueHidden?'':state.sandboxMode
        ? 'Turn ∞ · SANDBOX'
        : state.historyViewTurn!==null
            ? `Turn ${state.historyViewTurn} · VIEWING`
            : `Turn ${state.turn}`;
    const signature=`${trueHidden?'1':'0'}|${text}`;
    if(signature===turnDisplaySignature)return;
    turnDisplaySignature=signature;
    turnOrder.style.display=trueHidden?'none':'';
    if(playerZooName)playerZooName.style.visibility=trueHidden?'hidden':'';
    if(!trueHidden)turnOrder.textContent=text;
}

