function applyTrueViewToggleState(){
    const trueMode=state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo;
    const panel=document.getElementById('trueViewTogglePanel');if(panel)panel.style.display=trueMode?'flex':'none';
    const sex=state.gameOptions?.showSexIndicators===true;
    state.trueSexCountsAlways=sex;document.body.classList.toggle('true-sex-always',trueMode&&sex);
    const mode=[0,1,2].includes(Number(state.gameOptions?.animalCardVisibilityMode))?Number(state.gameOptions.animalCardVisibilityMode):0;
    document.body.dataset.animalCardView=trueMode?(mode===1?'dim':mode===2?'enclosure':'all'):'all';
    const trees=state.gameOptions?.showTopLayerTrees!==false;document.body.classList.toggle('true-top-trees-hidden',trueMode&&!trees);
    const sexB=document.getElementById('trueViewSexToggle');if(sexB){sexB.textContent=`Sex: ${sex?'On':'Off'}`;sexB.classList.toggle('active',sex);}
    const preview=state.gameOptions?.showAnimalPreview!==false,previewB=document.getElementById('trueViewPreviewToggle');if(previewB){previewB.textContent=`Zoomed in animal card: ${preview?'On':'Off'}`;previewB.classList.toggle('active',preview);}
    const cardsB=document.getElementById('trueViewCardsToggle');if(cardsB){cardsB.textContent=`Animal cards: ${mode===0?'Visible':mode===1?'30%':'Enclosure hover'}`;cardsB.classList.toggle('active',mode!==0);}
    const treeB=document.getElementById('trueViewTreesToggle');if(treeB){treeB.textContent=`Trees: ${trees?'On':'Off'}`;treeB.classList.toggle('active',trees);}
}
function activeZooColourScheme(){
    const key=String(state.zooColourScheme||'overloon').toLowerCase();
    return ZOO_COLOUR_SCHEMES[key]?key:'overloon';
}
function activeZooPalette(){return ZOO_COLOUR_SCHEMES[activeZooColourScheme()];}
function applyZooColourScheme(){
    ensureTrueModeControlTheme();
    const key=activeZooColourScheme();
    state.zooColourScheme=key;
    document.body.dataset.zooColourScheme=key;

    const button=document.getElementById('zooColourSchemeButton');
    if(button) button.textContent=`Map: ${ZOO_COLOUR_SCHEMES[key].label}`;
    ensureTrueZooGroundsVisual?.();
}
function closeZooColourSchemeMenu(){
    document.getElementById('zooColourSchemeMenu')?.remove();
}
function toggleZooColourSchemeMenu(){
    const button=document.getElementById('zooColourSchemeButton');if(!button)return;
    const existing=document.getElementById('zooColourSchemeMenu');if(existing){existing.remove();return;}
    const menu=document.createElement('div');menu.id='zooColourSchemeMenu';
    for(const [key,scheme] of Object.entries(ZOO_COLOUR_SCHEMES)){
        const option=document.createElement('button');option.type='button';option.textContent=scheme.label;
        option.classList.toggle('active',activeZooColourScheme()===key);
        option.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();state.zooColourScheme=key;closeZooColourSchemeMenu();applyZooColourScheme();});
        menu.appendChild(option);
    }
    document.body.appendChild(menu);
    const r=button.getBoundingClientRect(),m=menu.getBoundingClientRect();
    menu.style.left=`${Math.max(8,Math.min(innerWidth-m.width-8,r.left))}px`;
    menu.style.top=`${Math.min(innerHeight-m.height-8,r.bottom+5)}px`;
}
function ensureZooColourSchemeUI(){
    const prestige=document.getElementById('prestigeCounter');if(!prestige)return;
    let stack=document.getElementById('prestigeSexStack');
    if(!stack){
        stack=document.createElement('span');stack.id='prestigeSexStack';
        stack.style.cssText='display:inline-flex;flex-direction:column;align-items:center;gap:2px;';
        prestige.parentElement?.insertBefore(stack,prestige);stack.appendChild(prestige);
    }
    let button=document.getElementById('zooColourSchemeButton');
    if(!button){
        button=document.createElement('button');button.id='zooColourSchemeButton';button.type='button';
        button.title='Choose zoo map colour scheme';
        button.addEventListener('pointerdown',e=>e.stopPropagation());
        button.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();toggleZooColourSchemeMenu();});
        stack.appendChild(button);
    }else if(button.parentElement!==stack) stack.appendChild(button);
    applyZooColourScheme();
}

function updatePrestigeDisplay() {
    const element = document.getElementById('prestigeCounter');
    if (!element) return;
    element.removeAttribute('title');
    if (state.visitingZoo) {
        const text=`Prestige ${currentZooPrestige()}`;
        if(element.textContent!==text)element.textContent=text;
        return;
    }
    if (state.sandboxMode) {
        const text=`Prestige ${currentZooPrestige()}`;
        if(element.textContent!==text)element.textContent=text;
        return;
    }
    const prestigeBreakdown=state.gameMode==='true'?null:zooPrestigeBreakdown();
    const underlyingPrestige=prestigeBreakdown?Math.ceil(Math.max(0,prestigeBreakdown.current)):currentZooPrestige();
    const prestige = state.gameMode==='true' ? visibleZooPrestige() : underlyingPrestige;
    state.highestZooPrestige = Math.max(
        Number(state.highestZooPrestige) || 0,
        state.gameMode==='true' ? prestige : underlyingPrestige
    );
    const prestigeText=`Prestige ${prestige}`;
    if(element.textContent!==prestigeText)element.textContent=prestigeText;
    if(state.gameMode==='true'){
        unbindPrestigeBreakdownHover(element);
        bindTruePrestigeTestingHover(element);
    }else{
        bindPrestigeBreakdownHover(element,()=>prestigeBreakdown);
    }
}

function exchangeGroupKey(animal) {
    return `${animal.category}|${animal.level}`;
}

let exchangeGroupCountsCache=null,exchangeGroupCountsAnimals=null,exchangeGroupCountsCachedRevision=-1;
let exchangeGroupCountsRevision=0;
function invalidateExchangeGroupCounts(){exchangeGroupCountsRevision++;}
function exchangeGroupCounts() {
    const dragActive=state.drag?.type==='animal';
    if(!dragActive&&exchangeGroupCountsCache&&exchangeGroupCountsAnimals===state.animals&&exchangeGroupCountsCachedRevision===exchangeGroupCountsRevision)return exchangeGroupCountsCache;
    const counts = new Map();
    const seen = new Set();

    const add = animal => {
        if (!animal || seen.has(animal.id)) return;
        seen.add(animal.id);
        const key = exchangeGroupKey(animal);
        counts.set(key, (counts.get(key) || 0) + 1);
    };

    for (const animal of state.animals) {
        if (animal.enclosureId !== null) add(animal);
    }

    for (const animal of state.exchange) add(animal);

    if (state.drag?.type === 'animal') {
        const drag = state.drag;
        if (drag.originalEnclosureId !== null || drag.originalExchangeIndex >= 0) {
            add(drag.animal);
        }
    }

    if(!dragActive){
        exchangeGroupCountsCache=counts;
        exchangeGroupCountsAnimals=state.animals;
        exchangeGroupCountsCachedRevision=exchangeGroupCountsRevision;
    }
    return counts;
}

let lastExchangeGlowCountsRef=null;
function refreshExchangeGlowSuppression() {
    const counts=exchangeGroupCounts();
    if(counts===lastExchangeGlowCountsRef)return;
    lastExchangeGlowCountsRef=counts;
    const increased=new Set();
    for(const [key,count] of counts)
        if(count>(state.lastExchangeGroupCounts.get(key)||0))increased.add(key);
    if(increased.size)for(const animal of state.animals||[])
        if(animal&&increased.has(exchangeGroupKey(animal)))state.suppressedExchangeGlowIds.delete(animal.id);
    state.lastExchangeGroupCounts=new Map(counts);
}

function eligibleExchangeCategories() {
    const counts = exchangeGroupCounts();
    const categories = new Set();
    const owned=playerOwnedCardKeys();

    for (const [key, count] of counts) {
        if (count < 3) continue;

        const separator=String(key).lastIndexOf('|');
        const level=Number(String(key).slice(separator+1));
        const category=String(key).slice(0,separator);

        if (hasNextLevelInventory(category, level, owned)) {
            categories.add(category);
        }
    }

    return [...categories];
}

function isExchangeEligible(animal) {
    if (state.gameMode === 'true') return false;
    if (!animal || animal.level >= 5) return false;

    if (!hasNextLevelInventory(animal.category, animal.level)) {
        return false;
    }

    return (exchangeGroupCounts().get(exchangeGroupKey(animal)) || 0) >= 3;
}

function activeExchangeGlowFocusKey() {
    const slotted = state.exchange.find(Boolean);
    if (slotted) return exchangeGroupKey(slotted);
    return state.exchangeGlowFocusKey || null;
}

function shouldGlowForExchange(animal) {
    if (!state.exchangeEligibilityHoverActive) return false;
    if (state.outgoingOfferHoverSuppressesExchangeGlow) return false;

    if (
        state.gameOptions.showEligibilityGlows === false ||
        !isExchangeEligible(animal) ||
        state.suppressedExchangeGlowIds.has(animal.id)
    ) {
        return false;
    }

    const focusKey = activeExchangeGlowFocusKey();
    return !focusKey || exchangeGroupKey(animal) === focusKey;
}

function clearExchangeGlowFocusIfIdle() {
    if (!state.exchange.some(Boolean) && !state.result) {
        state.exchangeGlowFocusKey = null;
    }
}

function refreshContextualExchangeEligibilityGlows() {
    const active =
        state.exchangeEligibilityHoverActive &&
        !state.outgoingOfferHoverSuppressesExchangeGlow &&
        state.gameOptions.showEligibilityGlows !== false &&
        localClassicCanShowProgressionActionGlows();

    const focusKey = activeExchangeGlowFocusKey();
    const eligibleKeys=new Set();
    if(active){
        const availability=new Map();
        for(const [key,count] of exchangeGroupCounts()){
            if(count<3||focusKey&&key!==focusKey)continue;
            const parts=String(key).split('|');
            const level=Number(parts.pop()),category=parts.join('|'),lookup=`${category}|${level}`;
            let available=availability.get(lookup);
            if(available===undefined){available=hasNextLevelInventory(category,level);availability.set(lookup,available);}
            if(available)eligibleKeys.add(key);
        }
    }

    classicDropDomElements().animalCards.forEach(card => {
        const animal=classicAnimalById(card.dataset.animalId);
        const eligible=Boolean(
            active &&
            animal &&
            eligibleKeys.has(exchangeGroupKey(animal)) &&
            !state.suppressedExchangeGlowIds.has(animal.id)
        );

        card.classList.toggle('exchange-eligible', eligible);
        if (!eligible) card.classList.remove('exchange-glow-return');
    });
}

function setExchangeEligibilityHover(active) {
    active = Boolean(active) && !state.sandboxMode && !visitingAnotherZooForActionUI() && localClassicCanShowProgressionActionGlows();
    if (state.exchangeEligibilityHoverActive === active) return;
    state.exchangeEligibilityHoverActive = active;
    refreshContextualExchangeEligibilityGlows();
    scheduleAnimalGlowPrecedenceRefresh();
}

function setOutgoingOfferExchangeGlowSuppression(active) {
    active = Boolean(active) && !state.sandboxMode;
    if (state.outgoingOfferHoverSuppressesExchangeGlow === active) return;

    state.outgoingOfferHoverSuppressesExchangeGlow = active;
    document.body.classList.toggle('trade-hover-suppress-exchange', active);

    if (active) {
        document.querySelectorAll('.animal-card.exchange-eligible')
            .forEach(card => card.classList.remove('exchange-eligible'));
        document.querySelectorAll('.animal-card.exchange-glow-return')
            .forEach(card => card.classList.remove('exchange-glow-return'));
        scheduleAnimalGlowPrecedenceRefresh();
        return;
    }

    document.body.classList.remove('trade-hover-suppress-exchange');

    refreshContextualExchangeEligibilityGlows();
    scheduleAnimalGlowPrecedenceRefresh();
}

function animalImage(animal) {

    return animalPath(
        animal.category,
        animal.level,
        animal.filename
    );

}

function handleImageAssetError(event) {
    const image=event.currentTarget;
    const description=image?.dataset?.assetDescription || 'asset';

    console.error(
        `Could not load ${description}:`,
        image.src
    );

    image.classList.add(
        'asset-error'
    );

    image.title =
        `Missing asset: ${image.src}`;
}

function attachImageError(
    image,
    description
) {
    image.dataset.assetDescription=String(description || 'asset');
    image.addEventListener(
        'error',
        handleImageAssetError
    );
}

const translatedCardImageCache = new Map();
const CARD_NAMEPLATE = Object.freeze({
    x:72, y:1288, width:856, height:126,
    background:'#f0e4c0', foreground:'#2b1708'
});
const CARD_CATEGORYPLATE = Object.freeze({
    x:220, y:18, width:760, height:108,
    foreground:'#2b1708'
});

function normaliseTranslationKey(value) {
    return String(value || '')
        .replace(/\.[^.]+$/, '')
        .replace(/[‐‑‒–—_-]+/g, ' ')
        .replace(/[’‘]/g, "'")
        .replace(/\s+/g, ' ')
        .trim()
        .toLocaleLowerCase('en');
}

function translationLookup(table, value) {
    if (!table) return null;
    if (Object.prototype.hasOwnProperty.call(table, value)) return table[value];
    const wanted = normaliseTranslationKey(value);
    for (const [key, translated] of Object.entries(table)) {
        if (normaliseTranslationKey(key) === wanted) return translated;
    }
    return null;
}

function dutchAnimalName(animal) {
    return translationLookup(
        window.ZOO_TRANSLATIONS?.nl?.animals,
        animalDisplayName(animal)
    );
}

function dutchCategoryName(category) {
    return translationLookup(
        window.ZOO_TRANSLATIONS?.nl?.categories,
        category
    );
}

function splitCardNameLines(ctx,text,maxWidth) {
    const words=String(text||'').trim().split(/\s+/).filter(Boolean);
    if (!words.length || ctx.measureText(text).width<=maxWidth) return [text];
    let best=null;
    for(let i=1;i<words.length;i++){
        const a=words.slice(0,i).join(' '),b=words.slice(i).join(' ');
        const w=Math.max(ctx.measureText(a).width,ctx.measureText(b).width);
        if(!best||w<best.w)best={lines:[a,b],w};
    }
    return best?.lines||[text];
}

function paintDutchCardName(ctx,name) {
    const p=CARD_NAMEPLATE;
    ctx.fillStyle=p.background;
    ctx.fillRect(p.x,p.y,p.width,p.height);
    const maxWidth=p.width-34;
    let size=102,lines=[name];
    for(;size>=46;size-=2){
        ctx.font=`700 ${size}px Arial, Helvetica, sans-serif`;
        lines=splitCardNameLines(ctx,name,maxWidth);
        const widest=Math.max(...lines.map(x=>ctx.measureText(x).width));
        if(widest<=maxWidth && (lines.length===1 || size<=70)) break;
    }
    ctx.fillStyle=p.foreground;
    ctx.textAlign='center';
    ctx.textBaseline='middle';
    ctx.font=`700 ${size}px Arial, Helvetica, sans-serif`;
    const cx=p.x+p.width/2,cy=p.y+p.height/2;
    if(lines.length===1)ctx.fillText(lines[0],cx,cy+2);
    else {
        const lh=size*.91;
        ctx.fillText(lines[0],cx,cy-lh/2);
        ctx.fillText(lines[1],cx,cy+lh/2);
    }
}

function sampledCategoryColour(ctx) {
    const points=[[930,32],[850,28],[760,24],[500,20]];
    const samples=[];
    for(const [x,y] of points){
        try {
            const d=ctx.getImageData(x,y,1,1).data;
            if(d[3]>240)samples.push([d[0],d[1],d[2]]);
        } catch {}
    }
    if(!samples.length)return '#a26248';
    const avg=i=>Math.round(samples.reduce((s,v)=>s+v[i],0)/samples.length);
    return `rgb(${avg(0)}, ${avg(1)}, ${avg(2)})`;
}

function paintDutchCardCategory(ctx,name) {
    if(!name)return;
    const p=CARD_CATEGORYPLATE;
    ctx.fillStyle=sampledCategoryColour(ctx);
    ctx.fillRect(p.x,p.y,p.width,p.height);
    ctx.fillRect(p.x, p.y + p.height - 2, p.width, 22);
    const maxWidth=p.width-36;
    let size=88;
    for(;size>=48;size-=2){
        ctx.font=`700 ${size}px Arial, Helvetica, sans-serif`;
        if(ctx.measureText(name).width<=maxWidth)break;
    }
    ctx.fillStyle=p.foreground;
    ctx.textAlign='center';
    ctx.textBaseline='middle';
    ctx.font=`700 ${size}px Arial, Helvetica, sans-serif`;
    ctx.fillText(name,p.x+p.width/2,p.y+p.height/2+2);
}

function translatedAnimalCardUrl(animal) {
    const name=dutchAnimalName(animal);
    const categoryName=dutchCategoryName(animal?.category);
    const source=animalImage(animal);
    if(!name && !categoryName)return Promise.resolve(source);
    const key=`${source}|nl|${name||''}|${categoryName||''}`;
    if(translatedCardImageCache.has(key))return translatedCardImageCache.get(key);
    const promise=new Promise(resolve=>{
        const im=new Image();
        im.onload=()=>{
            try{
                const c=document.createElement('canvas');
                c.width=im.naturalWidth||1000;
                c.height=im.naturalHeight||1440;
                const ctx=c.getContext('2d');
                ctx.drawImage(im,0,0,c.width,c.height);
                ctx.save();
                ctx.scale(c.width/1000,c.height/1440);
                if(categoryName)paintDutchCardCategory(ctx,categoryName);
                if(name)paintDutchCardName(ctx,name);
                ctx.restore();
                c.toBlob(blob=>resolve(blob?URL.createObjectURL(blob):source),'image/png');
            }catch(e){
                console.warn('Dutch card overlay failed:',e);
                resolve(source);
            }
        };
        im.onerror=()=>resolve(source);
        im.src=source;
    });
    translatedCardImageCache.set(key,promise);
    return promise;
}

let localizedAnimalImageTokenCounter=0;
function applyLocalizedAnimalImage(image,animal) {
    const source=animalImage(animal);
    image.src=source;

    if(state.gameOptions.animalLanguage!=='nl'){
        delete image.dataset.localizedImageToken;
        return;
    }

    const token=String(++localizedAnimalImageTokenCounter);
    image.dataset.localizedImageToken=token;
    translatedAnimalCardUrl(animal).then(url=>{
        if(image.dataset.localizedImageToken===token&&state.gameOptions.animalLanguage==='nl')image.src=url;
    });
}

const uiOriginalText = new WeakMap();
const uiLocalizedTextNodes = new Set();
const uiLocalizedAttributeElements = new Set();
let uiLocalisationBusy = false;
let uiLocalisationQueued = false;

function translateUiString(text) {
    const table=window.ZOO_TRANSLATIONS?.nl?.ui||{};
    const categories=window.ZOO_TRANSLATIONS?.nl?.categories||{};
    const leading=(text.match(/^\s*/)||[''])[0];
    const trailing=(text.match(/\s*$/)||[''])[0];
    let core=text.trim();
    if(!core)return text;

    core=core.replace(/\s+/g, ' ');

    if(table[core]) core=table[core];
    else if(categories[core]) core=categories[core];
    else {
        core=core
            .replace(/^Turn (\d+)$/, 'Beurt $1')
            .replace(/^Level (\d+)$/, 'Niveau $1')
            .replace(/^Enclosure (\d+)$/, 'Verblijf $1')
            .replace(/^Decline \((\d+) turns? left\)$/, 'Weigeren ($1 beurten over)')
            .replace(/^Current Turn (\d+)$/, 'Huidige beurt $1')
            .replace(/^Current turn$/, 'Huidige beurt')
            .replace(/^Viewing Turn (\d+) — READ ONLY$/, 'Beurt $1 bekijken — ALLEEN LEZEN')
            .replace(/^Turn (\d+) - (.+)$/, 'Beurt $1 - $2')
            .replace(/^(.+) — Turn (\d+)$/, '$1 — Beurt $2')
            .replace(/^Turn (\d+) · VIEWING$/, 'Beurt $1 · BEKIJKEN')
            .replace(/(\d+) animals\b/g, '$1 dieren')
            .replace(/(\d+) enclosure cards\b/g, '$1 verblijfskaarten')
            .replace(/(\d+) starting animals\b/g, '$1 startdieren')
            .replace(/cards up to Level (\d+)/g, 'kaarten tot niveau $1')
            .replace(/(\d+) starting enclosure spaces\b/g, '$1 startplaatsen')
            .replace(/(\d+) spare spaces\b/g, '$1 vrije plaatsen')
            .replace(/Starting collection size:/g, 'Grootte startcollectie:')
            .replace(/Starting zoo size:/g, 'Grootte startdierentuin:')
            .replace(/Trade offer frequency:/g, 'Frequentie ruilaanbiedingen:')
            .replace(/Exchange 2 → Level (\d+)/g, 'Ruil 2 → niveau $1')
            .replace(/Level (\d+) Animals/g, 'Niveau $1-dieren')
            .replace(/^Country:\s*/i, 'Land: ')
            .replace(/^Province:\s*/i, 'Provincie: ')
            .replace(/^Location:\s*/i, 'Plaats: ')
            .replace(/^Zoo type:\s*/i, 'Type dierentuin: ')
            .replace(/^Prestige (\d+(?:\.\d+)?)$/i, 'Prestige $1')
            .replace(/^New Zoo:\s*/i, 'Nieuwe dierentuin: ')
            .replace(/^Originally from (.+)\.$/, 'Oorspronkelijk uit $1.')
            .replace(/^Exchanged by (.+) for$/, 'Ingeruild door $1 voor')
            .replace(/^(.+) — Trade History$/, '$1 — Ruilgeschiedenis')
            .replace(/^No trades with this zoo yet\.$/, 'Nog geen ruiltransacties met deze dierentuin.')
            .replace(/^No trades completed yet\.$/, 'Nog geen ruiltransacties voltooid.')
            .replace(/^COUNTRY:\s*/gmi, 'LAND: ')
            .replace(/^PROVINCE:\s*/gmi, 'PROVINCIE: ')
            .replace(/^LOCATION:\s*/gmi, 'PLAATS: ')
            .replace(/^Shown by:$/gmi, 'Getoond door:')
            .replace(/^First arrived at the zoo: Turn (\d+)$/gmi, 'Voor het eerst in de dierentuin: beurt $1')
            .replace(/^Acquisitions:$/gmi, 'Verkregen:')
            .replace(/^Shared exhibits:$/gmi, 'Gedeelde verblijven:')
            .replace(/^Departures:$/gmi, 'Vertrokken:')
            .replace(/^Turn (\d+): acquired$/gmi, 'Beurt $1: verkregen')
            .replace(/^Turn (\d+): acquired from (.+)$/gmi, 'Beurt $1: verkregen van $2')
            .replace(/^(.+) — from Turn (\d+)$/gmi, '$1 — vanaf beurt $2')
            .replace(/^Would you like to save (.+) before opening the New Zoo menu\?$/i, 'Wil je $1 opslaan voordat je het menu Nieuwe dierentuin opent?');
    }
    return leading+core+trailing;
}

function uiText(english) {
    if (state?.gameOptions?.animalLanguage !== 'nl') return english;
    return window.ZOO_TRANSLATIONS?.nl?.ui?.[english] || translateUiString(english);
}

function localizeDocument() {
    if(uiLocalisationBusy)return;
    uiLocalisationBusy=true;
    try {
        const dutch=state?.gameOptions?.animalLanguage==='nl';
        if (drawCard) drawCard.dataset.label = multiplayerVisitTheirOfferMode?.()
            ? (dutch?'HUN AANBOD':'THEIR OFFER')
            : (dutch?'TREK KAART':'DRAW CARD');

        if(dutch){
            const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
            while(walker.nextNode()){
                const node=walker.currentNode;
                const parent=node.parentElement;
                if(!parent || ['SCRIPT','STYLE','TEXTAREA'].includes(parent.tagName))continue;
                if(!uiOriginalText.has(node))uiOriginalText.set(node,node.nodeValue);
                const translated=translateUiString(uiOriginalText.get(node));
                if(node.nodeValue!==translated)node.nodeValue=translated;
                uiLocalizedTextNodes.add(node);
            }
            for(const el of document.querySelectorAll('[aria-label],[title],[placeholder]')){
                for(const attr of ['aria-label','title','placeholder']){
                    if(!el.hasAttribute(attr))continue;
                    const key=`i18nOriginal${attr.replace(/-([a-z])/g,(_,c)=>c.toUpperCase()).replace(/^./,c=>c.toUpperCase())}`;
                    if(!(key in el.dataset))el.dataset[key]=el.getAttribute(attr);
                    const translated=translateUiString(el.dataset[key]);
                    if(el.getAttribute(attr)!==translated)el.setAttribute(attr,translated);
                }
                uiLocalizedAttributeElements.add(el);
            }
        }else{
            for(const node of [...uiLocalizedTextNodes]){
                if(!node?.isConnected){uiLocalizedTextNodes.delete(node);continue;}
                if(uiOriginalText.has(node)){
                    const original=uiOriginalText.get(node);
                    if(node.nodeValue!==original)node.nodeValue=original;
                }
            }
            for(const el of [...uiLocalizedAttributeElements]){
                if(!el?.isConnected){uiLocalizedAttributeElements.delete(el);continue;}
                for(const attr of ['aria-label','title','placeholder']){
                    const key=`i18nOriginal${attr.replace(/-([a-z])/g,(_,c)=>c.toUpperCase()).replace(/^./,c=>c.toUpperCase())}`;
                    if(key in el.dataset&&el.getAttribute(attr)!==el.dataset[key])
                        el.setAttribute(attr,el.dataset[key]);
                }
            }
        }
    } finally {
        uiLocalisationBusy=false;
    }
}
function queueDocumentLocalisation(){
    if(uiLocalisationQueued)return;
    uiLocalisationQueued=true;
    enqueueMicrotask(()=>{
        uiLocalisationQueued=false;
        localizeDocument();
    });
}

const uiLocalisationObserver =
    typeof MutationObserver !== 'undefined'
        ? new MutationObserver(() => {
            if (state?.gameOptions?.animalLanguage === 'nl') queueDocumentLocalisation();
        })
        : null;
window.addEventListener('DOMContentLoaded', () => {
    uiLocalisationObserver?.observe(document.body, {
        childList: true,
        subtree: true,
        characterData: true
    });
});

function setupAnimalCard(
    image,
    animal,
    location,
    renderNow = Date.now(),
    cardRenderContext = null
) {

    const layoutToolEditing = cardRenderContext?.layoutToolEditing ?? trueLayoutToolEditingActive();
    const visitingActionUI = cardRenderContext?.visitingActionUI ?? visitingAnotherZooForActionUI();

    image.classList.add(
        'animal-card'
    );

    image.dataset.animalId =
        animal.id;

    if(state.sandboxMode&&!cardRenderContext?.delegatedClassicEnclosureCards){
        image.addEventListener('pointerenter',()=>{sandboxHoveredAnimalId=animal.id;});
        image.addEventListener('pointerleave',()=>{if(sandboxHoveredAnimalId===animal.id)sandboxHoveredAnimalId=null;});
    }

    applyLocalizedAnimalImage(image, animal);

    image.draggable =
        false;

    if (
        (cardRenderContext?.compatibilityAnimalGlowActive ?? ((state.compatibilityAnimalHoverIds?.size||0)>0)) &&
        state.compatibilityAnimalHoverIds.has(animal.id)
    ) {
        const now = renderNow;

        if (now < state.compatibilityAnimalHoverHoldUntil) {
            image.classList.add('compatibility-animal-match');
        }
        else if (now < state.compatibilityAnimalHoverFadeUntil) {
            image.classList.add('compatibility-animal-match-fading');
            const fadeElapsed = Math.max(
                0,
                now - state.compatibilityAnimalHoverHoldUntil
            );
            image.style.animationDelay = `${-Math.min(fadeElapsed, 1000)}ms`;
        }
    }

    attachImageError(
        image,
        `animal card ${animal.filename}`
    );

    if (location === 'sandbox-loose' && state.sandboxMode) {
        image.addEventListener('pointerdown', event => {
            if (event.button !== 0) return;
            if (areaToolActive) return;
            event.preventDefault(); event.stopPropagation();
            const animalId = animal.id;
            const startX=event.clientX, startY=event.clientY;
            const ox=animal.x, oy=animal.y;
            const move=e=>{
                animal.x=clamp(ox+(e.clientX-startX)/state.zoom,20,WORKSPACE_W-ANIMAL_W-20);
                animal.y=clamp(oy+(e.clientY-startY)/state.zoom,20,WORKSPACE_H-ANIMAL_H-20);
                const wrap=image.closest('.sandbox-loose-card');
                if(wrap){wrap.style.left=animal.x+'px';wrap.style.top=animal.y+'px';}
            };
            const up=e=>{
                window.removeEventListener('pointermove',move); window.removeEventListener('pointerup',up);
                const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.slot.empty-slot');
                if(target){
                    const enclosure=enclosureByIdFast(target.dataset.enclosureId);
                    const slotIndex=Number(target.dataset.slotIndex);
                    if(enclosure && canPlace(animal,enclosure,slotIndex)){
                        if (placeAnimal(animal,enclosure,slotIndex)) {
                            animal.sandboxLoose=false;
                            state.sandboxLooseAnimals=state.sandboxLooseAnimals.filter(x=>x.id!==animalId);
                            renderAll();
                            return;
                        }
                    }
                }

                const proposed={x:animal.x,y:animal.y,w:ANIMAL_W,h:ANIMAL_H};
                const hitsEnclosure=state.enclosures.some(enc=>rectanglesOverlap(
                    proposed,{x:enc.x,y:enc.y,w:ENCLOSURE_W,h:ENCLOSURE_H},0
                ));
                const hitsLoose=(state.sandboxLooseAnimals||[]).some(other=>
                    other.id!==animal.id && other.enclosureId==null &&
                    rectanglesOverlap(proposed,{x:other.x,y:other.y,w:ANIMAL_W,h:ANIMAL_H},20)
                );
                if(hitsEnclosure || hitsLoose){
                    animal.x=ox; animal.y=oy;
                }
                renderAll();
            };
            window.addEventListener('pointermove',move); window.addEventListener('pointerup',up,{once:true});
        });
    }

    if (
        location ===
        'enclosure'
    ) {

        image.classList.add(
            'enclosure-animal'
        );

        if(cardRenderContext?.newPlacementGlowActive ?? !state.visitingZoo){
            const glowStarted=state.visitingZoo?0:Number(state.newPlacementGlowStartedAt[animal.id]||0);
            const glowElapsed=glowStarted?renderNow-glowStarted:Infinity;
            if(!layoutToolEditing&&glowElapsed>=0&&glowElapsed<4000){
                image.classList.add('new-placement-glow');
                image.style.animationDelay=`${-glowElapsed}ms`;
            }
        }

    }

    const progressionGlowActive=
        !layoutToolEditing &&
        (cardRenderContext?.progressionGlowActive ??
         !!(state.progressionGlowHoverKey||state.progressionGlowPinnedKeys.size));
    const trackerKey=progressionGlowActive?progressionKey(animal.category,animal.level):null;
    if (
        progressionGlowActive &&
        (state.progressionGlowHoverKey === trackerKey ||
        state.progressionGlowPinnedKeys.has(trackerKey))
    ) {
        image.classList.add('progression-highlight-instant', 'progression-highlight');
        if (state.progressionGlowPinnedKeys.has(trackerKey)) {
            image.classList.add('progression-highlight-pinned');
        }
    }

    if (
        !layoutToolEditing &&
        !visitingActionUI && (
            cardRenderContext?.exchangeGlowPrecomputed
                ? !!cardRenderContext.exchangeGlowEligibleIds?.has(animal.id)
                : shouldGlowForExchange(animal)
        )
    ) {

        image.classList.add(
            'exchange-eligible'
        );

        if (renderNow < state.exchangeGlowReturnUntil && state.exchangeGlowReturnIds?.has(animal.id)) {
            image.classList.add('exchange-glow-return');
        }

    }

    if (
        !layoutToolEditing &&
        state.drag?.type === 'animal' &&
        state.drag.exchangeGlowIds?.has(animal.id)
    ) {
        image.classList.add('exchange-drag-glow');

        const elapsed = Math.max(
            0,
            renderNow - state.exchangeGlowDragStartedAt
        );
        image.style.animationDelay = `${-Math.min(elapsed, 2000)}ms`;
    } else if (
        !layoutToolEditing &&
        renderNow < state.exchangeGlowContinueUntil &&
        state.exchangeGlowContinueIds?.has(animal.id)
    ) {
        image.classList.add('exchange-drag-glow');
        const elapsed = Math.max(0, renderNow - state.exchangeGlowContinueStartedAt);
        image.style.animationDelay = `${-elapsed}ms`;
    }

    if(cardRenderContext?.delegatedClassicEnclosureCards||(location==='enclosure'&&!state.sandboxMode)){
        image.dataset.classicDelegatedAnimal='1';
    }else{
        image.addEventListener('mouseenter',()=>{requestHoverPreview(animal);requestCompatibilityIntent(animal);});
        image.addEventListener('mouseleave',()=>{hideHoverPreviewIfAllowed(animal);finishCompatibilityIntent(animal);});
        image.addEventListener('pointerdown',event=>{
            if(event.button!==0||areaToolActive||state.visitingZoo)return;
            event.preventDefault();event.stopPropagation();
            if(event.pointerType==='touch'&&zooTouchPointers.size>=2)return;
            startAnimalDrag(event,animal,location);
        });
    }

}

let classicAnimalDelegationRoot=null;
function ensureClassicAnimalCardDelegation(){
    const root=document;
    if(classicAnimalDelegationRoot===root)return;
    classicAnimalDelegationRoot=root;
    const cardFromEvent=event=>{
        const card=event.target instanceof Element
            ? event.target.closest('.animal-card[data-classic-delegated-animal="1"]')
            : null;
        return card&&zooCanvas?.contains(card)?card:null;
    };
    root.addEventListener('mouseover',event=>{
        const card=cardFromEvent(event);if(!card||card.contains(event.relatedTarget))return;
        const animal=classicAnimalById(card.dataset.animalId);if(!animal)return;
        requestHoverPreview(animal);requestCompatibilityIntent(animal);
    });
    root.addEventListener('mouseout',event=>{
        const card=cardFromEvent(event);if(!card||card.contains(event.relatedTarget))return;
        const animal=classicAnimalById(card.dataset.animalId);if(!animal)return;
        hideHoverPreviewIfAllowed(animal);finishCompatibilityIntent(animal);
    });
    root.addEventListener('pointerdown',event=>{
        const card=cardFromEvent(event);if(!card||event.button!==0||areaToolActive||state.visitingZoo)return;
        const animal=classicAnimalById(card.dataset.animalId);if(!animal)return;
        event.preventDefault();event.stopPropagation();
        if(event.pointerType==='touch'&&zooTouchPointers.size>=2)return;
        startAnimalDrag(event,animal,'enclosure');
    });
}
const COMPATIBILITY_INTENT_DELAY = 180;

function cancelCompatibilityIntent(animal = null) {
    if (animal && state.compatibilityIntentAnimalId !== animal.id) return;
    if (state.compatibilityIntentTimer) clearTimeout(state.compatibilityIntentTimer);
    state.compatibilityIntentTimer = null;
    state.compatibilityIntentAnimalId = null;
}

function requestCompatibilityIntent(animal) {
    if (visitingAnotherZooForActionUI() || trueLayoutToolEditingActive()) {
        cancelCompatibilityIntent();
        return;
    }

    if (state.drag?.type === 'animal') {
        cancelCompatibilityIntent();
        return;
    }

    cancelCompatibilityIntent();
    state.compatibilityIntentAnimalId = animal.id;

    state.compatibilityIntentTimer = setTimeout(() => {
        if (state.compatibilityIntentAnimalId !== animal.id) return;

        state.compatibilityIntentTimer = null;
        state.compatibilityIntentAnimalId = null;
        state.compatibilityIntentActiveAnimal = animal;

        state.compatibilityGlowFadeKeys.clear();
        state.compatibilityGlowHoldUntil = 0;
        state.compatibilityGlowFadeUntil = 0;
        applyCompatibilityDestinationGlowClasses();
    }, COMPATIBILITY_INTENT_DELAY);
}

function finishCompatibilityIntent(animal) {
    cancelCompatibilityIntent(animal);

    if (state.compatibilityIntentActiveAnimal?.id !== animal.id) return;

    const oldKeys = currentCompatibilityGlowKeys([animal]);
    state.compatibilityIntentActiveAnimal = null;
    beginCompatibilityGlowFade(oldKeys);
}

function cancelHoverPreviewHide() {
    if (state.previewHideTimer) {
        clearTimeout(state.previewHideTimer);
        state.previewHideTimer = null;
    }
    hoverPreview?.classList.remove('preview-fading');
}

const PREVIEW_INTENT_DELAY = 180;
const PREVIEW_VISIBLE_AFTER_LEAVE = 1000;
const PREVIEW_FADE_DURATION = 1000;
let previewInfoFaceContinuity = false;

function setHoverPreviewSuperZoom(enabled) {
    hoverPreview.classList.toggle('super-zoom', enabled);

    if (!enabled) {
        hoverPreview.style.removeProperty('width');
        hoverPreview.style.removeProperty('height');
        hoverPreview.style.removeProperty('aspect-ratio');
        return;
    }

    const mobile = window.matchMedia('(max-width: 700px)').matches;
    const margin = mobile ? 16 : 36;
    const maximumWidth = mobile ? 300 : 810 * desktopUiScale();
    const availableWidth = Math.max(120, window.innerWidth - margin);
    const availableHeight = Math.max(172.8, window.innerHeight - margin);
    const width = Math.min(maximumWidth, availableWidth, availableHeight * (1000 / 1440));
    const height = width * (1440 / 1000);

    hoverPreview.style.setProperty('width', `${width}px`, 'important');
    hoverPreview.style.setProperty('height', `${height}px`, 'important');
    hoverPreview.style.setProperty('aspect-ratio', '1000 / 1440', 'important');
}

function cancelHoverPreviewIntent(animal = null) {
    if (animal && state.previewIntentAnimalId !== animal.id) return;
    if (state.previewIntentTimer) clearTimeout(state.previewIntentTimer);
    state.previewIntentTimer = null;
    state.previewIntentAnimalId = null;
}

function dismissHoverPreviewForContextLoss(){
    cancelHoverPreviewIntent();
    const preview=document.getElementById('hoverPreview');
    if(preview){
        preview.classList.remove('visible');
        preview.style.display='none';
    }
    hideGeographicAreaPreview(true);
}

function normaliseTrueAnimalPopulation(animal) {
    if (!animal || !trueModeAllowsDuplicateSpecies()) return null;
    if (!animal.population || typeof animal.population !== 'object') {
        animal.population = { males: 1, females: 1, unknown: 0 };
    }
    if(animal.population.population&&typeof animal.population.population==='object')
        delete animal.population.population;
    for (const key of ['males', 'females', 'unknown']) {
        animal.population[key] = Math.max(0, Math.floor(Number(animal.population[key]) || 0));
    }
    return animal.population;
}

function normaliseTruePopulationCounts(value) {
    const source=(value&&typeof value==='object'&&value.population&&typeof value.population==='object')
        ? value.population
        : (value&&typeof value==='object'?value:{});
    return {
        males:Math.max(0,Math.floor(Number(source.males)||0)),
        females:Math.max(0,Math.floor(Number(source.females)||0)),
        unknown:Math.max(0,Math.floor(Number(source.unknown)||0))
    };
}
function trueAnimalPopulationTotal(animal) {
    const population = normaliseTrueAnimalPopulation(animal);
    return population ? population.males + population.females + population.unknown : 0;
}

function trueSexCountsDiagnostic(){
    const rows=(state.animals||[]).filter(Boolean).map(animal=>{
        const p=normaliseTrueAnimalPopulation(animal)||{males:0,females:0,unknown:0};
        const enclosure=enclosureByIdFast(animal.enclosureId);
        return {
            id:animal.id,
            animal:animalDisplayName(animal),
            males:p.males,
            females:p.females,
            unknown:p.unknown,
            total:p.males+p.females+p.unknown,
            enclosure:enclosure?.name||enclosure?.id||animal.enclosureId||'unplaced',
            backstage:Boolean(enclosure&&trueEnclosureIsCurrentBackstage(enclosure))
        };
    });
    const totals=rows.reduce((a,r)=>{
        a.males+=r.males;a.females+=r.females;a.unknown+=r.unknown;a.total+=r.total;return a;
    },{males:0,females:0,unknown:0,total:0});
    const unknownAnimals=rows.filter(r=>r.unknown>0);
    const result={
        ok:unknownAnimals.length===0,
        cardCount:rows.length,
        totals,
        unknownCardCount:unknownAnimals.length,
        unknownAnimalCount:unknownAnimals.reduce((n,r)=>n+r.unknown,0),
        unknownAnimals,
        animals:rows
    };
    console.table(rows);
    if(unknownAnimals.length){
        console.warn(`Unknown-sex animals found: ${result.unknownAnimalCount} across ${result.unknownCardCount} card(s).`,unknownAnimals);
    }else{
        console.info('Sex-count audit passed: every animal is male or female.');
    }
    return result;
}
if(typeof window!=='undefined'){
    window.zooSexCounts=trueSexCountsDiagnostic;
    window.sexCountsDiagnostic=trueSexCountsDiagnostic;
}

