function positionVisitedZooQuickTabs() {
    const strip = document.getElementById('visitedZooQuickTabs');
    if (!strip) return;
    const header = document.getElementById('actionMenu') || document.querySelector('header');
    const bottom = header ? header.getBoundingClientRect().bottom : 0;
    strip.style.top = `${Math.max(0, Math.round(bottom))}px`;
}
function renderVisitedZooQuickTabs() {
    if(state.gameMode==='true'){
        const host=document.getElementById('visitedZooQuickTabs');
        if(host)host.innerHTML='';
        return;
    }
    const strip = ensureVisitedZooQuickTabsUI();
    strip.replaceChildren();
    strip.classList.toggle('has-multiplayer-tabs',!!localClassicMatch);

    if (localClassicMatch) {
        const browserPeerMode=localMultiplayerBrowserTransport?.role==='peer';
        const controller=document.createElement('select');
        controller.className='local-multiplayer-controller-select';
        controller.title='Choose which player you are playing as. Zoo tabs only change which zoo is open.';
        controller.style.cssText='pointer-events:auto;height:24px;max-width:155px;margin-right:5px;border-radius:5px;font-size:10px;font-weight:800';
        for(const playerId of localClassicMatch.playerIds){
            const option=document.createElement('option');
            option.value=playerId;
            option.textContent=`Play as: ${localMultiplayerPlayerLabel(playerId)}`;
            option.selected=playerId===localClassicMatch.activePlayerId;
            controller.appendChild(option);
        }
        controller.addEventListener('change',async event=>{
            const nextId=event.target.value;
            if(nextId===localClassicMatch?.activePlayerId)return;
            await switchLocalClassicMatchPlayer(nextId);
        });

        for (const playerId of localClassicMatch.playerIds) {
            const tab = document.createElement('button');
            tab.type = 'button';
            tab.className = 'visited-zoo-quick-tab multiplayer-zoo-quick-tab';
            tab.dataset.multiplayerPlayerId = playerId;
            tab.style.setProperty('--multiplayer-player-colour', multiplayerPlayerColour(playerId));
            const viewedId = localClassicMatch.viewingPlayerId || localClassicMatch.activePlayerId;
            const hasZoo=!!localClassicMatch.players?.[playerId]?.snapshot;
            const isViewed = hasZoo && playerId === viewedId;
            const ownsTurn = hasZoo && playerId === localClassicMatch.turnPlayerId;
            const isOwnZoo = playerId === localClassicMatch.activePlayerId;
            const visitingOtherHuman = !!localClassicMatch.viewingPlayerId &&
                localClassicMatch.viewingPlayerId !== localClassicMatch.activePlayerId;
            if (isViewed) tab.classList.add('is-current');
            if (ownsTurn) tab.classList.add('is-turn');
            if(isOwnZoo)tab.classList.add('is-own-zoo');
            else{
                tab.classList.add('is-other-player');
                const ownIndex=localClassicMatch.playerIds.indexOf(localClassicMatch.activePlayerId);
                const playerIndex=localClassicMatch.playerIds.indexOf(playerId);
                tab.classList.add(playerIndex<ownIndex?'is-left-of-own':'is-right-of-own');
            }

            tab.style.fontWeight = isOwnZoo ? '900' : '700';

            const zooName=String(
                localClassicMatch.players?.[playerId]?.snapshot?.state?.zooName ||
                localMultiplayerPlayerLabel(playerId)
            );
            const label = document.createElement('span');
            label.className = 'visited-zoo-quick-tab-label';
            const serverPlayer=multiplayerServerPlayerForLocalId(playerId);
            const isHostPlayer=serverPlayer?.host===true ||
                (!serverPlayer && playerId==='player-1');
            label.textContent = `${ownsTurn ? '● ' : ''}${zooName}`;
            tab.title = hasZoo
                ? `${isViewed?'Viewing':'Visit'} ${zooName}${isHostPlayer?' — host':''}${isOwnZoo?' — your zoo':''}${ownsTurn?' — current turn':''}`
                : `Waiting for ${playerId.replace('player-','Player ')} to create their zoo${isHostPlayer?' — host':''}`;
            if(hasZoo&&localClassicMatch.players?.[playerId]?.connected===false){
                tab.classList.add('is-disconnected-player');
                tab.title += ' — disconnected';
            }
            if(!hasZoo){
                tab.classList.add('is-pending-player');
                tab.disabled=true;
            }
            if(isHostPlayer){
                const hostMarker=document.createElement('span');
                hostMarker.className='multiplayer-host-indicator';
                hostMarker.textContent=' HOST';
                hostMarker.setAttribute('aria-label','Host');
                hostMarker.style.cssText='font-size:8px;font-weight:900;opacity:.65;margin-left:3px;vertical-align:1px;';
                tab.appendChild(label);
                tab.appendChild(hostMarker);
            }else tab.appendChild(label);
            tab.addEventListener('click', async () => {
                if (!localClassicMatch || !hasZoo) return;
                const viewedId=localClassicMatch.viewingPlayerId||localClassicMatch.activePlayerId;
                if(playerId===viewedId)return;
                if(playerId===localClassicMatch.activePlayerId) await returnToActiveLocalClassicZoo();
                else await visitLocalClassicMatchPlayer(playerId);
            });
            strip.appendChild(tab);
        }
        const ownTab=strip.querySelector('.multiplayer-zoo-quick-tab.is-own-zoo');
        if(ownTab){
            const updateOwnTabSpacing=()=>{
                if(!ownTab.isConnected)return;
                const width=ownTab.getBoundingClientRect().width;
                if(width>0)strip.style.setProperty('--multiplayer-own-tab-half-width',`${width/2}px`);
            };
            updateOwnTabSpacing();
            requestAnimationFrame(updateOwnTabSpacing);
        }
    }else{
        strip.style.removeProperty('--multiplayer-own-tab-half-width');
    }

    if(state.gameMode==='true'&&!localClassicMatch){
        trueEventActiveItems(); // expire overdue active events before drawing tabs
        const activeEvents=(normaliseTrueEventState().items||[]).filter(event=>
            event.status==='active'||event.status==='engaged'
        );
        for(const event of activeEvents){
            const tab=document.createElement('button');
            tab.type='button';
            tab.className='visited-zoo-quick-tab true-event-quick-tab';
            tab.dataset.trueEventId=String(event.id);
            const label=document.createElement('span');
            label.className='visited-zoo-quick-tab-label';
            const animalName=event.animal?animalDisplayName(event.animal):'';
            label.textContent=animalName?`${event.title}: ${animalName}`:event.title;
            tab.title=`Open event: ${event.title}`;
            tab.addEventListener('click',()=>openTrueEventDialog(event.id));
            tab.appendChild(label);
            strip.appendChild(tab);
        }
    }

    for (const name of visitedZooQuickTabs) {
        const tab = document.createElement('button');
        tab.type = 'button';
        tab.className = 'visited-zoo-quick-tab ai-zoo-quick-tab';
        if (state.visitingZoo && realZooHoldingKey(state.visitingZoo.name) === realZooHoldingKey(name)) tab.classList.add('is-current');
        tab.title = `Visit ${name}`;
        const label = document.createElement('span');
        label.className = 'visited-zoo-quick-tab-label';
        label.textContent = name;
        const close = document.createElement('span');
        close.className = 'visited-zoo-quick-tab-close';
        close.textContent = '×';
        close.title = `Close ${name} tab`;
        close.setAttribute('role','button');
        close.setAttribute('aria-label',`Close ${name} tab`);
        close.addEventListener('click', event => {
            event.preventDefault(); event.stopPropagation();
            visitedZooQuickTabs = visitedZooQuickTabs.filter(n => realZooHoldingKey(n) !== realZooHoldingKey(name));
            renderVisitedZooQuickTabs();
        });
        tab.append(label, close);
        tab.addEventListener('click', () => {
            if (state.visitingZoo && realZooHoldingKey(state.visitingZoo.name) === realZooHoldingKey(name)) return;
            visitZooByName(name);
        });
        strip.appendChild(tab);
    }

    if(localClassicMatch){
        const ownTab=strip.querySelector('.multiplayer-zoo-quick-tab.is-own-zoo');
        const otherHumans=[...strip.querySelectorAll('.multiplayer-zoo-quick-tab.is-other-player')];
        const aiTabs=[...strip.querySelectorAll('.ai-zoo-quick-tab')];
        const layoutMultiplayerZooTabs=()=>{
            if(!ownTab?.isConnected)return;
            const ownWidth=ownTab.getBoundingClientRect().width;
            const ownIndex=localClassicMatch.playerIds.indexOf(localClassicMatch.activePlayerId);
            let leftOffset=ownWidth/2+6;
            let rightOffset=ownWidth/2+6;

            const leftHumans=[];
            const rightHumans=[];
            for(const tab of otherHumans){
                const playerId=tab.dataset.multiplayerPlayerId||'';
                const playerIndex=localClassicMatch.playerIds.indexOf(playerId);
                (playerIndex>=0&&playerIndex<ownIndex?leftHumans:rightHumans).push({tab,playerIndex});
            }
            leftHumans.sort((a,b)=>b.playerIndex-a.playerIndex);
            rightHumans.sort((a,b)=>a.playerIndex-b.playerIndex);
            for(const {tab} of leftHumans){
                tab.style.right=`calc(50% + ${leftOffset}px)`;
                tab.style.left='auto';
                leftOffset+=tab.getBoundingClientRect().width+6;
            }
            for(const {tab} of rightHumans){
                tab.style.left=`calc(50% + ${rightOffset}px)`;
                tab.style.right='auto';
                rightOffset+=tab.getBoundingClientRect().width+6;
            }

            for(const tab of aiTabs){
                tab.style.left=`calc(50% + ${rightOffset}px)`;
                tab.style.right='auto';
                rightOffset+=tab.getBoundingClientRect().width+6;
            }
        };
        layoutMultiplayerZooTabs();
        requestAnimationFrame(layoutMultiplayerZooTabs);
    }
    renderDirectHumanTradeControls(strip);
    if(state.gameMode==='true')trueEventActiveItems();
    const hasTrueEventTabs=state.gameMode==='true'&&(normaliseTrueEventState().items||[]).some(event=>
        event.status==='active'||event.status==='engaged'
    );
    strip.style.display = (visitedZooQuickTabs.length || localClassicMatch || hasTrueEventTabs) ? 'flex' : 'none';
    positionVisitedZooQuickTabs();
}
function rememberVisitedZooQuickTab(name) {
    name = String(name || '').trim();
    if (!name) return;
    if (!visitedZooQuickTabs.some(n => realZooHoldingKey(n) === realZooHoldingKey(name))) visitedZooQuickTabs.push(name);
    renderVisitedZooQuickTabs();
}
let visitedZooTabsResizeRaf=0;
window.addEventListener('resize',()=>{
    if(visitedZooTabsResizeRaf)return;
    visitedZooTabsResizeRaf=requestAnimationFrame(()=>{
        visitedZooTabsResizeRaf=0;
        positionVisitedZooQuickTabs();
    });
},{passive:true});

function snapshotSavedGameFields() {
    return Object.fromEntries(SAVE_STATE_KEYS.map(key => [key, cloneForSave(state[key])]));
}
function restoreSavedGameFields(snapshot) {
    if (!snapshot) return;
    for (const key of SAVE_STATE_KEYS) if (Object.prototype.hasOwnProperty.call(snapshot,key)) state[key]=cloneForSave(snapshot[key]);
    relinkRestoredAnimalReferences();
}

function relinkRestoredAnimalReferences() {
    const byId = new Map((state.animals || []).map(animal => [animal?.id, animal]));
    if(Array.isArray(state.trueProposalOutgoingOffers)){
        state.trueProposalOutgoingOffers=state.trueProposalOutgoingOffers.map(a=>a?.id!=null?(byId.get(a.id)||a):a).filter(Boolean).slice(0,3);
    }
    if (state.outgoingOffer?.id != null) {
        state.outgoingOffer = byId.get(state.outgoingOffer.id) || null;
    }
    if (Array.isArray(state.exchange)) {
        state.exchange = state.exchange.map(animal =>
            animal?.id != null ? (byId.get(animal.id) || null) : null
        );
    }
    if (state.result?.id != null && byId.has(state.result.id)) {
        state.result = byId.get(state.result.id);
    }
}
function realZooLocationText(record) {
    const raw = record?.location ?? record?.city ?? record?.place ?? record?.province ?? record?.country ?? '';
    if (typeof raw === 'string' || typeof raw === 'number') return String(raw).trim();
    if (raw && typeof raw === 'object') {
        const candidates = [raw.city, raw.place, raw.locality, raw.municipality, raw.location, raw.province, raw.region, raw.country];
        for (const value of candidates) if (typeof value === 'string' && value.trim()) return value.trim();
    }
    return String(record?.province || record?.country || '').trim();
}

function realZooRecordByName(name) {
    const wanted=normaliseGeographyPart(name||'');
    return (state.realZooData?.zoos||[]).find(r=>normaliseGeographyPart(r?.name||'')===wanted)||null;
}
function realZooTemplateKey(recordOrName) {
    return normaliseGeographyPart(typeof recordOrName === 'string' ? recordOrName : recordOrName?.name || '');
}
function captureRealZooVisitLayout(recordOrName) {
    const key=realZooTemplateKey(recordOrName);
    if(!key) return;
    const data={};
    for(const field of REAL_ZOO_VISIT_LAYOUT_KEYS) data[field]=cloneForSave(state[field]);
    data.holdingKeys=(state.animals||[]).map(animal=>animalCardKey(animal));
    data.viewLeft=zooBoard?.scrollLeft||0; data.viewTop=zooBoard?.scrollTop||0;
    data.viewZoom=Math.max(0.01,Number(state.zoom)||1);
    { const b=zooPrestigeBreakdown(); data.prestige={original:Math.ceil(b.base),current:Math.ceil(b.current),area_bonus_percent:b.areaBonusPercent,combination_bonus_percent:b.combinationUnits,curation_bonus_percent:b.curationPercent,identity_bonus_percent:b.identityPercent,husbandry_penalty_percent:b.husbandryPenaltyPercent}; }
    realZooVisitLayouts.set(key,data);
    realZooLivePrestige.set(key,cloneForSave(data.prestige));
    if(state.gameMode==='true') trueWorldStoreLiveLayout(recordOrName,data);
}
function restoreRealZooVisitLayout(record, layout) {
    if(!layout) return false;
    const key=realZooVisitLayoutKey(record);
    if(key&&layout.prestige&&Number.isFinite(Number(layout.prestige.current)))
        realZooLivePrestige.set(key,cloneForSave(layout.prestige));
    for(const field of REAL_ZOO_VISIT_LAYOUT_KEYS) {
        if(Object.prototype.hasOwnProperty.call(layout,field)) state[field]=cloneForSave(layout[field]);
    }
    state.zooName=record?.name||state.zooName||'Zoo';
    state.zooCountry=record?.country||'';
    state.zooProvince=record?.province||'';
    state.zooLocation=realZooLocationText(record);
    return true;
}
function visitAnimalTags(animal){ return new Set(animalInventoryTags(animal.category,animal.level,animal.filename)); }
function visitEnclosureThemeScore(enclosure, animal) {
    const wanted=visitAnimalTags(animal);
    if(!wanted.size) return 0;
    let score=0;
    for(const held of state.animals||[]) {
        if(held.id===animal.id || held.enclosureId!==enclosure.id) continue;
        const tags=visitAnimalTags(held);
        for(const tag of wanted) if(tags.has(tag)) score+=3;
    }
    for(const other of state.enclosures||[]) {
        if(other.id===enclosure.id) continue;
        const dx=Math.abs((other.x||0)-(enclosure.x||0));
        const dy=Math.abs((other.y||0)-(enclosure.y||0));
        if(dx>ENCLOSURE_W+ENCLOSURE_GAP+8 || dy>ENCLOSURE_H+ENCLOSURE_GAP+8) continue;
        for(const held of state.animals||[]) {
            if(held.enclosureId!==other.id) continue;
            const tags=visitAnimalTags(held);
            if([...wanted].some(tag=>tags.has(tag))) { score+=1; break; }
        }
    }
    return score;
}
function addVisitExpansionEnclosureNear(animal) {
    const wanted=visitAnimalTags(animal);
    let anchor=null, best=-1;
    for(const enclosure of state.enclosures||[]) {
        let score=0;
        for(const held of state.animals||[]) if(held.enclosureId===enclosure.id) {
            const tags=visitAnimalTags(held);
            score += [...wanted].filter(tag=>tags.has(tag)).length;
        }
        if(score>best){best=score;anchor=enclosure;}
    }
    const id=state.nextId++;
    let x=anchor ? anchor.x+ENCLOSURE_W+ENCLOSURE_GAP : 600;
    let y=anchor ? anchor.y : 600;
    const occupied=(px,py)=>(state.enclosures||[]).some(e=>Math.abs(e.x-px)<ENCLOSURE_W*.9 && Math.abs(e.y-py)<ENCLOSURE_H*.9);
    let tries=0;
    while(occupied(x,y) && tries<30){ tries++; x=(anchor?.x||600)+((tries%5)-2)*(ENCLOSURE_W+ENCLOSURE_GAP); y=(anchor?.y||600)+(Math.floor(tries/5)+1)*(ENCLOSURE_H+ENCLOSURE_GAP); }
    const enclosure={id,number:10,x,y,rotated180:false};
    state.enclosures.push(enclosure);
    state.enclosure10Unlocked=true;
    return enclosure;
}
function reconcileVisitedRealZoo(record) {
    const wantedNames=realZooSessionAnimalNames(record);
    const wantedSpecs=wantedNames.map(realZooAnimalSpecByName).filter(Boolean);
    const wantedKeys=new Set(wantedSpecs.map(animalCardKey));
    const currentByKey=new Map((state.animals||[]).map(a=>[animalCardKey(a),a]));
    let changed=false;
    state.animals=(state.animals||[]).filter(animal=>{
        const keep=wantedKeys.has(animalCardKey(animal));
        if(!keep) changed=true;
        return keep;
    });
    for(const spec of wantedSpecs){
        const key=animalCardKey(spec);
        if(currentByKey.has(key)) continue;
        let animal;
        try { animal=createAnimal(spec.category,spec.level,spec.filename); } catch(e){ continue; }
        state.animals.push(animal);
        let destinations=eligibleDestinationsForAnimal(animal);
        destinations=preferSizeAppropriateGenerationDestinations(animal,destinations);
        destinations.sort((a,b)=>visitEnclosureThemeScore(b.enclosure,animal)-visitEnclosureThemeScore(a.enclosure,animal));
        let destination=destinations[0]||null;
        if(!destination){
            const enclosure=addVisitExpansionEnclosureNear(animal);
            destination={enclosure,slotIndex:(getAllSlots(enclosure)[0]??0)};
        }
        animal.enclosureId=destination.enclosure.id;
        animal.slotIndex=destination.slotIndex;
        currentByKey.set(key,animal);
        changed=true;
    }
    if(changed){
        state.areaPlacementRevision=(Number(state.areaPlacementRevision)||0)+1;
    }
    return changed;
}

function ensureVisitReturnButton() {
    let b=document.getElementById('returnFromZooVisit');
    if(!b){
        b=document.createElement('button'); b.id='returnFromZooVisit'; b.type='button';
        b.addEventListener('click', returnFromZooVisit); document.body.appendChild(b);
    }
    return b;
}
