function trueGeneratedLayoutHasConstructiveAccess(enclosures,entranceCol,bounds,entranceSide='bottom',precomputedCells=null){
    const cols=Math.max(1,Number(bounds?.cols)||0),rows=Math.max(1,Number(bounds?.rows)||0);
    if(!cols||!rows||!enclosures?.length)return false;
    const dirs=[[1,0],[-1,0],[0,1],[0,-1]],size=cols*rows;
    const blocked=new Uint8Array(size),groups=[];
    for(let i=0;i<enclosures.length;i++){
        const cells=precomputedCells?.[i]||trueBuiltWorldCells(enclosures[i]);
        groups.push(cells);
        for(const c of cells)if(c.col>=0&&c.col<cols&&c.row>=0&&c.row<rows)
            blocked[c.row*cols+c.col]=1;
    }
    const startRow=entranceSide==='top'?0:rows-1,start=startRow*cols+entranceCol;
    if(entranceCol<0||entranceCol>=cols||blocked[start])return false;
    const seen=new Uint8Array(size),queue=[start];seen[start]=1;
    for(let qi=0;qi<queue.length;qi++){
        const index=queue[qi],c=index%cols,r=(index/cols)|0;
        for(const [dc,dr] of dirs){
            const nc=c+dc,nr=r+dr;
            if(nc<0||nc>=cols||nr<0||nr>=rows)continue;
            const next=nr*cols+nc;
            if(seen[next]||blocked[next])continue;
            seen[next]=1;queue.push(next);
        }
    }
    for(const cells of groups){
        let reachable=false;
        for(const c of cells){
            for(const [dc,dr] of dirs){
                const nc=c.col+dc,nr=c.row+dr;
                if(nc>=0&&nc<cols&&nr>=0&&nr<rows&&seen[nr*cols+nc]){
                    reachable=true;break;
                }
            }
            if(reachable)break;
        }
        if(!reachable)return false;
    }
    return true;
}

function repairTrueBuiltEnclosureGeometry(){
    if(state.gameMode!=='true'||state.sandboxMode)return false;
    const b=normaliseTrueEnclosureBuilderState();
    const currentEnclosures=(state.enclosures||[]).filter(e=>e?.trueBuilt);
    const occupiedIds=new Set((state.animals||[])
        .filter(a=>a?.enclosureId!=null&&!a?.trueArrivalPending)
        .map(a=>String(a.enclosureId)));
    const occupiedEnclosures=currentEnclosures.filter(e=>occupiedIds.has(String(e.id)));
    const grounds=b.zooGrounds;
    const sidesConnected=()=>{
        if(!grounds||!occupiedEnclosures.length)return false;
        const eps=2;
        let top=false,bottom=false,left=false,right=false;
        for(const enc of occupiedEnclosures){
            const baseCol=Math.round((Number(enc.x)||0)/TRUE_ENC_CELL_W);
            const baseRow=Math.round((Number(enc.y)||0)/TRUE_ENC_CELL_H);
            const cells=trueCanonicalCellList(enc.cells||[]);
            for(const c of cells){
                const x=(baseCol+c.col)*TRUE_ENC_CELL_W,y=(baseRow+c.row)*TRUE_ENC_CELL_H;
                if(Math.abs(y-grounds.y)<=eps)top=true;
                if(Math.abs((y+TRUE_ENC_CELL_H)-(grounds.y+grounds.h))<=eps)bottom=true;
                if(Math.abs(x-grounds.x)<=eps)left=true;
                if(Math.abs((x+TRUE_ENC_CELL_W)-(grounds.x+grounds.w))<=eps)right=true;
            }
        }
        return top&&bottom&&left&&right;
    };
    if(Number(b.geometryVersion)>=43)return false;
    const canonicalCellsById=new Map(occupiedEnclosures.map(
        enc=>[String(enc.id),trueCanonicalCellList(enc.cells||[])]
    ));
    const enclosures=occupiedEnclosures.slice()
      .sort((a,b)=>{
          const ac=canonicalCellsById.get(String(a.id))||[],bc=canonicalCellsById.get(String(b.id))||[];
          if(bc.length!==ac.length)return bc.length-ac.length;
          return (Number(a.y)||0)-(Number(b.y)||0)||
                 (Number(a.x)||0)-(Number(b.x)||0)||
                 (Number(a.id)||0)-(Number(b.id)||0);
      });
    const dormantIds=new Set(currentEnclosures
        .filter(enc=>!occupiedIds.has(String(enc.id)))
        .map(enc=>String(enc.id)));
    if(dormantIds.size){
        state.enclosures=(state.enclosures||[]).filter(enc=>!dormantIds.has(String(enc?.id)));
        for(const stale of currentEnclosures)
            if(dormantIds.has(String(stale.id)))trueInvalidateEnclosureGeometry(stale);
    }
    if(!enclosures.length){b.geometryVersion=43;return false;}

    const dimensionsById=new Map();
    for(const enc of enclosures){
        const cells=canonicalCellsById.get(String(enc.id))||[];
        let minCol=Infinity,maxCol=-Infinity,minRow=Infinity,maxRow=-Infinity;
        for(const cell of cells){
            if(cell.col<minCol)minCol=cell.col;if(cell.col>maxCol)maxCol=cell.col;
            if(cell.row<minRow)minRow=cell.row;if(cell.row>maxRow)maxRow=cell.row;
        }
        dimensionsById.set(String(enc.id),cells.length
            ?{w:maxCol-minCol+1,h:maxRow-minRow+1}:{w:1,h:1});
    }
    const original=enclosures.map(enc=>({enc,x:Number(enc.x)||0,y:Number(enc.y)||0}));
    const zooSeed=String(state.zooName||state.playerZooName||'Zoo Curator');
    let seed=2166136261;
    for(let i=0;i<zooSeed.length;i++){seed^=zooSeed.charCodeAt(i);seed=Math.imul(seed,16777619);}
    const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};

    const envelopes=[];
    let requiredCells=0;
    for(const enc of enclosures)
        requiredCells+=(canonicalCellsById.get(String(enc.id))||[]).length;
    const layoutDiag={
        startedAt:new Date().toISOString(),
        requiredCells,
        targetStartingPropertyCells:null,
        enclosureCount:enclosures.length,
        attempts:0,
        completedPlacements:0,
        accessibleCandidates:0,
        strictCandidates:0,
        searchBudgetInitial:220000,
        searchBudgetRemaining:220000,
        failureReasons:{},
        envelopes:[],
        chosen:null,
        finalFailure:null
    };
    const diagReject=reason=>{
        layoutDiag.failureReasons[reason]=(layoutDiag.failureReasons[reason]||0)+1;
        return false;
    };
    b.startLayoutDiagnostic=layoutDiag;
    const targetOpenFraction=.15+rand()*.08;
    const TRUE_STARTING_GROUNDS_MAX_CELLS=28;
    const TRUE_STARTING_GROUNDS_MAX_LONG_SIDE=7;
    const TRUE_STARTING_GROUNDS_MAX_SHORT_SIDE=5;
    const targetStartingPropertyCells=20;
    layoutDiag.targetStartingPropertyCells=targetStartingPropertyCells;
    const targetEnvelopeCells=Math.min(
        TRUE_STARTING_GROUNDS_MAX_CELLS,
        Math.max(requiredCells+3,targetStartingPropertyCells)
    );
    const maxEnvelopeCells=TRUE_STARTING_GROUNDS_MAX_CELLS;
    for(let rows=2;rows<=TRUE_STARTING_GROUNDS_MAX_LONG_SIDE;rows++)
        for(let cols=3;cols<=TRUE_STARTING_GROUNDS_MAX_LONG_SIDE;cols++){
            const longSide=Math.max(cols,rows),shortSide=Math.min(cols,rows);
            if(longSide>TRUE_STARTING_GROUNDS_MAX_LONG_SIDE||shortSide>TRUE_STARTING_GROUNDS_MAX_SHORT_SIDE)continue;
            if(cols*rows<requiredCells+2||cols*rows>35)continue;
            envelopes.push({cols,rows});
        }
    if(!envelopes.length){
        const cols=5,rows=4;
        if(requiredCells<cols*rows)envelopes.push({cols,rows});
    }
    const aspectTarget=[.85,1.0,1.18,1.35][Math.floor(rand()*4)];
    const preferIrregularFootprint=requiredCells>=6&&rand()<.72;
    for(const envelope of envelopes) envelope._layoutTie=rand();
    envelopes.sort((a,c)=>{
        const areaA=a.cols*a.rows,areaC=c.cols*c.rows;
        const scoreA=Math.abs(Math.min(areaA,TRUE_STARTING_GROUNDS_MAX_CELLS)-targetEnvelopeCells)*1.7+Math.abs((a.cols/a.rows)-aspectTarget)*4;
        const scoreC=Math.abs(Math.min(areaC,TRUE_STARTING_GROUNDS_MAX_CELLS)-targetEnvelopeCells)*1.7+Math.abs((c.cols/c.rows)-aspectTarget)*4;
        return scoreA-scoreC||a._layoutTie-c._layoutTie;
    });

    const searchEnvelopes=envelopes.slice(0,20);
    layoutDiag.envelopes=searchEnvelopes.map(e=>({cols:e.cols,rows:e.rows,area:e.cols*e.rows}));
    let totalSearchBudget=220000;
    let chosen=null,accessibleBackup=null;
    for(const envelope of searchEnvelopes){
        if(chosen||totalSearchBudget<=0)break;
        const {cols,rows}=envelope;
        const entranceCandidates=[];
        for(let col=0;col<cols;col++)entranceCandidates.push({
            col,tie:rand(),distance:Math.abs((col+.5)-cols/2)
        });
        entranceCandidates.sort((a,c)=>a.distance-c.distance||a.tie-c.tie);
        const entranceCols=entranceCandidates.slice(0,Math.min(3,cols)).map(entry=>entry.col);
        for(const entranceCol of entranceCols){
            if(totalSearchBudget<=0)break;
            const candidates=[];
            for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){
                if(row===rows-1&&col===entranceCol)continue;
                const tie=rand();
                const edgeDistance=Math.min(col,cols-1-col,row,rows-1-row);
                const perimeterBand=edgeDistance===0?0:edgeDistance===1?1:2;
                candidates.push({
                    col,row,tie,
                    band:perimeterBand+(perimeterBand===2&&tie<.32?-1:0),
                    distanceBand:Math.floor(Math.hypot(col-entranceCol,(rows-1)-row+.25)/2)
                });
            }
            candidates.sort((a,c)=>a.band-c.band||a.distanceBand-c.distanceBand||a.tie-c.tie);

            const placed=[],used=new Set();
            let searchBudget=Math.min(14000,totalSearchBudget);
            const entranceHasInteriorAccess=()=>{
                if(used.has(trueBuilderCellKey(entranceCol,rows-1)))return false;
                if(rows>=3&&used.has(trueBuilderCellKey(entranceCol,rows-2)))return false;
                if(rows>=3){
                    const inwardRow=rows-2;
                    const lateral=[entranceCol-1,entranceCol+1].filter(c=>c>=0&&c<cols);
                    if(lateral.length&&!lateral.some(c=>!used.has(trueBuilderCellKey(c,inwardRow))))return false;
                }
                return true;
            };
            const placeNext=index=>{
                searchBudget--;
                totalSearchBudget--;
                layoutDiag.attempts++;
                if(searchBudget<0||totalSearchBudget<0)return diagReject(searchBudget<0?'local-search-budget':'global-search-budget');
                if(index>=enclosures.length){
                    layoutDiag.completedPlacements++;
                    if(!entranceHasInteriorAccess())return diagReject('entrance-throat-blocked');
                    const leafWorldCells=placed.map(p=>
                        (canonicalCellsById.get(String(p.enc.id))||[]).map(c=>({
                            col:p.col+c.col,row:p.row+c.row
                        }))
                    );
                    if(!trueGeneratedLayoutHasConstructiveAccess(
                        enclosures,entranceCol,{cols,rows},'bottom',leafWorldCells
                    ))return diagReject('constructive-access-unreachable-enclosure');

                    const occupiedCount=used.size;
                    const groundsCellCount=cols*rows;
                    const openCount=groundsCellCount-occupiedCount;
                    if(openCount<3)return diagReject('fewer-than-3-free-canvas-cells');

                    if(preferIrregularFootprint){
                        const occ=new Set();
                        let minC=Infinity,maxC=-Infinity,minR=Infinity,maxR=-Infinity;
                        for(const cells of leafWorldCells)for(const cell of cells){
                            const col=cell.col,row=cell.row;
                            occ.add(trueBuilderCellKey(col,row));
                            if(col<minC)minC=col;if(col>maxC)maxC=col;
                            if(row<minR)minR=row;if(row>maxR)maxR=row;
                        }
                        let openCorners=0;
                        for(const [col,row] of [[minC,minR],[maxC,minR],[minC,maxR],[maxC,maxR]])
                            if(!occ.has(trueBuilderCellKey(col,row)))openCorners++;
                        if(openCorners<1)return diagReject('irregular-footprint-preference');
                    }

                    for(const p of placed){
                        p.enc.x=p.col*TRUE_ENC_CELL_W;
                        p.enc.y=p.row*TRUE_ENC_CELL_H;
                    }
                    layoutDiag.accessibleCandidates++;

                    if(!accessibleBackup)accessibleBackup={
                        cols,rows,entranceCol,placed:placed.map(p=>({...p}))
                    };
                    let perimeterEnclosures=0;
                    for(const p of placed){
                        const cells=canonicalCellsById.get(String(p.enc.id))||[];
                        if(cells.some(c=>
                            p.col+c.col===0||p.col+c.col===cols-1||
                            p.row+c.row===0||p.row+c.row===rows-1
                        ))perimeterEnclosures++;
                    }
                    const preferredPerimeterCount=Math.max(2,Math.ceil(enclosures.length*.6));
                    if(perimeterEnclosures<preferredPerimeterCount)
                        return diagReject('perimeter-enclosure-preference');
                    if(!trueGeneratedLayoutHasVariedFrontage(
                        enclosures,entranceCol,{cols,rows},'bottom',leafWorldCells
                    ))return diagReject('varied-frontage-aesthetic');
                    if(!trueGeneratedLayoutHasClusterCohesion(
                        enclosures,{cols,rows},leafWorldCells
                    ))return diagReject('cluster-cohesion-aesthetic');
                    layoutDiag.strictCandidates++;
                    chosen={cols,rows,entranceCol,placed:placed.map(p=>({...p}))};
                    return true;
                }
                const enc=enclosures[index],d=dimensionsById.get(String(enc.id));
                for(const at of candidates){
                    if(at.col+d.w>cols||at.row+d.h>rows){layoutDiag.failureReasons['shape-outside-envelope']=(layoutDiag.failureReasons['shape-outside-envelope']||0)+1;continue;}
                    const localCells=canonicalCellsById.get(String(enc.id))||[];
                    const keys=[];let free=true;
                    for(const cell of localCells){
                        const cc=at.col+cell.col,rr=at.row+cell.row,key=trueBuilderCellKey(cc,rr);
                        const blocksEntranceApproach=
                            cc===entranceCol&&(rr===rows-1||(rows>=3&&rr===rows-2));
                        if(cc<0||cc>=cols||rr<0||rr>=rows||used.has(key)||blocksEntranceApproach){
                            free=false;break;
                        }
                        keys.push(key);
                    }
                    if(!free){layoutDiag.failureReasons['placement-collision-or-entrance-reservation']=(layoutDiag.failureReasons['placement-collision-or-entrance-reservation']||0)+1;continue;}
                    keys.forEach(k=>used.add(k));
                    placed.push({enc,col:at.col,row:at.row});
                    enc.x=at.col*TRUE_ENC_CELL_W;enc.y=at.row*TRUE_ENC_CELL_H;
                    if(placeNext(index+1))return true;
                    placed.pop();keys.forEach(k=>used.delete(k));
                }
                return false;
            };
            if(placeNext(0))break;
        }
    }

    if(!chosen&&accessibleBackup)chosen=accessibleBackup;

    if(chosen)for(const p of chosen.placed){
        p.enc.x=p.col*TRUE_ENC_CELL_W;
        p.enc.y=p.row*TRUE_ENC_CELL_H;
        trueInvalidateEnclosureGeometry(p.enc);
    }

    let chosenWorldCells=null;
    if(chosen){
        chosenWorldCells=chosen.placed.map(p=>
            (canonicalCellsById.get(String(p.enc.id))||[]).map(c=>({col:p.col+c.col,row:p.row+c.row}))
        );
        let occupiedCount=0;
        for(const cells of chosenWorldCells)occupiedCount+=cells.length;
        const totalCells=chosen.cols*chosen.rows;
        const openCells=totalCells-occupiedCount;
        if(openCells<3){
            layoutDiag.finalFailure='final-fewer-than-3-free-canvas-cells';chosen=null;
        }
    }

    let changed=false;
    if(chosen){
        for(const p of chosen.placed){
            const nx=p.col*TRUE_ENC_CELL_W,ny=p.row*TRUE_ENC_CELL_H;
            const before=original.find(x=>x.enc===p.enc);
            if(!before||before.x!==nx||before.y!==ny)changed=true;
            p.enc.x=nx;p.enc.y=ny;trueInvalidateEnclosureGeometry(p.enc);
        }
        const groundCols=chosen.cols,groundRows=chosen.rows;
        b.zooGrounds={x:0,y:0,w:groundCols*TRUE_ENC_CELL_W,h:groundRows*TRUE_ENC_CELL_H};

        let entranceCol=Math.max(0,Math.min(groundCols-1,chosen.entranceCol));
        const bottomOccupied=new Set(chosenWorldCells.flat()
            .filter(c=>c.row===groundRows-1).map(c=>c.col));
        if(bottomOccupied.has(entranceCol)){
            let nearest=-1,nearestDistance=Infinity;
            for(let c=0;c<groundCols;c++)if(!bottomOccupied.has(c)){
                const distance=Math.abs(c-entranceCol);
                if(distance<nearestDistance){nearest=c;nearestDistance=distance;}
            }
            if(nearest>=0)entranceCol=nearest;
        }
        b.zooEntrance={side:'bottom',t:((entranceCol+.5)*TRUE_ENC_CELL_W)/b.zooGrounds.w};

        const gridSize=groundCols*groundRows,occupiedGrid=new Uint8Array(gridSize);
        for(const cells of chosenWorldCells)for(const c of cells)
            occupiedGrid[c.row*groundCols+c.col]=1;
        const entranceIndex=(groundRows-1)*groundCols+entranceCol;
        const visitorGrid=new Uint8Array(gridSize);visitorGrid[entranceIndex]=1;
        const visitor=[entranceIndex],enclosureGroups=chosenWorldCells;
        const frontages=enclosureGroups.map(group=>{
            const out=new Set();
            for(const c of group)for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
                const nc=c.col+dc,nr=c.row+dr;
                if(nc<0||nc>=groundCols||nr<0||nr>=groundRows)continue;
                const index=nr*groundCols+nc;
                if(!occupiedGrid[index])out.add(index);
            }
            return out;
        });
        const served=new Uint8Array(enclosureGroups.length);
        let servedCount=0;
        const markServed=()=>{
            for(let i=0;i<frontages.length;i++)if(!served[i]){
                for(const index of frontages[i])if(visitorGrid[index]){
                    served[i]=1;servedCount++;break;
                }
            }
        };
        markServed();
        let pathGuard=0;
        while(servedCount<enclosureGroups.length&&pathGuard++<enclosureGroups.length+4){
            const queue=visitor.slice(),prev=new Int32Array(gridSize);prev.fill(-1);
            const seen=new Uint8Array(gridSize);
            for(const index of queue)seen[index]=1;
            let hit=-1,hitIndex=-1;
            for(let qi=0;qi<queue.length&&hit<0;qi++){
                const index=queue[qi],c=index%groundCols,r=(index/groundCols)|0;
                for(let i=0;i<frontages.length;i++)if(!served[i]&&frontages[i].has(index)){
                    hit=index;hitIndex=i;break;
                }
                if(hit>=0)break;
                for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
                    const nc=c+dc,nr=r+dr;
                    if(nc<0||nc>=groundCols||nr<0||nr>=groundRows)continue;
                    const next=nr*groundCols+nc;
                    if(seen[next]||occupiedGrid[next])continue;
                    seen[next]=1;prev[next]=index;queue.push(next);
                }
            }
            if(hit<0)break;
            for(let index=hit;index>=0&&!visitorGrid[index];index=prev[index]){
                visitorGrid[index]=1;visitor.push(index);
            }
            if(!served[hitIndex]){served[hitIndex]=1;servedCount++;}
            markServed();
        }
        if(servedCount!==enclosureGroups.length){
            layoutDiag.finalFailure=`INVARIANT: validated constructive access but path served ${servedCount}/${enclosureGroups.length}`;
            chosen=null;
        }else{
            const propertyGrid=new Uint8Array(gridSize),property=[];
            for(let index=0;index<gridSize;index++)if(occupiedGrid[index]||visitorGrid[index]){
                propertyGrid[index]=1;property.push(index);
            }
            const targetCells=Math.min(TRUE_STARTING_GROUNDS_MAX_CELLS,
                Math.max(property.length,targetStartingPropertyCells));
            while(property.length<targetCells){
                let best=-1,bestEdge=2,bestTie=Infinity;
                const considered=new Uint8Array(gridSize);
                for(const index of visitor){
                    const c=index%groundCols,r=(index/groundCols)|0;
                    for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
                        const nc=c+dc,nr=r+dr;
                        if(nc<0||nc>=groundCols||nr<0||nr>=groundRows)continue;
                        const next=nr*groundCols+nc;
                        if(propertyGrid[next]||occupiedGrid[next]||considered[next])continue;
                        considered[next]=1;
                        const edge=(nc===0||nc===groundCols-1||nr===0||nr===groundRows-1)?1:0;
                        const tie=rand();
                        if(edge<bestEdge||(edge===bestEdge&&tie<bestTie)){
                            best=next;bestEdge=edge;bestTie=tie;
                        }
                    }
                }
                if(best<0)break;
                propertyGrid[best]=1;property.push(best);
                if(!visitorGrid[best]){visitorGrid[best]=1;visitor.push(best);}
            }
            b.startingGroundsCells=property.map(index=>
                trueBuilderCellKey(index%groundCols,(index/groundCols)|0)
            );

            const oldBackstageIds=new Set((b.backstageEnclosureIds||[]).map(String));
            if(oldBackstageIds.size){
                state.enclosures=(state.enclosures||[]).filter(enc=>!oldBackstageIds.has(String(enc?.id)));
                for(const animal of state.animals||[])if(oldBackstageIds.has(String(animal?.enclosureId))){
                    animal.enclosureId=null;animal.slotIndex=null;
                }
            }
            for(const enc of state.enclosures||[])delete enc.trueBackstage;
            b.backstageEnclosureIds=[];b.backstageCells=[];b.backstageFreeCell=null;
            trueInvalidateEnclosureGeometry();

            const publicSet=new Set(b.startingGroundsCells);
            const dirs=[['top',0,-1],['right',1,0],['bottom',0,1],['left',-1,0]];
            let minPC=Infinity,maxPC=-Infinity,minPR=Infinity,maxPR=-Infinity;
            for(const index of property){
                const c=index%groundCols,r=(index/groundCols)|0;
                if(c<minPC)minPC=c;if(c>maxPC)maxPC=c;
                if(r<minPR)minPR=r;if(r>maxPR)maxPR=r;
            }
            let backstageCells=null,backstageSide=null,backstageFreeCell=null,backstagePenCells=null;
            const targetBackstageCells=2;
            const outerPublic={top:[],right:[],bottom:[],left:[]};
            for(const index of property){
                if(occupiedGrid[index])continue;
                const c=index%groundCols,r=(index/groundCols)|0;
                if(r===minPR)outerPublic.top.push([c,r]);
                if(r===maxPR)outerPublic.bottom.push([c,r]);
                if(c===minPC)outerPublic.left.push([c,r]);
                if(c===maxPC)outerPublic.right.push([c,r]);
            }
            const shuffledDirs=dirs.slice();
            for(let i=shuffledDirs.length-1;i>0;i--){
                const j=Math.floor(rand()*(i+1));
                [shuffledDirs[i],shuffledDirs[j]]=[shuffledDirs[j],shuffledDirs[i]];
            }
            for(const [side,dc,dr] of shuffledDirs){
                let pick=null,candidateCount=0;
                const horizontal=side==='top'||side==='bottom';
                for(const [c,r] of outerPublic[side]){
                    const tc=horizontal?1:0,tr=horizontal?0:1;
                    for(const sign of [-1,1]){
                        const fc=c+dc,fr=r+dr,pc=fc+tc*sign,pr=fr+tr*sign;
                        const besideC=c+tc*sign,besideR=r+tr*sign;
                        if(besideC<0||besideC>=groundCols||besideR<0||besideR>=groundRows||
                           !propertyGrid[besideR*groundCols+besideC])continue;
                        if(fc>=0&&fc<groundCols&&fr>=0&&fr<groundRows&&propertyGrid[fr*groundCols+fc])continue;
                        if(pc>=0&&pc<groundCols&&pr>=0&&pr<groundRows&&propertyGrid[pr*groundCols+pc])continue;
                        candidateCount++;
                        if(rand()*candidateCount<1){
                            const free={col:fc,row:fr},penFront={col:pc,row:pr};
                            pick={free,pen:[penFront],cells:[free,penFront]};
                        }
                    }
                }
                if(pick){
                    backstageCells=pick.cells;backstageFreeCell=pick.free;backstagePenCells=pick.pen;backstageSide=side;
                    break;
                }
            }

            if(backstageCells){
                b.backstageCells=backstageCells.map(c=>trueBuilderCellKey(c.col,c.row));
                b.backstageFreeCell=trueBuilderCellKey(backstageFreeCell.col,backstageFreeCell.row);
                const makePen=cells=>{
                    const c0=Math.min(...cells.map(c=>c.col)),r0=Math.min(...cells.map(c=>c.row));
                    const enc={id:state.nextId++,trueBuilt:true,trueBackstage:true,sourceEnclosureNumber:1,
                        cells:trueCanonicalCellList(cells.map(c=>({col:c.col-c0,row:c.row-r0}))),
                        x:c0*TRUE_ENC_CELL_W,y:r0*TRUE_ENC_CELL_H};
                    state.enclosures.push(enc);return enc.id;
                };
                b.backstageEnclosureIds=[makePen(backstagePenCells)];
                const backstageAreaCells=backstageCells.map(c=>({col:c.col,row:c.row}));
                const backstageArea={
                    id:`true-backstage-area-${state.nextId++}`,
                    name:'Backstage',
                    type:'area',
                    color:'#6A7858',
                    colour:'#6A7858',
                    cells:backstageAreaCells,
                    geometry:areaCellGeometry(backstageAreaCells),
                    enclosureIds:[...b.backstageEnclosureIds],
                    tags:['Backstage'],
                    tag:'Backstage',
                    trueBackstageArea:true,
                    diagnostic:false
                };
                state.customAreas=(state.customAreas||[]).filter(a=>!a?.trueBackstageArea);
                state.customAreas.push(backstageArea);
                const allStarterAnimals=(state.animals||[]).filter(a=>!a?.trueArrivalPending);
                if(allStarterAnimals.length){
                    const speciesKey=a=>`${a.category}|${Number(a.level)||1}|${cleanFilename(a.filename)}`;
                    const counts=new Map();
                    for(const a of allStarterAnimals)counts.set(speciesKey(a),(counts.get(speciesKey(a))||0)+1);
                    const duplicateKeys=[...counts.entries()].filter(([,n])=>n===2).map(([k])=>k);

                    let tutorialAnimal=null;
                    if(duplicateKeys.length===1){
                        const pair=allStarterAnimals.filter(a=>speciesKey(a)===duplicateKeys[0]).sort((a,b)=>Number(b.id)-Number(a.id));
                        tutorialAnimal=pair.find(a=>a?.trueTutorialStartingDuplicate)||pair[0]||null;
                        for(const a of allStarterAnimals)delete a.trueTutorialStartingDuplicate;
                        if(tutorialAnimal)tutorialAnimal.trueTutorialStartingDuplicate=true;
                    }

                    const holding=tutorialAnimal?trueBackstageEnclosures()[0]||null:null;
                    if(tutorialAnimal&&holding){
                        const publicCopy=allStarterAnimals.find(a=>
                            a!==tutorialAnimal&&speciesKey(a)===speciesKey(tutorialAnimal)
                        )||null;
                        if(publicCopy){
                            trueOpeningDuplicatePopulationSplit(
                                publicCopy,tutorialAnimal,
                                `${state.zooName}|${speciesKey(tutorialAnimal)}`
                            );
                        }
                        tutorialAnimal.enclosureId=holding.id;
                        tutorialAnimal.slotIndex=0;
                        tutorialAnimal.reservedEnclosureId=null;
                        tutorialAnimal.reservedSlotIndex=null;
                        tutorialAnimal.reservation=null;
                        tutorialAnimal.x=holding.x;
                        tutorialAnimal.y=holding.y;
                        tutorialAnimal.trueTutorialBackstageStart=true;
                    }
                }
            }else{b.backstageCells=[];b.backstageEnclosureIds=[];b.backstageFreeCell=null;}

            {
                trueInvalidateEnclosureGeometry();
                const bounds=trueZooGroundsBounds();
                const publicGround=trueZooGroundCellSet();
                const occupiedNow=trueEnclosureSpatialIndex().occupied;
                const backstageNow=trueBackstageCellSet();
                const candidates=[];
                if(bounds&&publicGround?.size){
                    const minCol=Math.round(bounds.x/TRUE_ENC_CELL_W),maxCol=Math.round((bounds.x+bounds.w)/TRUE_ENC_CELL_W)-1;
                    const minRow=Math.round(bounds.y/TRUE_ENC_CELL_H),maxRow=Math.round((bounds.y+bounds.h)/TRUE_ENC_CELL_H)-1;
                    const addCandidate=(side,col,row)=>{
                        const key=trueBuilderCellKey(col,row);
                        if(!publicGround.has(key)||occupiedNow.has(key)||backstageNow?.has(key))return;
                        const outside=side==='top'?[col,row-1]:side==='bottom'?[col,row+1]:side==='left'?[col-1,row]:[col+1,row];
                        if(publicGround.has(trueBuilderCellKey(outside[0],outside[1])))return;
                        let px=(col+.5)*TRUE_ENC_CELL_W,py=(row+.5)*TRUE_ENC_CELL_H;
                        let spec;
                        if(side==='top'||side==='bottom'){
                            const t=Math.max(0,Math.min(1,(px-bounds.x)/bounds.w));
                            spec={side,t};
                        }else{
                            const t=Math.max(0,Math.min(1,(py-bounds.y)/bounds.h));
                            spec={side,t};
                        }
                        if(trueEntranceHasInteriorAccess(spec,bounds))candidates.push(spec);
                    };
                    for(const key of publicGround){
                        const [c,r]=String(key).split(',').map(Number);
                        addCandidate('top',c,r);addCandidate('right',c,r);
                        addCandidate('bottom',c,r);addCandidate('left',c,r);
                    }
                }
                if(candidates.length){
                    const old=b.zooEntrance||{side:'bottom',t:.5};
                    candidates.sort((a,c)=>(a.side===old.side?0:1)-(c.side===old.side?0:1)||Math.abs(a.t-old.t)-Math.abs(c.t-old.t));
                    b.zooEntrance=candidates[0];
                }
            }
        }
    }else{
        for(const before of original){
            before.enc.x=before.x;before.enc.y=before.y;
            trueInvalidateEnclosureGeometry(before.enc);
        }
        b.geometryVersion=0;
        console.warn('Could not generate a validated True zoo opening within the 28-cell starting perimeter; keeping previous geometry for this render. Run zooLayoutDiagnostic() in the console for the exact rejection counts.');
    }
    layoutDiag.searchBudgetRemaining=Math.max(0,totalSearchBudget);
    layoutDiag.chosen=chosen?{
        cols:chosen.cols,rows:chosen.rows,entranceCol:chosen.entranceCol,
        propertyCells:Array.isArray(b.startingGroundsCells)?b.startingGroundsCells.length:0
    }:null;
    if(!chosen&&!layoutDiag.finalFailure){
        const ranked=Object.entries(layoutDiag.failureReasons).sort((a,b)=>b[1]-a[1]);
        layoutDiag.finalFailure=ranked.length?`search-exhausted; top rejection: ${ranked[0][0]} (${ranked[0][1]})`:'search-exhausted-without-complete-placement';
    }
    layoutDiag.finishedAt=new Date().toISOString();
    b.zooGroundsVersion=12;
    if(chosen&&Array.isArray(b.startingGroundsCells)&&b.startingGroundsCells.length)b.geometryVersion=43;
    trueInvalidateEnclosureGeometry();
    if(changed)state.areaPlacementRevision=(Number(state.areaPlacementRevision)||0)+1;
    return changed;
}

function normaliseTrueEnclosureArchitecture(){
    if(state.gameMode!=='true'||state.sandboxMode)return false;
    const b=normaliseTrueEnclosureBuilderState();
    if(Number(b.architectureVersion)>=1)return false;
    let changed=false;
    for(const enc of state.enclosures||[])if(enc?.trueBuilt&&trueCanonicaliseEnclosure(enc))changed=true;
    b.architectureVersion=1;
    trueInvalidateEnclosureGeometry();
    if(changed)state.areaPlacementRevision=(Number(state.areaPlacementRevision)||0)+1;
    return changed;
}

function areaGridCellSize(){
    return state.gameMode==='true'
        ? {w:TRUE_ENC_CELL_W,h:TRUE_ENC_CELL_H}
        : {w:ENCLOSURE_W/2,h:ENCLOSURE_H/2};
}
function classicAreaLogicalUnits(){
    if(state.gameMode==='true')return [];
    return geographicLogicalExhibits().map(unit=>{
        const enc=unit._geoPhysicalEnclosure||unit;
        const group=(unit._geoGroup||getAllSlots(enc)).map(Number).filter(n=>n>=0&&n<=3);
        const slots=group.map(n=>({col:n%2,row:Math.floor(n/2)}));
        if(!slots.length)return null;
        const minC=Math.min(...slots.map(c=>c.col)),maxC=Math.max(...slots.map(c=>c.col));
        const minR=Math.min(...slots.map(c=>c.row)),maxR=Math.max(...slots.map(c=>c.row));
        const rect={x:enc.x+minC*(ENCLOSURE_W/2),y:enc.y+minR*(ENCLOSURE_H/2),w:(maxC-minC+1)*(ENCLOSURE_W/2),h:(maxR-minR+1)*(ENCLOSURE_H/2)};
        const center={x:rect.x+rect.w/2,y:rect.y+rect.h/2};
        const s=areaGridCellSize(),cell={col:Math.floor(center.x/s.w),row:Math.floor(center.y/s.h)};
        const logicalKey=`${String(enc.id)}:${[...new Set(group)].sort((a,b)=>a-b).join(',')}`;
        return {unit,rect,cell,key:trueAreaCellKey(cell.col,cell.row),logicalKey};
    }).filter(Boolean);
}
function classicAreaUnitForCell(c){return classicAreaLogicalUnits().find(u=>u.cell.col===c.col&&u.cell.row===c.row)||null;}
function classicAreaLogicalKeysForCells(cells){
    const keys=[];
    for(const cell of cells||[]){
        const unit=classicAreaUnitForCell(cell);
        if(unit?.logicalKey)keys.push(unit.logicalKey);
    }
    return [...new Set(keys)];
}
function classicAreaUnitAtPoint(x,y){
    return classicAreaLogicalUnits().find(u=>x>=u.rect.x&&x<=u.rect.x+u.rect.w&&y>=u.rect.y&&y<=u.rect.y+u.rect.h)||null;
}
function areaSnapWorldPoint(x,y){
    if(state.gameMode!=='true'){const u=classicAreaUnitAtPoint(x,y);if(u)return {...u.cell};}
    const s=areaGridCellSize();return{col:Math.floor(x/s.w),row:Math.floor(y/s.h)};
}
function areaCellRenderRect(c){
    if(state.gameMode!=='true'){
        const u=classicAreaUnitForCell(c);
        if(u){
            const inset=8;
            return{x:u.rect.x+inset,y:u.rect.y+inset,w:Math.max(1,u.rect.w-inset*2),h:Math.max(1,u.rect.h-inset*2)};
        }
    }
    const s=areaGridCellSize();return{x:c.col*s.w,y:c.row*s.h,w:s.w,h:s.h};
}
function areaCellGeometry(cells){
    if(!cells?.length)return null;
    const rs=cells.map(areaCellRenderRect).filter(Boolean);if(!rs.length)return null;
    const minX=Math.min(...rs.map(r=>r.x)),minY=Math.min(...rs.map(r=>r.y)),maxX=Math.max(...rs.map(r=>r.x+r.w)),maxY=Math.max(...rs.map(r=>r.y+r.h));
    return{x:minX,y:minY,w:maxX-minX,h:maxY-minY};
}
function classicAreaOuterCardRect(area,pad=12){
    if(state.gameMode==='true')return null;
    const rects=trueAreaCells(area).map(areaCellRenderRect).filter(Boolean);
    if(!rects.length)return null;
    const minX=Math.min(...rects.map(r=>r.x))-pad,minY=Math.min(...rects.map(r=>r.y))-pad;
    const maxX=Math.max(...rects.map(r=>r.x+r.w))+pad,maxY=Math.max(...rects.map(r=>r.y+r.h))+pad;
    return{x:minX,y:minY,w:maxX-minX,h:maxY-minY};
}
function classicAreaUnionBoundarySegments(area,pad=0){
    if(state.gameMode==='true')return [];
    const sourceRects=trueAreaCells(area).map(c=>{
        const unit=classicAreaUnitForCell(c);
        return unit?.rect||areaCellRenderRect(c);
    }).filter(Boolean);
    if(!sourceRects.length)return [];

    const bridgeTol=ENCLOSURE_AREA_ADJACENCY_TOLERANCE+8;
    const expansions=sourceRects.map(()=>({left:0,right:0,top:0,bottom:0}));
    for(let i=0;i<sourceRects.length;i++)for(let j=i+1;j<sourceRects.length;j++){
        const a=sourceRects[i],b=sourceRects[j];
        const vo=Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y);
        const ho=Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x);
        const hGap=Math.max(0,Math.max(b.x-(a.x+a.w),a.x-(b.x+b.w)));
        const vGap=Math.max(0,Math.max(b.y-(a.y+a.h),a.y-(b.y+b.h)));

        if(vo>8&&hGap>0&&hGap<=ENCLOSURE_GAP+bridgeTol){
            const leftIndex=a.x<=b.x?i:j,rightIndex=leftIndex===i?j:i;
            const half=hGap/2;
            expansions[leftIndex].right=Math.max(expansions[leftIndex].right,half);
            expansions[rightIndex].left=Math.max(expansions[rightIndex].left,hGap-half);
        }else if(ho>8&&vGap>0&&vGap<=ENCLOSURE_GAP+bridgeTol){
            const topIndex=a.y<=b.y?i:j,bottomIndex=topIndex===i?j:i;
            const half=vGap/2;
            expansions[topIndex].bottom=Math.max(expansions[topIndex].bottom,half);
            expansions[bottomIndex].top=Math.max(expansions[bottomIndex].top,vGap-half);
        }
    }
    const rects=sourceRects.map((r,index)=>{
        const e=expansions[index];
        return {
            x:r.x-e.left-pad,
            y:r.y-e.top-pad,
            w:r.w+e.left+e.right+pad*2,
            h:r.h+e.top+e.bottom+pad*2
        };
    });

    const xs=[...new Set(rects.flatMap(r=>[r.x,r.x+r.w]))].sort((a,b)=>a-b);
    const ys=[...new Set(rects.flatMap(r=>[r.y,r.y+r.h]))].sort((a,b)=>a-b);
    const occupied=(x0,x1,y0,y1)=>rects.some(r=>
        x0>=r.x-0.01&&x1<=r.x+r.w+0.01&&
        y0>=r.y-0.01&&y1<=r.y+r.h+0.01
    );
    const segs=[];
    for(let yi=0;yi<ys.length;yi++)for(let xi=0;xi<xs.length-1;xi++){
        const y=ys[yi],x0=xs[xi],x1=xs[xi+1];
        if(x1-x0<0.01)continue;
        const above=yi>0&&occupied(x0,x1,ys[yi-1],y);
        const below=yi<ys.length-1&&occupied(x0,x1,y,ys[yi+1]);
        if(above!==below)segs.push([{x:x0,y},{x:x1,y}]);
    }
    for(let xi=0;xi<xs.length;xi++)for(let yi=0;yi<ys.length-1;yi++){
        const x=xs[xi],y0=ys[yi],y1=ys[yi+1];
        if(y1-y0<0.01)continue;
        const left=xi>0&&occupied(xs[xi-1],x,y0,y1);
        const right=xi<xs.length-1&&occupied(x,xs[xi+1],y0,y1);
        if(left!==right)segs.push([{x,y:y0},{x,y:y1}]);
    }
    const mergeAxisSegments=(segments,horizontal)=>{
        const groups=new Map();
        for(const [p0,p1] of segments){
            const fixed=horizontal?p0.y:p0.x;
            const a=horizontal?Math.min(p0.x,p1.x):Math.min(p0.y,p1.y);
            const b=horizontal?Math.max(p0.x,p1.x):Math.max(p0.y,p1.y);
            const key=(Math.round(fixed*100)/100).toFixed(2);
            if(!groups.has(key))groups.set(key,{fixed,ranges:[]});
            groups.get(key).ranges.push([a,b]);
        }
        const merged=[];
        for(const {fixed,ranges} of groups.values()){
            ranges.sort((a,b)=>a[0]-b[0]);
            let [lo,hi]=ranges[0]||[];
            if(lo==null)continue;
            for(let i=1;i<ranges.length;i++){
                const [a,b]=ranges[i];
                if(a<=hi+.05)hi=Math.max(hi,b);
                else{
                    merged.push(horizontal
                        ? [{x:lo,y:fixed},{x:hi,y:fixed}]
                        : [{x:fixed,y:lo},{x:fixed,y:hi}]);
                    [lo,hi]=[a,b];
                }
            }
            merged.push(horizontal
                ? [{x:lo,y:fixed},{x:hi,y:fixed}]
                : [{x:fixed,y:lo},{x:fixed,y:hi}]);
        }
        return merged;
    };
    const horizontal=segs.filter(([a,b])=>Math.abs(a.y-b.y)<.01);
    const vertical=segs.filter(([a,b])=>Math.abs(a.x-b.x)<.01);
    return [...mergeAxisSegments(horizontal,true),...mergeAxisSegments(vertical,false)];
}

const CLASSIC_AREA_BORDER_WIDTH=8;
const CLASSIC_AREA_TRACK_GAP=3;
function classicAreaTrackGeometry(area,orderedAreas=null){
    if(state.gameMode==='true')return null;

    const minimumPad=0;
    const level=areaGeographyIdentity(area)?.level||'';
    const hierarchyInset=level==='realm'?10:level==='subregion'?5:0;
    const basePad=minimumPad+hierarchyInset;

    return {
        pad:basePad,
        depth:0,
        basePad,
        trackStep:CLASSIC_AREA_BORDER_WIDTH+CLASSIC_AREA_TRACK_GAP
    };
}
function classicAreaLocalBoundarySegments(area,orderedAreas){
    const track=classicAreaTrackGeometry(area,orderedAreas);
    const basePad=track?.basePad||0;

    const identity=areaGeographyIdentity(area);
    if(identity?.level==='realm'||identity?.level==='subregion'||identity?.level==='bioregion'){
        return classicAreaUnionBoundarySegments(area,basePad);
    }

    const step=track?.trackStep||11;
    const own=classicAreaUnionBoundarySegments(area,basePad);
    const idx=Math.max(0,(orderedAreas||[]).indexOf(area));
    if(idx<=0)return own;

    const earlier=(orderedAreas||[]).slice(0,idx).map(peer=>
        classicAreaUnionBoundarySegments(peer,basePad)
    );
    const eps=.5;
    const out=[];
    for(const [p0,p1] of own){
        const horizontal=Math.abs(p0.y-p1.y)<eps;
        const fixed=horizontal?p0.y:p0.x;
        const lo=horizontal?Math.min(p0.x,p1.x):Math.min(p0.y,p1.y);
        const hi=horizontal?Math.max(p0.x,p1.x):Math.max(p0.y,p1.y);
        const cuts=new Set([lo,hi]);
        for(const segs of earlier)for(const [q0,q1] of segs){
            const qh=Math.abs(q0.y-q1.y)<eps;
            if(qh!==horizontal)continue;
            const qfixed=horizontal?q0.y:q0.x;
            if(Math.abs(qfixed-fixed)>eps)continue;
            const qlo=horizontal?Math.min(q0.x,q1.x):Math.min(q0.y,q1.y);
            const qhi=horizontal?Math.max(q0.x,q1.x):Math.max(q0.y,q1.y);
            const a=Math.max(lo,qlo),b=Math.min(hi,qhi);
            if(b-a>eps){cuts.add(a);cuts.add(b);}
        }
        const points=[...cuts].sort((a,b)=>a-b);
        for(let i=0;i<points.length-1;i++){
            const a=points[i],b=points[i+1];
            if(b-a<=eps)continue;
            const mid=(a+b)/2;
            let depth=0;
            for(const segs of earlier){
                const occupied=segs.some(([q0,q1])=>{
                    const qh=Math.abs(q0.y-q1.y)<eps;
                    if(qh!==horizontal)return false;
                    const qfixed=horizontal?q0.y:q0.x;
                    if(Math.abs(qfixed-fixed)>eps)return false;
                    const qlo=horizontal?Math.min(q0.x,q1.x):Math.min(q0.y,q1.y);
                    const qhi=horizontal?Math.max(q0.x,q1.x):Math.max(q0.y,q1.y);
                    return mid>qlo-eps&&mid<qhi+eps;
                });
                if(occupied)depth++;
            }
            let delta=0;
            if(depth){
                const cards=[];
                for(const c of trueAreaCells(area)){
                    const u=classicAreaUnitForCell(c);
                    const enc=u?._geoPhysicalEnclosure||u?.unit?._geoPhysicalEnclosure;
                    if(enc?.id!=null&&!cards.some(e=>String(e.id)===String(enc.id)))cards.push(enc);
                }
                const occupiedPoint=(x,y)=>cards.some(enc=>
                    x>=Number(enc.x)-basePad-.01&&x<=Number(enc.x)+ENCLOSURE_W+basePad+.01&&
                    y>=Number(enc.y)-basePad-.01&&y<=Number(enc.y)+ENCLOSURE_H+basePad+.01
                );
                const sample=Math.max(1,CLASSIC_AREA_BORDER_WIDTH);
                if(horizontal){
                    const above=occupiedPoint(mid,fixed-sample);
                    const below=occupiedPoint(mid,fixed+sample);
                    const sign=above&&!below?1:(!above&&below?-1:0);
                    delta=sign*depth*step;
                    out.push([{x:a,y:fixed+delta},{x:b,y:fixed+delta}]);
                }else{
                    const left=occupiedPoint(fixed-sample,mid);
                    const right=occupiedPoint(fixed+sample,mid);
                    const sign=left&&!right?1:(!left&&right?-1:0);
                    delta=sign*depth*step;
                    out.push([{x:fixed+delta,y:a},{x:fixed+delta,y:b}]);
                }
            }else{
                out.push(horizontal?[{x:a,y:fixed},{x:b,y:fixed}]:[{x:fixed,y:a},{x:fixed,y:b}]);
            }
        }
    }
    return out;
}
function classicAreaDisplayRect(area,orderedAreas=null){
    if(state.gameMode==='true')return null;
    const raw=classicAreaOuterCardRect(area,0);if(!raw)return null;
    const track=classicAreaTrackGeometry(area,orderedAreas);if(!track)return raw;
    const pad=track.pad;
    return{x:raw.x-pad,y:raw.y-pad,w:raw.w+pad*2,h:raw.h+pad*2,_trackDepth:track.depth};
}
function areaCellInsideWorkspace(c){
    if(state.gameMode==='true')return trueWorldCellInsideZooGrounds(c.col,c.row);
    return !!classicAreaUnitForCell(c);
}
function areaCellsForPhysicalEnclosure(enc){
    if(state.gameMode==='true')return trueBuiltWorldCells(enc);
    return geographicLogicalExhibits().filter(u=>String(u._geoPhysicalEnclosure?.id)===String(enc.id)).map(u=>{const r=geographicUnitRect(u);return areaSnapWorldPoint(r.x+r.w/2,r.y+r.h/2);});
}
function trueAreaBuilderState(){
    if(!state.trueAreaBuilder||typeof state.trueAreaBuilder!=='object')state.trueAreaBuilder={};
    const a=state.trueAreaBuilder;if(!['area','house'].includes(a.type))a.type='area';if(!a.color)a.color='#5b78c7';return a;
}
function trueAreaRect(area){
    if(area?.geometry&&Number(area.geometry.w)>0&&Number(area.geometry.h)>0)return area.geometry;
    const es=(area?.enclosureIds||[]).map(id=>enclosureByIdFast(id)).filter(Boolean);if(!es.length)return null;
    const minX=Math.min(...es.map(e=>e.x)),minY=Math.min(...es.map(e=>e.y)),maxX=Math.max(...es.map(e=>e.x+trueEnclosureWidth(e))),maxY=Math.max(...es.map(e=>e.y+trueEnclosureHeight(e)));
    return {x:minX,y:minY,w:maxX-minX,h:maxY-minY};
}
function trueAreaCellKey(c,r){return `${c},${r}`;}
function trueAreaCells(area){
    if(Array.isArray(area?.cells)&&area.cells.length)return area.cells.map(c=>({col:Number(c.col)||0,row:Number(c.row)||0}));
    const r=trueAreaRect(area);if(!r)return [];const a=areaSnapWorldPoint(r.x,r.y),b=areaSnapWorldPoint(r.x+r.w,r.y+r.h),out=[];
    for(let row=Math.min(a.row,b.row);row<Math.max(a.row,b.row);row++)for(let col=Math.min(a.col,b.col);col<Math.max(a.col,b.col);col++)out.push({col,row});return out;
}
function trueAreaCellsConnected(cells){
    if(!cells?.length)return false;
    if(state.gameMode!=='true'){
        const remaining=[...cells],seen=new Set([trueAreaCellKey(remaining[0].col,remaining[0].row)]),stack=[remaining[0]];
        const near=(a,b)=>{const ra=areaCellRenderRect(a),rb=areaCellRenderRect(b);if(!ra||!rb)return false;const gap=ENCLOSURE_GAP+20;return ra.x<=rb.x+rb.w+gap&&ra.x+ra.w+gap>=rb.x&&ra.y<=rb.y+rb.h+gap&&ra.y+ra.h+gap>=rb.y;};
        while(stack.length){const a=stack.pop();for(const b of remaining){const k=trueAreaCellKey(b.col,b.row);if(!seen.has(k)&&near(a,b)){seen.add(k);stack.push(b);}}}
        return seen.size===cells.length;
    }
    const keys=new Set(cells.map(c=>trueAreaCellKey(c.col,c.row))),seen=new Set(),stack=[cells[0]];
    while(stack.length){const c=stack.pop(),k=trueAreaCellKey(c.col,c.row);if(seen.has(k))continue;seen.add(k);for(const[d,e]of[[1,0],[-1,0],[0,1],[0,-1]]){const nk=trueAreaCellKey(c.col+d,c.row+e);if(keys.has(nk)&&!seen.has(nk))stack.push({col:c.col+d,row:c.row+e});}}
    return seen.size===cells.length;
}
function trueRefreshCustomAreaMembership(area){
    const cells=trueAreaCells(area);
    const keys=new Set(cells.map(c=>trueAreaCellKey(c.col,c.row)));
    area.enclosureIds=(state.enclosures||[]).filter(enc=>areaCellsForPhysicalEnclosure(enc).some(c=>keys.has(trueAreaCellKey(c.col,c.row)))).map(enc=>enc.id);
    if(state.gameMode!=='true')area.classicLogicalKeys=classicAreaLogicalKeysForCells(cells);
}
let classicAreaReconcileSignature='';
function reconcileClassicCustomAreaCells(){
    if(state.gameMode==='true')return false;
    const signature=`${Number(state.areaPlacementRevision)||0}|${state.enclosures?.length||0}|${state.customAreas?.length||0}|`+
        (state.customAreas||[]).map(area=>`${area?.id??''}:${area?.classicLogicalKeys?.join(',')||''}:${area?.cells?.length||0}`).join(';');
    if(signature===classicAreaReconcileSignature)return false;
    const units=classicAreaLogicalUnits();
    const byLogicalKey=new Map(units.map(unit=>[unit.logicalKey,unit]));
    let changed=false;
    for(const area of state.customAreas||[]){
        if(area?.type==='house')continue;

        let logicalKeys=Array.isArray(area.classicLogicalKeys)
            ? [...new Set(area.classicLogicalKeys.map(String))]
            : classicAreaLogicalKeysForCells(trueAreaCells(area));
        if(!Array.isArray(area.classicLogicalKeys)){
            area.classicLogicalKeys=logicalKeys;
            changed=true;
        }

        const matched=logicalKeys.map(key=>byLogicalKey.get(key)).filter(Boolean);
        if(!matched.length)continue;
        const next=[...new Map(matched.map(unit=>[unit.key,{...unit.cell}])).values()];
        const before=trueAreaCells(area).map(c=>trueAreaCellKey(c.col,c.row)).sort().join('|');
        const after=next.map(c=>trueAreaCellKey(c.col,c.row)).sort().join('|');
        if(before!==after){
            area.cells=next;
            area.geometry=areaCellGeometry(next);
            changed=true;
        }

        const physicalIds=[...new Set(matched.map(wrapper=>wrapper.unit?._geoPhysicalEnclosure||wrapper.unit)
            .map(enc=>enc?.id).filter(id=>id!=null))];
        if(JSON.stringify((area.enclosureIds||[]).map(String).sort())!==JSON.stringify(physicalIds.map(String).sort())){
            area.enclosureIds=physicalIds;
            changed=true;
        }
    }
    if(changed)trueRefreshAreaHierarchy();
    classicAreaReconcileSignature=`${Number(state.areaPlacementRevision)||0}|${state.enclosures?.length||0}|${state.customAreas?.length||0}|`+
        (state.customAreas||[]).map(area=>`${area?.id??''}:${area?.classicLogicalKeys?.join(',')||''}:${area?.cells?.length||0}`).join(';');
    return changed;
}
function trueCommitPaintedAreaCells(cells,targetId=null){
    cells=[...new Map((cells||[]).map(c=>[trueAreaCellKey(c.col,c.row),c])).values()];if(!cells.length||!cells.every(c=>areaCellInsideWorkspace(c))||!trueAreaCellsConnected(cells))return false;
    if(targetId!=null){const area=(state.customAreas||[]).find(a=>String(a.id)===String(targetId));if(!area)return false;const merged=[...new Map([...trueAreaCells(area),...cells].map(c=>[trueAreaCellKey(c.col,c.row),c])).values()];if(!trueAreaCellsConnected(merged))return false;truePushBuilderUndo('area-add');area.cells=merged;area.geometry=areaCellGeometry(merged);trueRefreshCustomAreaMembership(area);trueAreaBuilderSelectedId=String(area.id);}
    else{const a=trueAreaBuilderState();truePushBuilderUndo('area-new');normaliseCustomAreaZOrder();const area={id:`custom-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,name:a.type==='house'?'House':'Area',color:a.color,type:a.type,lineStyle:'solid',zOrder:Math.max(-1,...(state.customAreas||[]).map(x=>Number(x.zOrder)||0))+1,cells,geometry:areaCellGeometry(cells),enclosureIds:[],_new:true};trueRefreshCustomAreaMembership(area);state.customAreas.push(area);trueAreaBuilderSelectedId=String(area.id);}
    trueRefreshAreaHierarchy();state.areaPlacementRevision=(Number(state.areaPlacementRevision)||0)+1;renderAll();refreshTrueEnclosureCapacityBadge();return true;
}
function trueDeletePaintedAreaCell(id,col,row){
    const area=(state.customAreas||[]).find(a=>String(a.id)===String(id));if(!area)return false;
    const cells=trueAreaCells(area),remaining=cells.filter(c=>c.col!==col||c.row!==row);if(remaining.length===cells.length)return false;
    if(remaining.length&&!trueAreaCellsConnected(remaining))return false;
    truePushBuilderUndo(remaining.length?'area-cell-delete':'area-delete');
    clearCustomAreaLeader?.(area.id);document.getElementById('areaStyleMenu')?.remove();
    if(!remaining.length){
        state.customAreas=state.customAreas.filter(a=>a!==area);
        trueAreaBuilderSelectedId=null;trueAreaBuilderSelectedCell=null;
    }else{
        area.cells=remaining;area.geometry=areaCellGeometry(remaining);trueRefreshCustomAreaMembership(area);
        if(String(trueAreaBuilderSelectedId)===String(area.id)){
            const fallback=remaining[0];
            trueAreaBuilderSelectedCell=fallback?{...fallback}:null;
        }
    }
    trueRefreshAreaHierarchy();state.areaPlacementRevision=(Number(state.areaPlacementRevision)||0)+1;
    renderAll();return true;
}
function trueRefreshAreaHierarchy(){
    const areas=state.customAreas||[];
    const cached=new Map(areas.map(area=>{
        const cells=trueAreaCells(area);
        return [area,{cells,keys:new Set(cells.map(c=>trueAreaCellKey(c.col,c.row)))}];
    }));
    for(const area of areas){
        const own=cached.get(area)?.cells||[];
        area.lineStyle=areas.some(other=>{
            if(other===area)return false;
            const peer=cached.get(other);
            return peer&&peer.cells.length>own.length&&
                own.every(c=>peer.keys.has(trueAreaCellKey(c.col,c.row)));
        })?'dotted':'solid';
    }
}
function trueHouseCellsForEnclosure(enc){
    if(state.gameMode!=='true')return [];
    const encKeys=new Set(trueBuiltWorldCells(enc).map(c=>trueAreaCellKey(c.col,c.row))),out=[];
    for(const house of state.customAreas||[]){if(house.type!=='house')continue;for(const c of trueAreaCells(house))if(encKeys.has(trueAreaCellKey(c.col,c.row)))out.push({col:c.col,row:c.row,house});}
    return out;
}

function trueBuilderCellKey(x,y){return `${Math.round(x)},${Math.round(y)}`;}
function trueBuilderOccupiedWorldCells(exceptId=null){
    if(exceptId==null)return new Set(trueEnclosureSpatialIndex().occupied);
    const out=new Set();
    for(const enc of state.enclosures||[]){
        if(!enc?.trueBuilt||String(enc.id)===String(exceptId))continue;
        for(const c of trueBuiltWorldCells(enc))out.add(trueBuilderCellKey(c.col,c.row));
    }
    return out;
}
function trueBuilderCanPlaceWorldCells(cells,exceptId=null){
    const occupied=trueBuilderOccupiedWorldCells(exceptId);
    return cells.every(c=>!occupied.has(trueBuilderCellKey(c.col,c.row)));
}
function trueBuilderAccessReport(candidateCells=[],exceptId=null){
    const grounds=trueZooGroundsBounds();
    if(!grounds)return {ok:true,blockedCells:[]};

    const minCol=Math.ceil(grounds.x/TRUE_ENC_CELL_W);
    const maxCol=Math.floor((grounds.x+grounds.w)/TRUE_ENC_CELL_W)-1;
    const minRow=Math.ceil(grounds.y/TRUE_ENC_CELL_H);
    const maxRow=Math.floor((grounds.y+grounds.h)/TRUE_ENC_CELL_H)-1;
    if(maxCol-minCol<2||maxRow-minRow<2)return {ok:false,blockedCells:[...(candidateCells||[])]};

    const spec=trueZooEntranceSpec(grounds);
    const entranceCells=trueEntranceInteriorCells(spec,grounds);
    if(!entranceCells.length)return {ok:false,blockedCells:[...(candidateCells||[])]};

    const inGrounds=c=>c.col>=minCol&&c.col<=maxCol&&c.row>=minRow&&c.row<=maxRow;

    const analyse=(occupied,enclosures)=>{
        const free=c=>inGrounds(c)&&!occupied.has(trueBuilderCellKey(c.col,c.row));
        if(!entranceCells.every(free))return {reachable:new Set(),blocked:[...enclosures],entranceBlocked:true};
        const reachable=new Set(),queue=[...entranceCells];
        while(queue.length){
            const c=queue.shift(),k=trueBuilderCellKey(c.col,c.row);
            if(reachable.has(k)||!free(c))continue;
            reachable.add(k);
            for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]])
                queue.push({col:c.col+dc,row:c.row+dr});
        }
        const blocked=enclosures.filter(enc=>{
            const cells=enc.cells||[];
            return !cells.some(c=>[[1,0],[-1,0],[0,1],[0,-1]].some(([dc,dr])=>
                reachable.has(trueBuilderCellKey(c.col+dc,c.row+dr))
            ));
        });
        return {reachable,blocked};
    };

    const existing=[];
    const baseOccupied=new Set();
    for(const enc of state.enclosures||[]){
        if(!enc?.trueBuilt)continue;
        if(exceptId!=null&&String(enc.id)===String(exceptId))continue;
        const cells=trueBuiltWorldCells(enc);
        existing.push({id:String(enc.id),cells});
        for(const c of cells)baseOccupied.add(trueBuilderCellKey(c.col,c.row));
    }

    const before=analyse(baseOccupied,existing);
    const beforeBlockedIds=new Set(before.blocked.map(enc=>enc.id));

    const afterOccupied=new Set(baseOccupied);
    for(const c of candidateCells||[])afterOccupied.add(trueBuilderCellKey(c.col,c.row));
    const candidate={id:'__candidate__',cells:[...(candidateCells||[])]};
    const after=analyse(afterOccupied,[...existing,candidate]);

    const candidateIsBackstage=(candidateCells||[]).length>0&&(candidateCells||[]).every(c=>trueCellIsBackstage(c.col,c.row));
    const candidateBlocked=!candidateIsBackstage&&after.blocked.some(enc=>enc.id==='__candidate__');
    const newlyCutOff=after.blocked.filter(enc=>{
        if(enc.id==='__candidate__'||beforeBlockedIds.has(enc.id))return false;
        const actual=enclosureByIdFast(enc.id);
        return !actual?.trueBackstage;
    });
    const blockedCells=[
        ...(candidateBlocked?(candidateCells||[]):[]),
        ...newlyCutOff.flatMap(enc=>enc.cells||[])
    ];
    return {
        ok:!candidateBlocked&&!newlyCutOff.length,
        blockedCells,
        cutOffEnclosureIds:newlyCutOff.map(enc=>enc.id),
        preExistingBlockedEnclosureIds:[...beforeBlockedIds]
    };
}
function trueCompactConnectedCells(count){
    count=Math.max(1,Math.round(Number(count)||1));
    const cols=Math.max(1,Math.ceil(Math.sqrt(count))),cells=[];
    for(let i=0;i<count;i++)cells.push({col:i%cols,row:Math.floor(i/cols)});
    return cells;
}
function trueRepairOpeningCompatibility(){
    if(state.gameMode!=='true'||state.sandboxMode||state.gameOptions?.enforceAnimalCombinations===false)return true;
    const enclosures=(state.enclosures||[]).filter(e=>e?.trueBuilt&&!trueEnclosureIsCurrentBackstage(e));
    const residentsByEnclosure=()=>new Map(enclosures.map(enc=>[
        String(enc.id),classicAnimalsByEnclosure(enc.id)
    ]));
    let guard=50;
    while(guard-->0){
        const residentMap=residentsByEnclosure();
        const problem=enclosures.map(enc=>({enc,residents:residentMap.get(String(enc.id))||[]}))
            .find(entry=>entry.residents.length>1&&!animalsFormCompatibilityChain(entry.residents));
        if(!problem)return true;

        // Try every resident, not only the last one. A mixed opening group can often be
        // repaired by moving a different species while the last resident has no legal home.
        let destination=null,moving=null;
        for(let movingIndex=problem.residents.length-1;movingIndex>=0&&!destination;movingIndex--){
            const candidate=problem.residents[movingIndex];
            for(const enc of enclosures){
                if(String(enc.id)===String(problem.enc.id))continue;
                const residents=residentMap.get(String(enc.id))||[];
                if(residents.length&&
                   !animalsFormCompatibilityChain([...residents,candidate]))continue;
                const capacity=Math.max(1,trueBuiltWorldCells(enc).length);
                const occupied=new Uint8Array(capacity);
                for(const a of residents){
                    const slot=Number(a.slotIndex);
                    if(slot>=0&&slot<capacity)occupied[slot]=1;
                }
                const slot=occupied.findIndex(value=>!value);
                if(slot<0)continue;
                moving=candidate;destination={enc,slot};break;
            }
        }

        // Opening generation must not fail merely because every compatible converted
        // enclosure is full. True enclosures are cell-based and can safely gain one
        // compact cell here; this preserves all 5-7 opening animals instead of aborting.
        if(!destination){
            outer:
            for(let movingIndex=problem.residents.length-1;movingIndex>=0;movingIndex--){
                const candidate=problem.residents[movingIndex];
                for(const enc of enclosures){
                    if(String(enc.id)===String(problem.enc.id))continue;
                    const residents=residentMap.get(String(enc.id))||[];
                    if(residents.length&&
                       !animalsFormCompatibilityChain([...residents,candidate]))continue;
                    const oldCapacity=Math.max(1,trueBuiltWorldCells(enc).length);
                    enc.cells=trueCompactCellShape(oldCapacity+1);
                    trueInvalidateEnclosureGeometry(enc);
                    moving=candidate;destination={enc,slot:oldCapacity};
                    break outer;
                }
            }
        }
        if(!destination||!moving)return false;
        const builder=normaliseTrueEnclosureBuilderState();
        builder.totalSpaces=Math.max(Number(builder.totalSpaces)||0,trueBuilderUsedSpaces());
        moving.enclosureId=destination.enc.id;
        moving.slotIndex=destination.slot;
        clearAnimalZooReservation(moving);
    }
    const finalResidents=residentsByEnclosure();
    return enclosures.every(enc=>{
        const residents=finalResidents.get(String(enc.id))||[];
        return residents.length<2||animalsFormCompatibilityChain(residents);
    });
}

function truePrepareOpeningZooChallenges(){
    if(state.gameMode!=='true'||state.sandboxMode)return false;
    const animals=(state.animals||[]).filter(a=>a&&a.enclosureId!=null);
    const enclosures=(state.enclosures||[]).filter(e=>e?.trueBuilt);
    if(!animals.length||!enclosures.length)return false;
    const residentsByEnclosure=new Map(enclosures.map(e=>[String(e.id),[]]));
    for(const animal of animals)
        residentsByEnclosure.get(String(animal.enclosureId))?.push(animal);
    const residentsOf=enc=>residentsByEnclosure.get(String(enc.id))||[];

    for(const animal of animals){
        animal.population=trueKnownSexLegalPopulation(
            animal,`opening-legal|${state.zooName}|${animalCardKey(animal)}|${animal.id}`
        );
    }

    for(const enc of enclosures){
        const residents=residentsOf(enc);
        if(!residents.length)continue;
        const required=Math.max(1,...residents.map(trueAnimalManagedEnclosureCells));
        enc.cells=trueCompactConnectedCells(required);
        trueInvalidateEnclosureGeometry(enc);
    }

    const groupOrder=[...animals].sort((a,b)=>
        seededRoll(`opening-group|${state.zooName}|${a.id}`).roll-
        seededRoll(`opening-group|${state.zooName}|${b.id}`).roll);
    let groupChallenge=null;
    for(const animal of groupOrder){
        const legal={...animal.population};
        const status=truePopulationGroupSizeStatus(animal);
        if(!Number.isFinite(status.max)||status.max<1)continue;
        const preferredTotal=Math.max(1,legal.males+legal.females);
        const targetTotal=preferredTotal+2;
        const population={males:0,females:0,unknown:0};
        const femaleShare=(legal.males+legal.females)>0
            ? legal.females/(legal.males+legal.females)
            : .5;
        population.females=Math.max(0,Math.min(targetTotal,Math.round(targetTotal*femaleShare)));
        population.males=targetTotal-population.females;
        animal.population=population;
        groupChallenge=animal;
        animal.trueOpeningPreferredGroupSize=preferredTotal;
        animal.trueOpeningGroupSurplus=2;
        break;
    }

    const occupied=enclosures.filter(enc=>residentsOf(enc).length);
    const shuffled=[...occupied].sort((a,b)=>
        seededRoll(`opening-space|${state.zooName}|${a.id}`).roll-
        seededRoll(`opening-space|${state.zooName}|${b.id}`).roll);
    let smallEnc=null,bigEnc=null;
    for(const enc of shuffled){
        const residents=residentsOf(enc);
        const required=Math.max(1,...residents.map(trueAnimalManagedEnclosureCells));
        if(required>1){smallEnc=enc;break;}
    }
    for(const enc of shuffled){
        if(enc===smallEnc)continue;
        bigEnc=enc;break;
    }
    if(!smallEnc){
        smallEnc=shuffled[0]||null;
        if(smallEnc){
            const animal=residentsOf(smallEnc)[0];
            if(animal){
                const p=normaliseTrueAnimalPopulation(animal);
                while(trueAnimalManagedEnclosureCells(animal)<2){
                    if(p.females>p.males)p.females++;else p.males++;
                }
            }
        }
    }
    if(!bigEnc)bigEnc=shuffled.find(e=>e!==smallEnc)||null;

    const setRelative=(enc,delta)=>{
        if(!enc)return;
        const residents=residentsOf(enc);
        const required=Math.max(1,...residents.map(trueAnimalManagedEnclosureCells));
        const count=Math.max(1,residents.length,required+delta);
        enc.cells=trueCompactConnectedCells(count);
        trueInvalidateEnclosureGeometry(enc);
    };
    setRelative(smallEnc,-1);
    setRelative(bigEnc,1);

    let used=trueBuilderUsedSpaces();
    if(used>9){
        const protectedIds=new Set([smallEnc?.id,bigEnc?.id].filter(x=>x!=null).map(String));
        for(const enc of enclosures){
            if(used<=9||protectedIds.has(String(enc.id)))continue;
            const current=trueCanonicalCellList(enc.cells||[]).length;
            const residents=residentsOf(enc);
            const managedFloor=Math.max(1,residents.length,...residents.map(trueAnimalManagedEnclosureCells));
            if(current<=managedFloor)continue;
            const remove=Math.min(current-managedFloor,used-9);
            enc.cells=trueCompactConnectedCells(current-remove);
            trueInvalidateEnclosureGeometry(enc);used-=remove;
        }
    }
    const enclosureById=new Map(enclosures.map(e=>[String(e.id),e]));
    const undersizedSpecies=()=>{
        const out=[];
        for(const animal of animals){
            const enc=enclosureById.get(String(animal.enclosureId));
            if(!enc)continue;
            const cells=Math.max(1,trueCanonicalCellList(enc.cells||[]).length);
            if(cells<trueAnimalManagedEnclosureCells(animal))out.push({animal,enc,cells});
        }
        return out;
    };
    const enclosureRequirement=enc=>Math.max(1,...residentsOf(enc).map(trueAnimalManagedEnclosureCells));

    for(const enc of enclosures){
        const residents=residentsOf(enc);if(!residents.length)continue;
        const required=Math.max(1,residents.length,...residents.map(trueAnimalManagedEnclosureCells));
        if(trueCanonicalCellList(enc.cells||[]).length<required){
            enc.cells=trueCompactConnectedCells(required);
            trueInvalidateEnclosureGeometry(enc);
        }
    }

    const challengeOrder=[...enclosures].sort((a,b)=>{
        if(a===smallEnc)return -1;if(b===smallEnc)return 1;
        const ar=residentsOf(a).length,br=residentsOf(b).length;
        if(ar!==br)return ar-br;
        return seededRoll(`opening-space-final|${state.zooName}|${a.id}`).roll-
               seededRoll(`opening-space-final|${state.zooName}|${b.id}`).roll;
    });
    let finalSpaceChallenge=null;
    for(const enc of challengeOrder){
        const residents=residentsOf(enc);if(!residents.length)continue;
        const required=Math.max(1,residents.length,...residents.map(trueAnimalManagedEnclosureCells));
        for(let cells=required-1;cells>=1;cells--){
            if(cells<residents.length)continue;
            const affected=residents.filter(a=>trueAnimalManagedEnclosureCells(a)>cells);
            if(affected.length<1||affected.length>2)continue;
            enc.cells=trueCompactConnectedCells(cells);
            trueInvalidateEnclosureGeometry(enc);
            finalSpaceChallenge={enc,cells,affected:affected.map(a=>a.id)};
            break;
        }
        if(finalSpaceChallenge)break;
    }

    if(!finalSpaceChallenge){
        const enc=challengeOrder.find(e=>residentsOf(e).length===1)||null;
        const animal=enc?residentsOf(enc)[0]:null;
        if(enc&&animal){
            const p=normaliseTrueAnimalPopulation(animal);
            let safety=20;
            while(trueAnimalManagedEnclosureCells(animal)<2&&safety-->0){
                if(p.females>p.males)p.females++;else p.males++;
                animal.population={males:p.males,females:p.females,unknown:0};
            }
            if(trueAnimalManagedEnclosureCells(animal)>=2){
                enc.cells=trueCompactConnectedCells(1);
                trueInvalidateEnclosureGeometry(enc);
                finalSpaceChallenge={enc,cells:1,affected:[animal.id]};
            }
        }
    }

    const undersized=undersizedSpecies();
    if(undersized.length<1||undersized.length>2){
        throw new Error(`True opening must contain 1-2 undersized species; generated ${undersized.length}.`);
    }

    const b=normaliseTrueEnclosureBuilderState();
    b.unlockedCellCapacity=12;b.totalSpaces=12;b.cellCapacityInitialised=true;b.openingCellCapacityFloor=12;
    b.geometryVersion=0;
    return true;
}



function trueCompactCellShape(count){
    count=Math.max(1,Math.round(Number(count)||1));
    const cols=Math.max(1,Math.ceil(Math.sqrt(count*1.35)));
    const cells=[];
    for(let row=0;cells.length<count;row++)for(let col=0;col<cols&&cells.length<count;col++)cells.push({col,row});
    return cells;
}
function trueGeneratedEnclosureTargetCells(animals,currentCells=1){
    const occupants=(animals||[]).filter(Boolean);
    if(!occupants.length)return Math.max(1,Number(currentCells)||1);
    const baselineLevel=Math.max(...occupants.map(animalSpaceRequirement));
    const currentLevel=(()=>{
        const n=Math.max(1,Number(currentCells)||1);
        if(n>=13)return 7;if(n>=9)return 6;if(n>=6)return 5;if(n>=4)return 4;
        return n;
    })();
    const low=Math.max(1,baselineLevel-1),high=Math.min(7,baselineLevel+1);
    const targetLevel=Math.max(low,Math.min(high,currentLevel));
    return [0,1,2,3,4,6,9,13][targetLevel]||1;
}
function convertCurrentTrueZooToBuiltEnclosures(){
    if(state.gameMode!=='true'||state.sandboxMode)return false;
    const b=normaliseTrueEnclosureBuilderState();
    if((state.enclosures||[]).every(e=>e?.trueBuilt)){b.converted=true;return false;}
    const old=[...(state.enclosures||[])]; if(!old.length){b.converted=true;return false;}
    const replacements=[],oldToNew=new Map();
    let nextId=Math.max(Number(state.nextId)||1,...old.map(e=>Number(e.id)||0))+1;
    for(const card of old){
        if(card?.trueBuilt){replacements.push(card);oldToNew.set(card.id,[card.id]);continue;}
        const groups=getGroups(card),ids=[];
        groups.forEach((group,gi)=>{
            const id=gi===0?card.id:nextId++;ids.push(id);
            const residents=(state.animals||[]).filter(animal=>
                String(animal.enclosureId)===String(card.id)&&group.includes(Number(animal.slotIndex)));
            // A converted True enclosure must always have at least one physical cell/slot
            // per animal already assigned to this Classic enclosure group. The generated
            // husbandry target can legitimately be smaller than the resident count; using
            // it directly made normaliseTrueBuiltEnclosureOccupancy() eject the overflow
            // animals and could leave compatibility repair with nowhere safe to move them.
            const targetCells=Math.max(
                residents.length,
                trueGeneratedEnclosureTargetCells(residents,Math.max(1,group.length))
            );
            const cells=trueCompactCellShape(targetCells);
            const localCol=gi%2,localRow=Math.floor(gi/2);
            replacements.push({id,trueBuilt:true,cells,x:(Number(card.x)||0)+localCol*(TRUE_ENC_CELL_W*2),y:(Number(card.y)||0)+localRow*TRUE_ENC_CELL_H,sourceEnclosureNumber:card.number});
            for(const animal of residents){
                animal.enclosureId=id;animal.slotIndex=Math.max(0,group.indexOf(Number(animal.slotIndex)));
            }
        });
        oldToNew.set(card.id,ids);
    }
    state.enclosures=replacements;state.nextId=Math.max(Number(state.nextId)||1,nextId);
    const remap=ids=>[...new Set((ids||[]).flatMap(id=>oldToNew.get(id)||[id]))];
    if(state.generatedAreaMembership instanceof Map){for(const [k,ids] of state.generatedAreaMembership)state.generatedAreaMembership.set(k,remap(ids));}
    else if(state.generatedAreaMembership&&typeof state.generatedAreaMembership==='object'){for(const k of Object.keys(state.generatedAreaMembership))state.generatedAreaMembership[k]=remap(state.generatedAreaMembership[k]);}
    for(const area of state.customAreas||[])area.enclosureIds=remap(area.enclosureIds);
    b.converted=true;
    b.geometryVersion=0;
    b.totalSpaces=Math.max(Number(b.totalSpaces)||0,trueBuilderUsedSpaces());
    normaliseTrueBuiltEnclosureOccupancy();
    // Conversion is not allowed to unplace opening animals. If a future enclosure-shape
    // rule undersizes a converted enclosure, grow it and normalize once more.
    for(const enc of state.enclosures||[]){
        if(!enc?.trueBuilt)continue;
        const residents=(state.animals||[]).filter(a=>String(a?.enclosureId)===String(enc.id));
        if(residents.length>(enc.cells?.length||0)){
            enc.cells=trueCompactCellShape(residents.length);
            trueInvalidateEnclosureGeometry(enc);
        }
    }
    normaliseTrueBuiltEnclosureOccupancy();
    repairTrueBuiltEnclosureGeometry();
    normaliseTrueEnclosureArchitecture();
    normaliseTrueDevelopment();
    return true;
}

let trueDecorationToolActive=false;
let trueDecorationDrag=null;
const TRUE_DECORATION_PRESETS=[
    {name:'Water',colour:'#78AFC2'},
    {name:'Dirt',colour:'#8C704F'},
    {name:'Sand',colour:'#D8C38A'},
    {name:'Dry grass',colour:'#C9C47A'},
    {name:'Grass',colour:'#C7DEA0'},
    {name:'Dark grass',colour:'#9FBD78'},
    {name:'Deep grass',colour:'#748F5B'},
    {name:'Forest green',colour:'#66863F'}
];
function normaliseTrueDecorations(){
    if(!Array.isArray(state.trueEnclosureDecorations))state.trueEnclosureDecorations=[];
    if(!Array.isArray(state.truePlacedDecorations))state.truePlacedDecorations=[];
    else state.truePlacedDecorations=state.truePlacedDecorations.filter(d=>d&&['bush','rock','tree'].includes(d.kind)&&Number.isFinite(Number(d.x))&&Number.isFinite(Number(d.y)));
    if(!state.trueDecorationBrush||typeof state.trueDecorationBrush!=='object')state.trueDecorationBrush={colour:'#78AFC2',size:34};
    state.trueDecorationBrush.size=Math.max(8,Math.min(100,Number(state.trueDecorationBrush.size)||34));
    if(!['paint','line','rectangle','bush','rock','tree','erase'].includes(state.trueDecorationMode))state.trueDecorationMode='paint';
    state.trueDecorationObjectScale=Math.max(.1,Math.min(2,Number(state.trueDecorationObjectScale)||.5));
    if(!Number.isInteger(state.trueDecorationPreviewVariant))state.trueDecorationPreviewVariant=Math.floor(Math.random()*20);
    return state.trueEnclosureDecorations;
}
