function clearAutoResumeSnapshot() {
    try {
        localStorage.removeItem(AUTO_RESUME_STORAGE_KEY);
    } catch (error) {
        console.warn('Could not clear automatic resume snapshot:', error);
    }
    lastAutoResumeTurn = null;
}

function multiplayerOwnedGameStateForResume() {
    if (localClassicMatch?.viewingPlayerId &&
        localClassicMatch.viewingPlayerId !== localClassicMatch.activePlayerId) {
        const owned = localClassicMatch.players?.[localClassicMatch.activePlayerId]?.snapshot;
        if (owned?.state) return compactPortableGameSnapshot(owned);
    }
    return exportCurrentGameState({ compactHistory:true });
}

function compactLocalMatchForPersistence(match) {
    if(!match)return null;
    const copy=cloneForSave(match);
    for(const player of Object.values(copy.players||{})){
        if(player?.snapshot?.state)player.snapshot=compactPortableGameSnapshot(player.snapshot);
    }
    return copy;
}

let classicAutoResumeIdleQueued=false;
let classicAutoResumeIdleGeneration=0;
function queueClassicAutoResumeSnapshot(){
    if(classicAutoResumeIdleQueued||state.gameMode==='true'||!state.loaded)return;
    classicAutoResumeIdleQueued=true;
    const generation=++classicAutoResumeIdleGeneration;
    const run=()=>{
        if(generation!==classicAutoResumeIdleGeneration)return;
        classicAutoResumeIdleQueued=false;
        if(!state.loaded||state.gameMode==='true'||state.historyViewTurn!==null)return;
        writeAutoResumeSnapshot();
    };
    if(typeof requestIdleCallback==='function')requestIdleCallback(run,{timeout:1200});
    else setTimeout(run,0);
}
function writeAutoResumeSnapshot(force = false) {
    if (
        !state.loaded ||
        autoResumeWriteSuppressed ||
        state.suppressHistoryCapture ||
        state.historyViewTurn !== null
    ) return false;

    const resumeGame = localClassicMatch ? multiplayerOwnedGameStateForResume() : exportCurrentGameState();
    const resumeTurn = Number(resumeGame?.state?.turn);
    const turn = Number.isFinite(resumeTurn) ? resumeTurn : (Number(state.turn) || 0);
    if (!force && lastAutoResumeTurn === turn) return false;

    try {
        const record = {
            formatVersion: AUTO_RESUME_FORMAT_VERSION,
            gameVersion: ZOO_CURATOR_VERSION,
            savedAt: new Date().toISOString(),
            turn,
            zooName: resumeGame?.state?.zooName || state.zooName,
            game: serialiseSpecial(resumeGame),
            localClassicMatch: localClassicMatch
                ? serialiseSpecial(compactLocalMatchForPersistence(getLocalClassicMatchSnapshot()))
                : null
        };

        localStorage.setItem(
            AUTO_RESUME_STORAGE_KEY,
            JSON.stringify(record)
        );
        lastAutoResumeTurn = turn;
        return true;
    } catch (error) {
        console.warn('Could not update automatic resume snapshot:', error);
        return false;
    }
}

function persistCurrentCameraForReload() {
    classicAutoResumeIdleGeneration++;
    classicAutoResumeIdleQueued=false;
    lastTrueCalendarAutoResumeWriteAt=Date.now();
    lastTrueCalendarAutosavePerfAt=performance.now();
    trueCalendarAutosaveGeneration++;
    trueCalendarAutosaveQueued=false;
    if(localMultiplayerBrowserTransport&&localClassicMatch){
        const transport=localMultiplayerBrowserTransport;
        if(transport.role==='host'&&!state.visitingZoo&&state.historyViewTurn===null)
            syncActiveZooIntoLocalMatch();
        if(transport.matchId&&(transport.role==='host'||transport.role==='peer'))
            writeActiveMultiplayerSession(transport.matchId,transport.role);
    }

    if (!state.loaded || state.visitingZoo || state.historyViewTurn !== null) return;
    writeAutoResumeSnapshot(true);
}

window.addEventListener('pagehide', persistCurrentCameraForReload);
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') persistCurrentCameraForReload();
});

function readAutoResumeSnapshot() {
    try {
        const raw = localStorage.getItem(AUTO_RESUME_STORAGE_KEY);
        if (!raw) return null;

        const record = JSON.parse(raw);
        if (!record || !record.game) return null;

        return {
            ...record,
            game: deserialiseSpecial(record.game),
            localClassicMatch: record.localClassicMatch
                ? deserialiseSpecial(record.localClassicMatch)
                : null
        };
    } catch (error) {
        console.warn('Automatic resume snapshot is invalid:', error);
        clearAutoResumeSnapshot();
        return null;
    }
}

function zooNameNeedsRepair(value) {
    if (typeof value !== 'string') return true;
    const name = value.trim();
    if (!name) return true;

    const placeholder = name.toLowerCase().replace(/\s+/g, ' ');
    return (
        placeholder === 'loading zoo...' ||
        placeholder === 'loading zoo…' ||
        placeholder === 'loading zoo' ||
        placeholder === 'loading...'
    );
}

function repairLoadedZooName() {
    if (!zooNameNeedsRepair(state.zooName)) return false;

    const pool = buildZooNamePool(state.zooNamesData);
    state.zooName = pool.length
        ? randomItem(pool)
        : randomItem([
            'Riverside Zoo',
            'Forest Wildlife Park',
            'Lakeside Zoo',
            'Highland Wildlife Park',
            'Meadowlands Zoo',
            'Coastal Animal Park'
        ]);

    return true;
}

function restoreAutoResumeSnapshot() {
    const record = readAutoResumeSnapshot();
    if (!record) return false;

    try {
        autoResumeWriteSuppressed = true;
        importGameState(record.game, { deferRender: true });

        if(['classic-multiplayer','classic-two-player'].includes(record.localClassicMatch?.mode)){
            localClassicMatch=cloneForSave(record.localClassicMatch);
            localClassicMatch.mode='classic-multiplayer';
            if(!Array.isArray(localClassicMatch.playerIds)||localClassicMatch.playerIds.length<1){
                throw new Error('Saved multiplayer match has invalid player seats.');
            }
            localClassicMatch.viewingPlayerId=null;
            localClassicMatch.events=Array.isArray(localClassicMatch.events)?localClassicMatch.events:[];
            localClassicMatch.tradeDrafts=localClassicMatch.tradeDrafts||{};
            localClassicMatch.pendingPlayerTrades=Array.isArray(localClassicMatch.pendingPlayerTrades)?localClassicMatch.pendingPlayerTrades:[];
            localClassicMatch.nextEventSequence=Number(localClassicMatch.nextEventSequence)||1;
            for(const [playerId,player] of Object.entries(localClassicMatch.players||{})){
                if(!player)continue;
                if(typeof player.connected!=='boolean')player.connected=playerId==='player-1';
                if(!player.reconnectToken&&playerId!=='player-1')
                    player.reconnectToken=createLocalMultiplayerReconnectToken();
            }
            if(localClassicMatch.players?.['player-1'])
                localClassicMatch.players['player-1'].connected=true;
            if(!localClassicMatch.rules){
                localClassicMatch.rules={
                    gameMode:state.gameMode==='true'?'true':'classic',
                    turnMode:'alternating',
                    activeCategories:[...state.activeCategories]
                };
            }
            if(localClassicMatch.rules?.activeCategories){
                const restoredCategories=Object.keys(FOLDERS).filter(category=>
                    localClassicMatch.rules.activeCategories.includes(category)
                );
                localClassicMatch.rules.activeCategories=restoredCategories.length
                    ? restoredCategories
                    : Object.keys(FOLDERS);
                localClassicMatch.rules.gameMode=
                    localClassicMatch.rules.gameMode==='true'?'true':'classic';
                localClassicMatch.rules.turnMode=
                    localClassicMatch.rules.turnMode==='simultaneous'?'simultaneous':'alternating';
                pendingMultiplayerSetup=cloneForSave(localClassicMatch.rules);
                applyMultiplayerCategoryRules(localClassicMatch.rules.activeCategories);
            }

            const resumeOwner=localClassicMatch.players?.[localClassicMatch.activePlayerId]?.snapshot;
            if(resumeOwner?.state){
                importGameState(cloneForSave(resumeOwner),{deferRender:true});
                if(localClassicMatch.rules?.activeCategories)
                    applyMultiplayerCategoryRules(localClassicMatch.rules.activeCategories);
            }
            syncActiveZooIntoLocalMatch();
            disableLocalMultiplayerPeerSimulation();
        }

        const repairedZooName = repairLoadedZooName();
        if (repairedZooName) {
            createZooNameEditor();
        }

        lastAutoResumeTurn = Number(record.turn) || Number(state.turn) || 0;
        return true;
    } catch (error) {
        console.warn('Could not restore automatic resume snapshot:', error);
        clearAutoResumeSnapshot();
        return false;
    } finally {
        autoResumeWriteSuppressed = false;
    }
}

function normaliseLoadedCollection(value, kind = 'Set') {
    if (kind === 'Map') {
        if (value instanceof Map) return value;
        if (Array.isArray(value)) return new Map(value);
        if (value && typeof value === 'object') {
            if (value.__zooType === 'Map') {
                return new Map(value.entries || []);
            }
            return new Map(Object.entries(value));
        }
        return new Map();
    }

    if (value instanceof Set) return value;
    if (Array.isArray(value)) return new Set(value);
    if (value && typeof value === 'object') {
        if (value.__zooType === 'Set') {
            return new Set(value.values || []);
        }
        return new Set(
            Object.entries(value)
                .filter(([, enabled]) => Boolean(enabled))
                .map(([key]) => key)
        );
    }
    return new Set();
}

function normaliseLoadedGameCollections() {
    const setKeys = [
        'activeCategories',
        'playerLevelsSeen',
        'enclosureRewards',
        'glowingEnclosureIds',
        'suppressedExchangeGlowIds',
        'exchangeGlowReturnIds',
        'exchangeGlowContinueIds',
        'discoveredCategoryLevels',
        'acquiredLevel2Categories',
        'awardedLevel2Milestones',
        'awardedProgressMilestones',
        'progressionGlowPinnedKeys',
        'realZooTradeDirtyZoos'
    ];

    for (const key of setKeys) {
        state[key] = normaliseLoadedCollection(state[key], 'Set');
    }

    for (const key of ['playerLevelsSeen', 'suppressedExchangeGlowIds']) {
        state[key] = new Set(
            [...state[key]].map(value => {
                const numeric = Number(value);
                return Number.isFinite(numeric) ? numeric : value;
            })
        );
    }

    state.realZooSessionHoldings = decodePortableRealZooSessionHoldings(state.realZooSessionHoldings);

    state.collectionRecords = decodePortableCollectionRecords(state.collectionRecords);
    state.animalLineage = decodePortableAnimalLineage(state.animalLineage);

    const mapKeys = [
        'lastExchangeGroupCounts',
        'animalLineage',
        'tradeOfferCache',
        'assetPreloadPromises'
    ];

    for (const key of mapKeys) {
        state[key] = normaliseLoadedCollection(state[key], 'Map');
    }

    if (state.animalLineage instanceof Map) {
        const normalisedLineage = new Map();
        for (const [key, record] of state.animalLineage.entries()) {
            const numericKey = Number(key);
            const lineageKey = Number.isFinite(numericKey) ? numericKey : key;
            normalisedLineage.set(lineageKey, record);
        }
        state.animalLineage = normalisedLineage;
    }
}

function relinkSandboxLooseAnimals() {
    const byId = new Map((state.animals || []).map(animal => [animal.id, animal]));
    const relinked = [];
    const seenIds = new Set();

    for (const loose of state.sandboxLooseAnimals || []) {
        if (!loose || loose.id == null || seenIds.has(loose.id)) continue;

        let canonical = byId.get(loose.id);
        if (!canonical) {
            canonical = loose;
            state.animals.push(canonical);
            byId.set(canonical.id, canonical);
        }

        if (Number.isFinite(Number(loose.x))) canonical.x = Number(loose.x);
        if (Number.isFinite(Number(loose.y))) canonical.y = Number(loose.y);
        canonical.sandboxLoose = true;
        canonical.enclosureId = null;
        canonical.slotIndex = null;

        relinked.push(canonical);
        seenIds.add(canonical.id);
    }

    state.sandboxLooseAnimals = relinked;
    return byId;
}

function relinkLoadedPlayerReferences() {
    const byId = relinkSandboxLooseAnimals();
    if (!(state.animalLineage instanceof Map)) state.animalLineage = new Map();
    state.collectionRecords = normaliseLoadedCollection(state.collectionRecords, 'Map');
    state.collectionCohabitationActive = normaliseLoadedCollection(state.collectionCohabitationActive, 'Map');
    state.collectionActiveLevel = Math.min(5, Math.max(1, Number(state.collectionActiveLevel) || 1));
    for (const animal of state.animals) {
        if (!state.animalLineage.has(animal.id)) {
            ensureAnimalLineage(animal, state.zooName || 'Your Zoo');
        }
    }
    state.exchange = (state.exchange || [null, null])
        .map(animal => animal ? (byId.get(animal.id) || animal) : null);
    if (state.outgoingOffer) {
        state.outgoingOffer =
            byId.get(state.outgoingOffer.id) || state.outgoingOffer;
    }
}

function repairLoadedNextId() {
    let highestId = 0;
    const noteId = value => {
        const numeric = Number(value);
        if (Number.isInteger(numeric) && numeric > highestId) highestId = numeric;
    };
    const noteAnimal = animal => {
        if (animal && typeof animal === 'object') noteId(animal.id);
    };

    for (const animal of state.animals || []) noteAnimal(animal);
    for (const animal of state.sandboxLooseAnimals || []) noteAnimal(animal);
    for (const enclosure of state.enclosures || []) noteId(enclosure?.id);
    for (const stock of state.opponentTradeStocks || []) {
        for (const animal of stock || []) noteAnimal(animal);
    }
    for (const animal of state.exchange || []) noteAnimal(animal);
    noteAnimal(state.result);
    noteAnimal(state.outgoingOffer);

    if (state.animalLineage instanceof Map) {
        for (const [key, record] of state.animalLineage.entries()) {
            noteId(key);
            noteId(record?.animalId);
        }
    }
    for (const trade of state.tradeHistory || []) {
        noteId(trade?.outgoingId);
        noteId(trade?.incomingId);
    }

    const loadedNextId = Number(state.nextId);
    const safeNextId = highestId + 1;
    state.nextId = Number.isInteger(loadedNextId) && loadedNextId > highestId
        ? loadedNextId
        : safeNextId;
}

