function migrateLegacyAnimalCategories(value,seen=new WeakSet()){
    if(!value||typeof value!=='object')return value;
    if(seen.has(value))return value;
    seen.add(value);
    if(Array.isArray(value)){
        for(let i=0;i<value.length;i++){
            const item=value[i];
            if(typeof item==='string')value[i]=canonicalAnimalCategory(item);
            else migrateLegacyAnimalCategories(item,seen);
        }
        return value;
    }
    if(value instanceof Set){
        const migrated=[...value].map(item=>typeof item==='string'?canonicalAnimalCategory(item):item);
        value.clear();
        for(const item of migrated){
            if(item&&typeof item==='object')migrateLegacyAnimalCategories(item,seen);
            value.add(item);
        }
        return value;
    }
    if(value instanceof Map){
        const entries=[...value.entries()];
        value.clear();
        for(let [key,item] of entries){
            if(typeof key==='string')key=canonicalAnimalCategory(key);
            if(typeof item==='string')item=canonicalAnimalCategory(item);
            else migrateLegacyAnimalCategories(item,seen);
            value.set(key,item);
        }
        return value;
    }
    if(typeof value.category==='string')value.category=canonicalAnimalCategory(value.category);
    for(const key of Object.keys(value)){
        const item=value[key];
        if(key==='category')continue;
        if(typeof item==='string'){
            if(item==='Carnivora')value[key]='Carnivores';
        }else migrateLegacyAnimalCategories(item,seen);
        if(key==='Carnivora'&&key!=='Carnivores'){
            if(!Object.prototype.hasOwnProperty.call(value,'Carnivores'))value.Carnivores=value[key];
            delete value.Carnivora;
        }
    }
    return value;
}

function importGameState(saveData, { deferRender = false } = {}) {
    lifetimeCollectionLastMergeSignature='';
    if (!saveData || !saveData.state) {
        throw new Error(uiText('This save file does not contain a valid Zoo Curator game.'));
    }
    migrateLegacyAnimalCategories(saveData);

    areaSignatureTaskCache=null;
    areaSignatureTaskShape='';
    areaSignatureTaskCacheScheduled=false;
    invalidateClassicGeneratedGeography();
    geographicAdjacencyGeometryCache={signature:null,index:null};
    activeGeographicAnimalIndex=null;
    activeGeographicResidentCache=null;
    activeGeographicCandidateUnitIndex=null;

    const legacyFlattenedCollection = key => {
        const value = saveData.state?.[key];
        return value && typeof value === 'object' && !Array.isArray(value) &&
            !(value instanceof Set) && !(value instanceof Map) &&
            value.__zooType == null && Object.keys(value).length === 0;
    };
    const legacyProgressRewardsFlattened =
        legacyFlattenedCollection('awardedProgressMilestones');
    const legacyGeneratedAreasFlattened =
        legacyFlattenedCollection('generatedAreaMembership');
    const rebuildLegacyGeneratedAreas = legacyGeneratedAreasFlattened;

    exitHistoryView(false);
    state.suppressHistoryCapture = true;

    resetTransientStateForImport();

    const legacyHandIds = new Set(
        Array.isArray(saveData.state.hand)
            ? saveData.state.hand.map(animal => Number(animal?.id)).filter(Number.isFinite)
            : []
    );

    for (const key of SAVE_STATE_KEYS) {
        if (Object.prototype.hasOwnProperty.call(saveData.state, key)) {
            state[key] = cloneForSave(saveData.state[key]);
        } else {
            state[key] = cloneForSave(SAVE_STATE_DEFAULTS[key]);
        }
    }

    if (!Object.prototype.hasOwnProperty.call(saveData.state, 'zooType')) {
        state.zooType = inferZooTypeFromAnyGeneratedName(state.zooName);
    }
    state.zooType = normaliseZooTypes(state.zooType)[0];

    state.sandboxMode = Boolean(state.sandboxMode);
    if (!['classic', 'true', 'sandbox'].includes(state.gameMode)) {
        state.gameMode = state.sandboxMode ? 'sandbox' : 'classic';
    }
    if (state.sandboxMode) state.gameMode = 'sandbox';
    if (state.gameMode === 'true') {
        normaliseTrueCalendarState();
        normaliseTrueDecorations();
        for (const animal of state.animals || []) normaliseTrueAnimalPopulation(animal);
        requestAnimationFrame(()=>refreshTrueDecorationVisuals());
    }
    if (!Array.isArray(state.sandboxLooseAnimals)) state.sandboxLooseAnimals = [];
    state.turnHistory = decodePortableTurnHistory(saveData.turnHistory || []);
    if(Array.isArray(state.turnHistory)){
        const byTurn=new Map();
        for(const snapshot of state.turnHistory){
            const turn=Number(snapshot?.turn);
            if(!Number.isFinite(turn))continue;
            if(!Array.isArray(snapshot?.enclosures)||!Array.isArray(snapshot?.animals))continue;
            snapshot.turn=turn;
            byTurn.set(turn,snapshot);
        }
        state.turnHistory=[...byTurn.entries()]
            .sort((a,b)=>a[0]-b[0])
            .map(([,snapshot])=>snapshot);
    }else{
        state.turnHistory=[];
    }
    state.historyViewTurn = null;
    state.historyLiveView = null;
    state.drag = null;
    state.pan = null;

    normaliseLoadedGameCollections();

    if (!state.activeCategories.size) {
        state.activeCategories = new Set(Object.keys(FOLDERS));
    }

    if (legacyProgressRewardsFlattened) {
        state.awardedProgressMilestones = progressionRewardKeysForMilestones(
            state.gameOptions?.enclosureRewardMilestones || []
        );
        state.awardedLevel2Milestones = new Set(
            [...state.awardedProgressMilestones]
                .map(key => String(key).split('|'))
                .filter(([levelText]) => Number(levelText) === 2)
                .map(([, milestoneText]) => Number(milestoneText))
        );
    }

    invalidateConnectedAreaReconciliation();
    renderedConnectedAreaGroups = [];
    renderedConnectedAreaGroupsSignature = '';
    stableConnectedAreaGroups = [];
    stableConnectedAreaGroupsSignature = '';
    generatedModernGeographicAreas = [];
    if (legacyGeneratedAreasFlattened) {
        state.generatedAreaMembership = new Map();

        const legacyEnclosures = Array.isArray(state.enclosures) ? state.enclosures : [];
        if (legacyEnclosures.length > 1) {
            const stepX = ENCLOSURE_W + ENCLOSURE_GAP;
            const stepY = ENCLOSURE_H + ENCLOSURE_GAP;
            const xs = [...new Set(legacyEnclosures.map(e => Number(e?.x)).filter(Number.isFinite))]
                .sort((a,b) => a-b);
            const ys = [...new Set(legacyEnclosures.map(e => Number(e?.y)).filter(Number.isFinite))]
                .sort((a,b) => a-b);

            const hasGridSizedGap = values => values.some(
                (value,index) => index > 0 &&
                    value - values[index-1] > Math.max(stepX, stepY) * 1.45
            );

            if (hasGridSizedGap(xs) || hasGridSizedGap(ys)) {
                const originX = xs[0];
                const originY = ys[0];
                const xIndex = new Map(xs.map((value,index) => [value,index]));
                const yIndex = new Map(ys.map((value,index) => [value,index]));

                for (const enclosure of legacyEnclosures) {
                    const xi = xIndex.get(Number(enclosure.x));
                    const yi = yIndex.get(Number(enclosure.y));
                    if (Number.isInteger(xi)) enclosure.x = originX + xi * stepX;
                    if (Number.isInteger(yi)) enclosure.y = originY + yi * stepY;
                }

                state.areaPlacementRevision = (Number(state.areaPlacementRevision) || 0) + 1;
                invalidateConnectedAreaReconciliation();
                renderedConnectedAreaGroups = [];
                renderedConnectedAreaGroupsSignature = '';
                stableConnectedAreaGroups = [];
                stableConnectedAreaGroupsSignature = '';
                generatedModernGeographicAreas = [];
            }
        }
    }

    if(!state.sandboxMode)ensureLifetimePlaythroughId();
    relinkLoadedPlayerReferences();
    repairLoadedNextId();

    for (const id of legacyHandIds) {
        const animal = classicAnimalById(id);
        if (!animal || animal.enclosureId != null) continue;
        const destination = randomEligibleDestinationForAnimal(animal);
        if (destination) {
            placeAnimal(animal, destination.enclosure, destination.slotIndex);
        } else {
            console.warn(`Legacy hand card ${id} could not be auto-placed; leaving save unchanged for that card.`);
        }
    }

    if (!Object.prototype.hasOwnProperty.call(saveData.state, 'zooProvince')) {
        state.zooProvince = zooSetupProvinceForLocation(
            state.zooCountry,
            state.zooLocation
        );
    }
    if (!Object.prototype.hasOwnProperty.call(saveData.state, 'highestZooPrestige')) {
        state.highestZooPrestige = (state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo)
            ? visibleZooPrestige()
            : currentZooPrestige();
    }
    updateHighestZooPrestige();

    document.documentElement.style.setProperty('--zoo-zoom', state.zoom);
    document.body.classList.remove('history-viewing');

    applyZooColourScheme();

    if (deferRender) {
        state.suppressHistoryCapture = false;
        if (saveData.view) {
            state.pendingRestoredView = {
                scrollLeft: Number(saveData.view.scrollLeft) || 0,
                scrollTop: Number(saveData.view.scrollTop) || 0
            };
        }
        return;
    }

    renderAll();

    if (rebuildLegacyGeneratedAreas && state.gameOptions?.autoGeneratedAreasZones !== false) {
        invalidateConnectedAreaReconciliation();
        try {
            generatedGeographicAreaGroups();
        } catch (error) {
            console.warn('Legacy generated-Area reconstruction could not complete:', error);
        }
    }

    requestAnimationFrame(() => {
        if (saveData.view) {
            const left=Math.max(0,Number(saveData.view.scrollLeft)||0);
            const top=Math.max(0,Number(saveData.view.scrollTop)||0);
            zooBoard.scrollLeft=left;
            zooBoard.scrollTop=top;
            requestAnimationFrame(() => {
                if (Math.abs(zooBoard.scrollLeft-left)>1) zooBoard.scrollLeft=left;
                if (Math.abs(zooBoard.scrollTop-top)>1) zooBoard.scrollTop=top;
            });
        }
        state.suppressHistoryCapture = false;
        captureTurnSnapshot();
        updateHistoryControls();
    });
}

