function progressionCountForLevel(level) {
    updateDiscoveredCategoryLevels();

    let count = 0;
    for (const key of state.discoveredCategoryLevels) {
        const [, levelText] = key.split('|');
        if (Number(levelText) === level) count++;
    }
    return count;
}

function progressionRewardKeysForMilestones(milestones) {
    updateDiscoveredCategoryLevels();
    const keys = new Set();
    for (let level = 2; level <= 5; level++) {
        const count = progressionCountForLevel(level);
        for (const milestone of normalizeRewardMilestones(milestones)) {
            if (count >= milestone) keys.add(`${level}|${milestone}`);
        }
    }
    return keys;
}

function emptyEnclosures() {
    const occupied = new Set();
    for (const animal of state.animals) {
        if (!animal) continue;
        if (animal.enclosureId !== null && animal.enclosureId !== undefined) {
            occupied.add(animal.enclosureId);
        }
        if (animal.reservedEnclosureId !== null && animal.reservedEnclosureId !== undefined) {
            occupied.add(animal.reservedEnclosureId);
        }
    }
    return state.enclosures.filter(enclosure => !occupied.has(enclosure.id));
}

function removeEmptyEnclosures(count) {
    const available = emptyEnclosures();
    const chosen = available
        .slice()
        .sort((a,b) => Number(b.id) - Number(a.id))
        .slice(0, Math.max(0, count));
    const ids = new Set(chosen.map(enclosure => enclosure.id));
    state.enclosures = state.enclosures.filter(enclosure => !ids.has(enclosure.id));
    for (const id of ids) { state.glowingEnclosureIds.delete(id); state.newEnclosureGlowStartedAt.delete(id); }
    return { removed: chosen.length, available: available.length };
}

function applyMilestonesToCurrentZoo(newMilestones, retroactive) {
    const oldAwarded = new Set(state.awardedProgressMilestones || []);
    const expected = progressionRewardKeysForMilestones(newMilestones);

    if (!retroactive) {
        state.awardedProgressMilestones = expected;
    } else {
        const delta = expected.size - oldAwarded.size;

        if (delta > 0) {
            for (let i=0; i<delta; i++) addRewardEnclosure();
        } else if (delta < 0) {
            const wanted = -delta;
            const result = removeEmptyEnclosures(wanted);
            if (result.removed < wanted) {
                const missing = wanted - result.removed;
                showGameNotice(
                    `The new milestone settings would remove ${wanted} enclosure card${wanted===1?'':'s'}, ` +
                    `but only ${result.removed} completely empty enclosure card${result.removed===1?' is':'s are'} available.\n\n` +
                    `Only the ${result.removed} available empty enclosure card${result.removed===1?' has':'s have'} been removed. ` +
                    `${missing} occupied enclosure card${missing===1?' was':'s were'} left in place.`
                );
            }
        }
        state.awardedProgressMilestones = expected;
    }

    state.awardedLevel2Milestones = new Set(
        [...state.awardedProgressMilestones]
            .map(key => String(key).split('|'))
            .filter(([levelText]) => Number(levelText) === 2)
            .map(([, milestoneText]) => Number(milestoneText))
    );
}

function checkCurrentProgressionRewards() {
    updateDiscoveredCategoryLevels();
    let rewardsAdded=0;

    for (let level = 2; level <= 5; level++) {
        const count = progressionCountForLevel(level);

        for (const milestone of state.gameOptions.enclosureRewardMilestones) {
            const rewardKey = `${level}|${milestone}`;

            if (
                count >= milestone &&
                !state.awardedProgressMilestones.has(rewardKey)
            ) {
                state.awardedProgressMilestones.add(rewardKey);
                addRewardEnclosure();
                rewardsAdded++;
            }
        }
    }

    state.awardedLevel2Milestones = new Set(
        [...state.awardedProgressMilestones]
            .map(key => String(key).split('|'))
            .filter(([levelText]) => Number(levelText) === 2)
            .map(([, milestoneText]) => Number(milestoneText))
    );
    return rewardsAdded;
}

function checkEnclosureReward(animal, source='upgrade') {
    if (!animal) return 0;
    if(source!=='upgrade'&&source!=='exchange')return 0;

    if ((Number(animal.level) || 0) < 2) return 0;

    return checkCurrentProgressionRewards();
}

function prepareExchangeGlowAfterAnimalDrag(drag) {
    const before = drag?.exchangeGlowIds || new Set();
    const nowEligible = new Set(
        state.animals
            .filter(animal => shouldGlowForExchange(animal))
            .map(animal => animal.id)
    );

    const newlyEligible = new Set(
        [...nowEligible].filter(id => !before.has(id))
    );

    state.exchangeGlowContinueIds.clear();
    state.exchangeGlowContinueStartedAt = 0;
    state.exchangeGlowContinueUntil = 0;

    state.exchangeGlowReturnIds = newlyEligible;
    state.exchangeGlowReturnUntil =
        newlyEligible.size ? Date.now() + 1000 : 0;
}

function moveHumanTradeRequestDrag(event){
    const drag=state.drag;if(drag?.type!=='human-trade-request')return;
    drag.maxDistance=Math.max(Number(drag.maxDistance)||0,
        Math.hypot(event.clientX-drag.startClientX,event.clientY-drag.startClientY));
    drag.image.style.left=`${event.clientX-drag.offsetX}px`;
    drag.image.style.top=`${event.clientY-drag.offsetY}px`;
    sendMultiplayerLiveAnimalDrag?.(event,false);
}
async function finishHumanTradeRequestDrag(event){
    const drag=state.drag;if(drag?.type!=='human-trade-request')return;
    sendMultiplayerLiveAnimalDrag?.(event,true);
    const target=elementUnderPointer(event);
    const dropped=target&&drawCard&&(target===drawCard||drawCard.contains(target));
    const deliberate=(Number(drag.maxDistance)||0)>=6 ||
        Math.hypot(event.clientX-drag.startClientX,event.clientY-drag.startClientY)>=6;
    drag.image?.remove();state.drag=null;
    if(!dropped||!deliberate){refreshDrawAvailabilityState();return;}

    const ownerId=localClassicMatch?.activePlayerId;
    if(!ownerId||drag.requestedPlayerId===ownerId)return;
    const ownerAnimals=localClassicMatch.players?.[ownerId]?.snapshot?.state?.animals||[];
    const requestedKey=animalCardKey(drag.animal);
    if(ownerAnimals.some(a=>animalCardKey(a)===requestedKey)){
        showGameNotice?.('Your zoo already has this species.');
        refreshDrawAvailabilityState();
        return;
    }

    let staged=false;
    if(serverAuthoritativeMultiplayerActive()){
        const draft=localHumanTradeDraft(ownerId);
        draft.requestedPlayerId=drag.requestedPlayerId;
        draft.requestedServerPlayerId=drag.requestedServerPlayerId||
            multiplayerServerPlayerForLocalId(drag.requestedPlayerId)?.playerId||null;
        draft.requestedAnimalId=drag.requestedAnimalId??drag.animal.id;
        draft.requestedAnimalIdentity=cloneForSave(drag.requestedAnimalIdentity||{
            category:drag.animal?.category,level:drag.animal?.level,filename:drag.animal?.filename,
            enclosureId:drag.animal?.enclosureId??null,
            slotIndex:Number.isFinite(Number(drag.animal?.slotIndex))?Number(drag.animal.slotIndex):null
        });
        
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('trade-draft-staged',{
            playerId:ownerId,requestedPlayerId:drag.requestedPlayerId,
            requestedAnimalId:drag.requestedAnimalId??drag.animal.id
        });
        staged=true;
    }else if(localMultiplayerPeerReplica?.playerId===ownerId ||
       (localMultiplayerBrowserTransport?.role==='peer'&&localMultiplayerBrowserTransport.playerId===ownerId)){
        const result=await dispatchLocalMultiplayerAction(ownerId,'stage-human-trade-request',{
            requestedPlayerId:drag.requestedPlayerId,
            requestedServerPlayerId:drag.requestedServerPlayerId||
                multiplayerServerPlayerForLocalId(drag.requestedPlayerId)?.playerId||null,
            requestedAnimalId:drag.requestedAnimalId??drag.animal.id,
            requestedAnimalIdentity:cloneForSave(drag.requestedAnimalIdentity||{
                category:drag.animal?.category,level:drag.animal?.level,filename:drag.animal?.filename,
                enclosureId:drag.animal?.enclosureId??null,
                slotIndex:Number.isFinite(Number(drag.animal?.slotIndex))?Number(drag.animal.slotIndex):null
            })
        });
        staged=!!result?.ok;
    }else{
        const draft=localHumanTradeDraft(ownerId);
        draft.requestedPlayerId=drag.requestedPlayerId;
        draft.requestedServerPlayerId=drag.requestedServerPlayerId||
            multiplayerServerPlayerForLocalId(drag.requestedPlayerId)?.playerId||null;
        draft.requestedAnimalId=drag.requestedAnimalId??drag.animal.id;
        draft.requestedAnimalIdentity=cloneForSave(drag.requestedAnimalIdentity||{
            category:drag.animal?.category,level:drag.animal?.level,filename:drag.animal?.filename,
            enclosureId:drag.animal?.enclosureId??null,
            slotIndex:Number.isFinite(Number(drag.animal?.slotIndex))?Number(drag.animal.slotIndex):null
        });
        
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('trade-draft-staged',{
            playerId:ownerId,requestedPlayerId:drag.requestedPlayerId,
            requestedAnimalId:drag.requestedAnimalId??drag.animal.id
        });
        staged=true;
    }
    if(!staged){refreshDrawAvailabilityState();renderTrade();return;}
    await returnToActiveLocalClassicZoo();
    resetDrawCardFromTheirOfferMode();
    selectedMultiplayerPublicListingPlayerId=null;
    selectedHumanTradeProposalId=null;
    refreshDrawAvailabilityState();
    renderTrade();
}

function refreshClassicEnclosureCards(enclosureIds) {
    if(state.gameMode==='true'||state.sandboxMode)return false;
    const ids=[...new Set((enclosureIds||[]).filter(id=>id!=null).map(String))];
    if(!ids.length)return false;

    const layer=document.getElementById('zooEnclosureLayer');
    if(!layer)return false;

    const targets=[];
    for(const id of ids){
        const enclosure=enclosureByIdFast(id);
        const oldElement=layer.querySelector(
            `.enclosure[data-enclosure-id="${CSS.escape(id)}"]`
        );
        if(!enclosure||!oldElement)return false;
        targets.push({id,enclosure,oldElement});
    }

    const targetIdSet=new Set(ids);
    ensureClassicOccupancyCache();
    const targetAnimals=[],targetAnimalIds=new Set(),occupiedEnclosureIds=new Set();
    for(const [slotKey,animals] of classicOccupancyBySlot){
        const split=slotKey.lastIndexOf(':'),enclosureKey=slotKey.slice(0,split);
        if(animals?.length)occupiedEnclosureIds.add(enclosureKey);
        if(!targetIdSet.has(enclosureKey))continue;
        for(const animal of animals||[])if(!targetAnimalIds.has(animal.id)){
            targetAnimalIds.add(animal.id);targetAnimals.push(animal);
        }
    }
    for(const [slotKey,animals] of classicReservedOccupancyBySlot){
        const split=slotKey.lastIndexOf(':'),enclosureKey=slotKey.slice(0,split);
        if(animals?.length)occupiedEnclosureIds.add(enclosureKey);
        if(!targetIdSet.has(enclosureKey))continue;
        for(const animal of animals||[])if(!targetAnimalIds.has(animal.id)){
            targetAnimalIds.add(animal.id);targetAnimals.push(animal);
        }
    }

    const compatibilityGlowKeys=new Set();
    const compatibilityCandidates=compatibilityHintAnimals();
    if(compatibilityCandidates.length&&!visitingAnotherZooForActionUI() && !trueLayoutToolEditingActive()){
        for(const target of targets){
            for(const slotIndex of getAllSlots(target.enclosure)){
                if(slotIsCompatibilityMatch(
                    target.enclosure,
                    slotIndex,
                    compatibilityCandidates
                )){
                    compatibilityGlowKeys.add(
                        slotCompatibilityGlowKey(target.enclosure.id,slotIndex)
                    );
                }
            }
        }
    }
    const renderNow=Date.now();

    const exchangeGlowEligibleIds=new Set();
    const exchangeGlowActive =
        state.exchangeEligibilityHoverActive &&
        !state.outgoingOfferHoverSuppressesExchangeGlow &&
        state.gameOptions.showEligibilityGlows !== false &&
        localClassicCanShowProgressionActionGlows();
    if(exchangeGlowActive){
        const targetExchangeAnimals=targetAnimals;
        const relevantKeys=new Set(targetExchangeAnimals.map(exchangeGroupKey));
        const focusKey=activeExchangeGlowFocusKey();
        if(focusKey){
            for(const key of [...relevantKeys])if(key!==focusKey)relevantKeys.delete(key);
        }
        if(relevantKeys.size){
            const allCounts=exchangeGroupCounts();
            const counts=new Map([...relevantKeys].map(key=>[key,allCounts.get(key)||0]));
            const eligibleKeys=new Set();
            for(const [key,count] of counts){
                if(count<3)continue;
                const parts=String(key).split('|');
                const level=Number(parts.pop());
                const category=parts.join('|');
                if(hasNextLevelInventory(category,level))eligibleKeys.add(key);
            }
            for(const animal of targetExchangeAnimals){
                if(
                    eligibleKeys.has(exchangeGroupKey(animal)) &&
                    !state.suppressedExchangeGlowIds.has(animal.id)
                ) exchangeGlowEligibleIds.add(animal.id);
            }
        }
    }
    const cardRenderContext={
        layoutToolEditing:false,
        visitingActionUI:visitingAnotherZooForActionUI(),
        exchangeGlowEligibleIds
    };

    const themesByEnclosure=new Map();
    const currentAreaSignature=areaRenderStateSignature();
    const currentConnectedGroups=(
        renderedConnectedAreaGroups &&
        renderedConnectedAreaGroupsSignature===currentAreaSignature
    ) ? renderedConnectedAreaGroups : null;
    if(currentConnectedGroups){
        for(const group of currentConnectedGroups||[]){
            const theme=group?.theme;
            if(!theme)continue;
            for(const enclosure of group.enclosures||[]){
                const key=String(enclosure.id);
                if(!targetIdSet.has(key))continue;
                let list=themesByEnclosure.get(key);
                if(!list){list=[];themesByEnclosure.set(key,list);}
                if(!list.some(item=>item.key===theme.key))list.push(theme);
            }
        }
    }

    const visibleAnimalsByEnclosure=new Map();
    const reservedAnimalsByEnclosure=new Map();
    const animalSizeById=new Map();
    const addTargetAnimal=(index,enclosureId,slotIndex,animal)=>{
        if(enclosureId==null||slotIndex==null)return;
        const key=String(enclosureId);
        if(!targetIdSet.has(key))return;
        let bySlot=index.get(key);
        if(!bySlot){bySlot=new Map();index.set(key,bySlot);}
        bySlot.set(Number(slotIndex),animal);
    };
    const husbandrySizeRulesEnabled=
        state.gameMode!=='true' &&
        state.gameOptions?.enforceMinimumExhibitSize !== false;
    for(const id of targetIdSet){
        const sourceVisible=classicOccupancyByEnclosure.get(id),sourceReserved=classicReservedOccupancyByEnclosure.get(id);
        if(sourceVisible){
            const visible=new Map();
            for(const [slot,list] of sourceVisible)if(list?.length)visible.set(slot,list[0]);
            if(visible.size)visibleAnimalsByEnclosure.set(id,visible);
        }
        if(sourceReserved){
            const reserved=new Map();
            for(const [slot,list] of sourceReserved)if(list?.length)reserved.set(slot,list[0]);
            if(reserved.size)reservedAnimalsByEnclosure.set(id,reserved);
        }
    }
    if(husbandrySizeRulesEnabled)for(const animal of targetAnimals)
        if(animal?.id!=null)animalSizeById.set(animal.id,classicCachedAnimalEnclosureSize(animal));

    const husbandryStatusByEnclosure=new Map();
    const husbandryProblemEnclosureIds=new Set();
    for(const target of targets){
        const key=target.id;
        const visible=visibleAnimalsByEnclosure.get(key) || new Map();
        const reserved=reservedAnimalsByEnclosure.get(key) || null;
        const bySlot=new Map();
        for(const group of classicRenderGroups(target.enclosure)){
            const seenAnimalIds=new Set();
            const occupants=[];
            for(const slotIndex of group){
                for(const animal of [
                    visible.get(Number(slotIndex)),
                    reserved?.get(Number(slotIndex))
                ]){
                    if(!animal||seenAnimalIds.has(animal.id))continue;
                    seenAnimalIds.add(animal.id);
                    occupants.push(animal);
                }
            }
            const status=exhibitHusbandryStatus(
                target.enclosure,
                group,
                occupants,
                animalSizeById
            );
            if(status.invalid)husbandryProblemEnclosureIds.add(key);
            for(const slotIndex of group)bySlot.set(Number(slotIndex),status);
        }
        husbandryStatusByEnclosure.set(key,bySlot);
    }

    const targetedRenderContext={
        renderNow,
        husbandryUIReady:true,
        cardRenderContext,
        themesByEnclosure,
        visibleAnimalsByEnclosure,
        reservedAnimalsByEnclosure,
        animalSizeById,
        husbandryStatusByEnclosure,
        husbandryProblemEnclosureIds
    };
    for(const id of ids){
        if(!themesByEnclosure.has(id) && currentConnectedGroups)themesByEnclosure.set(id,[]);
    }
    ensureHusbandryUI();

    hideHusbandryPopup();

    const replacements=[];
    try{
        for(const target of targets){
            const fragment=document.createDocumentFragment();
            renderEnclosure(
                target.enclosure,
                compatibilityGlowKeys,
                occupiedEnclosureIds,
                targetedRenderContext,
                fragment
            );
            const replacement=fragment.firstElementChild;
            if(!replacement)return false;
            replacements.push({...target,fragment,replacement});
        }
    }catch(error){
        console.error('Targeted enclosure refresh failed before commit',error);
        return false;
    }

    for(const item of replacements){
        item.oldElement.replaceWith(item.fragment);
        if(item.enclosure.rotated180){
            mirrorRotatedEnclosureSlots(item.replacement,item.enclosure);
        }
    }
    refreshAnimalGlowPrecedence(zooCanvas);
    return true;
}

function renderClassicCrossExhibitRelocation(drag, animal) {
    if(
        state.gameMode==='true' ||
        state.sandboxMode ||
        drag?.type!=='animal' ||
        drag.originalEnclosureId==null ||
        animal?.enclosureId==null
    ) return false;

    if(classicMoveStaysInSameLogicalExhibit(drag,animal))return false;

    const sourceId=String(drag.originalEnclosureId);
    const destinationId=String(animal.enclosureId);

    stableConnectedAreaGroups=null;
    stableConnectedAreaGroupsSignature='';
    invalidateConnectedAreaReconciliation();
    refreshClassicAreaVisuals();

    if(!refreshClassicEnclosureCards([sourceId,destinationId]))return false;
    return true;
}

function renderClassicSameExhibitRelocation(drag, animal) {
    if(!classicMoveStaysInSameLogicalExhibit(drag,animal))return false;
    return refreshClassicEnclosureCards([animal.enclosureId]);
}

function restoreClassicAnimalDragSourceNode(drag) {
    if(state.gameMode==='true'||drag?.type!=='animal'||drag.location!=='enclosure')return false;
    const node=drag.transientSourceNode,parent=drag.transientSourceParent;
    if(!node||!parent?.isConnected)return false;
    const next=drag.transientSourceNextSibling;
    if(next?.parentNode===parent)parent.insertBefore(node,next);
    else parent.appendChild(node);
    drag.transientSourceSlot?.classList.remove('empty-slot');
    refreshContextualExchangeEligibilityGlows();
    applyCompatibilityDestinationGlowClasses();
    refreshAnimalGlowPrecedence(zooCanvas);
    return true;
}

function renderAfterTransientAnimalDrag(drag) {
    const restoredSource=profiledZooRenderStage(
        'drag-finish.targeted-classic',
        () => restoreClassicAnimalDragSourceNode(drag)
    );
    if(!restoredSource)profiledZooRenderStage('drag-finish.zoo', () => renderZoo());
    profiledZooRenderStage('drag-finish.exchange-ui', () => renderExchange());
    profiledZooRenderStage('drag-finish.trade-ui', () => renderTrade());
    queueDocumentLocalisation();
}

function finishAnimalDrag(event) {
    const drag = state.drag;
    if (!drag || drag.type !== 'animal') return;
    sendMultiplayerLiveAnimalDrag?.(event,true);
    const animal = drag.animal;
    const clickDistance = Math.hypot(event.clientX-drag.startClientX, event.clientY-drag.startClientY);

    if (clickDistance < 6 && drag.originalWasTrueArrivalOverlay) {
        drag.image?.remove();
        state.drag=null;
        return;
    }

    if (clickDistance < 6 && (drag.originalEnclosureId !== null || drag.originalWasTrueLoose)) {
        restoreDraggedAnimal();

        const mobileLayout = window.matchMedia('(max-width: 700px)').matches;

        if (mobileLayout) {
            showHoverPreview(animal);
            ensureWikipediaBack();
            setHoverPreviewSuperZoom(true);
        } else if (isExchangeEligible(animal)) {
            state.exchangeGlowFocusKey = exchangeGroupKey(animal);
        }

        prepareExchangeGlowAfterAnimalDrag(drag);
        drag.image?.remove();
        state.drag = null;
        renderAfterTransientAnimalDrag(drag);
        return;
    }

    const preDropReservations=localClassicMatch
        ? (state.animals||[]).map(a=>({
            id:a.id,
            enclosureId:a.enclosureId,slotIndex:a.slotIndex,
            reservedEnclosureId:a.reservedEnclosureId,
            reservedSlotIndex:a.reservedSlotIndex
        }))
        : null;

    let placed = tryClassicOccupiedCardSwap(event, animal);
    if (!placed) placed = tryDropOnOutgoingOffer(event, animal);
    if (!placed) placed = tryDropOnExchange(event, animal);
    if (!placed) placed = tryDropOnExactSlot(event, animal);
    if (!placed) placed = tryDropOnEnclosure(event, animal);
    if (!placed) {
        if(!drag.originalWasTrueArrivalOverlay) restoreDraggedAnimal();

        clearExchangeGlowFocusIfIdle();
        prepareExchangeGlowAfterAnimalDrag(drag);
        drag.image?.remove();
        state.drag = null;
        renderAfterTransientAnimalDrag(drag);
        return;
    }

    if(serverAuthoritativeMultiplayerActive() &&
       (drag.originalWasPublicTradeListing || drag.originalWasOutgoing) &&
       animal.enclosureId!=null){
        clearAnimalZooReservation(animal);
        withdrawMultiplayerTradeListing().then(ok=>{
            if(!ok){
                multiplayerDiagnostic('trade-listing-takeback-withdraw-failed',{
                    animalId:animal.id,enclosureId:animal.enclosureId,slotIndex:animal.slotIndex
                });
            }
            scheduleLocalMultiplayerSync?.('trade-listing-takeback');
            renderTrade();
        }).catch(error=>{
            console.warn('Could not withdraw taken-back multiplayer listing:',error);
            scheduleLocalMultiplayerSync?.('trade-listing-takeback-recovery');
        });
    }

    beginCompatibilityGlowFade(drag.compatibilityGlowKeys);

    const peerOwnsDrag=localClassicMatch && (
        localMultiplayerPeerReplica?.playerId===localClassicMatch.activePlayerId ||
        (localMultiplayerBrowserTransport?.role==='peer' &&
         localMultiplayerBrowserTransport.playerId===localClassicMatch.activePlayerId)
    );
    const movedWithinZoo=placed &&
        String(state.outgoingOffer?.id??'')!==String(animal.id) &&
        animal.enclosureId!=null &&
        (String(animal.enclosureId)!==String(drag.originalEnclosureId)||
         Number(animal.slotIndex)!==Number(drag.originalSlotIndex));
    if(peerOwnsDrag&&movedWithinZoo&&drag.originalEnclosureId!=null){
        const destination={
            enclosure:enclosureByIdFast(animal.enclosureId),
            slotIndex:animal.slotIndex
        };
        if(!serverAuthoritativeMultiplayerActive()){
            if(preDropReservations){
                const before=new Map(preDropReservations.map(p=>[String(p.id),p]));
                for(const current of state.animals||[]){
                    const p=before.get(String(current.id));if(!p)continue;
                    current.enclosureId=p.enclosureId;current.slotIndex=p.slotIndex;
                    if(p.reservedEnclosureId==null)delete current.reservedEnclosureId;
                    else current.reservedEnclosureId=p.reservedEnclosureId;
                    if(p.reservedSlotIndex==null)delete current.reservedSlotIndex;
                    else current.reservedSlotIndex=p.reservedSlotIndex;
                }
            }else{
                animal.enclosureId=drag.originalEnclosureId;
                animal.slotIndex=drag.originalSlotIndex;
            }
        }
        drag.image?.remove();state.drag=null;
        if(serverAuthoritativeMultiplayerActive())renderAll();
        sendLocalMultiplayerAnimalMove(localClassicMatch.activePlayerId,animal.id,destination);
        return;
    }

    clearExchangeGlowFocusIfIdle();
    prepareExchangeGlowAfterAnimalDrag(drag);
    drag.image?.remove();

    const sameExhibitRelocation=profiledZooRenderStage(
        'drag-finish.same-exhibit',
        () => renderClassicSameExhibitRelocation(drag,animal)
    );
    state.drag = null;
    if(sameExhibitRelocation){
        renderExchange();
        renderTrade();
        refreshDrawAvailabilityState();
        renderProgressTracker();
        updatePrestigeDisplay();
        updateTurnDisplay();
        captureTurnSnapshot();
        writeAutoResumeSnapshot();
        queueDocumentLocalisation();
        return;
    }

    const crossExhibitRelocation=profiledZooRenderStage(
        'drag-finish.cross-exhibit',
        () => renderClassicCrossExhibitRelocation(drag,animal)
    );
    if(crossExhibitRelocation){
        renderExchange();
        renderTrade();
        refreshDrawAvailabilityState();
        renderProgressTracker();
        updatePrestigeDisplay();
        updateTurnDisplay();
        captureTurnSnapshot();
        writeAutoResumeSnapshot();
        queueDocumentLocalisation();
        return;
    }

    renderAll();
}

function enclosureDragAreaFollowers(enclosure){
    if(state.gameMode==='true')return [];
    const units=classicAreaLogicalUnits().filter(unit=>
        String((unit._geoPhysicalEnclosure||unit)?.id)===String(enclosure?.id)
    );
    if(!units.length)return [];
    const unitKeys=new Set(units.map(geographicLogicalCellKey));
    const areas=[...(generatedModernGeographicAreas||[]),...(state.customAreas||[])];
    return areas.filter(area=>{
        const cells=new Set((area.cells||[]).map(c=>trueAreaCellKey(c.col,c.row)));
        return [...unitKeys].some(key=>cells.has(key));
    }).map(area=>String(area.id));
}
function setDraggedEnclosureAreaVisualOffset(areaIds,dx,dy){
    if(!areaIds?.length)return;
    const wanted=new Set(areaIds.map(String));
    for(const node of zooCanvas.querySelectorAll('[data-area-id]')){
        if(!wanted.has(String(node.dataset.areaId||'')))continue;
        node.style.setProperty('--enclosure-drag-area-x',`${dx}px`);
        node.style.setProperty('--enclosure-drag-area-y',`${dy}px`);
        node.classList.add('enclosure-drag-area-follower');
    }
}
function clearDraggedEnclosureAreaVisualOffset(areaIds){
    if(!areaIds?.length)return;
    const wanted=new Set(areaIds.map(String));
    for(const node of zooCanvas.querySelectorAll('[data-area-id]')){
        if(!wanted.has(String(node.dataset.areaId||'')))continue;
        node.classList.remove('enclosure-drag-area-follower');
        node.style.removeProperty('--enclosure-drag-area-x');
        node.style.removeProperty('--enclosure-drag-area-y');
    }
}

function startEnclosureDrag(
    event,
    enclosure,
    element
) {

    if (trueEnclosureBuilderActive && event.button === 0) return;

    if (state.visitingZoo) return;

    if(localClassicMatch?.viewingPlayerId &&
       localClassicMatch.viewingPlayerId!==localClassicMatch.activePlayerId)
        return;

    if (
        state.drag ||
        state.pan
    ) {
        return;
    }

    state.drag = {

        type:
            'enclosure',

        enclosure,

        element,

        startClientX:
            event.clientX,

        startClientY:
            event.clientY,

        startX:
            enclosure.x,

        startY:
            enclosure.y,

        areaFollowerIds:
            enclosureDragAreaFollowers(enclosure)

    };

    element.classList.add(
        'dragging-enclosure'
    );

}

function moveEnclosureDrag(
    event
) {

    const drag =
        state.drag;

    if (
        !drag ||
        drag.type !==
            'enclosure'
    ) {
        return;
    }

    const dx =
        (
            event.clientX -
            drag.startClientX
        ) /
        state.zoom;

    const dy =
        (
            event.clientY -
            drag.startClientY
        ) /
        state.zoom;

    const renderedWorldWidth = Math.max(
        ENCLOSURE_W,
        parseFloat(zooCanvas.style.width) || (zooCanvas.scrollWidth / Math.max(state.zoom, 0.0001))
    );
    const renderedWorldHeight = Math.max(
        ENCLOSURE_H,
        parseFloat(zooCanvas.style.height) || (zooCanvas.scrollHeight / Math.max(state.zoom, 0.0001))
    );

    drag.enclosure.x =
        clamp(
            drag.startX + dx,
            0,
            renderedWorldWidth - ENCLOSURE_W
        );

    drag.enclosure.y =
        clamp(
            drag.startY + dy,
            0,
            renderedWorldHeight - ENCLOSURE_H
        );

    drag.element.style.left =
        drag.enclosure.x +
        'px';

    drag.element.style.top =
        drag.enclosure.y +
        'px';

    setDraggedEnclosureAreaVisualOffset(
        drag.areaFollowerIds,
        drag.enclosure.x-drag.startX,
        drag.enclosure.y-drag.startY
    );

}

function enclosurePlacementIsValid(enclosure, x, y) {
    const candidate = { x, y, w: ENCLOSURE_W, h: ENCLOSURE_H };
    return state.enclosures.every(other => {
        if (other.id === enclosure.id) return true;
        return !rectanglesOverlap(
            candidate,
            { x: other.x, y: other.y, w: ENCLOSURE_W, h: ENCLOSURE_H },
            ENCLOSURE_GAP
        );
    });
}

function nearestValidEnclosureSnap(enclosure) {
    const candidates = [];

    for (const other of state.enclosures) {
        if (other.id === enclosure.id) continue;
        candidates.push(
            { x: other.x + ENCLOSURE_W + ENCLOSURE_GAP, y: other.y },
            { x: other.x - ENCLOSURE_W - ENCLOSURE_GAP, y: other.y },
            { x: other.x, y: other.y + ENCLOSURE_H + ENCLOSURE_GAP },
            { x: other.x, y: other.y - ENCLOSURE_H - ENCLOSURE_GAP }
        );
    }

    const valid = candidates.filter(pos =>
        pos.x >= 0 && pos.y >= 0 &&
        enclosurePlacementIsValid(enclosure, pos.x, pos.y)
    );

    if (!valid.length) return { x: enclosure.x, y: enclosure.y };

    valid.sort((a, b) =>
        Math.hypot(a.x - enclosure.x, a.y - enclosure.y) -
        Math.hypot(b.x - enclosure.x, b.y - enclosure.y)
    );

    return valid[0];
}

function finishEnclosureDrag() {

    if (
        !state.drag ||
        state.drag.type !==
            'enclosure'
    ) {
        return;
    }

    const enclosure = state.drag.enclosure;
    const snapped = nearestValidEnclosureSnap(enclosure);
    enclosure.x = snapped.x;
    enclosure.y = snapped.y;

    state.drag.element.style.left = `${enclosure.x}px`;
    state.drag.element.style.top = `${enclosure.y}px`;

    state.drag.element
        ?.classList
        .remove(
            'dragging-enclosure'
        );

    const moved=
        Math.abs(enclosure.x-state.drag.startX)>0.01 ||
        Math.abs(enclosure.y-state.drag.startY)>0.01;
    clearDraggedEnclosureAreaVisualOffset(state.drag.areaFollowerIds);
    state.drag = null;

    if(moved){
        stableConnectedAreaGroups=null;
        stableConnectedAreaGroupsSignature='';
        invalidateConnectedAreaReconciliation();
        if(state.gameMode==='true')renderZoo();
        else refreshClassicAreaVisuals();
        writeAutoResumeSnapshot?.(true);
    }

}

function startPan(event) {

    if ((areaToolActive || trueEnclosureBuilderActive) && event.button === 0) {
        return;
    }

    if (
        state.drag ||
        state.pan
    ) {
        return;
    }

    state.pan = {

        startClientX:
            event.clientX,

        startClientY:
            event.clientY,

        startScrollLeft:
            zooBoard.scrollLeft,

        startScrollTop:
            zooBoard.scrollTop,

        pointerId:
            event.pointerId,

        pointerType:
            event.pointerType

    };

    zooBoard.classList.add(
        'panning'
    );

}

function movePan(event) {

    if (!state.pan) {
        return;
    }

    if (
        zooPinch ||
        (state.pan.pointerId != null && event.pointerId !== state.pan.pointerId)
    ) {
        return;
    }

    const dx =
        event.clientX -
        state.pan.startClientX;

    const dy =
        event.clientY -
        state.pan.startClientY;

    zooBoard.scrollLeft =
        state.pan.startScrollLeft -
        dx;

    zooBoard.scrollTop =
        state.pan.startScrollTop -
        dy;

}

function finishPan() {

    if (!state.pan) {
        return;
    }

    state.pan = null;

    zooBoard.classList.remove(
        'panning'
    );

}

function pointerIsOnZooScrollbar(event) {
    if (event.pointerType === 'touch') return false;

    const rect = zooBoard.getBoundingClientRect();
    const verticalScrollbarWidth = Math.max(0, zooBoard.offsetWidth - zooBoard.clientWidth);
    const horizontalScrollbarHeight = Math.max(0, zooBoard.offsetHeight - zooBoard.clientHeight);

    const onVerticalScrollbar =
        verticalScrollbarWidth > 0 &&
        event.clientX >= rect.right - verticalScrollbarWidth &&
        event.clientX <= rect.right;

    const onHorizontalScrollbar =
        horizontalScrollbarHeight > 0 &&
        event.clientY >= rect.bottom - horizontalScrollbarHeight &&
        event.clientY <= rect.bottom;

    return onVerticalScrollbar || onHorizontalScrollbar;
}

zooBoard.addEventListener(
    'pointerdown',
    event => {

        if (
            event.button !== 0 &&
            event.button !== 1
        ) {
            return;
        }
        if (trueCuratorCameraLocked()) {
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        if ((areaToolActive || trueEnclosureBuilderActive) && event.button === 0) {
            return;
        }

        if (pointerIsOnZooScrollbar(event)) {
            return;
        }

        if (
            event.pointerType === 'touch' &&
            (zooPinch || zooTouchPointers.size > 1)
        ) {
            return;
        }

        if (
            event.target.closest(
                '.animal-card'
            )
        ) {
            return;
        }

        if (
            event.target.closest(
                '.enclosure'
            )
        ) {
            return;
        }

        event.preventDefault();

        startPan(
            event
        );

    }
);

let zooPrimaryPointerDown=false;
document.addEventListener('pointerdown',event=>{
    if(event.button===0)zooPrimaryPointerDown=true;
},true);
document.addEventListener('pointerup',()=>{zooPrimaryPointerDown=false;},true);
document.addEventListener('pointercancel',()=>{
    // Do not clear state.drag here: the existing bubble-phase pointercancel
    // handler below restores animals/results/reservations safely.
    zooPrimaryPointerDown=false;
},true);
window.addEventListener('blur',()=>{
    zooPrimaryPointerDown=false;
    const drag=state.drag;
    if(drag?.type==='animal'){
        restoreDraggedAnimal();
        drag.image?.remove();
        state.drag=null;
        renderAfterTransientAnimalDrag(drag);
        refreshDrawAvailabilityState();
    }else if(drag?.image){
        drag.image.remove();
        state.drag=null;
    }
    removeOrphanedAnimalDragImages();
});

document.addEventListener(
    'pointermove',
    event => {

        if (state.drag?.type === 'draw-result') { moveDrawDragImage(event); return; }
        if (state.drag?.type === 'direct-human-trade-sender-claim') { moveDirectHumanTradeSenderClaimDrag(event); return; }
        if (state.drag?.type === 'human-trade-request') { moveHumanTradeRequestDrag(event); return; }
        if (state.drag?.type === 'public-human-trade-proposal') { movePublicTradeListingDrag(event); return; }
        if (state.drag?.type === 'direct-human-trade-result') { moveDirectHumanTradeResultDrag(event); return; }
        if (state.drag?.type === 'trade-result') { moveTradeResultDragImage(event); return; }

        if (state.drag?.type === 'result') {
            moveResultDragImage(event);
            return;
        }

        if (
            state.drag?.type ===
            'animal'
        ) {

            moveAnimalDragImage(
                event
            );

            return;

        }

        if (
            state.drag?.type ===
            'enclosure'
        ) {

            moveEnclosureDrag(
                event
            );

            return;

        }

        if (state.pan) {

            movePan(
                event
            );

        }

    }
);

document.addEventListener(
    'pointerup',
    async event => {

        if (state.drag?.type === 'draw-result') { finishDrawDrag(event); return; }
        if (state.drag?.type === 'direct-human-trade-sender-claim') { finishDirectHumanTradeSenderClaimDrag(event); return; }
        if (state.drag?.type === 'human-trade-request') { await finishHumanTradeRequestDrag(event); return; }
        if (state.drag?.type === 'public-human-trade-proposal') { await finishPublicTradeListingDrag(event); return; }
        if (state.drag?.type === 'direct-human-trade-result') { finishDirectHumanTradeResultDrag(event); return; }
        if (state.drag?.type === 'trade-result') { await finishTradeResultDrag(event); return; }

        if (state.drag?.type === 'result') {
            finishResultDrag(event);
            return;
        }

        if (
            state.drag?.type ===
            'animal'
        ) {

            finishAnimalDrag(
                event
            );

            return;

        }

        if (
            state.drag?.type ===
            'enclosure'
        ) {

            finishEnclosureDrag();

            return;

        }

        if (
            state.pan &&
            (state.pan.pointerId == null || event.pointerId === state.pan.pointerId)
        ) {

            finishPan();

        }

    }
);

document.addEventListener(
    'pointercancel',
    event => {

        if (state.drag?.type === 'result') {
            state.drag.image?.remove();
            state.drag = null;
            renderExchange();
        }
        else if (state.drag?.type === 'draw-result') {
            state.drag.image?.remove();
            state.drag = null;
            refreshDrawAvailabilityState();
        }
        else if(state.drag?.type==='animal'){
            const cancelledAnimalDrag=state.drag;
            restoreDraggedAnimal();
            cancelledAnimalDrag.image?.remove();
            state.drag=null;
            renderAfterTransientAnimalDrag(cancelledAnimalDrag);
            refreshDrawAvailabilityState();
        }
        else if (state.drag?.type === 'trade-result') {
            const cancelledTradeDrag = state.drag;
            cancelledTradeDrag.image?.remove();
            state.drag = null;
            if (state.outgoingOffer && cancelledTradeDrag.releasedOutgoingReservation) {
                reserveAnimalZooSlot(
                    state.outgoingOffer,
                    cancelledTradeDrag.releasedOutgoingReservation.enclosureId,
                    cancelledTradeDrag.releasedOutgoingReservation.slotIndex
                );
            }
            renderTrade();
            refreshDrawAvailabilityState();
        }
        else if(state.drag?.type==='direct-human-trade-result'){
            const cancelled=state.drag;
            cancelled.image?.remove();
            state.drag=null;
            const released=cancelled.releasedRequestedPlacement;
            const animal=classicAnimalById(released?.animalId);
            if(animal&&released){
                animal.enclosureId=released.enclosureId;
                animal.slotIndex=released.slotIndex;
            }
            renderTrade();
            renderAnimals?.();
            refreshDrawAvailabilityState();
        }
        else if(state.drag?.type==='direct-human-trade-sender-claim'){
            state.drag.image?.remove();
            state.drag=null;
            renderTrade();
        }
        else if(state.drag?.type==='public-human-trade-proposal'){
            state.drag.image?.remove();
            state.drag=null;
            renderTrade();
        }
        else         if (
            state.drag?.type ===
            'animal'
        ) {

            restoreDraggedAnimal();

            state.drag.image
                ?.remove();

            const cancelledDrag = state.drag;
            prepareExchangeGlowAfterAnimalDrag(cancelledDrag);
            state.drag = null;

            renderAfterTransientAnimalDrag(cancelledDrag);

        }
        else if (
            state.drag?.type ===
            'enclosure'
        ) {

            finishEnclosureDrag();

        }

        if (
            state.pan &&
            (state.pan.pointerId == null || event.pointerId === state.pan.pointerId)
        ) {
            finishPan();
        }

    }
);

function setZoom(
    newZoom,
    clientX = null,
    clientY = null
) {
    const oldZoom = state.zoom;
    const nextZoom = clamp(
        Math.round(newZoom * 100) / 100,
        currentZoomMin(),
        ZOOM_MAX
    );
    if (nextZoom === oldZoom) return;

    const boardRect = zooBoard.getBoundingClientRect();
    const pointerX = clientX !== null ? clientX - boardRect.left : zooBoard.clientWidth / 2;
    const pointerY = clientY !== null ? clientY - boardRect.top : zooBoard.clientHeight / 2;

    const anchorWorldX = (zooBoard.scrollLeft + pointerX) / oldZoom;
    const anchorWorldY = (zooBoard.scrollTop + pointerY) / oldZoom;

    state.zoom = nextZoom;
    document.documentElement.style.setProperty('--zoo-zoom', state.zoom);

    const restoreMouseAnchor = () => {
        const maxLeft = Math.max(0, zooBoard.scrollWidth - zooBoard.clientWidth);
        const maxTop = Math.max(0, zooBoard.scrollHeight - zooBoard.clientHeight);

        zooBoard.scrollLeft = Math.max(
            0,
            Math.min(maxLeft, anchorWorldX * state.zoom - pointerX)
        );
        zooBoard.scrollTop = Math.max(
            0,
            Math.min(maxTop, anchorWorldY * state.zoom - pointerY)
        );
    };

    restoreMouseAnchor();
    requestAnimationFrame(restoreMouseAnchor);
}

const zooTouchPointers = new Map();
let zooPinch = null;

if (zooBoard) zooBoard.style.touchAction = 'none';

function zooPinchDistance(a, b) {
    return Math.hypot(b.clientX - a.clientX, b.clientY - a.clientY);
}

function zooPinchMidpoint(a, b) {
    return { x: (a.clientX + b.clientX) / 2, y: (a.clientY + b.clientY) / 2 };
}

function cancelAnimalDragForPinch() {
    if (state.drag?.type !== 'animal') return;
    const cancelledDrag = state.drag;
    restoreDraggedAnimal();
    prepareExchangeGlowAfterAnimalDrag(cancelledDrag);
    state.drag.image?.remove();
    state.drag = null;
    renderAfterTransientAnimalDrag(cancelledDrag);
}

function beginZooPinchIfReady() {
    if (zooPinch || zooTouchPointers.size < 2) return;
    const pair = [...zooTouchPointers.entries()].slice(0, 2);
    const [[pointerA, a], [pointerB, b]] = pair;
    const distance = zooPinchDistance(a, b);
    const midpoint = zooPinchMidpoint(a, b);
    if (!distance) return;

    cancelAnimalDragForPinch();
    if (state.drag) return;
    finishPan();

    const boardRect = zooBoard.getBoundingClientRect();
    zooPinch = {
        pointerA,
        pointerB,
        startDistance: distance,
        startZoom: state.zoom,
        anchorWorldX: (zooBoard.scrollLeft + midpoint.x - boardRect.left) / state.zoom,
        anchorWorldY: (zooBoard.scrollTop + midpoint.y - boardRect.top) / state.zoom
    };
}

zooBoard.addEventListener('pointerdown', event => {
    if (trueCuratorCameraLocked()) { event.preventDefault(); return; }
    if (event.pointerType !== 'touch') return;
    zooTouchPointers.set(event.pointerId, { clientX: event.clientX, clientY: event.clientY });
    if (zooTouchPointers.size >= 2) beginZooPinchIfReady();
}, { capture: true });

zooBoard.addEventListener('pointermove', event => {
    if (event.pointerType !== 'touch' || !zooTouchPointers.has(event.pointerId)) return;
    zooTouchPointers.set(event.pointerId, { clientX: event.clientX, clientY: event.clientY });
    if (!zooPinch) return;
    const a=zooTouchPointers.get(zooPinch.pointerA);
    const b=zooTouchPointers.get(zooPinch.pointerB);
    if (!a || !b) return;

    event.preventDefault();
    event.stopPropagation();

    const distance = zooPinchDistance(a, b);
    const midpoint = zooPinchMidpoint(a, b);
    if (!distance || !zooPinch.startDistance) return;

    const nextZoom = clamp(
        zooPinch.startZoom * (distance / zooPinch.startDistance),
        currentZoomMin(),
        ZOOM_MAX
    );
    state.zoom = Math.round(nextZoom * 1000) / 1000;
    document.documentElement.style.setProperty('--zoo-zoom', state.zoom);

    const boardRect = zooBoard.getBoundingClientRect();
    zooBoard.scrollLeft = zooPinch.anchorWorldX * state.zoom - (midpoint.x - boardRect.left);
    zooBoard.scrollTop = zooPinch.anchorWorldY * state.zoom - (midpoint.y - boardRect.top);
}, { capture: true, passive: false });

function endZooTouchPointer(event) {
    if (event.pointerType !== 'touch') return;

    const endedPinchFinger = Boolean(
        zooPinch &&
        (event.pointerId === zooPinch.pointerA || event.pointerId === zooPinch.pointerB)
    );
    const wasPinching = Boolean(zooPinch);
    zooTouchPointers.delete(event.pointerId);

    if (endedPinchFinger) {
        zooPinch = null;
    }
    if (!zooPinch && zooTouchPointers.size >= 2) {
        beginZooPinchIfReady();
    }

    if (wasPinching && !zooPinch && zooTouchPointers.size === 1) {
        finishPan();
        const [remainingPointerId, remaining] = [...zooTouchPointers.entries()][0];
        state.pan = {
            startClientX: remaining.clientX,
            startClientY: remaining.clientY,
            startScrollLeft: zooBoard.scrollLeft,
            startScrollTop: zooBoard.scrollTop,
            pointerId: remainingPointerId,
            pointerType: 'touch',
            touchContinuation: true
        };
        zooBoard.classList.add('panning');
    }

    if (zooTouchPointers.size === 0 && state.pan?.touchContinuation) {
        finishPan();
    }
}

zooBoard.addEventListener('pointerup', endZooTouchPointer, { capture: true });
zooBoard.addEventListener('pointercancel', endZooTouchPointer, { capture: true });

window.addEventListener('blur', () => {
    zooTouchPointers.clear();
    zooPinch = null;
    if (state.pan?.touchContinuation) finishPan();
});

zooBoard.addEventListener(
    'wheel',
    event => {

        event.preventDefault();
        if (trueCuratorCameraLocked()) return;

        const direction =
            event.deltaY < 0
                ? 1
                : -1;

        setZoom(
            state.zoom +
                direction *
                ZOOM_STEP,
            event.clientX,
            event.clientY
        );

    },
    {
        passive: false
    }
);

function isDrawSafeDestinationForAnimal(animal, enclosure, slotIndex) {
    if (!animal || !enclosure || slotIndex == null) return false;
    if (!state.sandboxMode && enclosure.number === 10 && !state.enclosure10Unlocked && !level4IsInZoo()) return false;

    const group = enclosureGroupForSlot(enclosure, slotIndex);
    if (!group) return false;

    const hasReservation = state.animals.some(existing =>
        existing?.reservedEnclosureId === enclosure.id &&
        group.includes(existing.reservedSlotIndex)
    );
    if (hasReservation) return false;

    if (group.length > 1) {
        if (animalsInEnclosureGroup(enclosure, group, null, true).length > 0) return false;
    } else if (animalAtSlot(enclosure.id, slotIndex, null, true)) {
        return false;
    }

    return canPlace(animal, enclosure, slotIndex);
}

function drawSafeDestinationsForAnimal(animal) {
    const result = [];
    for (const enclosure of state.enclosures) {
        for (const slotIndex of getAllSlots(enclosure)) {
            if (isDrawSafeDestinationForAnimal(animal, enclosure, slotIndex)) {
                result.push({ enclosure, slotIndex });
            }
        }
    }
    return result;
}

function noteAuthoritativeOwnZooRevision(revision){
    const t=localMultiplayerBrowserTransport;
    const value=Math.max(0,Number(revision)||0);
    if(!t)return value;
    t.durableZooRevision=Math.max(Math.max(0,Number(t.durableZooRevision)||0),value);
    if(!(t.appliedAuthoritativeOwnActionZooRevisions instanceof Set))
        t.appliedAuthoritativeOwnActionZooRevisions=new Set(t.appliedAuthoritativeOwnActionZooRevisions||[]);
    if(value>0){
        t.appliedAuthoritativeOwnActionZooRevisions.add(value);
        if(t.appliedAuthoritativeOwnActionZooRevisions.size>16){
            const ordered=[...t.appliedAuthoritativeOwnActionZooRevisions].sort((a,b)=>a-b);
            for(const revision of ordered.slice(0,-16))
                t.appliedAuthoritativeOwnActionZooRevisions.delete(revision);
        }
    }
    if(!(t.serverZooRevisionByPlayer instanceof Map))
        t.serverZooRevisionByPlayer=new Map(t.serverZooRevisionByPlayer||[]);
    const serverPlayerId=String(t.serverPlayerId||'');
    if(serverPlayerId){
        const known=Math.max(0,Number(t.serverZooRevisionByPlayer.get(serverPlayerId))||0);
        if(value>known)t.serverZooRevisionByPlayer.set(serverPlayerId,value);
    }
    const localPlayer=localClassicMatch?.players?.[t.playerId];
    if(localPlayer) localPlayer.lastServerZooRevision=Math.max(
        Math.max(0,Number(localPlayer.lastServerZooRevision)||0),value
    );
    return value;
}

async function commitServerAuthoritativeLevelOneDraw(message,destination){
    const t=localMultiplayerBrowserTransport;
    const zoo=message?.zoo;
    const raw=message?.card;
    const category=String(raw?.category||'').trim();
    const filename=cleanFilename(raw?.fileName||raw?.filename||'');
    if(!category||!filename||!zoo?.state||!Array.isArray(zoo.state.animals))return false;
    if(String(message.playerId||'')!==String(t?.serverPlayerId||''))return false;

    noteAuthoritativeOwnZooRevision(message.zooRevision);
    t.durableOwnZooSnapshot=cloneForSave(zoo);
    t.durableZooQueuedSnapshot=null;
    t.durableZooQueuedSignature='';
    const drawVisitToken=multiplayerHumanVisitTransitionToken;
    if(localClassicMatch?.viewingPlayerId)return false;
    autoResumeWriteSuppressed=true;
    try{
        await importGameState(cloneForSave(zoo),{deferRender:false});
    }finally{autoResumeWriteSuppressed=false;}
    if(drawVisitToken!==multiplayerHumanVisitTransitionToken||localClassicMatch?.viewingPlayerId)
        return false;

    ensureAnimalLineage(message.animal||{
        id:null,category,level:1,filename
    },state.zooName||'Your Zoo');
    removePlayerClaimedCardFromOpponents(category,1,filename);
    markPlayerLevelSeen(1);
    state.nextDrawSpec=null;
    state.nextDrawReadyPromise=null;

    finalizeClassicProgressionCommit('Server-authoritative Level 1 draw');

    const committedDrawSnapshot=exportCurrentGameState();
    commitOwnZooStateToServer(committedDrawSnapshot);
    if(t?.role==='peer'&&t.playerId===localClassicMatch?.activePlayerId){
        const bridge=await sendLocalMultiplayerBrowserAction('replace-player-zoo',{
            snapshot:committedDrawSnapshot
        });
        if(!bridge?.ok)console.warn('Could not bridge authoritative Draw into host zoo state:',bridge?.reason||'unknown');
    }
    return true;
}

function buildAuthoritativeMultiplayerLevelOneDeck(){
    const remaining=availableLevelOneDrawSpecs().map(spec=>({
        category:spec.category,level:1,filename:cleanFilename(spec.filename)
    }));
    const deck=[];
    while(remaining.length){
        const byCategory=new Map();
        for(const spec of remaining){
            if(!byCategory.has(spec.category))byCategory.set(spec.category,[]);
            byCategory.get(spec.category).push(spec);
        }
        const categories=[...byCategory.keys()];
        const category=randomItem(categories);
        const choices=byCategory.get(category);
        const chosen=randomItem(choices);
        if(!chosen)break;
        deck.push({category:chosen.category,fileName:chosen.filename});
        const index=remaining.indexOf(chosen);
        if(index>=0)remaining.splice(index,1);
    }
    return deck;
}
function initialiseAuthoritativeMultiplayerProgressionIfHost(){
    const t=localMultiplayerBrowserTransport;
    const channel=localMultiplayerBrowserChannel;
    if(!t?.serverAuthenticated||Number(t.serverSeat)!==1||!channel?.postServerMessage)return false;
    if(t.serverProgression||t.serverProgressionInitSent)return false;
    const level1Deck=buildAuthoritativeMultiplayerLevelOneDeck();
    if(!level1Deck.length)return false;
    t.serverProgressionInitSent=true;
    channel.postServerMessage({type:'progression-init',level1Deck});
    t.sent++;t.lastMessageType='progression-init';
    return true;
}

async function requestServerAuthoritativeExchange(destination=null,autoPlace=false){
    if(!serverAuthoritativeMultiplayerActive())return null;
    if(state.outgoingOffer||!state.result)return false;

    const sources=(state.exchange||[]).filter(Boolean);
    if(sources.length!==2)return false;
    const resultSpec={
        category:state.result.category,
        level:Number(state.result.level)||0,
        filename:cleanFilename(state.result.filename)
    };
    const prospective={
        id:state.nextId,category:resultSpec.category,level:resultSpec.level,
        filename:resultSpec.filename,enclosureId:null,slotIndex:null
    };
    let chosen=destination;
    if(autoPlace&&!chosen)chosen=randomEligibleDestinationForAnimal(prospective);
    if(!chosen?.enclosure||chosen.slotIndex==null||
       !canPlace(prospective,chosen.enclosure,chosen.slotIndex))return false;

    syncActiveZooIntoLocalMatch();
    const preExchangeSnapshot=sanitizeTransientExchangeState(exportCurrentGameState());
    commitOwnZooStateToServer(preExchangeSnapshot);
    const durableExchangeReady=await awaitDurableZooCommitIdle(5000);
    if(!durableExchangeReady){
        console.warn('Authoritative Exchange paused because the durable zoo changed.');
        return false;
    }
    if(localClassicMatch?.viewingPlayerId)return false;

    const response=await sendMultiplayerServerAction('exchange',{
        sourceIds:sources.map(animal=>animal.id),
        result:resultSpec,
        destination:multiplayerDestinationToWire(chosen,prospective)
    });
    if(response?.type!=='action-committed'||response?.action!=='exchange'){
        if(response?.code)console.warn('Authoritative Exchange rejected:',response.code);
        return false;
    }
    const t=localMultiplayerBrowserTransport;
    if(String(response.playerId||'')!==String(t?.serverPlayerId||''))return false;
    if(!response.zoo?.state||!Array.isArray(response.zoo.state.animals))return false;
    if(localClassicMatch?.viewingPlayerId)return false;
    const currentSourceIds=(state.exchange||[]).filter(Boolean).map(a=>String(a.id)).sort().join('|');
    const requestedSourceIds=sources.map(a=>String(a.id)).sort().join('|');
    if(currentSourceIds!==requestedSourceIds)return false;

    noteAuthoritativeOwnZooRevision(response.zooRevision);
    const authoritativeExchangeZoo=sanitizeTransientExchangeState(cloneForSave(response.zoo));
    t.durableOwnZooSnapshot=cloneForSave(authoritativeExchangeZoo);
    t.durableZooQueuedSnapshot=null;
    t.durableZooQueuedSignature='';
    const exchangeVisitToken=multiplayerHumanVisitTransitionToken;
    autoResumeWriteSuppressed=true;
    try{
        await importGameState(authoritativeExchangeZoo,{deferRender:true});
    }finally{autoResumeWriteSuppressed=false;}
    if(exchangeVisitToken!==multiplayerHumanVisitTransitionToken||localClassicMatch?.viewingPlayerId)
        return false;

    const resultAnimal=(state.animals||[]).find(a=>
        String(a?.id)===String(response.resultAnimal?.id));
    if(resultAnimal){
        ensureAnimalLineage(resultAnimal,state.zooName||'Your Zoo');
        removePlayerClaimedCardFromOpponents(
            resultAnimal.category,resultAnimal.level,resultAnimal.filename);
        markPlayerLevelSeen(resultAnimal.level);
        if(autoPlace)markNewPlacementGlow(resultAnimal);
        checkEnclosureReward(resultAnimal,'exchange');
    }
    state.exchange=[null,null];
    state.result=null;
    state.exchangeGlowFocusKey=null;
    for(const source of sources)state.suppressedExchangeGlowIds.delete(source.id);
    renderExchange();

    finalizeClassicProgressionCommit('Server-authoritative Exchange');

    const snapshot=exportCurrentGameState();
    const ownMatchPlayer=localClassicMatch?.players?.[localClassicMatch.activePlayerId];
    if(ownMatchPlayer)ownMatchPlayer.snapshot=cloneForSave(snapshot);
    const rewardPersisted=await commitOwnZooStateToServer(snapshot);
    const rewardDurable=rewardPersisted!==false && await awaitDurableZooCommitIdle(5000);
    if(!rewardDurable){
        console.warn('Multiplayer exchange reward state did not become durable before completion.');
        showGameNotice?.('Exchange completed, but the enclosure reward is still syncing. Please wait before leaving the game.');
    }
    if(t?.role==='peer'&&t.playerId===localClassicMatch?.activePlayerId){
        const bridge=await sendLocalMultiplayerBrowserAction('replace-player-zoo',{snapshot});
        if(!bridge?.ok)console.warn('Could not bridge authoritative Exchange into host zoo state:',bridge?.reason||'unknown');
    }
    return true;
}

async function requestServerAuthoritativeLevelOneDraw(destination=null){
    if(!serverAuthoritativeMultiplayerActive())return null;
    if(state.drawCommitInProgress||hasPendingPlayerAction())return false;
    let chosen=destination;
    if(!chosen){
        const candidates=[];
        for(const enclosure of state.enclosures||[]){
            for(const slotIndex of getAllSlots(enclosure)){
                const group=enclosureGroupForSlot(enclosure,slotIndex);
                if(!group)continue;
                const hasReservation=(state.animals||[]).some(a=>
                    a?.reservedEnclosureId===enclosure.id&&group.includes(a.reservedSlotIndex));
                if(hasReservation)continue;
                if(group.length>1){
                    if(animalsInEnclosureGroup(enclosure,group,null,true).length===0)
                        candidates.push({enclosure,slotIndex});
                }else if(!animalAtSlot(enclosure.id,slotIndex,null,true)){
                    candidates.push({enclosure,slotIndex});
                }
            }
        }
        if(!candidates.length)return false;
        chosen=randomItem(candidates);
    }
    state.drawCommitInProgress=true;
    refreshDrawAvailabilityState();
    try{
        if(localClassicMatch &&
           (!localClassicMatch.viewingPlayerId ||
            localClassicMatch.viewingPlayerId===localClassicMatch.activePlayerId)){
            syncActiveZooIntoLocalMatch();
        }
        if(!await awaitDurableZooCommitIdle(5000)){
            console.warn('Authoritative Draw paused because the durable zoo changed.');
            return false;
        }
        const result=await sendMultiplayerServerAction('draw-level1',{
            destination:{...multiplayerDestinationToWire(chosen),clientPlacementValidated:true}
        });
        if(result?.type!=='action-committed'||result?.action!=='draw-level1'){
            if(result?.code)console.warn('Authoritative Draw rejected:',result.code);
            return false;
        }
        const t=localMultiplayerBrowserTransport;
        if(String(result.playerId||'')!==String(t?.serverPlayerId||''))return false;
        return await commitServerAuthoritativeLevelOneDraw(result,chosen);
    }finally{
        state.drawCommitInProgress=false;
        refreshDrawAvailabilityState();
    }
}

async function createLevelOneForDrawUnlocked(destination) {
    if (!guardLocalClassicProgressionCommit('Level 1 draw')) return false;
    if (!destination?.enclosure || destination.slotIndex == null) return false;
    if (hasPendingPlayerAction()) return false;

    await prepareNextDrawAsset();
    const spec = state.nextDrawSpec;
    if (!spec) {
        refreshDrawAvailabilityState();
        return false;
    }

    if (!isDrawSafeDestinationForAnimal(
        spec,
        destination.enclosure,
        destination.slotIndex
    )) {
        refreshDrawAvailabilityState();
        return false;
    }

    if (state.nextDrawSpec !== spec || !levelOneSpecStillDrawable(spec)) {
        refreshDrawAvailabilityState();
        return false;
    }
    const committedSpec = spec;
    state.nextDrawSpec = null;
    state.nextDrawReadyPromise = null;

    const animal = {
        id: state.nextId,
        category: committedSpec.category,
        level: 1,
        filename: cleanFilename(committedSpec.filename),
        enclosureId: null,
        slotIndex: null
    };

    if (!placeAnimal(animal, destination.enclosure, destination.slotIndex)) {
        console.error('Validated Level 1 draw destination unexpectedly rejected placement.', {
            animal, destination
        });
        state.nextDrawSpec = committedSpec;
        state.nextDrawReadyPromise = preloadAnimalAsset(committedSpec);
        refreshDrawAvailabilityState();
        return false;
    }

    state.nextId++;
    ensureAnimalLineage(animal, state.zooName || 'Your Zoo');
    removePlayerClaimedCardFromOpponents(
        animal.category,
        animal.level,
        animal.filename
    );
    state.animals.push(animal);
    markPlayerLevelSeen(animal.level);
    finalizeClassicProgressionCommit('Level 1 draw commit');
    advanceClassicTutorial(2);

    prepareNextDrawAsset();
    return true;
}

async function createLevelOneForDraw(destination) {
    if (state.drawCommitInProgress) return false;

    state.drawCommitInProgress = true;
    refreshDrawAvailabilityState();
    let placed=false;
    try {
        placed=await createLevelOneForDrawUnlocked(destination);
        return placed;
    } finally {
        state.drawCommitInProgress = false;
        refreshDrawAvailabilityState();
        if(placed)removeOrphanedAnimalDragImages();
    }
}

async function drawLevelOne() {
    if (state.gameMode === 'true') return false;
    if (state.drawCommitInProgress || hasPendingPlayerAction()) return false;

    state.drawCommitInProgress = true;
    refreshDrawAvailabilityState();
    try {
        await prepareNextDrawAsset();
        const spec = state.nextDrawSpec;
        if (!spec || !levelOneSpecStillDrawable(spec)) {
            refreshDrawAvailabilityState();
            return false;
        }

        const destinations = drawSafeDestinationsForAnimal(spec);
        if (!destinations.length) {
            refreshDrawAvailabilityState();
            return false;
        }

        return await createLevelOneForDrawUnlocked(randomItem(destinations));
    } finally {
        state.drawCommitInProgress = false;
        refreshDrawAvailabilityState();
    }
}

function startDrawDrag(event) {
    if(drawCard?.dataset?.multiplayerTheirOffer==='true')return;
    if (state.gameMode === 'true') return;
    if (state.drag || state.pan) return;
    const rect = drawCard.getBoundingClientRect();
    const source = drawCard.querySelector('img');
    const image = document.createElement('img');
    image.className = 'dragging-animal dragging-result';
    image.src = source?.src || animalBackPath('Carnivores',1);
    Object.assign(image.style,{
        position:'fixed',
        width:`${rect.width}px`,
        height:`${rect.height}px`,
        objectFit:'contain',
        pointerEvents:'none',
        zIndex:'10020'
    });
    document.body.appendChild(image);
    state.drag = {
        type:'draw-result',
        image,
        startClientX:event.clientX,
        startClientY:event.clientY,
        offsetX:event.clientX-rect.left,
        offsetY:event.clientY-rect.top,
        moved:false,
        maxDistance:0
    };
    moveDrawDragImage(event);
}
function moveDrawDragImage(event) {
    if (state.drag?.type !== 'draw-result') return;
    const distance=Math.hypot(
        event.clientX-state.drag.startClientX,
        event.clientY-state.drag.startClientY
    );
    state.drag.maxDistance=Math.max(Number(state.drag.maxDistance)||0,distance);
    if(state.drag.maxDistance>=6)state.drag.moved=true;
    state.drag.image.style.left = `${event.clientX-state.drag.offsetX}px`;
    state.drag.image.style.top = `${event.clientY-state.drag.offsetY}px`;
}
async function finishDrawDrag(event) {
    const drag = state.drag;
    if (!drag || drag.type !== 'draw-result') return;

    const releaseDistance=Math.hypot(
        event.clientX-drag.startClientX,
        event.clientY-drag.startClientY
    );
    const wasDragged=!!drag.moved ||
        Math.max(Number(drag.maxDistance)||0,releaseDistance)>=6;

    drag.image?.remove?.();
    state.drag = null;

    if (!wasDragged) {
        await performClassicGameAction({ type:CLASSIC_GAME_ACTION.DRAW_LEVEL_1 });
        return;
    }

    const destination = levelOneDrawDropDestinationAtPoint(
        event.clientX,event.clientY
    );

    if (!destination) {
        renderAll?.();
        return;
    }

    const placed = await performClassicGameAction({
        type:CLASSIC_GAME_ACTION.DRAW_LEVEL_1,
        destination,
        autoPlace:false
    });

    if (!placed) {
        renderAll?.();
    }
}

if (drawCard) drawCard.dataset.label = state.gameOptions.animalLanguage === 'nl' ? 'TREK KAART' : 'DRAW CARD';

function isBeginnerHintTurn() {
    return Number(state.turn || 0) <= 10;
}

function blueHintInitialDelay() {
    return isBeginnerHintTurn() ? 4000 : 15000;
}

function blueHintRepeatDelay() {
    return isBeginnerHintTurn() ? 14000 : 19000;
}

function yellowHintQuietDelay() {
    return isBeginnerHintTurn() ? 4000 : 15000;
}

let lateTurnHintActivityScheduled = false;

const hoveredHintControls = new Set();

function hintControlIsBeingInspected() {
    return hoveredHintControls.size > 0;
}

function cancelHintGlowsForInspectedControl() {
    actionHintGeneration++;
    if (actionHintTimer) clearTimeout(actionHintTimer);
    if (actionHintRepeatTimer) clearTimeout(actionHintRepeatTimer);
    actionHintTimer = null;
    actionHintRepeatTimer = null;
    removeActionHintOverlay();

    if (yellowExchangeHintTimer) clearTimeout(yellowExchangeHintTimer);
    yellowExchangeHintTimer = null;
    yellowExchangeHintPhase = 'waiting';
    clearYellowExchangeHintOverlays();
}

function resumeHintsAfterInspectedControl() {
    if (hintControlIsBeingInspected() || !state.loaded || state.historyViewTurn !== null) return;

    armActionHint(blueHintInitialDelay());
    yellowExchangeHintWasPossible = yellowExchangePossible();
    if (yellowExchangeHintWasPossible) {
        scheduleYellowExchangeHint(yellowHintQuietDelay());
    }
}

function bindHintInspectionGuard(target) {
    if (!target) return;

    target.addEventListener('mouseenter', () => {
        hoveredHintControls.add(target);
        cancelHintGlowsForInspectedControl();
    });

    target.addEventListener('mouseleave', () => {
        hoveredHintControls.delete(target);
        resumeHintsAfterInspectedControl();
    });
}

function noteLateTurnScreenActivity() {
    if (isBeginnerHintTurn() || !state.loaded || state.historyViewTurn !== null) return;
    if (lateTurnHintActivityScheduled) return;
    lateTurnHintActivityScheduled = true;

    requestAnimationFrame(() => {
        lateTurnHintActivityScheduled = false;
        if (isBeginnerHintTurn() || !state.loaded || state.historyViewTurn !== null) return;

        actionHintGeneration++;
        if (actionHintTimer) clearTimeout(actionHintTimer);
        if (actionHintRepeatTimer) clearTimeout(actionHintRepeatTimer);
        actionHintTimer = null;
        actionHintRepeatTimer = null;
        removeActionHintOverlay();
        armActionHint(15000);

        if (yellowExchangeHintTimer) clearTimeout(yellowExchangeHintTimer);
        yellowExchangeHintTimer = null;
        clearYellowExchangeHintOverlays();
        yellowExchangeHintPhase = 'waiting';
        yellowExchangeHintWasPossible = yellowExchangePossible();
        if (yellowExchangeHintWasPossible) scheduleYellowExchangeHint(15000);
    });
}

for (const eventName of ['pointermove', 'pointerdown', 'wheel', 'keydown']) {
    document.addEventListener(eventName, noteLateTurnScreenActivity, {
        capture: true,
        passive: eventName !== 'keydown'
    });
}

let yellowExchangeHintTimer = null;
let yellowExchangeHintOverlays = [];
let yellowExchangeHintAnimations = [];
let yellowExchangeHintWasPossible = false;
let yellowExchangeHintPhase = 'waiting';

function yellowExchangePossible() {
    return (
        !state.sandboxMode &&
        !state.visitingZoo &&
        state.loaded &&
        state.historyViewTurn === null &&
        localClassicCanShowProgressionActionGlows() &&
        eligibleExchangeCategories().length > 0 &&
        !state.exchange.some(Boolean) &&
        !state.result
    );
}

function clearYellowExchangeHintOverlays() {
    for (const animation of yellowExchangeHintAnimations) {
        try { animation?.cancel?.(); } catch (_) {}
    }
    yellowExchangeHintAnimations = [];

    for (const overlay of yellowExchangeHintOverlays) {
        overlay?.remove?.();
    }
    yellowExchangeHintOverlays = [];
}

function makeYellowHintOverlay(target, duration = 2000) {
    if (!target) return null;
    const rect = target.getBoundingClientRect();
    if (rect.width < 2 || rect.height < 2) return null;

    const ring = document.createElement('div');
    Object.assign(ring.style, {
        position: 'fixed',
        left: `${rect.left - 7}px`,
        top: `${rect.top - 7}px`,
        width: `${rect.width + 14}px`,
        height: `${rect.height + 14}px`,
        boxSizing: 'border-box',
        border: '5px solid rgb(255, 210, 35)',
        borderRadius: '10px',
        background: 'rgba(255, 215, 45, .08)',
        boxShadow: '0 0 13px 7px rgba(255,210,35,.98), 0 0 32px 14px rgba(255,190,20,.72)',
        pointerEvents: 'none',
        zIndex: '8999',
        opacity: '0'
    });
    document.body.appendChild(ring);
    yellowExchangeHintOverlays.push(ring);

    if (typeof ring.animate === 'function') {
        const animation = ring.animate([
            { opacity: 0, transform: 'scale(.985)' },
            { opacity: 1, transform: 'scale(1.025)', offset: .18 },
            { opacity: 1, transform: 'scale(1.025)', offset: .72 },
            { opacity: 0, transform: 'scale(.99)' }
        ], { duration, easing: 'ease-in-out' });
        yellowExchangeHintAnimations.push(animation);
    } else {
        ring.style.opacity = '1';
    }

    return ring;
}

function scheduleYellowExchangeHint(delay = 4000) {
    if (yellowExchangeHintTimer) clearTimeout(yellowExchangeHintTimer);
    yellowExchangeHintTimer = null;

    if (!yellowExchangePossible()) {
        yellowExchangeHintWasPossible = false;
        yellowExchangeHintPhase = 'waiting';
        clearYellowExchangeHintOverlays();
        return;
    }

    yellowExchangeHintWasPossible = true;
    yellowExchangeHintPhase = 'waiting';

    yellowExchangeHintTimer = setTimeout(() => {
        yellowExchangeHintTimer = null;
        if (!yellowExchangePossible()) {
            clearYellowExchangeHintOverlays();
            yellowExchangeHintWasPossible = false;
            return;
        }

        if (hintControlIsBeingInspected()) {
            clearYellowExchangeHintOverlays();
            scheduleYellowExchangeHint(yellowHintQuietDelay());
            return;
        }

        if (actionHintOverlay) {
            scheduleYellowExchangeHint(isBeginnerHintTurn() ? 4000 : 15000);
            return;
        }

        yellowExchangeHintPhase = 'exchange';
        clearYellowExchangeHintOverlays();
        makeYellowHintOverlay(exchange1, 2000);
        makeYellowHintOverlay(exchange2, 2000);

        yellowExchangeHintTimer = setTimeout(() => {
            yellowExchangeHintTimer = null;
            if (!yellowExchangePossible()) {
                clearYellowExchangeHintOverlays();
                yellowExchangeHintWasPossible = false;
                return;
            }

            yellowExchangeHintPhase = 'upgrade';
            clearYellowExchangeHintOverlays();
            makeYellowHintOverlay(resultBox, 2000);

            yellowExchangeHintTimer = setTimeout(() => {
                yellowExchangeHintTimer = null;
                clearYellowExchangeHintOverlays();
                if (yellowExchangePossible()) {
                    scheduleYellowExchangeHint(yellowHintQuietDelay());
                } else {
                    yellowExchangeHintWasPossible = false;
                }
            }, 2000);
        }, 2000);
    }, delay);
}

function refreshYellowExchangeHintState() {
    const possible = yellowExchangePossible();

    if (possible && !yellowExchangeHintWasPossible) {
        scheduleYellowExchangeHint(yellowHintQuietDelay());
    } else if (!possible && yellowExchangeHintWasPossible) {
        if (yellowExchangeHintTimer) clearTimeout(yellowExchangeHintTimer);
        yellowExchangeHintTimer = null;
        yellowExchangeHintWasPossible = false;
        yellowExchangeHintPhase = 'waiting';
        clearYellowExchangeHintOverlays();
    }
}

let actionHintTimer = null;
let actionHintRepeatTimer = null;
let actionHintOverlay = null;
let actionHintAnimation = null;
let actionHintGeneration = 0;

function removeActionHintOverlay() {
    actionHintAnimation?.cancel?.();
    actionHintAnimation = null;
    actionHintOverlay?.remove?.();
    actionHintOverlay = null;
}

function pauseAllHintGlowsForMenu() {
    if (actionHintTimer) clearTimeout(actionHintTimer);
    if (actionHintRepeatTimer) clearTimeout(actionHintRepeatTimer);
    actionHintTimer = null;
    actionHintRepeatTimer = null;
    ++actionHintGeneration;
    removeActionHintOverlay();

    if (yellowExchangeHintTimer) clearTimeout(yellowExchangeHintTimer);
    yellowExchangeHintTimer = null;
    yellowExchangeHintWasPossible = false;
    yellowExchangeHintPhase = 'waiting';
    clearYellowExchangeHintOverlays();
}

function resumeHintGlowsAfterMenu() {
    armActionHint(blueHintInitialDelay());
    refreshYellowExchangeHintState();
}

function anyOutgoingTradeAvailableForHint() {
    if (
        state.sandboxMode ||
        state.historyViewTurn !== null ||
        state.outgoingOffer ||
        hasPendingPlayerAction()
    ) {
        return false;
    }

    if (state.autonomousTradeOffer) {
        return state.animals.some(animal =>
            animal?.enclosureId != null &&
            outgoingFitsAutonomousOffer(animal)
        );
    }

    for (const animal of state.animals) {
        if (animal?.enclosureId == null) continue;
        const cached = cachedPlayerTradeOffers(animal);
        if (lockedPlayerTradeOffersHaveLiveOffer(animal, cached)) return true;
    }

    return false;
}

function actionHintTarget() {
    if (!state.loaded) return null;
    if(!localClassicCanShowProgressionActionGlows())return null;

    const drawEnabled = drawCard &&
        drawCard.getAttribute('aria-disabled') !== 'true' &&
        !drawCard.classList.contains('draw-no-space');

    if (drawEnabled) return drawCard;
    return anyOutgoingTradeAvailableForHint() ? outgoingOfferBox : null;
}

function showActionHintNow() {
    if (hintControlIsBeingInspected()) {
        return false;
    }

    if (yellowExchangeHintPhase !== 'waiting' || yellowExchangeHintOverlays.length) {
        return false;
    }

    const target = actionHintTarget();
    if (!target) {
        return false;
    }

    const rect = target.getBoundingClientRect();
    if (rect.width < 2 || rect.height < 2) {
        return false;
    }

    removeActionHintOverlay();

    const ring = document.createElement('div');
    ring.setAttribute('data-zoo-action-hint', 'true');
    ring.dataset.hintTarget = target.id || '';
    Object.assign(ring.style, {
        position: 'fixed',
        left: `${rect.left - 8}px`,
        top: `${rect.top - 8}px`,
        width: `${rect.width + 16}px`,
        height: `${rect.height + 16}px`,
        boxSizing: 'border-box',
        border: '6px solid #3b9cff',
        borderRadius: '12px',
        background: 'rgba(45,145,255,.10)',
        boxShadow: '0 0 12px 7px rgba(55,155,255,1), 0 0 34px 17px rgba(55,145,255,.85)',
        pointerEvents: 'none',
        zIndex: '9000',
        opacity: '1'
    });
    document.body.appendChild(ring);
    actionHintOverlay = ring;

    if (yellowExchangeHintTimer) clearTimeout(yellowExchangeHintTimer);
    yellowExchangeHintTimer = null;
    clearYellowExchangeHintOverlays();

    if (yellowExchangePossible()) {
        yellowExchangeHintWasPossible = true;
        scheduleYellowExchangeHint(isBeginnerHintTurn() ? 4000 : 15000);
    }

    if (typeof ring.animate === 'function') {
        actionHintAnimation = ring.animate([
            { opacity: .25, transform: 'scale(.985)' },
            { opacity: 1, transform: 'scale(1.035)' },
            { opacity: .45, transform: 'scale(1)' },
            { opacity: 1, transform: 'scale(1.035)' },
            { opacity: 0, transform: 'scale(.99)' }
        ], { duration: 4000, easing: 'ease-in-out' });
        actionHintAnimation.onfinish = removeActionHintOverlay;
    } else {
        setTimeout(removeActionHintOverlay, 4000);
    }
    return true;
}

function armActionHint(delay = 4000) {
    if (actionHintTimer) clearTimeout(actionHintTimer);
    if (actionHintRepeatTimer) clearTimeout(actionHintRepeatTimer);
    const generation = ++actionHintGeneration;

    actionHintTimer = setTimeout(function fireHint() {
        if (generation !== actionHintGeneration) {
            return;
        }

        if (state.drag || state.pan) {
            actionHintTimer = setTimeout(fireHint, 250);
            return;
        }

        if (showActionHintNow()) {
            actionHintRepeatTimer = setTimeout(() => {
                if (generation === actionHintGeneration) fireHint();
            }, blueHintRepeatDelay());
        } else {
            actionHintTimer = setTimeout(fireHint, 500);
        }
    }, delay);
}

function noteNewCardAction() {
    actionHintGeneration++;
    if (actionHintTimer) clearTimeout(actionHintTimer);
    if (actionHintRepeatTimer) clearTimeout(actionHintRepeatTimer);
    actionHintTimer = null;
    actionHintRepeatTimer = null;
    removeActionHintOverlay();

    armActionHint(blueHintInitialDelay());
}

for (const hintControl of [exchange1, exchange2, resultBox, outgoingOfferBox]) {
    bindHintInspectionGuard(hintControl);
}

const exchangeEligibilityHoverTargets = [exchange1, exchange2, resultBox].filter(Boolean);
const EXCHANGE_HOVER_MARGIN = 10;

function pointInsideExpandedExchangeHoverArea(clientX, clientY) {
    return exchangeEligibilityHoverTargets.some(target => {
        const rect = target.getBoundingClientRect();
        return (
            clientX >= rect.left - EXCHANGE_HOVER_MARGIN &&
            clientX <= rect.right + EXCHANGE_HOVER_MARGIN &&
            clientY >= rect.top - EXCHANGE_HOVER_MARGIN &&
            clientY <= rect.bottom + EXCHANGE_HOVER_MARGIN
        );
    });
}

function refreshExchangeHoverFromPointer(event) {
    if (window.matchMedia('(max-width: 700px)').matches) return;
    const inside = pointInsideExpandedExchangeHoverArea(event.clientX, event.clientY);
    setExchangeEligibilityHover(inside);
}

for (const target of exchangeEligibilityHoverTargets) {
    target.addEventListener('mouseenter', event => {
        if (window.matchMedia('(max-width: 700px)').matches) return;
        setExchangeEligibilityHover(true);
    });
}

document.addEventListener('mousemove', event => {
    if (!state.exchangeEligibilityHoverActive) return;
    refreshExchangeHoverFromPointer(event);
}, { passive: true });

drawCard?.addEventListener('pointerdown', event => {
    if (event.button !== 0) return;
    if (visitingAnotherZooForActionUI()) { event.preventDefault(); event.stopPropagation(); refreshDrawAvailabilityState(); return; }

    drawCard.classList.add('draw-no-space');
    drawCard.setAttribute('aria-disabled', 'true');
    const immediateDrawImage = drawCard.querySelector('img');
    if (immediateDrawImage) {
        immediateDrawImage.style.opacity = '0.38';
        immediateDrawImage.style.filter = 'grayscale(1) brightness(.72) contrast(.82)';
    }

    if (state.drawCommitInProgress || hasPendingPlayerAction()) {
        event.preventDefault();
        event.stopPropagation();
        renderAll?.();
        return;
    }

    if (!nextLevelOneHasEligibleDestination()) {
        event.preventDefault();
        event.stopPropagation();
        renderAll?.();
        return;
    }

    event.preventDefault();
    event.stopPropagation();
    startDrawDrag(event);
});

let sandboxPickerOverlay = null;
let sandboxToolbarInstalled = false;
let sandboxHoveredAnimalId = null;
let sandboxHoveredEnclosureId = null;

function removeSandboxAnimalById(animalId) {
    if (!state.sandboxMode) return false;
    const id = Number(animalId);
    if (!Number.isFinite(id) || !state.animals.some(animal => animal.id === id)) return false;

    state.animals = state.animals.filter(animal => animal.id !== id);
    state.sandboxLooseAnimals = (state.sandboxLooseAnimals || []).filter(animal => animal.id !== id);
    state.exchange = (state.exchange || []).map(animal => animal?.id === id ? null : animal);
    if (state.result?.id === id) state.result = null;
    if (state.outgoingOffer?.id === id) state.outgoingOffer = null;
    state.tradeOffers = (state.tradeOffers || []).filter(offer =>
        offer?.animal?.id !== id && offer?.outgoing?.id !== id
    );
    sandboxHoveredAnimalId = null;
    renderAll();
    return true;
}

function removeSandboxEnclosureById(enclosureId) {
    if (!state.sandboxMode) return false;
    const id = Number(enclosureId);
    const enclosure = enclosureByIdFast(id);
    if (!enclosure) return false;

    const animalIds = new Set(
        state.animals.filter(animal => animal.enclosureId === id).map(animal => animal.id)
    );
    state.animals = state.animals.filter(animal => !animalIds.has(animal.id));
    state.sandboxLooseAnimals = (state.sandboxLooseAnimals || []).filter(animal => !animalIds.has(animal.id));
    state.enclosures = state.enclosures.filter(item => item.id !== id);
    state.glowingEnclosureIds.delete(id);
    state.newEnclosureGlowStartedAt.delete(id);
    sandboxHoveredEnclosureId = null;
    sandboxHoveredAnimalId = null;
    renderAll();
    return true;
}

window.addEventListener('keydown', event => {
    if (!state.sandboxMode) return;
    if (event.key !== 'Backspace' && event.key !== 'Delete') return;
    if (event.target instanceof HTMLInputElement ||
        event.target instanceof HTMLTextAreaElement ||
        event.target instanceof HTMLSelectElement ||
        event.target?.isContentEditable) return;

    if (sandboxHoveredAnimalId != null && removeSandboxAnimalById(sandboxHoveredAnimalId)) {
        event.preventDefault();
        event.stopPropagation();
        return;
    }
    if (sandboxHoveredEnclosureId != null && removeSandboxEnclosureById(sandboxHoveredEnclosureId)) {
        event.preventDefault();
        event.stopPropagation();
    }
});
