        const entry=entries[carouselIndex],ps=proposalState(entry);
        const stage=document.createElement('div');Object.assign(stage.style,{flex:'1',minHeight:'0',display:'grid',gridTemplateColumns:'58px minmax(0,1fr) 58px',alignItems:'stretch',gap:'6px',padding:'4px 10px 8px'});
        const prev=mkButton('‹',()=>{carouselIndex--;renderCarousel();});const next=mkButton('›',()=>{carouselIndex++;renderCarousel();});
        for(const b of [prev,next])Object.assign(b.style,{width:'48px',height:'86px',fontSize:'38px',padding:'0',justifySelf:'center',alignSelf:'center',borderRadius:'12px'});
        const hero=document.createElement('div');
